package com.ascent.climb.data.i18n

/**
 * Quiz en français (629 questions / 3 954 entrées).
 * Clés identiques à PackEnQuiz.kt ; chiffres, posologies et échelles inchangés.
 */

internal val PACK_FR_QUIZ: Map<String, String> = mapOf(

    // ---------- l1 Comprendre le risque en montagne ----------
    "q.l1#0.p" to "Lequel des éléments suivants est un danger objectif ?",
    "q.l1#0.o0" to "Chutes de pierres et chutes de glace",
    "q.l1#0.o1" to "Une erreur de jugement",
    "q.l1#0.o2" to "Un manque d'énergie",
    "q.l1#0.o3" to "Un état d'esprit de compétition",
    "q.l1#0.e" to "Les dangers objectifs sont des facteurs du milieu qui ne changent pas avec votre niveau ou votre attitude : chutes de pierres, chutes de glace, avalanches, météo, crevasses. Les trois autres sont des dangers subjectifs que l'entraînement et la discipline peuvent maîtriser.",

    "q.l1#1.p" to "Quand l'altitude augmente, comment évoluent la température de l'air et la pression partielle d'oxygène ?",
    "q.l1#1.o0" to "La température monte et la pression partielle d'oxygène baisse",
    "q.l1#1.o1" to "La température baisse d'environ 6,5 °C par 1 000 m, et la pression partielle d'oxygène baisse avec elle",
    "q.l1#1.o2" to "Ni l'une ni l'autre ne change",
    "q.l1#1.o3" to "La température baisse et la pression partielle d'oxygène monte",
    "q.l1#1.e" to "Pour chaque 1 000 m de montée, l'air se refroidit d'environ 6,5 °C, tandis que la pression atmosphérique et la pression partielle d'oxygène baissent de concert. C'est pourquoi le mal d'altitude et le froid arrivent ensemble.",

    "q.l1#2.p" to "Quelle affirmation sur le rôle de l'entraînement est correcte ?",
    "q.l1#2.o0" to "Un bon entraînement supprime tous les dangers objectifs",
    "q.l1#2.o1" to "L'entraînement réduit les dangers subjectifs mais ne peut pas supprimer les dangers objectifs",
    "q.l1#2.o2" to "Les dangers objectifs relèvent uniquement de la chance",
    "q.l1#2.o3" to "Si vous êtes assez en forme, il n'y a aucun danger",
    "q.l1#2.e" to "L'entraînement technique améliore votre jugement et vos réactions, mais les chutes de pierres, les avalanches et la météo ne disparaissent pas parce que vous êtes expérimenté. La bonne attitude face aux dangers objectifs est de les éviter et de conserver une échappatoire.",

    "q.l1#3.p" to "Pourquoi les alpinistes insistent-ils sur la marge plutôt que sur la réparation sur place ?",
    "q.l1#3.o0" to "Parce que la marge augmente le taux de réussite au sommet",
    "q.l1#3.o1" to "Parce que la marge agit tôt dans la chaîne d'accident, alors que la réparation intervient au dernier maillon",
    "q.l1#3.o2" to "Parce que la marge fait économiser de l'argent",
    "q.l1#3.o3" to "Parce que les règles exigent une réserve",
    "q.l1#3.e" to "La marge prend plusieurs formes : temps, énergie, vivres, fenêtre météo. Leur point commun est que vous créez l'espace alors que vous pouvez encore choisir. La réparation commence toujours après qu'un problème est survenu, quand les options sont rares.",

    "q.l1#4.p" to "Quelle est la meilleure mesure du niveau d'une cordée ?",
    "q.l1#4.o0" to "L'altitude la plus élevée atteinte par un membre",
    "q.l1#4.o1" to "Le nombre de sorties par an",
    "q.l1#4.o2" to "Sa capacité à reculer en sécurité quand il le faut et à maintenir un risque acceptable",
    "q.l1#4.o3" to "La valeur totale de son matériel",
    "q.l1#4.e" to "Les records de sommet prouvent seulement que quelque chose a fonctionné un jour ; la capacité de reculer prouve la maîtrise. En haute altitude, la prochaine occasion arrive toujours, un accident grave non. Ce qui distingue vraiment les cordées, c'est la qualité de leurs décisions dans des conditions défavorables.",

    "q.l1#5.p" to "La réglementation chinoise limite l'alpinisme aux « sommets indépendants ». Comment un sommet indépendant se définit-il sur une carte topographique ?",
    "q.l1#5.o0" to "Tout massif de plus de 5 000 m",
    "q.l1#5.o1" to "Un massif entouré d'une courbe de niveau fermée",
    "q.l1#5.o2" to "Un massif portant un glacier visible",
    "q.l1#5.o3" to "Un massif que personne n'a gravi",
    "q.l1#5.e" to "Sur une carte topographique, un sommet indépendant apparaît comme une courbe de niveau fermée, ce qui signifie que le massif s'abaisse de tous les côtés. Cette définition sépare l'alpinisme de la simple marche vers un point haut, et c'est elle qui structure l'administration et le décompte de l'activité.",

    "q.l1#6.p" to "Quel est le schéma le plus fréquent dans les analyses d'accidents ?",
    "q.l1#6.o0" to "Presque chaque accident provient d'une seule grosse erreur",
    "q.l1#6.o1" to "Les accidents graves résultent généralement de plusieurs petites erreurs accumulées",
    "q.l1#6.o2" to "Les accidents n'ont aucun lien avec l'expérience",
    "q.l1#6.o3" to "La défaillance du matériel en est la cause principale",
    "q.l1#6.e" to "Un accident typique est une chaîne : une décision d'itinéraire trop optimiste, puis du retard sur l'horaire, puis une protection simplifiée pour gagner du temps, puis la fatigue qui dégrade la gestuelle. Cassez un seul maillon et l'accident n'a pas lieu — c'est exactement pourquoi la marge vaut mieux que la réparation.",

    "q.l1#7.p" to "[Choix multiple] Lesquels sont des dangers objectifs en alpinisme ?",
    "q.l1#7.o0" to "Chutes de pierres et chutes de glace",
    "q.l1#7.o1" to "Avalanche",
    "q.l1#7.o2" to "Un changement brusque de météo",
    "q.l1#7.o3" to "Crevasses",
    "q.l1#7.o4" to "Un état d'esprit de compétition",
    "q.l1#7.e" to "Les quatre premiers ne changent pas avec votre niveau ou votre attitude : ce sont des propriétés du milieu. Face aux dangers objectifs, vous ne pouvez qu'éviter, choisir le moment et garder une échappatoire. Les dangers subjectifs — mauvais jugement, préparation insuffisante, comparaison avec les autres — sont la part que l'entraînement peut réellement réduire.",

    "q.l1#8.p" to "Avant une course en haute altitude, quelles trois choses devez-vous vérifier d'abord ?",
    "q.l1#8.o0" to "Condition physique, matériel, itinéraire et assurance",
    "q.l1#8.o1" to "La réputation des partenaires, la célébrité du sommet, les marques du matériel",
    "q.l1#8.o2" to "Les photos, la vidéo et votre plan de réseaux sociaux",
    "q.l1#8.o3" to "Les prévisions, les vols et les hôtels",
    "q.l1#8.e" to "La condition physique décide si vous pouvez terminer, le matériel décide si vous survivez à de mauvaises conditions, et l'itinéraire plus l'assurance décident s'il existe des secours quand quelque chose tourne mal. Les trois sont entièrement sous votre contrôle avant le départ — d'où l'absence d'excuse quand ils font défaut.",

    "q.l1#9.p" to "Pourquoi des alpinistes expérimentés peuvent-ils encore se mettre en difficulté ?",
    "q.l1#9.o0" to "Parce que l'expérience élève peu à peu ce que vous acceptez comme risque normal",
    "q.l1#9.o1" to "Parce que les personnes expérimentées tentent des itinéraires plus durs",
    "q.l1#9.o2" to "Parce que l'expérience n'a aucun rapport avec la sécurité",
    "q.l1#9.o3" to "Parce que les personnes expérimentées se fatiguent plus vite",
    "q.l1#9.e" to "Cela s'appelle la normalisation du risque : après avoir traversé plusieurs fois les mêmes conditions sans incident, vous les reclassez inconsciemment comme « sûres » et élargissez le critère un peu à la fois. Plus vous êtes expérimenté, plus vous avez besoin de règles explicites — une heure de demi-tour, par exemple — pour contenir votre jugement.",

    // ---------- l2 Piolet et crampons ----------
    "q.l2#0.p" to "À quoi sert principalement un piolet de type T (technique) ?",
    "q.l2#0.o0" to "À flâner sur des pentes de neige douces",
    "q.l2#0.o1" to "Aux pentes de glace raides et à l'escalade technique",
    "q.l2#0.o2" to "Uniquement à la photographie",
    "q.l2#0.o3" to "Uniquement au bivouac sur neige",
    "q.l2#0.e" to "Une hampe de type T peut être plantée dans la glace et supporter une traction, ce qui convient à la glace raide. Une hampe de type B est plus faible : elle est dimensionnée pour la marche et l'auto-assurage et ne doit pas servir d'ancrage technique.",

    "q.l2#1.p" to "Quelle catégorie de crampons va avec une chaussure B3 entièrement rigide ?",
    "q.l2#1.o0" to "C1, entièrement à sangle",
    "q.l2#1.o1" to "C2, sangle à l'avant et clip à l'arrière",
    "q.l2#1.o2" to "C3, entièrement à clip",
    "q.l2#1.o3" to "N'importe quelle catégorie convient",
    "q.l2#1.e" to "Une chaussure B3 possède des débords avant et arrière, et un crampon C3 à clip intégral est l'accord le plus sûr. B1 avec C1, B2 avec C2 et B3 avec C3 : c'est la règle d'appariement de base.",

    "q.l2#2.p" to "Que se passe-t-il si vous montez des crampons C3 à clip intégral sur une chaussure de randonnée à semelle souple ?",
    "q.l2#2.o0" to "Aucun problème, et c'est plus rapide à mettre",
    "q.l2#2.o1" to "La chaussure se déforme sous la charge, les clips perdent leur prise et le crampon peut se détacher — un montage dangereux",
    "q.l2#2.o2" to "Vous marcherez plus vite",
    "q.l2#2.o3" to "C'est seulement inesthétique",
    "q.l2#2.e" to "Les crampons à clip intégral comptent sur une chaussure rigide pour garder leur forme. Sur une chaussure souple, celle-ci fléchit, les clips perdent prise et le crampon peut partir dans une pente raide. C'est un appariement manifestement dangereux.",

    "q.l2#3.p" to "La longueur du piolet se choisit en général selon la taille. Que recommande-t-on pour un alpiniste d'environ 173–180 cm ?",
    "q.l2#3.o0" to "50 cm",
    "q.l2#3.o1" to "55 cm",
    "q.l2#3.o2" to "60 cm",
    "q.l2#3.o3" to "70 cm",
    "q.l2#3.e" to "Repère courant : sous 157 cm environ, 50 cm ; 157–170 cm, 55 cm ; 173–180 cm, 60 cm ; au-dessus de 183 cm, 65–70 cm. Seule une longueur adaptée permet d'enfoncer efficacement la panne dans la neige lors de l'auto-assurage.",

    "q.l2#4.p" to "Lors du choix des crampons, quelle est l'exigence la plus élémentaire et la plus importante ?",
    "q.l2#4.o0" to "Aussi légers que possible",
    "q.l2#4.o1" to "Ils doivent s'adapter à la chaussure, idéalement acier 12 pointes avec plaques anti-bottage",
    "q.l2#4.o2" to "La couleur doit s'accorder au reste du matériel",
    "q.l2#4.o3" to "Plus il y a de pointes, mieux c'est — 20 ou plus",
    "q.l2#4.e" to "Un crampon ne vaut que par sa liaison avec la chaussure. Plus de pointes n'est pas automatiquement mieux ; ce qui compte, c'est l'ajustement et les plaques anti-bottage (qui empêchent la neige de s'accumuler sous le pied). Un mauvais ajustement est la façon classique de perdre un crampon dans une pente raide.",

    "q.l2#5.p" to "[Mise en situation] Pour une journée de sommet technique en haute altitude avec crampons, piolet, couche isolante de rechange, nourriture, eau et kit d'urgence, quel volume net de sac est recommandé ?",
    "q.l2#5.o0" to "15–25 litres",
    "q.l2#5.o1" to "35–50 litres",
    "q.l2#5.o2" to "60–75 litres",
    "q.l2#5.o3" to "90 litres ou plus",
    "q.l2#5.e" to "Pour « matériel technique personnel + couche isolante de rechange + kit d'urgence », 35–50 litres est la fourchette habituelle, idéalement avec une poche dédiée aux crampons.\nMais le volume n'est pas fixe : sur une pente de neige très fréquentée, avec le matériel collectif porté par l'encadrement et une météo stable, un sac de sommet de 15–25 litres peut suffire ; si vous devez porter vous-même la tente ou les cordes, il en faut davantage.\nLe critère est toujours ce que vous avez réellement à porter, pas un chiffre universel.",

    "q.l2#6.p" to "À quoi sert principalement la dragonne d'un piolet ?",
    "q.l2#6.o0" to "À la décoration et à l'identification de la cordée",
    "q.l2#6.o1" to "À éviter de perdre le piolet, afin de pouvoir encore le contrôler après un dérapage",
    "q.l2#6.o2" to "À ajouter du poids pour que le piolet appuie plus fort",
    "q.l2#6.o3" to "À suspendre le piolet au sac",
    "q.l2#6.e" to "La dragonne compte à l'instant du dérapage : une fois le piolet parti de votre main, vous avez perdu le seul objet capable de freiner. La dragonne le garde avec vous pendant les mouvements violents — d'où l'insistance de tant de manuels à l'utiliser.",

    "q.l2#7.p" to "[Choix multiple] Quels facteurs comptent au moment de choisir des crampons ?",
    "q.l2#7.o0" to "Le mode de fixation à la chaussure (sangle / semi-automatique / automatique)",
    "q.l2#7.o1" to "Le nombre et la forme des pointes convenant au terrain",
    "q.l2#7.o2" to "La présence de plaques anti-bottage",
    "q.l2#7.o3" to "La fiabilité des fixations et des sangles",
    "q.l2#7.o4" to "La couleur assortie au sac",
    "q.l2#7.e" to "Les quatre premiers comptent. La fixation décide si le crampon se monte tout court, la forme des pointes décide de l'adéquation au terrain (pointes avant pour la glace raide, pointes plates pour la neige douce), les plaques décident si la neige botte dessous, et les fixations décident si le crampon reste en place.",

    "q.l2#8.p" to "Pourquoi vérifier les sangles et fixations des crampons avant chaque départ ?",
    "q.l2#8.o0" to "Pour garder le matériel en ordre",
    "q.l2#8.o1" to "Parce qu'un crampon qui se détache dans une pente raide menace directement la vie",
    "q.l2#8.o2" to "Parce que les sangles vieillissent et changent de couleur",
    "q.l2#8.o3" to "Parce que la discipline de cordée l'exige",
    "q.l2#8.e" to "Les crampons ont tendance à lâcher au pire moment : dans une face raide, pendant une traversée, au premier pas en charge. Perdre l'accroche sous un pied déplace instantanément votre centre de masse. La vérification ne coûte presque rien ; la conséquence est totalement disproportionnée.",

    "q.l2#9.p" to "Quelle affirmation sur la forme de la panne d'un piolet est correcte ?",
    "q.l2#9.o0" to "Toutes les pannes de piolet sont droites",
    "q.l2#9.o1" to "Une panne courbée entre plus facilement dans la glace et ressort moins facilement ; elle est courante sur les piolets techniques",
    "q.l2#9.o2" to "Une panne courbée ne sert qu'à marcher sur la neige",
    "q.l2#9.o3" to "La forme de la panne n'a aucun rapport avec l'usage",
    "q.l2#9.e" to "Un long piolet d'alpinisme a en général une panne courbée vers le bas, qui mord au balancement ou au freinage et ne ressort pas facilement. Les outils de cascade de glace ont des pannes plus acérées et plus inclinées, pour un placement rapide et un retrait facile sur glace raide. L'usage dicte la forme.",

    // ---------- l3 Chaussures, lunettes, vêtements ----------
    "q.l3#0.p" to "Quel est le principal avantage des chaussures doubles sur les simples ?",
    "q.l3#0.o0" to "Plus légères",
    "q.l3#0.o1" to "Plus chaudes, et la chaussure intérieure se retire pour sécher",
    "q.l3#0.o2" to "Moins chères",
    "q.l3#0.o3" to "Plus faciles à chausser et déchausser",
    "q.l3#0.e" to "La chaussure intérieure se retire : on peut la sécher contre le corps ou dans le sac de couchage la nuit et elle ne gèle pas — le point clé sur les courses de plusieurs jours en altitude. Le prix à payer est le poids et le coût.",

    "q.l3#1.p" to "Quelle est la spécification la plus importante pour des lunettes de glacier ?",
    "q.l3#1.o0" to "La teinte du verre",
    "q.l3#1.o1" to "La protection ultraviolet UV400",
    "q.l3#1.o2" to "La marque de la monture",
    "q.l3#1.o3" to "Le fait que le verre soit miroir",
    "q.l3#1.e" to "La neige réfléchit énormément d'ultraviolets. UV400 signifie un blocage quasi complet des UV et c'est la clé pour éviter l'ophtalmie des neiges ; la teinte n'affecte que le confort visuel.",

    "q.l3#2.p" to "Que faut-il prendre en compte pour choisir la taille d'une chaussure d'alpinisme ?",
    "q.l3#2.o0" to "Plus serré c'est mieux, pour que le pied ne glisse pas",
    "q.l3#2.o1" to "Les orteils ne doivent pas toucher l'avant, avec un peu de place pour que la descente ne les blesse pas",
    "q.l3#2.o2" to "Plus grand c'est mieux, pour mettre des chaussettes plus épaisses",
    "q.l3#2.o3" to "Exactement la même taille que vos chaussures de ville",
    "q.l3#2.e" to "En descente, le pied glisse vers l'avant. Si les orteils butent contre la pointe, une longue descente peut les meurtrir, voire faire perdre un ongle. Laissez un peu de place et verrouillez le talon avec le laçage.",

    "q.l3#3.p" to "Quel est le trait de conception clé d'une chaussure de sommet pour 8 000 m ?",
    "q.l3#3.o0" to "Aussi légère que possible",
    "q.l3#3.o1" to "Une doublure isolante amovible avec une tige imperméable, coupe-vent et résistante à l'abrasion",
    "q.l3#3.o2" to "Elle doit être à simple paroi",
    "q.l3#3.o3" to "Plus la semelle est souple, plus c'est confortable",
    "q.l3#3.e" to "Une doublure amovible peut être sortie la nuit pour sécher ou être gardée au chaud contre le corps, de sorte qu'elle ne gèle jamais — la clé pour garder des pieds fonctionnels sur les courses de plusieurs jours en altitude. La tige est en général un complexe trois couches pour l'imperméabilité, la résistance au vent et la durabilité.",

    "q.l3#4.p" to "Pourquoi une première couche ne doit-elle jamais être en coton ?",
    "q.l3#4.o0" to "Le coton coûte trop cher",
    "q.l3#4.o1" to "Le coton retient la sueur et sèche lentement : un tissu humide contre la peau accélère la perte de chaleur",
    "q.l3#4.o2" to "Le coton provoque des allergies",
    "q.l3#4.o3" to "Le coton ne respire pas, donc il paraît plus froid",
    "q.l3#4.e" to "Le rôle de la première couche est d'évacuer la sueur loin de la peau. Le coton absorbe l'eau et ne la relâche presque pas : un tissu humide et froid continue de pomper la chaleur. Choisissez du polyester ou de la laine mérinos, qui évacuent vite l'humidité.",

    "q.l3#5.p" to "Quel matériau est recommandé pour une chaussure de 6 000 m ?",
    "q.l3#5.o0" to "Du cuir ordinaire",
    "q.l3#5.o1" to "Un matériau imperméable et respirant comme le GORE-TEX",
    "q.l3#5.o2" to "Du tissu en coton pur",
    "q.l3#5.o3" to "Une coque en plastique rigide",
    "q.l3#5.e" to "Une chaussure de 6 000 m privilégie la légèreté, le confort et l'accroche, et doit aussi bien marcher pendant des heures. Une membrane imperméable-respirante comme le GORE-TEX bloque l'eau tout en laissant sortir la vapeur — imperméable sans respirabilité, elle emprisonne simplement la sueur et vous finissez mouillé et froid quand même.",

    "q.l3#6.p" to "Quel matériau les chaussettes d'alpinisme doivent-elles éviter ?",
    "q.l3#6.o0" to "La laine mérinos",
    "q.l3#6.o1" to "Les fibres synthétiques comme le polyester",
    "q.l3#6.o2" to "Le coton",
    "q.l3#6.o3" to "Le nylon",
    "q.l3#6.e" to "Même logique que la première couche : le coton absorbe la sueur et ne la relâche presque pas, donc un tissu humide et froid continue de drainer la chaleur et augmente fortement le risque d'ampoules. Choisissez du synthétique (sans coton) ou du mérinos, dans une coupe genou qui équilibre chaleur et circulation.",

    "q.l3#7.p" to "Quelle est la bonne approche pour choisir des guêtres ?",
    "q.l3#7.o0" to "Utiliser les mêmes guêtres courtes à chaque sortie",
    "q.l3#7.o1" to "Pour les hauts sommets, préférer des guêtres longues qui empêchent la neige d'entrer dans la chaussure",
    "q.l3#7.o2" to "Les guêtres ne servent que contre la pluie",
    "q.l3#7.o3" to "Plus court et plus léger, c'est toujours mieux",
    "q.l3#7.e" to "Les guêtres sont un tube de tissu par-dessus la chaussure qui empêche la neige et les débris d'entrer. Dans la neige profonde d'altitude, une paire courte est vite ensevelie et inutile ; les longues sont donc recommandées. Les courtes conviennent aux itinéraires de trekking connus et à une neige peu épaisse de style alpin.",

    "q.l3#8.p" to "À quoi servent les chaussons et sandales de camp, et que doivent-ils avoir ?",
    "q.l3#8.o0" to "Au sommet ; ils doivent être très rigides",
    "q.l3#8.o1" to "À circuler dans le camp ; ils doivent être chauds, imperméables et antidérapants",
    "q.l3#8.o2" to "À l'escalade technique ; ils ont besoin de pointes avant",
    "q.l3#8.o3" to "Purement décoratifs ; facultatifs",
    "q.l3#8.e" to "Ils permettent à vos chaussures principales de se reposer : on enfile des chaussons ou des sandales dans la tente pour que les doublures sèchent et que les pieds ne soient pas comprimés toute la journée. Ils n'ont aucune fonction technique, mais ils influent directement sur l'état de vos pieds le lendemain matin.",

    "q.l3#9.p" to "Qu'apporte une chaussette montante jusqu'au genou lors d'une longue expédition ?",
    "q.l3#9.o0" to "Elle fait plus professionnel",
    "q.l3#9.o1" to "Elle garde le pied au chaud tout en soutenant la circulation",
    "q.l3#9.o2" to "Elle est plus facile à enfiler",
    "q.l3#9.o3" to "Elle ajoute de l'épaisseur amortissante",
    "q.l3#9.e" to "Lors des longues journées, les pieds gonflent et la circulation souffre. Une chaussette montante couvre le mollet, le réchauffe et, par une pression régulière, favorise le retour veineux — ce qui, sur une course de plusieurs jours, décide si vos pieds fonctionnent encore le troisième jour.",

    // ---------- l4 Techniques de déplacement sur neige ----------
    "q.l4#0.p" to "Quelle est la bonne façon de tailler des marches ?",
    "q.l4#0.o0" to "Faire de longues enjambées pour prendre moins de pas",
    "q.l4#0.o1" to "Tailler de petites marches à un rythme régulier en gardant le centre de masse stable",
    "q.l4#0.o2" to "N'utiliser que la pointe des pieds",
    "q.l4#0.o3" to "Enfoncer le talon dans la neige tout du long",
    "q.l4#0.e" to "De petits pas à rythme régulier gardent le centre de masse stable et gaspillent moins d'énergie. Les longues enjambées font balancer le corps d'un côté à l'autre — la façon la plus simple de perdre l'équilibre sur une pente de neige.",

    "q.l4#1.p" to "De quelle main faut-il porter le piolet en marche ?",
    "q.l4#1.o0" to "La main côté aval",
    "q.l4#1.o1" to "La main côté amont, prête à passer directement en auto-assurage",
    "q.l4#1.o2" to "Aucune des deux",
    "q.l4#1.o3" to "À l'extérieur du sac",
    "q.l4#1.e" to "Portez-le dans la main côté amont en position piolet-canadienne, panne vers l'arrière et tête vers l'avant. En cas de dérapage, vous pouvez appuyer en auto-assurage sans changer de main — et ces quelques secondes de transfert sont souvent toute la fenêtre de l'accident.",

    "q.l4#2.p" to "Quelle technique soulage l'essoufflement en altitude à la montée ?",
    "q.l4#2.o0" to "Retenir sa respiration en marchant",
    "q.l4#2.o1" to "La respiration sous pression : inspiration profonde et expiration forcée, synchronisées avec le rythme des pas",
    "q.l4#2.o2" to "Une respiration rapide et superficielle",
    "q.l4#2.o3" to "Respirer à travers un gant",
    "q.l4#2.e" to "La respiration sous pression crée une pression positive dans les poumons en expirant activement, ce qui améliore les échanges gazeux. Associée au rythme des pas — une respiration toutes les deux ou trois enjambées, par exemple — elle réduit nettement la sensation d'étouffement de l'altitude.",

    "q.l4#3.p" to "Quand une cordée monte une pente de neige, quelle est la bonne façon de tailler les marches ?",
    "q.l4#3.o0" to "Chacun taille sa propre ligne",
    "q.l4#3.o1" to "Le premier taille un escalier régulier et tous ceux derrière utilisent les mêmes marches",
    "q.l4#3.o2" to "Chacun taille comme il veut",
    "q.l4#3.o3" to "Les tailler aussi profondes et larges que possible",
    "q.l4#3.e" to "Un seul jeu de marches réduit beaucoup l'effort de tous ceux qui suivent et garde la cordée sur une ligne et un rythme. Un escalier régulier et également espacé est en soi une marque d'efficacité et de sécurité collective.",

    "q.l4#4.p" to "En altitude, quel est le principe central de l'allure ?",
    "q.l4#4.o0" to "Aller le plus vite possible et se reposer plus tôt",
    "q.l4#4.o1" to "Tenir une allure régulière soutenable et éviter les efforts explosifs répétés",
    "q.l4#4.o2" to "Alterner rapide et lent pour économiser l'énergie",
    "q.l4#4.o3" to "Suivre simplement son partenaire en ignorant son propre état",
    "q.l4#4.e" to "La captation d'oxygène est limitée en altitude, donc les efforts explosifs répétés accumulent le lactate et aggravent l'hypoxie. Une allure régulière avec respiration sous pression vous mène plus loin, et évite que toute la cordée soit perturbée par une personne qui sprinte.",

    "q.l4#5.p" to "Qui doit donner l'allure à une cordée sur une pente de neige ?",
    "q.l4#5.o0" to "La personne la plus en forme de la cordée",
    "q.l4#5.o1" to "Elle doit suivre le membre le plus lent pour que la cordée reste groupée",
    "q.l4#5.o2" to "Le chef de cordée, calé sur l'horaire",
    "q.l4#5.o3" to "Chacun à son propre rythme",
    "q.l4#5.e" to "Dès que des écarts s'ouvrent sur une pente de neige, ceux de derrière perdent à la fois protection et soutien ; et une allure trop rapide épuise les plus faibles avant même qu'ils atteignent le terrain dangereux. Marcher à l'allure du plus lent garde la marge de sécurité avec toute la cordée.",

    "q.l4#6.p" to "Pour traverser une pente de glace nettement inclinée, que recommande le manuel ?",
    "q.l4#6.o0" to "Progresser en cordée normale",
    "q.l4#6.o1" to "Installer une corde fixe ou assurer en alternance ; en général ne pas progresser ensemble",
    "q.l4#6.o2" to "Traverser au plus vite",
    "q.l4#6.o3" to "Retirer les crampons pour avoir plus d'adhérence",
    "q.l4#6.e" to "Le freinage sur glace est bien moins fiable que sur neige, et une cordée sur glace peut entraîner tout le groupe dans la chute. Sur une glace inclinée, la bonne approche est la corde fixe ou l'assurage en alternance — une protection qui vient du système, pas de la capacité de freinage individuelle.",

    "q.l4#7.p" to "Quel est le principal avantage de monter en zigzag plutôt qu'en ligne droite sur une pente de neige ?",
    "q.l4#7.o0" to "Une distance plus courte",
    "q.l4#7.o1" to "Cela réduit l'angle effectif de chaque portion et économise l'énergie",
    "q.l4#7.o2" to "De meilleures vues",
    "q.l4#7.o3" to "On n'a pas besoin du piolet",
    "q.l4#7.e" to "Le zigzag découpe une pente raide en plusieurs portions plus douces, ce qui réduit beaucoup la charge sur les mollets et les chevilles et convient à la technique française (pied à plat). Le prix est la distance : ajustez votre budget temps — une raison de plus de garder une marge dans l'heure de demi-tour.",

    // ---------- l5 Techniques de crampons : française / allemande / mixte ----------
    "q.l5#0.p" to "Quel est le point clé de la technique française (pied à plat) ?",
    "q.l5#0.o0" to "Planter uniquement les pointes avant dans la glace",
    "q.l5#0.o1" to "Poser toutes les pointes inférieures du crampon à plat sur la pente, le pied à plat",
    "q.l5#0.o2" to "Sauter sur un pied",
    "q.l5#0.o3" to "Enfoncer le côté de la chaussure dans la glace",
    "q.l5#0.e" to "La technique française repose sur le plat : les douze pointes inférieures mordent et la charge se répartit dans la cuisse et tout le corps, ce qui la rend la moins fatigante. D'où son intérêt sur de longues étendues de neige douce.",

    "q.l5#1.p" to "Pourquoi la technique des pointes avant (allemande) est-elle la plus fatigante ?",
    "q.l5#1.o0" to "Parce qu'elle sollicite les bras",
    "q.l5#1.o1" to "Parce que la charge repose sur les pointes avant et que le mollet doit travailler en continu",
    "q.l5#1.o2" to "Parce qu'il faut retenir sa respiration",
    "q.l5#1.o3" to "Parce que le frottement est plus élevé",
    "q.l5#1.e" to "Les pointes avant placent votre poids sur deux ou trois points : le mollet maintient une contraction continue pour garder la position. C'est extrêmement fatigant et impossible à tenir longtemps — d'où son usage réservé au terrain raide.",

    "q.l5#2.p" to "Quel jeu de pieds faut-il utiliser en traversée sur une pente de neige ?",
    "q.l5#2.o0" to "Les pointes avant, enfoncées droit devant",
    "q.l5#2.o1" to "Le pas de canard : talons rapprochés, pointes vers l'extérieur, pour que tout le crampon repose sur la pente",
    "q.l5#2.o2" to "Des sauts latéraux",
    "q.l5#2.o3" to "Ramper sur les genoux",
    "q.l5#2.e" to "Le pas de canard permet aux pointes latérales et inférieures de mordre en même temps, de sorte que le poids ne se concentre pas sur les pointes intérieures où il peut glisser. Penchez-vous légèrement vers la pente pendant la traversée.",

    "q.l5#3.p" to "Quel terrain convient le mieux à la technique française (pied à plat) ?",
    "q.l5#3.o0" to "La glace verticale",
    "q.l5#3.o1" to "La neige dure à pente faible à modérée, où l'on progresse pendant des heures",
    "q.l5#3.o2" to "Les toits en surplomb",
    "q.l5#3.o3" to "Uniquement le terrain plat",
    "q.l5#3.e" to "La technique française répartit la charge dans tout le corps et la cuisse : elle est donc la moins fatigante et la technique de base pour les pentes faibles à modérées et les longs névés. Le terrain raide exige les pointes avant, mais celles-ci ne se tiennent pas.",

    "q.l5#4.p" to "Que se passe-t-il si vous restez longtemps sur les pointes avant dans une pente raide ?",
    "q.l5#4.o0" to "Cela devient plus facile au fil de la montée",
    "q.l5#4.o1" to "Le mollet se fatigue vite jusqu'à ce que vous ne puissiez plus tenir la position",
    "q.l5#4.o2" to "Les crampons tombent tout seuls",
    "q.l5#4.o3" to "Rien du tout",
    "q.l5#4.e" to "Les pointes avant concentrent votre poids sur deux ou trois points et maintiennent le mollet en contraction continue : la fatigue arrive vite. D'où leur usage limité aux courtes sections raides — et la nécessité d'en tenir compte dans votre budget d'énergie quand vous planifiez un itinéraire.",

    "q.l5#5.p" to "Dans la technique mixte (américaine), comment les deux pieds se répartissent-ils le travail ?",
    "q.l5#5.o0" to "Les deux pieds restent à plat sur la pente",
    "q.l5#5.o1" to "Les deux pieds utilisent les pointes avant",
    "q.l5#5.o2" to "Un pied à plat pour l'appui, l'autre poussant sur les pointes avant, en alternance",
    "q.l5#5.o3" to "Un pied fait tout le travail, l'autre se repose",
    "q.l5#5.e" to "La technique mixte fait le pont entre la française et l'allemande : le pied à plat donne la stabilité et un instant de repos, le pied sur pointes avant fournit la poussée. Sur les pentes modérées à raides, elle garde l'efficacité sans épuiser les mollets comme le fait la technique pure des pointes avant.",

    "q.l5#6.p" to "[Association] Associez chaque catégorie de crampons à sa chaussure.",
    "q.l5#6.l0" to "C1, entièrement à sangle",
    "q.l5#6.r0" to "Chaussure B1 souple",
    "q.l5#6.l1" to "C2, sangle à l'avant et clip à l'arrière",
    "q.l5#6.r1" to "Chaussure B2 semi-rigide",
    "q.l5#6.l2" to "C3, entièrement à clip",
    "q.l5#6.r2" to "Chaussure B3 entièrement rigide",
    "q.l5#6.e" to "Chaussure et crampon doivent s'accorder : souple avec C1, semi-rigide avec C2, rigide avec C3. Des crampons à clip intégral sur une chaussure souple laissent celle-ci fléchir, les clips perdent prise et le crampon peut partir dans une pente raide — un montage manifestement dangereux.",

    "q.l5#7.p" to "Quelles sont les deux techniques de base du déplacement sur glace ?",
    "q.l5#7.o0" to "Le pied à plat et le pas latéral",
    "q.l5#7.o1" to "La technique à plat (française) et la technique des pointes avant (allemande)",
    "q.l5#7.o2" to "Le saut et la glissade",
    "q.l5#7.o3" to "La technique de montée et la technique de descente",
    "q.l5#7.e" to "La technique à plat engage toutes les pointes verticales sauf les pointes avant ; la technique des pointes avant enfonce celles-ci droit dans la glace. Le terrain complexe mélange généralement les deux — d'où la nécessité de maîtriser l'une et l'autre avant d'aborder la technique mixte.",

    "q.l5#8.p" to "Avec la technique à plat (française), quels muscles portent la charge ?",
    "q.l5#8.o0" to "Les mollets",
    "q.l5#8.o1" to "Les cuisses",
    "q.l5#8.o2" to "Les avant-bras",
    "q.l5#8.o3" to "Le bas du dos",
    "q.l5#8.e" to "Comme le pied reste à plat, ce sont les cuisses et tout le corps qui portent la charge : la technique est économique et se tient pendant des heures. Les pointes avant font l'inverse : la charge repose sur deux ou trois points et le mollet fait tout le travail — deux budgets d'énergie très différents.",

    "q.l5#9.p" to "La technique à plat (française) convient particulièrement à quel angle de pente ?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Plus de 70°",
    "q.l5#9.e" to "Les manuels indiquent explicitement 0°–30°. Au-delà, le pied ne peut plus rester à plat et il faut passer aux pointes avant. Connaître la plage d'angle de chaque technique, c'est en réalité savoir quand changer de technique.",

    // ---------- l6 Utilisation du piolet et auto-assurage ----------
    "q.l6#0.p" to "Où doivent être vos pieds pendant un auto-assurage ?",
    "q.l6#0.o0" to "Enfoncés dans la neige pour freiner",
    "q.l6#0.o1" to "Levés au-dessus de la neige, pointes vers le haut, pour que tout votre poids passe par le piolet",
    "q.l6#0.o2" to "Pointes plantées dans la neige pour s'ancrer",
    "q.l6#0.o3" to "Jointifs et à plat sur la neige",
    "q.l6#0.e" to "Dès qu'un pied touche la neige, il retire du poids au piolet, l'efficacité du freinage s'effondre et vous risquez une blessure de la cheville ou du genou. Levez les deux pieds pour que tout le poids du corps passe par la panne dans la neige.",

    "q.l6#1.p" to "Vous glissez la tête en avant, les pieds en amont. Que faites-vous en premier ?",
    "q.l6#1.o0" to "Essayer d'attraper la corde",
    "q.l6#1.o1" to "Rouler immédiatement sur le ventre avec les pieds en aval, puis établir l'auto-assurage",
    "q.l6#1.o2" to "Continuer à glisser en attendant que la vitesse baisse",
    "q.l6#1.o3" to "Jeter d'abord son sac",
    "q.l6#1.e" to "La tête en avant, la panne ne peut pas être plaquée efficacement dans la neige, et un choc tête première est extrêmement dangereux. Utilisez le tronc et les abdominaux pour basculer d'abord en position ventrale d'auto-assurage, puis plantez la panne.",

    "q.l6#2.p" to "Quelle est la bonne façon d'apprendre l'auto-assurage ?",
    "q.l6#2.o0" to "Regarder une vidéo suffit",
    "q.l6#2.o1" to "Lire le manuel et mémoriser les points clés",
    "q.l6#2.o2" to "Répéter sur une pente de neige douce et sûre, assuré par un encadrant, jusqu'à ce que ce soit un réflexe",
    "q.l6#2.o3" to "L'apprendre en chutant une fois sur une vraie pente raide",
    "q.l6#2.e" to "L'auto-assurage est une compétence de niveau réflexe : il faut des centaines de répétitions en conditions contrôlées pour qu'elle devienne fiable. Entraînez-vous sur une pente douce avec une zone d'arrêt dégagée, de la neige douce et un encadrant à l'assurage.",

    "q.l6#3.p" to "Quelle est la façon la plus efficace d'appliquer la force lors d'un auto-assurage ?",
    "q.l6#3.o0" to "Appuyer fort avec les bras",
    "q.l6#3.o1" to "Plaquer la panne avec le poids du corps, à la verticale",
    "q.l6#3.o2" to "Traîner la hampe latéralement sur la neige",
    "q.l6#3.o3" to "Balayer rapidement la surface avec la panne",
    "q.l6#3.e" to "La force des bras lâche avec la fatigue et la panique ; seul le poids du corps enfonce la panne. C'est pourquoi la position — ventral, pieds levés — compte plus que la force brute.",

    "q.l6#4.p" to "Sur neige dure ou sur glace, quelle est l'efficacité d'un auto-assurage ?",
    "q.l6#4.o0" to "Meilleure — il s'arrête aussitôt",
    "q.l6#4.o1" to "La distance d'arrêt augmente beaucoup et il peut échouer complètement",
    "q.l6#4.o2" to "Identique à la neige douce",
    "q.l6#4.o3" to "Il se transforme automatiquement en glissade",
    "q.l6#4.e" to "La panne mord difficilement sur neige dure et sur glace. C'est pourquoi on ne s'engage pas sans protection sur une pente raide de neige dure — la technique ne remplace pas l'évitement, et connaître les limites d'une technique compte tout autant.",

    "q.l6#5.p" to "Lors d'un auto-assurage, comment les deux mains se répartissent-elles le travail ?",
    "q.l6#5.o0" to "Les deux mains sur la hampe",
    "q.l6#5.o1" to "Les deux mains sur la tête",
    "q.l6#5.o2" to "Une main sur la tête près de la panne pour la force vers le bas, l'autre sur la hampe pour la direction et la stabilité",
    "q.l6#5.o3" to "Une main suffit ; gardez l'autre libre",
    "q.l6#5.e" to "La main sur la tête transmet le poids du corps à la panne ; la main sur la hampe stabilise et corrige la direction. Avec des rôles clairs, l'auto-assurage est à la fois puissant et rectiligne.",

    "q.l6#6.p" to "[Ordre] Placez les étapes d'un auto-assurage dans le bon ordre.",
    "q.l6#6.o0" to "Saisir fermement le piolet et plaquer la tête sous le corps en prise d'auto-assurage",
    "q.l6#6.o1" to "Basculer sur le ventre, tête en amont et visage vers la neige",
    "q.l6#6.o2" to "Enfoncer la panne dans la neige et la glace avec le poids du corps, jambes écartées, genoux contre la surface",
    "q.l6#6.o3" to "Lever les deux pieds pour que les crampons n'accrochent pas et ne vous fassent pas basculer",
    "q.l6#6.e" to "L'étape la plus souvent oubliée est la dernière : lever les pieds. Dès qu'un pied touche la neige, il vole du poids au piolet, et les crampons peuvent soudain mordre et vous retourner — interrompant l'auto-assurage lui-même.",

    "q.l6#7.p" to "Pendant un auto-assurage, où doit se trouver la panne large (le côté plat de la tête) ?",
    "q.l6#7.o0" to "À l'extérieur du genou",
    "q.l6#7.o1" to "Dans le creux de l'épaule",
    "q.l6#7.o2" to "Au niveau de la hanche",
    "q.l6#7.o3" to "Loin sur le côté de la tête",
    "q.l6#7.e" to "Avec la panne large dans le creux de l'épaule, la hampe reste près de l'axe du corps et la charge se centre sous le tronc, là où la force vers le bas est la plus efficace. Plus loin, la charge se disperse, la panne dérive et la distance d'arrêt augmente nettement.",

    "q.l6#8.p" to "[Choix multiple] Qu'est-ce qui détermine principalement la réussite d'un auto-assurage ?",
    "q.l6#8.o0" to "L'angle de la neige ou de la glace",
    "q.l6#8.o1" to "La dureté de la neige ou de la glace",
    "q.l6#8.o2" to "La position de l'alpiniste qui chute",
    "q.l6#8.o3" to "La vitesse de réaction",
    "q.l6#8.o4" to "La marque et le prix du matériel",
    "q.l6#8.e" to "Les manuels sont francs : outre la vitesse de réaction, la réussite dépend de l'angle, de la dureté et de la position — « parfois même le geste le plus répété ne peut arrêter la chute ». Accepter cette limite rend évident pourquoi ne pas chuter compte plus que savoir s'arrêter.",

    "q.l6#9.p" to "Quelle est la position correcte des jambes et des genoux pendant l'auto-assurage ?",
    "q.l6#9.o0" to "Jambes jointes, genoux décollés",
    "q.l6#9.o1" to "Jambes écartées, genoux appuyés contre la neige et la glace",
    "q.l6#9.o2" to "Une jambe tendue, l'autre pliée",
    "q.l6#9.o3" to "Les deux jambes levées au-dessus de la neige",
    "q.l6#9.e" to "Les jambes écartées donnent la stabilité latérale et empêchent la rotation ; les genoux contre la surface ajoutent un point d'appui qui aide à garder le poids sur le piolet. Notez la différence : les genoux peuvent toucher légèrement, alors que les pieds — et les crampons — doivent se lever.",
    // ---------- l7 Glissades et auto-arrêt ----------
    "q.l7#0.p" to "Quel est le moyen le plus efficace d'éviter une glissade pendant la progression ?",
    "q.l7#0.o0" to "Marcher plus vite",
    "q.l7#0.o1" to "Utiliser le piolet en auto-assurage, en se donnant un point d'appui temporaire à chaque pas",
    "q.l7#0.o2" to "Ranger le piolet dans le sac",
    "q.l7#0.o3" to "Compter uniquement sur la corde",
    "q.l7#0.e" to "L'auto-assurage est la défense la plus directe pendant la progression : à chaque pas, la main qui tient le piolet plante le manche dans la neige et crée un troisième point d'appui. La grande majorité des glissades se produisent à l'instant précis où ce point d'appui manque.",

    "q.l7#1.p" to "Votre compagnon chute soudainement alors que vous progressez encordés. Que faites-vous en premier ?",
    "q.l7#1.o0" to "Descendre en courant pour le rattraper",
    "q.l7#1.o1" to "Passer immédiatement en position d'auto-arrêt et reprendre de la corde pour le retenir",
    "q.l7#1.o2" to "Se désencorder pour ne pas être entraîné",
    "q.l7#1.o3" to "Crier à l'aide et attendre",
    "q.l7#1.e" to "Une cordée fonctionne parce que vous vous retenez d'abord vous-même — la corde transmet ensuite l'arrêt. Descendre en courant ou se désencorder entraîne toute la cordée dans la glissade : c'est l'enchaînement classique des accidents de glacier.",

    "q.l7#2.p" to "À l'instant où vous perdez pied, quelle est la première action ?",
    "q.l7#2.o0" to "Réorganiser son matériel",
    "q.l7#2.o1" to "Crier un avertissement et se jeter immédiatement à plat ventre pour s'arrêter",
    "q.l7#2.o2" to "Estimer l'angle de la pente",
    "q.l7#2.o3" to "Regarder ce qu'il y a en dessous",
    "q.l7#2.e" to "Les deux premières secondes décident de l'issue. L'avertissement met vos compagnons en position de protection au moment même où vous vous jetez à plat ventre — ce basculement est l'action essentielle qui limite les dégâts.",

    "q.l7#3.p" to "Dans quel état la corde doit-elle être lorsqu'on progresse en cordée ?",
    "q.l7#3.o0" to "Aussi détendue que possible pour garder sa liberté de mouvement",
    "q.l7#3.o1" to "Modérément tendue, sans grandes boucles pendantes",
    "q.l7#3.o2" to "Complètement tendue",
    "q.l7#3.o3" to "Comme on se sent le plus à l'aise",
    "q.l7#3.e" to "Les grandes boucles font que la personne qui chute tombe d'abord librement avant que la corde ne se tende, ce qui multiplie l'impact et laisse la corde scier la neige. Une tension modérée permet à l'arrêt de s'engager plus tôt.",

    "q.l7#4.p" to "Pourquoi « ne pas glisser » est-il plus fondamental que « apprendre à s'arrêter » ?",
    "q.l7#4.o0" to "Parce que la technique d'arrêt est inutile",
    "q.l7#4.o1" to "Parce que l'arrêt peut échouer sur neige dure et en pente raide — ne pas perdre pied est la protection fiable",
    "q.l7#4.o2" to "Parce que s'arrêter est trop fatigant",
    "q.l7#4.o3" to "Parce que les formateurs interdisent de s'entraîner",
    "q.l7#4.e" to "L'auto-arrêt est indispensable, mais il a des limites évidentes. La stratégie fiable consiste à ne pas s'engager dans un terrain où l'on pourrait glisser sans protection. La technique est la dernière ligne de défense, pas la première.",

    "q.l7#5.p" to "Pendant l'arrêt, la pointe du piolet rebondit sur la neige dure et ne mord pas. Que faire ?",
    "q.l7#5.o0" to "La relever et frapper à nouveau",
    "q.l7#5.o1" to "Rester à plat ventre et continuer d'appuyer de tout son poids pour que la pointe morde peu à peu",
    "q.l7#5.o2" to "Traîner le manche latéralement sur la neige",
    "q.l7#5.o3" to "Renoncer à l'arrêt et protéger sa tête",
    "q.l7#5.e" to "Relever le piolet annule complètement l'arrêt et vous fait perdre la position d'appui que vous aviez construite. Restez à plat ventre et continuez d'appuyer : la pointe s'enfonce progressivement à mesure que vous glissez. L'arrêt est un processus progressif, pas un geste unique.",

    "q.l7#6.p" to "Pourquoi dit-on que l'arrêt sur glace est très difficile ?",
    "q.l7#6.o0" to "Parce que la glace est trop froide",
    "q.l7#6.o1" to "Parce que la pointe mord mal dans la glace : sur une pente de glace, on installe une corde fixe au lieu de compter sur l'arrêt",
    "q.l7#6.o2" to "Parce que le frottement sur la glace est trop élevé",
    "q.l7#6.o3" to "Parce que la glace casse facilement",
    "q.l7#6.e" to "L'arrêt repose sur la morsure de la pointe, et la glace est la surface la plus difficile à mordre. Les manuels répondent de façon systémique : sur une pente de glace, on installe une corde d'itinéraire ou on assure en alternance, et de façon générale on ne progresse pas encordés — on résout le problème par le système, pas par l'espoir mis dans la technique individuelle.",

    "q.l7#7.p" to "[Ordre] Votre compagnon chute alors que vous progressez encordés. Quelle est la séquence correcte ?",
    "q.l7#7.o0" to "Passer immédiatement en position d'auto-arrêt et se retenir",
    "q.l7#7.o1" to "Reprendre de la corde pour arrêter la chute",
    "q.l7#7.o2" to "Construire un ancrage indépendant (piquet à neige, piolet enfoui, etc.)",
    "q.l7#7.o3" to "Transférer la charge sur l'ancrage, puis commencer le sauvetage",
    "q.l7#7.e" to "Ces quatre étapes ne peuvent pas être réordonnées : il faut se retenir avant de pouvoir faire quoi que ce soit, et secourir sans ancrage met le poids des deux personnes sur vous. En réalité, ces étapes prennent des minutes : il faut donc les répéter à l'avance.",

    "q.l7#8.p" to "L'arrêt a fonctionné et la glissade est stoppée. Et ensuite ?",
    "q.l7#8.o0" to "Se relever et continuer",
    "q.l7#8.o1" to "Maintenir l'arrêt, construire une protection pas à pas et transférer son poids sur l'ancrage",
    "q.l7#8.o2" to "Dénouer la corde",
    "q.l7#8.o3" to "Vérifier si le matériel est abîmé",
    "q.l7#8.e" to "Une glissade stoppée n'est pas la sécurité : vous êtes encore en position non protégée et auriez du mal à arrêter une nouvelle chute. Maintenez l'arrêt pendant que vous construisez une protection fiable, libérez-vous, et seulement ensuite occupez-vous des blessures et de l'itinéraire.",

    "q.l7#9.p" to "[Choix multiple] Lesquels évitent efficacement les glissades ?",
    "q.l7#9.o0" to "S'auto-assurer au piolet en continu pendant la progression",
    "q.l7#9.o1" to "Installer une corde fixe sur neige dure ou pente de glace",
    "q.l7#9.o2" to "Tenir une allure régulière et soutenue, en évitant les efforts brusques qui cassent l'équilibre",
    "q.l7#9.o3" to "Progresser au rythme du plus lent pour que la cordée ne s'étire pas",
    "q.l7#9.o4" to "Accélérer pour réduire l'exposition",
    "q.l7#9.e" to "Ces quatre points agissent à des niveaux différents : technique personnelle, protection du système, gestion de l'allure et cohésion de la cordée. La prévention des glissades n'est jamais une action unique — c'est l'ensemble de ces couches à la fois.",

    // ---------- l8 Descente ----------
    "q.l8#0.p" to "Pourquoi les accidents sont-ils plus fréquents à la descente ?",
    "q.l8#0.o0" to "Parce que le terrain descendant est plus dur",
    "q.l8#0.o1" to "Parce que la fatigue dégrade l'attention et la qualité du mouvement",
    "q.l8#0.o2" to "Parce que le temps est toujours plus mauvais à la descente",
    "q.l8#0.o3" to "Parce que le matériel lâche",
    "q.l8#0.e" to "Une fois le sommet atteint, la vigilance baisse alors que le corps est déjà presque à vide. Une grande part des accidents d'alpinisme survient à la descente — d'où le dicton selon lequel le sommet n'est que la moitié du chemin.",

    "q.l8#1.p" to "Dans quelles conditions pouvez-vous glisser volontairement sur la neige ?",
    "q.l8#1.o0" to "Dès que la pente est assez raide",
    "q.l8#1.o1" to "Pas de crevasse, pas de risque de chutes de pierres, un dégagement net en dessous, et la capacité de s'arrêter à tout moment",
    "q.l8#1.o2" to "Sur n'importe quelle pente de neige",
    "q.l8#1.o3" to "Dès que vos compagnons sont d'accord",
    "q.l8#1.e" to "Une glissade volontaire est une accélération irréversible — une fois lancée, il est difficile de s'arrêter. Il faut exclure les crevasses, les chutes de pierres et toute personne en dessous, et être sûr de pouvoir basculer en arrêt à n'importe quel point. Sinon, on descend proprement.",

    "q.l8#2.p" to "Quelle est la manière préférée de descendre un terrain technique ?",
    "q.l8#2.o0" to "Descendre face à la pente, en gardant trois points d'appui",
    "q.l8#2.o1" to "Descendre en courant, face au vide",
    "q.l8#2.o2" to "Glisser volontairement",
    "q.l8#2.o3" to "S'asseoir et glisser",
    "q.l8#2.e" to "Faire face à la pente permet de voir ses appuis, garde le centre de gravité près de la surface et laisse les deux mains libres pour s'aider. Faire face au vide cache les appuis — une erreur très courante.",

    "q.l8#3.p" to "Quelle est l'erreur la plus dangereuse et la plus fréquente à la descente ?",
    "q.l8#3.o0" to "Faire face à la pente et descendre sur trois points",
    "q.l8#3.o1" to "Se pencher en avant et descendre face au vide",
    "q.l8#3.o2" to "Garder un rythme régulier",
    "q.l8#3.o3" to "S'auto-assurer au piolet",
    "q.l8#3.e" to "Face au vide, on ne voit pas ses appuis, et se pencher en avant rend encore plus instable. Ajoutez la fatigue qui réduit le contrôle des jambes, et vous avez la vraie raison pour laquelle les descentes sont si propices aux accidents.",

    "q.l8#4.p" to "Que faut-il faire avant d'amorcer une glissade volontaire ?",
    "q.l8#4.o0" to "Ranger le piolet dans le sac",
    "q.l8#4.o1" to "Vérifier que personne n'est en dessous, qu'il n'y a ni crevasse ni chute de pierres sur la ligne, et garder le piolet prêt à freiner",
    "q.l8#4.o2" to "Serrer les sangles du sac",
    "q.l8#4.o3" to "Prévenir sa famille de l'itinéraire",
    "q.l8#4.e" to "Une glissade est une accélération irréversible. Avant de partir, il faut exclure toute personne en dessous, les crevasses et les chutes de pierres, et garder le piolet en main — sinon, en cas de problème, vous n'avez aucun moyen de ralentir.",

    "q.l8#5.p" to "Comment gérer la fatigue de la cordée sur une longue descente ?",
    "q.l8#5.o0" to "Marcher d'une traite en faisant le moins de pauses possible",
    "q.l8#5.o1" to "Faire de courtes pauses planifiées, boire et manger, et réévaluer l'état de la cordée",
    "q.l8#5.o2" to "Accélérer pour réduire l'exposition",
    "q.l8#5.o3" to "Ne s'arrêter qu'en cas de blessure",
    "q.l8#5.e" to "La descente est la moitié à risque, et la fatigue en est le moteur principal. Des pauses courtes et régulières restaurent l'énergie et permettent de relire le temps, l'itinéraire et l'état de ses compagnons — des jugements qui sont la première chose à disparaître dans un long effort.",

    "q.l8#6.p" to "[Ordre] Remettez dans un ordre logique les étapes de préparation d'une descente.",
    "q.l8#6.o0" to "Confirmer la ligne de descente et le point d'arrivée, et dégager les personnes en dessous",
    "q.l8#6.o1" to "Vérifier que corde, dispositif d'assurage, mousquetons et sangles sont bien là",
    "q.l8#6.o2" to "Construire un ancrage fiable, ou confirmer le relais existant",
    "q.l8#6.o3" to "Préparer la corde pour éviter nœuds et emmêlements, puis commencer la descente",
    "q.l8#6.e" to "Une descente confie votre vie à un point unique : l'ordre est donc de décider où l'on va, de confirmer le matériel, puis de s'engager. Préparer la corde compte tout autant — un nœud ou un emmêlement vous laisse bloqué longtemps suspendu à la corde.",

    "q.l8#7.p" to "Qu'est-ce qui décide principalement entre rappel et descente en escalade ?",
    "q.l8#7.o0" to "Plus la descente est courte, plus il faut rappeler",
    "q.l8#7.o1" to "La difficulté du terrain, la fiabilité des ancrages et le niveau de la cordée",
    "q.l8#7.o2" to "La météo",
    "q.l8#7.o3" to "La nouveauté du matériel",
    "q.l8#7.e" to "Le rappel est rapide mais dépend des ancrages et de l'exécution ; la descente en escalade est plus lente mais autonome. Terrain, fiabilité des ancrages et compétence de la cordée décident ensemble. Rappelons que le rappel a un taux d'accident élevé parce que la marge d'erreur de l'opérateur y est très faible.",

    "q.l8#8.p" to "Quel matériel technique un rappel demande-t-il normalement ?",
    "q.l8#8.o0" to "Un mousqueton et une sangle",
    "q.l8#8.o1" to "Plusieurs mousquetons, une longue sangle ou une longe personnelle, de la cordelette de prussik, etc.",
    "q.l8#8.o2" to "Juste une corde",
    "q.l8#8.o3" to "Juste un dispositif d'assurage",
    "q.l8#8.e" to "Les manuels citent plusieurs mousquetons, une longue sangle ou une daisy, et de la cordelette de prussik. Une descente implique souvent de démonter les ancrages au fur et à mesure tout en gardant une sécurité : trop peu de matériel oblige à improviser en hauteur, exactement là où naissent les accidents.",

    "q.l8#9.p" to "[Choix multiple] Quels sont les principaux risques à la descente ?",
    "q.l8#9.o0" to "Rupture d'ancrage",
    "q.l8#9.o1" to "Sortir de la corde parce que les extrémités n'étaient pas nouées",
    "q.l8#9.o2" to "Corde coincée ou emmêlée",
    "q.l8#9.o3" to "Chutes de pierres et personnes en dessous",
    "q.l8#9.o4" to "La descente est moins risquée que la montée car la gravité aide",
    "q.l8#9.e" to "Les quatre premiers sont les causes habituelles des accidents de rappel. La plus négligée est l'extrémité de corde non nouée : si la corde est trop courte et que les bouts sont libres, on sort de la corde sans s'en apercevoir et on chute. Cette erreur est particulièrement fréquente lors d'une descente fatiguée.",

    // ---------- l9 Nœuds ----------
    "q.l9#0.p" to "Quel nœud relie la corde au baudrier et constitue le choix habituel sur les itinéraires glaciaires ?",
    "q.l9#0.o0" to "Nœud de huit réenfilé",
    "q.l9#0.o1" to "Nœud plat",
    "q.l9#0.o2" to "Nœud simple",
    "q.l9#0.o3" to "Nœud de chaise",
    "q.l9#0.e" to "Le huit réenfilé est solide, facile à lire et à faire vérifier par les autres, et se défait encore après avoir été chargé. Un nœud plat peut glisser ou se coincer sous charge et ne doit jamais servir à une liaison vitale.",

    "q.l9#1.p" to "Quel nœud permet d'ajuster la longueur d'une seule main pour fixer la corde à un mousqueton ?",
    "q.l9#1.o0" to "Pêcheur double",
    "q.l9#1.o1" to "Demi-cabestan",
    "q.l9#1.o2" to "Nœud de papillon",
    "q.l9#1.o3" to "Nœud de sangle",
    "q.l9#1.e" to "Le demi-cabestan se règle en poussant et tirant sur un mousqueton d'une seule main : c'est la façon standard de s'auto-assurer au relais. Le pêcheur double relie deux cordes ; le papillon crée un point d'attache au milieu de la corde.",

    "q.l9#2.p" to "Quelle est la propriété essentielle d'un nœud autobloquant comme le prussik ?",
    "q.l9#2.o0" to "Il serre la corde sous charge et coulisse le long de la corde lorsqu'il n'est pas chargé",
    "q.l9#2.o1" to "Il peut remplacer définitivement la corde principale",
    "q.l9#2.o2" to "Il est purement décoratif",
    "q.l9#2.o3" to "Il se dénoue tout seul sous charge",
    "q.l9#2.e" to "C'est ce serrage à sens unique qui rend les nœuds autobloquants utiles pour remonter, pour les sécurités et dans les systèmes de mouflage. Et comme la fiabilité dépend du diamètre cordelette/corde et du nombre de tours, il faut l'essayer sur le terrain avant de lui faire confiance.",

    "q.l9#3.p" to "Quelle longueur de bout libre doit-on laisser après avoir terminé un nœud ?",
    "q.l9#3.o0" to "Environ 1 cm suffit",
    "q.l9#3.o1" to "Au moins dix diamètres de corde",
    "q.l9#3.o2" to "Aucun bout libre n'est nécessaire",
    "q.l9#3.o3" to "Le plus long possible — au moins 1 m",
    "q.l9#3.e" to "Un bout libre suffisant est la sécurité de base contre le glissement du nœud sous charge ou son desserrage par secousses. Prenez aussi l'habitude de vous contrôler mutuellement : les nœuds sont la seule partie du système de protection entièrement faite à la main, sans contrôle d'usine.",

    "q.l9#4.p" to "Quel nœud relie deux cordes ou ferme une boucle de cordelette ?",
    "q.l9#4.o0" to "Nœud plat",
    "q.l9#4.o1" to "Pêcheur double",
    "q.l9#4.o2" to "Nœud simple",
    "q.l9#4.o3" to "Nœud de chaise",
    "q.l9#4.e" to "Le pêcheur double est extrêmement stable et se desserre très peu, mais il est difficile à défaire après charge — ce qui convient pour relier des cordes et fermer des boucles de cordelette. Un nœud plat peut glisser sous charge et ne doit jamais porter.",

    "q.l9#5.p" to "Pourquoi la fiabilité d'un nœud autobloquant dépend-elle du diamètre de la cordelette ?",
    "q.l9#5.o0" to "Le diamètre ne change rien",
    "q.l9#5.o1" to "Si la cordelette est beaucoup plus fine que la corde, la surface de contact et la force de serrage sont trop faibles pour mordre",
    "q.l9#5.o2" to "Plus la cordelette est fine, mieux elle mord",
    "q.l9#5.o3" to "Plus la cordelette est épaisse, mieux elle mord",
    "q.l9#5.e" to "Un nœud autobloquant mord en serrant la corde principale. Trop fin, la surface de contact et la force de serrage sont insuffisantes ; trop épais, il ne s'enroule pas étroitement. Vérifiez donc la combinaison à chaque fois, et testez-la en sécurité avant de compter dessus.",

    "q.l9#6.p" to "À quoi sert principalement le nœud de papillon alpin ?",
    "q.l9#6.o0" to "Relier deux cordes",
    "q.l9#6.o1" to "Créer une boucle fixe au milieu de la corde, pouvant être chargée dans plusieurs directions",
    "q.l9#6.o2" to "Remplacer le huit comme nœud d'encordement",
    "q.l9#6.o3" to "Fabriquer une boucle de prussik",
    "q.l9#6.e" to "Le papillon forme une boucle au milieu de la corde qui tient la charge dans les deux sens, d'où sa présence dans les cordées, la progression glaciaire et les systèmes de sauvetage. On le noue aussi entre les alpinistes pour ajouter du frottement là où la corde frotte la neige.",

    "q.l9#7.p" to "[Association] Associez chaque nœud à son usage principal.",
    "q.l9#7.l0" to "Nœud de huit",
    "q.l9#7.r0" to "Encordement habituel sur un ancrage ou un baudrier",
    "q.l9#7.l1" to "Pêcheur double",
    "q.l9#7.r1" to "Relier deux cordes, ou fermer une boucle de cordelette",
    "q.l9#7.l2" to "Nœud autobloquant (prussik)",
    "q.l9#7.r2" to "Nœud de friction : serre sous charge, coulisse à vide",
    "q.l9#7.l3" to "Nœud de chaise",
    "q.l9#7.r3" to "S'attacher à un ancrage ; courant aussi pour amarrer un bateau",
    "q.l9#7.e" to "Ces quatre nœuds couvrent l'essentiel de la progression glaciaire et de la protection de base. Les manuels les classent par fonction — s'attacher à un ancrage, relier des cordes, nœud de friction. Les apprendre par fonction reste bien mieux en mémoire que par forme.",

    "q.l9#8.p" to "Quelle affirmation sur les nœuds et la résistance de la corde est correcte ?",
    "q.l9#8.o0" to "Les nœuds n'affectent pas la résistance de la corde",
    "q.l9#8.o1" to "Chaque nœud réduit la résistance de la corde à cet endroit, dans des proportions variables",
    "q.l9#8.o2" to "Les nœuds rendent la corde plus solide",
    "q.l9#8.o3" to "Un nœud bien fait n'a aucun effet sur la résistance",
    "q.l9#8.e" to "À l'endroit d'un nœud, la corde se courbe et, sous charge, les fibres travaillent inégalement : la résistance baisse toujours — seule l'ampleur varie. C'est pourquoi les manuels publient un tableau des pertes de résistance par nœud : choisissez un nœud pour son fonctionnement et pour ce qu'il coûte en résistance.",

    "q.l9#9.p" to "Le manuel résume l'utilité des nœuds en une phrase : « Un nœud donne ( ) à la corde. »",
    "q.l9#9.a0" to "vie",
    "q.l9#9.a1" to "la vie",
    "q.l9#9.e" to "Le texte original dit « un nœud donne vie à la corde ». Cela résume l'essentiel : une corde seule n'est qu'un bout de ligne, et c'est par les nœuds — qui la relient à la protection, aux ancrages et aux autres cordes — qu'elle devient un système capable de porter une vie.",

    // ---------- l10 Cordée sur glacier ----------
    "q.l10#0.p" to "Quelle est la taille idéale d'une cordée sur glacier ?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 ou plus",
    "q.l10#0.o3" to "Une personne seule",
    "q.l10#0.e" to "Une cordée de trois dispose d'assez de personnes pour construire un ancrage et monter un système de sauvetage quand l'un tombe dans une crevasse. À deux, si l'un tombe, l'autre doit arrêter la chute, construire l'ancrage et hisser en même temps — presque aucune marge.",

    "q.l10#1.p" to "Quel espacement de corde est habituel pour la progression sur glacier ?",
    "q.l10#1.o0" to "2–3 m",
    "q.l10#1.o1" to "8–12 m",
    "q.l10#1.o2" to "Plus de 30 m",
    "q.l10#1.o3" to "Le plus court possible",
    "q.l10#1.e" to "8 à 12 m laissent aux compagnons le temps et la distance de réagir et de s'arrêter, tout en permettant de communiquer et de coopérer. Trop court, il ne reste presque plus de corde pour absorber l'impact.",

    "q.l10#2.p" to "De quoi une cordée a-t-elle besoin avant d'apporter réellement une protection ?",
    "q.l10#2.o0" to "Il suffit d'être encordé pour être en sécurité",
    "q.l10#2.o1" to "De compagnons capables de s'arrêter efficacement et de construire une protection",
    "q.l10#2.o2" to "D'une corde assez longue",
    "q.l10#2.o3" to "D'une cordée assez nombreuse",
    "q.l10#2.e" to "La sécurité d'une cordée vient de deux actions exécutées de façon fiable : l'arrêt et l'ancrage. Une cordée sans compétence d'arrêt ni technique d'ancrage, c'est simplement plusieurs personnes attachées ensemble qui tombent dans le même trou.",

    "q.l10#3.p" to "Pourquoi nouer des nœuds (comme le papillon) entre les alpinistes sur un glacier ?",
    "q.l10#3.o0" to "Purement décoratif",
    "q.l10#3.o1" to "Pour ajouter du frottement là où la corde passe sur la neige et limiter la distance de chute",
    "q.l10#3.o2" to "Pour reconnaître ses compagnons",
    "q.l10#3.o3" to "Pour alléger la corde",
    "q.l10#3.e" to "Chaque nœud crée un point de frottement supplémentaire sur la surface neigeuse, ce qui raccourcit nettement la chute et donne aux compagnons du dessus le temps de construire une protection. C'est un frein très bon marché et très efficace.",

    "q.l10#4.p" to "Où doit-on porter le matériel de sauvetage pendant la progression sur glacier ?",
    "q.l10#4.o0" to "Au fond du sac",
    "q.l10#4.o1" to "À portée de main, prêt à servir à tout instant",
    "q.l10#4.o2" to "Laissé sous la tente au camp",
    "q.l10#4.o3" to "Confier à un compagnon",
    "q.l10#4.e" to "La fenêtre d'or d'un sauvetage en crevasse se compte en minutes. Si les cordelettes de prussik, les mousquetons et les piquets sont enfouis au fond du sac, le temps de les sortir votre compagnon peut être en hypothermie ou la corde avoir scié la lèvre.",

    "q.l10#5.p" to "Quel est le principal risque d'une cordée de deux par rapport à trois ?",
    "q.l10#5.o0" to "Elle avance plus lentement",
    "q.l10#5.o1" to "Si l'un tombe, la personne restante ne peut pas à la fois tenir l'arrêt et conduire le sauvetage",
    "q.l10#5.o2" to "La corde n'est pas assez longue",
    "q.l10#5.o3" to "Il faut porter plus de matériel",
    "q.l10#5.e" to "À deux, si l'un tombe dans une crevasse, l'autre doit tenir l'arrêt, construire un ancrage et manœuvrer un système de hissage en même temps — presque aucune marge. Si vous devez progresser à deux, choisissez un itinéraire plus prudent et anticipez davantage.",

    "q.l10#6.p" to "Pourquoi ne faut-il pas se désencorder à volonté pendant la progression sur glacier ?",
    "q.l10#6.o0" to "Parce que se désencorder et se réencorder est pénible",
    "q.l10#6.o1" to "Parce que le risque en terrain crevassé est continu — dès l'instant où l'on se désencorde, on n'a plus de protection",
    "q.l10#6.o2" to "Parce que la corde pourrait être perdue",
    "q.l10#6.o3" to "Parce que les compagnons vont râler",
    "q.l10#6.e" to "Le risque sur un glacier est inégalement réparti et difficile à prévoir, et on se désencorde généralement sur le faux jugement que « ce passage est tranquille ». S'il faut vraiment se désencorder, arrêtez-vous d'abord, confirmez le terrain et la neige, puis agissez en cordée.",

    "q.l10#7.p" to "[Association] Associez les consignes internationales de cordée à leur signification.",
    "q.l10#7.l0" to "Assure !",
    "q.l10#7.r0" to "L'assurage est prêt, tu peux partir",
    "q.l10#7.l1" to "Je pars",
    "q.l10#7.r1" to "Je commence à grimper",
    "q.l10#7.l2" to "Je tombe",
    "q.l10#7.r2" to "Je chute (avertissement)",
    "q.l10#7.l3" to "Désassure",
    "q.l10#7.r3" to "Assurage relâché, la protection est terminée",
    "q.l10#7.e" to "Le système de consignes fonctionne parce qu'il n'a pas besoin d'explication. Le vent est fort et les distances grandes en altitude : des mots courts au sens identique de chaque côté suppriment l'ambiguïté. Le moment le plus dangereux à l'assurage est celui où chacun suppose que l'autre sait. Les manuels listent les consignes internationales parce qu'elles sont l'accord minimum entre cordées et entre langues.",

    "q.l10#8.p" to "De quel équipement technique de base un assureur a-t-il besoin ?",
    "q.l10#8.o0" to "Un baudrier, un mousqueton, un dispositif d'assurage, une paire de gants, un casque",
    "q.l10#8.o1" to "Juste un dispositif d'assurage et un mousqueton",
    "q.l10#8.o2" to "Un casque et des lunettes de soleil",
    "q.l10#8.o3" to "Un baudrier et une corde",
    "q.l10#8.e" to "La liste paraît simple, mais chaque élément manquant a une conséquence concrète : sans gants, on se brûle les mains et le contrôle de la corde se dégrade ; sans casque, on n'a aucune réponse aux chutes de pierres. L'assureur est celui qui rattrape les autres : son propre équipement doit donc être complet en premier.",

    "q.l10#9.p" to "Pourquoi faire un contrôle mutuel avant de commencer à grimper ?",
    "q.l10#9.o0" to "Parce que la discipline de cordée l'exige",
    "q.l10#9.o1" to "Parce que les erreurs de baudrier, de nœud et de dispositif d'assurage sont souvent invisibles pour celui qui les porte",
    "q.l10#9.o2" to "Pour enregistrer la progression",
    "q.l10#9.o3" to "Pour s'échauffer",
    "q.l10#9.e" to "En se contrôlant soi-même, on voit ce que l'on croit avoir noué. Un compagnon voit de derrière et de côté, dans les endroits que vous ne voyez pas. Les manuels placent le contrôle mutuel en tête de la communication d'assurage : il utilise les yeux d'un autre pour couvrir votre angle mort.",
    // ---------- l11 Principes de l'ancrage ----------
    "q.l11#0.p" to "Dans les principes SRENE, que signifie le R ?",
    "q.l11#0.o0" to "Rapide",
    "q.l11#0.o1" to "Redondant",
    "q.l11#0.o2" to "Corde",
    "q.l11#0.o3" to "Rigide",
    "q.l11#0.e" to "Redondant signifie que le système comporte plusieurs points de protection indépendants : si l'un lâche, les autres portent encore la charge. C'est l'élément le plus important de la sécurité d'un ancrage.",

    "q.l11#1.p" to "Que signifie le principe « pas d'extension » (No Extension) ?",
    "q.l11#1.o0" to "Plus la corde est longue, mieux c'est",
    "q.l11#1.o1" to "Si un point lâche, le système ne doit pas s'allonger et choquer les autres points",
    "q.l11#1.o2" to "Il ne faut pas construire les ancrages trop bas",
    "q.l11#1.o3" to "Aucun matériel de rechange n'est nécessaire",
    "q.l11#1.e" to "S'il y a du mou entre les points, une rupture fait tomber la charge sur les points restants comme un choc soudain, bien supérieur à la charge statique. « Pas d'extension » signifie égaliser et pré-tendre pour que ce choc n'entre jamais dans le système.",

    "q.l11#2.p" to "Quelle est l'idée centrale du dimensionnement d'un ancrage ?",
    "q.l11#2.o0" to "Utiliser le moins de matériel possible",
    "q.l11#2.o1" to "La rupture d'un seul point ne doit pas faire s'effondrer tout le système",
    "q.l11#2.o2" to "Construire le plus haut possible",
    "q.l11#2.o3" to "N'utiliser que la corde la plus épaisse",
    "q.l11#2.e" to "Un ancrage sur rocher ou sur neige n'est jamais absolument certain : le système est donc conçu pour tolérer l'erreur. Aucune rupture unique n'est fatale, ce qui donne à l'alpiniste le temps de réagir et une sécurité de repli.",

    "q.l11#3.p" to "Quelles deux dimensions EARNEST ajoute-t-il à SRENE ?",
    "q.l11#3.o0" to "Efficace et rapide (Efficient, Timely)",
    "q.l11#3.o1" to "Facile et serré (Easy, Tight)",
    "q.l11#3.o2" to "Égal et agréable (Equal, Nice)",
    "q.l11#3.o3" to "Vide et vrai (Empty, True)",
    "q.l11#3.e" to "Un ancrage ne doit pas seulement être sûr : il doit se construire vite et se manipuler simplement — car le temps passé à le construire est du temps d'exposition. C'est exactement là qu'EARNEST colle au terrain réel mieux que SRENE.",

    "q.l11#4.p" to "De quoi dépend principalement la fiabilité d'un ancrage sur neige ?",
    "q.l11#4.o0" to "De la marque du matériel",
    "q.l11#4.o1" to "De la qualité de la neige et de la qualité de l'enterrement",
    "q.l11#4.o2" to "De la couleur de la corde",
    "q.l11#4.o3" to "De l'altitude",
    "q.l11#4.e" to "Le même piquet ou le même ancrage enterré tient des charges très différentes en neige profonde, en neige humide et au bord d'un pont de neige. Un ancrage sur neige exige de lire le manteau sur place — une procédure figée ne suffit pas.",

    "q.l11#5.p" to "Pourquoi un ancrage doit-il être égalisé ?",
    "q.l11#5.o0" to "Pour que l'ancrage soit esthétique",
    "q.l11#5.o1" to "Pour que la charge se répartisse entre les points comme prévu et qu'aucun point ne soit surchargé",
    "q.l11#5.o2" to "Pour économiser du matériel",
    "q.l11#5.o3" to "Pour faciliter le démontage",
    "q.l11#5.e" to "Égaliser signifie que chaque point porte une charge proche de sa charge de calcul, au lieu qu'un seul prenne tout. Si un point atteint sa limite et lâche, la charge saute brusquement sur les autres et peut déclencher une rupture en chaîne.",

    "q.l11#6.p" to "Lequel de ces cas viole le principe de redondance ?",
    "q.l11#6.o0" to "Utiliser des pièces de résistances différentes",
    "q.l11#6.o1" to "Deux points de protection qui dépendent en fait de la même fissure ou du même bloc",
    "q.l11#6.o2" to "Relier les points avec des sangles",
    "q.l11#6.o3" to "Placer trois points de protection",
    "q.l11#6.e" to "La redondance exige que chaque point puisse lâcher indépendamment. Si deux points partagent une même fissure, l'ouverture de celle-ci les emporte tous les deux d'un coup — cela ressemble à deux points, mais fonctionne comme un seul. Cette fausse redondance est courante et mortelle.",

    "q.l11#7.p" to "[Association] Associez chaque terme d'évaluation d'un ancrage à sa signification.",
    "q.l11#7.l0" to "S (Solide)",
    "q.l11#7.r0" to "Fort : chaque point peut porter la charge attendue",
    "q.l11#7.l1" to "R (Redondant)",
    "q.l11#7.r1" to "Redondant : plusieurs points de protection indépendants",
    "q.l11#7.l2" to "E (Égalisé)",
    "q.l11#7.r2" to "Égalisé : charge répartie de façon sensée entre les points",
    "q.l11#7.l3" to "Pas d'extension",
    "q.l11#7.r3" to "Pas d'extension : une rupture ne crée pas d'allongement choquant",
    "q.l11#7.e" to "Ces quatre termes forment le cadre de base, abrégé SRENE. L'ordre vaut la peine d'être retenu : demandez d'abord si chaque point est solide, puis si le système est redondant — si un seul point n'est pas fiable, discuter de redondance n'a aucun sens.",

    "q.l11#8.p" to "D'après les valeurs de charge, quel angle entre les brins de sangle faut-il viser ?",
    "q.l11#8.o0" to "Moins de 60°",
    "q.l11#8.o1" to "Moins de 90°",
    "q.l11#8.o2" to "Moins de 120°",
    "q.l11#8.o3" to "L'angle n'influence pas la charge",
    "q.l11#8.e" to "À 0°, chaque point porte environ 50 % ; à 60°, environ 58 % ; à 90°, environ 71 % — plus l'angle est ouvert, plus le poids d'une personne charge chaque point. La règle empirique « rester sous 60° » découle directement de ces chiffres.",

    "q.l11#9.p" to "Pourquoi l'efficacité et la rapidité font-elles partie de l'évaluation d'un ancrage ?",
    "q.l11#9.o0" to "Pour que le travail paraisse plus beau",
    "q.l11#9.o1" to "Parce que construire l'ancrage est en soi du temps d'exposition au risque",
    "q.l11#9.o2" to "Pour économiser du matériel",
    "q.l11#9.o3" to "Pour faciliter l'enseignement",
    "q.l11#9.e" to "Pendant la construction d'un ancrage, on est souvent non protégé ou mal protégé. Plus cette exposition est courte, plus le risque est faible — « vite construit, simple à manipuler » n'est donc pas de la paresse, c'est une composante de la sécurité.",

    "q.l11#10.p" to "[Choix multiple] À quoi ressemble un ancrage correct ?",
    "q.l11#10.o0" to "Chaque point de protection est solide en lui-même",
    "q.l11#10.o1" to "Les points lâchent indépendamment les uns des autres",
    "q.l11#10.o2" to "La charge est répartie de façon sensée entre les points",
    "q.l11#10.o3" to "On laisse du mou dans le système pour absorber le choc",
    "q.l11#10.e" to "Les trois premiers sont des exigences ; le dernier est l'inverse. Un ancrage doit être sans extension, pas avec du mou de réserve — le mou fait qu'un point qui lâche choque les autres, et les charges de choc sont bien supérieures aux charges statiques.",

    "q.l11#11.p" to "Si les conditions n'autorisent qu'un seul point de protection, quelle est la bonne attitude ?",
    "q.l11#11.o0" to "Renoncer à la course et redescendre par où l'on est venu",
    "q.l11#11.o1" to "Le rendre aussi fiable que possible et réduire au minimum le temps que le système passe dessus",
    "q.l11#11.o2" to "Ajouter n'importe quel second point, pour en avoir deux",
    "q.l11#11.o3" to "Attacher directement la corde au baudrier",
    "q.l11#11.e" to "Les situations à point unique existent réellement — une bonne broche à glace, par exemple. L'attitude honnête est d'admettre l'absence de marge : rendre ce point aussi bon que possible et faire passer les personnes vite, plutôt que d'ajouter un second point inutile qui fabrique une fausse confiance.",

    // ---------- l12 Sauvetage en crevasse ----------
    "q.l12#0.p" to "Votre compagnon tombe dans une crevasse. Quelle est la première étape ?",
    "q.l12#0.o0" to "Sauter après lui",
    "q.l12#0.o1" to "Passer en auto-arrêt, construire un ancrage et transférer la charge dessus",
    "q.l12#0.o2" to "Appeler d'abord à l'aide",
    "q.l12#0.o3" to "Couper la corde",
    "q.l12#0.e" to "Tout le poids de la personne qui a chuté pèse sur vous à cet instant. Arrêtez d'abord pour vous retenir, puis construisez un ancrage indépendant et transférez la charge — c'est seulement alors que vous avez les mains libres pour le système de sauvetage. Sauter ou couper la corde aggrave immédiatement la situation.",

    "q.l12#1.p" to "Quel est le système de mouflage le plus courant pour le hissage de sauvetage ?",
    "q.l12#1.o0" to "Traction directe 1:1",
    "q.l12#1.o1" to "Le système en Z 3:1 (Z-poulie)",
    "q.l12#1.o2" to "Un système 10:1",
    "q.l12#1.o3" to "Aucun mouflage n'est nécessaire",
    "q.l12#1.e" to "Le système en Z 3:1 utilise un prussik et une poulie pour obtenir trois fois la force. Il est simple, rapide à monter et demande peu de matériel : c'est pour cela qu'il est la référence du sauvetage en crevasse.",

    "q.l12#2.p" to "Pourquoi les ponts de neige sont-ils particulièrement dangereux ?",
    "q.l12#2.o0" to "Parce qu'ils font toujours du bruit",
    "q.l12#2.o1" to "Parce que, couverts de neige fraîche, ils ressemblent à un sol ordinaire et sont difficiles à identifier",
    "q.l12#2.o2" to "Parce qu'ils n'apparaissent que la nuit",
    "q.l12#2.o3" to "Parce qu'ils sont toujours minces",
    "q.l12#2.e" to "Un pont de neige est le danger le plus dissimulé du glacier : la surface paraît lisse et épaisse alors que le vide est en dessous. Le juger impose de lire les lignes de fissure, la structure du manteau et la saison — c'est précisément pourquoi on progresse encordés.",

    "q.l12#3.p" to "Dans quel état la corde doit-elle être pour traverser un terrain crevassé ?",
    "q.l12#3.o0" to "Complètement détendue pour garder sa liberté de mouvement",
    "q.l12#3.o1" to "Modérément tendue, sans grandes boucles pendantes",
    "q.l12#3.o2" to "Aussi tendue que possible",
    "q.l12#3.o3" to "L'encordement est inutile",
    "q.l12#3.e" to "Le mou laisse la personne qui chute tomber librement avant que la corde ne se charge, ce qui multiplie l'impact et augmente le risque que la corde scie la lèvre. Une tension modérée engage l'arrêt plus tôt et réduit ce risque.",

    "q.l12#4.p" to "Quelle est la manière la plus sûre de traverser un pont de neige ?",
    "q.l12#4.o0" to "Traverser seul en courant, vite",
    "q.l12#4.o1" to "Progresser encordés avec la corde tendue, une personne qui traverse pendant que les autres se tiennent prêts à arrêter",
    "q.l12#4.o2" to "Éviter systématiquement tous les ponts de neige",
    "q.l12#4.o3" to "Taper fort pour tester, puis traverser",
    "q.l12#4.e" to "On ne peut pas juger un pont de neige à l'œil. S'encorder et se tenir prêt à arrêter transforme l'incertitude en risque géré. Taper fort pour tester peut simplement le faire s'effondrer sous vous.",

    "q.l12#5.p" to "Pendant qu'un compagnon pend à la corde dans une crevasse, quel est le plus grand danger ?",
    "q.l12#5.o0" to "Que votre compagnon s'endorme au fond",
    "q.l12#5.o1" to "Que la corde chargée scie la lèvre de neige jusqu'à ce qu'elle cède soudainement",
    "q.l12#5.o2" to "Que du matériel tombe",
    "q.l12#5.o3" to "Un changement brusque de météo",
    "q.l12#5.e" to "Une corde chargée va et vient sur la lèvre et creuse une gorge de plus en plus profonde. C'est la principale source de pression temporelle dans un sauvetage — il faut hisser ou transférer la charge sur un ancrage sain avant que la lèvre ne soit sciée.",

    "q.l12#6.p" to "Lorsqu'on monte un système en Z avec des prussiks, pourquoi une sécurité est-elle nécessaire ?",
    "q.l12#6.o0" to "Pour que le système paraisse complet",
    "q.l12#6.o1" to "Si le prussik principal lâche, on perd instantanément le mouflage et la personne retombe",
    "q.l12#6.o2" to "Pour ajouter du frottement",
    "q.l12#6.o3" to "Pour économiser de la corde",
    "q.l12#6.e" to "Un prussik mord par frottement, et la glace, la saleté ou l'usure de la corde peuvent le mettre en échec. Un prussik de sécurité rattrape la charge si le principal lâche, évitant une seconde chute et les blessures et retards supplémentaires qu'elle entraîne.",

    "q.l12#7.p" to "[Ordre] Remettez dans l'ordre la séquence standard de sauvetage en crevasse.",
    "q.l12#7.o0" to "S'arrêter immédiatement en auto-arrêt et se retenir",
    "q.l12#7.o1" to "Construire un ancrage indépendant",
    "q.l12#7.o2" to "Transférer le poids de son corps sur l'ancrage",
    "q.l12#7.o3" to "Hisser avec un système de mouflage 3:1",
    "q.l12#7.e" to "Ces quatre étapes ne peuvent pas être réordonnées. La troisième est celle que l'on saute le plus souvent : sans transfert de charge, il faut continuer à retenir son compagnon avec son corps et l'on n'a plus de mains pour manœuvrer le système — la raison la plus fréquente d'échec des sauvetages.",

    "q.l12#8.p" to "Que doit faire la personne qui est dans la crevasse ?",
    "q.l12#8.o0" to "Secouer fort la corde pour attirer l'attention",
    "q.l12#8.o1" to "Rester calme, essayer de remonter au prussik et éviter que la corde continue de scier la lèvre",
    "q.l12#8.o2" to "Se désencorder immédiatement",
    "q.l12#8.o3" to "Descendre chercher une sortie",
    "q.l12#8.e" to "La coopération de la personne qui a chuté facilite beaucoup le sauvetage. Secouer la corde aggrave le sciage, et se désencorder coupe votre seule liaison. Restez immobile, réduisez le sciage et, si possible, prenez une partie de votre poids sur un prussik.",

    "q.l12#9.p" to "[Choix multiple] Quels éléments de sauvetage faut-il porter sur soi et à portée de main sur un glacier ?",
    "q.l12#9.o0" to "Cordelette de prussik",
    "q.l12#9.o1" to "Mousquetons et une poulie",
    "q.l12#9.o2" to "Un piquet à neige ou une broche à glace",
    "q.l12#9.o3" to "Des sangles",
    "q.l12#9.o4" to "Des bâtons de marche",
    "q.l12#9.e" to "Ces quatre éléments forment ensemble le système improvisé : la cordelette de prussik pour le serrage à sens unique, les mousquetons et la poulie pour le mouflage, le piquet ou la broche pour l'ancrage, les sangles pour la liaison et l'extension. L'essentiel est qu'ils soient à portée de main — du matériel au fond du sac n'existe pas.",

    "q.l12#10.p" to "Pourquoi faut-il transférer la charge sur l'ancrage avant de hisser ?",
    "q.l12#10.o0" to "Pour mieux répartir la charge sur la corde",
    "q.l12#10.o1" to "Parce que sinon vos mains restent mobilisées à tenir l'arrêt et ne peuvent pas manœuvrer le système",
    "q.l12#10.o2" to "Pour économiser de l'énergie",
    "q.l12#10.o3" to "Pour protéger la corde",
    "q.l12#10.e" to "Avec tout le poids de la personne qui a chuté sur vous, vous devez continuer de tenir l'arrêt : vous ne pouvez ni libérer vos mains ni manœuvrer régulièrement. Passer la charge à l'ancrage est le seul moyen de cesser d'être un ancrage humain pour devenir l'opérateur.",

    "q.l12#11.p" to "Quel rôle joue le prussik dans un système de sauvetage ?",
    "q.l12#11.o0" to "Décoration",
    "q.l12#11.o1" to "Serrage à sens unique — il tient sous charge et coulisse le long de la corde quand il est libre",
    "q.l12#11.o2" to "Il augmente la résistance de la corde",
    "q.l12#11.o3" to "L'étanchéité",
    "q.l12#11.e" to "C'est précisément ce serrage à sens unique qui rend possible un système de mouflage : le prussik avance le long de la corde mais ne recule pas sous charge. Sa fiabilité dépend du diamètre de la cordelette et du nombre de tours : testez-le avant de compter sur lui.",
    // ---------- l13 Mal aigu des montagnes ----------
    "q.l13#0.p" to "Selon les critères de Lake Louise, quel symptôme doit être présent pour poser le diagnostic de MAM ?",
    "q.l13#0.o0" to "Céphalée plus au moins un des symptômes suivants : nausées, vertiges, fatigue ou insomnie",
    "q.l13#0.o1" to "Toux isolée",
    "q.l13#0.o2" to "Douleurs aux jambes isolées",
    "q.l13#0.o3" to "Appétit amélioré isolé",
    "q.l13#0.e" to "La céphalée est le symptôme central du MAM. La fatigue ou l'insomnie seules ne suffisent pas : elles doivent s'accompagner de céphalée. L'intérêt pratique de ces critères est de pouvoir s'auto-évaluer au camp et d'agir en conséquence.",

    "q.l13#1.p" to "Quelle est la bonne réaction quand les symptômes du MAM apparaissent ?",
    "q.l13#1.o0" to "Prendre un antalgique et continuer l'ascension comme prévu",
    "q.l13#1.o1" to "Arrêter de monter ; redescendre immédiatement si les symptômes s'aggravent",
    "q.l13#1.o2" to "Boire plus de café pour l'énergie et continuer à marcher",
    "q.l13#1.o3" to "Ignorer et serrer les dents",
    "q.l13#1.e" to "Le MAM peut évoluer vers un OCHA ou un OPHA mortel. Arrêter l'ascension laisse au corps le temps de s'adapter ; dès que les symptômes s'aggravent, la descente est le seul traitement définitif. Tout plan consistant à forcer est un pari avec sa vie.",

    "q.l13#2.p" to "La céphalée a disparu après un antalgique. Pouvez-vous continuer à monter ?",
    "q.l13#2.o0" to "Oui, le symptôme a disparu",
    "q.l13#2.o1" to "Non — masquer un symptôme ne signifie pas que le corps s'est acclimaté",
    "q.l13#2.o2" to "Oui, mais en marchant plus lentement",
    "q.l13#2.o3" to "Oui, à condition de boire plus d'eau",
    "q.l13#2.e" to "Un antalgique supprime le signal ; la contrainte physiologique de l'altitude, elle, continue. Monter sous ce couvert peut laisser le MAM évoluer vers un OCHA ou un OPHA sans aucun avertissement.",

    "q.l13#3.p" to "Combien de temps après l'arrivée en altitude les symptômes du MAM apparaissent-ils habituellement ?",
    "q.l13#3.o0" to "Immédiatement",
    "q.l13#3.o1" to "6 à 12 heures",
    "q.l13#3.o2" to "Après trois jours",
    "q.l13#3.o3" to "Après une semaine",
    "q.l13#3.e" to "Le moment compte : les symptômes commencent souvent une fois arrivé au camp, après le dîner, au moment d'aller dormir — et la nuit est précisément le moment où ils passent le plus facilement inaperçus et où ils risquent le plus de s'aggraver.",

    "q.l13#4.p" to "Quelle est la bonne conduite sur le terrain en cas de MAM léger ?",
    "q.l13#4.o0" to "Continuer l'ascension comme prévu",
    "q.l13#4.o1" to "Arrêter de gagner de l'altitude, se reposer à l'altitude actuelle, et redescendre si les symptômes persistent ou s'aggravent",
    "q.l13#4.o2" to "Prendre un antalgique et continuer à monter",
    "q.l13#4.o3" to "Redescendre immédiatement de 2 000 m",
    "q.l13#4.e" to "En cas de MAM léger, le premier choix est d'arrêter de monter et de laisser du temps au corps. Un antalgique soulage la céphalée mais ne modifie pas l'acclimatation. Si les symptômes persistent ou s'aggravent après le repos, la descente est le traitement définitif.",

    "q.l13#5.p" to "Pourquoi « monter haut, dormir bas » améliore-t-il l'acclimatation ?",
    "q.l13#5.o0" to "Parce que la journée est plus chaude",
    "q.l13#5.o1" to "L'hypoxie diurne fournit le stimulus, tandis que redescendre pour dormir protège la qualité du sommeil",
    "q.l13#5.o2" to "Parce qu'on porte moins de matériel",
    "q.l13#5.o3" to "Parce que progresser de nuit est plus sûr",
    "q.l13#5.e" to "L'acclimatation a besoin d'une contrainte hypoxique, mais la qualité du sommeil est elle aussi nécessaire — une hypoxie nocturne sévère aggrave la respiration périodique et les symptômes. « Monter haut, dormir bas » concilie les deux, ce qui explique pourquoi c'est plus efficace que de rester en altitude en permanence.",

    "q.l13#6.p" to "Quelle est la pire conséquence de continuer à monter avec un MAM ?",
    "q.l13#6.o0" to "On se sent un peu plus fatigué",
    "q.l13#6.o1" to "L'évolution vers un OCHA ou un OPHA, potentiellement mortel en quelques heures",
    "q.l13#6.o2" to "Un appétit moins bon",
    "q.l13#6.o3" to "Un sommeil moins bon",
    "q.l13#6.e" to "Le MAM se stabilise en général avec le repos ou la descente, mais il peut être le précurseur d'une maladie grave. C'est exactement pourquoi « ne pas monter avec des symptômes » est répété si souvent : cela coupe le premier maillon de toute la chaîne de dégradation.",

    "q.l13#7.p" to "Pour juger si le MAM s'aggrave, que faut-il surveiller en priorité ?",
    "q.l13#7.o0" to "Si la céphalée a disparu",
    "q.l13#7.o1" to "Si les symptômes s'aggravent progressivement, en particulier la conscience, la marche et la respiration",
    "q.l13#7.o2" to "Si la température corporelle est normale",
    "q.l13#7.o3" to "Si la saturation affichée a augmenté",
    "q.l13#7.e" to "Le passage du MAM à l'OCHA ou à l'OPHA se lit sur trois plans : la conscience, la marche et la respiration. Surveiller ces trois points est plus fiable que de suivre un symptôme isolé ou un chiffre d'oxymètre.",

    "q.l13#8.p" to "Qu'est-ce qui caractérise la céphalée du MAM ?",
    "q.l13#8.o0" to "C'est généralement le premier symptôme",
    "q.l13#8.o1" to "Elle n'apparaît que la nuit",
    "q.l13#8.o2" to "Elle n'apparaît qu'à l'effort",
    "q.l13#8.o3" to "C'est généralement le dernier symptôme à apparaître",
    "q.l13#8.e" to "La céphalée est souvent le signal le plus précoce et constitue un élément obligatoire des critères de Lake Louise. Comme elle est très banale, on la met facilement sur le compte d'une fatigue ordinaire — l'essentiel est donc le contexte : elle est apparue après avoir gagné de l'altitude.",

    "q.l13#9.p" to "Quand l'acétazolamide est utilisé pour prévenir le mal d'altitude, quel schéma le manuel recommande-t-il ?",
    "q.l13#9.o0" to "250 mg trois fois par jour",
    "q.l13#9.o1" to "125 mg deux fois par jour, en commençant environ un jour avant l'ascension et en arrêtant environ deux jours après",
    "q.l13#9.o2" to "500 mg une fois par jour",
    "q.l13#9.o3" to "Seulement après l'apparition des symptômes",
    "q.l13#9.e" to "Suivant les recommandations médicales les plus récentes, la dose conseillée est de 125 mg deux fois par jour, inférieure à l'ancien schéma de 250 mg trois fois par jour. La dose plus faible reste efficace tout en exposant moins à des effets indésirables sévères. C'est un médicament sur ordonnance : il faut suivre un avis médical.",

    "q.l13#10.p" to "Pourquoi le soulagement des symptômes par un médicament ne justifie-t-il pas de continuer à monter ?",
    "q.l13#10.o0" to "Parce que le médicament crée une illusion",
    "q.l13#10.o1" to "Parce que le médicament soulage les symptômes mais n'améliore pas l'acclimatation à l'hypoxie",
    "q.l13#10.o2" to "Parce que le médicament cesse d'agir",
    "q.l13#10.o3" to "Parce qu'il faut augmenter la dose sans cesse",
    "q.l13#10.e" to "C'est l'idée la plus importante de la prise en charge du mal d'altitude : le symptôme est l'alarme, pas la maladie. Le médicament fait taire l'alarme alors que la contrainte hypoxique continue de s'accumuler — monter sous ce couvert laisse la maladie progresser en silence.",

    "q.l13#11.p" to "[Choix multiple] Quelles situations se confondent facilement avec le MAM et demandent une différenciation soigneuse ?",
    "q.l13#11.o0" to "La déshydratation",
    "q.l13#11.o1" to "Les infections respiratoires hautes, comme le rhume",
    "q.l13#11.o2" to "La sur-fatigue",
    "q.l13#11.o3" to "Le manque de sommeil",
    "q.l13#11.o4" to "La cécité des neiges (kératite ultraviolette)",
    "q.l13#11.e" to "Les quatre premières causes donnent céphalée, fatigue, nausées ou mauvais sommeil — un recouvrement important avec le MAM. Les critères utiles sont : les symptômes sont-ils apparus avec le gain d'altitude, s'améliorent-ils au repos, et la marche ou la conscience ont-elles changé ?",

    "q.l13#12.p" to "Selon les sources cliniques et les guides, quelle proportion de personnes au-dessus de 4 000 m développe un mal aigu des montagnes ?",
    "q.l13#12.o0" to "5 à 10 %",
    "q.l13#12.o1" to "20 à 30 %",
    "q.l13#12.o2" to "50 à 65 %",
    "q.l13#12.o3" to "Presque 100 %",
    "q.l13#12.e" to "Plus on monte haut et vite, plus c'est fréquent : environ 50 à 65 % des personnes au-dessus de 4 000 m développent un mal aigu des montagnes, et les études entre 2 500 et 4 300 m donnent à peu près 25 à 43 %. Le mal d'altitude est donc normal, pas exceptionnel — d'où la nécessité d'un plan d'acclimatation, qui n'est pas de la prudence excessive.",

    "q.l13#13.p" to "Quelle affirmation sur l'âge et le risque de mal d'altitude est correcte ?",
    "q.l13#13.o0" to "Les jeunes ne font pas de mal d'altitude",
    "q.l13#13.o1" to "Plus on est âgé, plus le risque doit être élevé",
    "q.l13#13.o2" to "L'âge n'augmente pas significativement le risque ; ce qui compte, c'est la vitesse d'ascension et l'altitude de sommeil",
    "q.l13#13.o3" to "Seules les personnes peu entraînées en souffrent",
    "q.l13#13.e" to "Les études montrent que des trekkeurs plus âgés à altitude modérée (65 ans en moyenne) ont des taux comparables à ceux des plus jeunes. Ce qui décide réellement du risque, c'est la vitesse d'ascension, l'altitude de sommeil et la physiologie individuelle — accuser l'âge ou la condition physique est un jugement dangereux.",

    // ---------- l14 OCHA et OPHA ----------
    "q.l14#0.p" to "Quels signes doivent faire craindre un OCHA ?",
    "q.l14#0.o0" to "Démarche instable (impossible de marcher droit) et troubles de la conscience",
    "q.l14#0.o1" to "Une céphalée légère",
    "q.l14#0.o2" to "Un appétit un peu diminué",
    "q.l14#0.o3" to "Des courbatures légères aux jambes",
    "q.l14#0.e" to "L'ataxie et les troubles de la conscience sont les marqueurs centraux de l'OCHA : l'œdème cérébral atteint déjà la motricité et la cognition. Avec ces signes, il faut redescendre immédiatement et chercher un appui médical — plus question d'observer et d'attendre.",

    "q.l14#1.p" to "Quel est le signe précoce le plus typique de l'OPHA ?",
    "q.l14#1.o0" to "Essoufflement au repos, avec effondrement de la capacité à l'effort",
    "q.l14#1.o1" to "Un léger écoulement nasal",
    "q.l14#1.o2" to "Un léger engourdissement des doigts",
    "q.l14#1.o3" to "La soif",
    "q.l14#1.e" to "L'OPHA se caractérise par un essoufflement même au repos. Contrairement à la simple fatigue, il ne s'améliore pas avec le repos, il continue de s'aggraver, et peut évoluer vers des expectorations mousseuses et une cyanose — un signal pour redescendre immédiatement.",

    "q.l14#2.p" to "Quel est le traitement fondamental de l'OCHA et de l'OPHA ?",
    "q.l14#2.o0" to "Prendre un antalgique et continuer à grimper",
    "q.l14#2.o1" to "Redescendre immédiatement à une altitude plus basse, avec de l'oxygène et les autres mesures de soutien",
    "q.l14#2.o2" to "Se reposer sur place pendant deux jours",
    "q.l14#2.o3" to "Boire plus d'eau et dormir davantage",
    "q.l14#2.e" to "La descente est la seule mesure qui inverse fiablement la maladie, parce qu'elle supprime la cause : l'hypoxie. L'oxygène, le caisson hyperbare et les médicaments sont des adjuvants qui font gagner du temps quand la descente ne peut pas commencer tout de suite.",

    "q.l14#3.p" to "Selon les sources cliniques, quel est le schéma habituel de dexaméthasone dans le traitement de l'OCHA ?",
    "q.l14#3.o0" to "8 à 10 mg en dose initiale, puis 4 mg toutes les 6 heures",
    "q.l14#3.o1" to "2 mg une fois par jour",
    "q.l14#3.o2" to "10 mg toutes les 2 heures",
    "q.l14#3.o3" to "Seulement si le patient est inconscient",
    "q.l14#3.e" to "Il s'agit d'une dose de traitement, qui doit être administrée sous surveillance médicale. Le médicament fait gagner du temps pour la descente ; il ne la remplace jamais. La descente reste le traitement fondamental de l'OCHA comme de l'OPHA.",

    "q.l14#4.p" to "À quelle fréquence l'OPHA et l'OCHA surviennent-ils ensemble ?",
    "q.l14#4.o0" to "Presque jamais",
    "q.l14#4.o1" to "Environ 13 à 20 % des OPHA développent aussi un OCHA",
    "q.l14#4.o2" to "Dans 100 % des cas",
    "q.l14#4.o3" to "Seulement chez les enfants",
    "q.l14#4.e" to "Ce chiffre montre que les deux formes critiques du mal d'altitude apparaissent souvent ensemble. Donc quand un membre de la cordée présente des signes d'œdème pulmonaire, surveillez aussi la conscience et la marche, préparez le pire et redescendez immédiatement.",

    "q.l14#5.p" to "Si un membre de la cordée ne peut plus marcher, quelle est la priorité ?",
    "q.l14#5.o0" to "L'encourager à continuer de marcher",
    "q.l14#5.o1" to "Organiser un portage, donner de l'oxygène, envisager un caisson hyperbare et redescendre le plus vite possible",
    "q.l14#5.o2" to "Se reposer sur place en attendant la récupération",
    "q.l14#5.o3" to "Retourner d'abord au camp chercher le matériel",
    "q.l14#5.e" to "Perdre la capacité de marcher signifie une maladie grave. La descente dépend alors du portage par la cordée ou d'un secours extérieur — la vraie stratégie de sécurité est donc de ne jamais laisser quelqu'un arriver à ce point, ce qui est exactement la valeur d'une reconnaissance précoce du MAM.",

    "q.l14#6.p" to "À quoi sert un caisson hyperbare portable (type Gamow) ?",
    "q.l14#6.o0" to "Guérir complètement le mal d'altitude",
    "q.l14#6.o1" to "Simuler une altitude plus basse pour stabiliser le patient quand la descente immédiate est impossible",
    "q.l14#6.o2" to "Remplacer la descente",
    "q.l14#6.o3" to "Surtout à réchauffer",
    "q.l14#6.e" to "Un caisson hyperbare fait gagner du temps ; ce n'est pas la fin du traitement. Il peut contenir la maladie par mauvais temps, en attendant un hélicoptère, ou quand la descente ne peut pas commencer tout de suite — mais la descente reste nécessaire au final.",

    "q.l14#7.p" to "Quelle est la bonne attitude vis-à-vis des médicaments du mal d'altitude ?",
    "q.l14#7.o0" to "Si les symptômes s'atténuent, continuer à monter",
    "q.l14#7.o1" to "Ce sont des adjuvants qui font gagner du temps, utilisés sur avis médical, et qui ne remplacent jamais la descente",
    "q.l14#7.o2" to "Ils peuvent être partagés librement entre les membres de la cordée",
    "q.l14#7.o3" to "Le plus tôt possible, sans évaluation médicale",
    "q.l14#7.e" to "Ces médicaments ont des indications, des contre-indications et des effets indésirables précis, et monter sous leur couvert masque les signes d'aggravation. La règle est de les utiliser après évaluation médicale, avec la descente comme traitement fondamental.",

    "q.l14#8.p" to "Quelle dose de dexaméthasone est habituelle dans l'œdème cérébral de haute altitude ?",
    "q.l14#8.o0" to "20 mg toutes les 12 heures",
    "q.l14#8.o1" to "4 mg toutes les 6 heures",
    "q.l14#8.o2" to "8 mg une fois par jour",
    "q.l14#8.o3" to "10 mg toutes les 2 heures",
    "q.l14#8.e" to "Le manuel indique 4 mg toutes les 6 heures. Cela abaisse la pression intracrânienne et atténue l'œdème cérébral, avec en général une amélioration nette en six heures — mais cela ne fait que gagner du temps pour la descente et ne la remplace jamais.",

    "q.l14#9.p" to "La dexaméthasone traite-t-elle l'œdème pulmonaire de haute altitude ?",
    "q.l14#9.o0" to "Oui, c'est le médicament de premier choix",
    "q.l14#9.o1" to "Non, elle n'a aucun effet thérapeutique sur l'œdème pulmonaire",
    "q.l14#9.o2" to "Oui, mais il faut doubler la dose",
    "q.l14#9.o3" to "Elle n'agit que chez l'enfant",
    "q.l14#9.e" to "La confusion est facile : la dexaméthasone vise l'œdème cérébral et est inefficace sur l'œdème pulmonaire, tandis que la nifédipine vise l'œdème pulmonaire et n'a qu'un effet limité sur l'œdème cérébral. Les deux formes critiques demandent des médicaments différents — le mauvais choix n'est pas un traitement.",

    "q.l14#10.p" to "Pour l'œdème pulmonaire de haute altitude, quel schéma de nifédipine est recommandé, et quel est son effet indésirable important ?",
    "q.l14#10.o0" to "20 à 30 mg à libération prolongée toutes les 12 heures ; la tension peut chuter rapidement, si bien que se lever brusquement peut provoquer une syncope",
    "q.l14#10.o1" to "4 mg toutes les 6 heures ; cela somnole",
    "q.l14#10.o2" to "125 mg une fois par jour ; cela augmente la tension",
    "q.l14#10.o3" to "Uniquement en intraveineuse ; aucun effet indésirable",
    "q.l14#10.e" to "La nifédipine lève la vasoconstriction pulmonaire hypoxique et sert à prévenir et traiter l'œdème pulmonaire. Son effet indésirable est très concret : la tension peut baisser vite, si bien que se lever depuis la position assise ou allongée peut provoquer une syncope — particulièrement dangereux sur une pente raide ou en se levant la nuit.",

    "q.l14#11.p" to "Comment administrer la dexaméthasone à un patient en mal d'altitude qui vomit sans arrêt ?",
    "q.l14#11.o0" to "Par voie orale, à dose plus élevée",
    "q.l14#11.o1" to "Il faut l'injecter",
    "q.l14#11.o2" to "Sous la langue",
    "q.l14#11.o3" to "On ne peut pas l'administrer ; il suffit d'attendre",
    "q.l14#11.e" to "Des vomissements persistants signifient que les médicaments oraux ne sont pas absorbés et peuvent être simplement rejetés. Le manuel indique clairement qu'une injection est nécessaire — rappel que la voie d'administration fait elle aussi partie de ce qu'il faut anticiper dans tout plan d'urgence en altitude.",
    // ---------- l15 Acclimatation et médicaments ----------
    "q.l15#0.p" to "Au-dessus de 3 000 m, de combien l'altitude de sommeil doit-elle augmenter par jour ?",
    "q.l15#0.o0" to "Pas plus de 500 m",
    "q.l15#0.o1" to "Pas plus de 1 500 m",
    "q.l15#0.o2" to "Le plus vite possible",
    "q.l15#0.o3" to "Il n'y a pas de limite",
    "q.l15#0.e" to "Limiter la montée quotidienne de l'altitude de sommeil à 500 m, avec un jour de repos environ tous les 1 000 m, est la recommandation de base répétée dans les guides internationaux. Cela laisse au corps le temps de compenser. (Les sources proposent des valeurs entre 300 et 700 m ; ce cours retient l'une des plus courantes.)",

    "q.l15#1.p" to "Que signifie « monter haut, dormir bas » ?",
    "q.l15#1.o0" to "Monter plus haut dans la journée et redescendre dormir à une altitude plus basse",
    "q.l15#1.o1" to "Se reposer le jour et progresser la nuit",
    "q.l15#1.o2" to "Rester à la même altitude tout le temps",
    "q.l15#1.o3" to "Ne dormir qu'au point le plus haut",
    "q.l15#1.e" to "L'exposition diurne en altitude stimule la production de globules rouges et l'adaptation respiratoire, tandis que redescendre dormir atténue les symptômes et protège la qualité du sommeil. Combiner les deux est la façon la plus efficace de s'acclimater.",

    "q.l15#2.p" to "Lequel de ces facteurs alourdit la charge d'acclimatation ?",
    "q.l15#2.o0" to "Boire suffisamment d'eau",
    "q.l15#2.o1" to "L'alcool ou les médicaments sédatifs",
    "q.l15#2.o2" to "Manger surtout des glucides",
    "q.l15#2.o3" to "Dormir suffisamment",
    "q.l15#2.e" to "L'alcool et les sédatifs dépriment la commande respiratoire et aggravent la respiration périodique nocturne et l'hypoxie, ce qui augmente nettement le risque de maladie. En altitude, la qualité de la respiration pendant le sommeil fait elle-même partie de l'acclimatation.",

    "q.l15#3.p" to "À quoi sert de surveiller la saturation en oxygène avec un oxymètre de pouls ?",
    "q.l15#3.o0" to "Cela peut remplacer entièrement l'évaluation des symptômes",
    "q.l15#3.o1" to "Cela donne une référence objective, surtout pour les personnes ayant des antécédents de mal d'altitude",
    "q.l15#3.o2" to "Seulement à tenir un registre",
    "q.l15#3.o3" to "Cela n'a aucune valeur pratique",
    "q.l15#3.e" to "La saturation est une référence utile, mais les variations individuelles sont larges et elle ne peut pas fonder seule les décisions. Les symptômes et l'état fonctionnel — la personne marche-t-elle droit, est-elle capable d'agir — restent le critère principal.",

    "q.l15#4.p" to "Pour les personnes à haut risque d'OPHA, quels médicaments préventifs un médecin peut-il envisager ?",
    "q.l15#4.o0" to "La nifédipine ou le sildénafil (un inhibiteur de la PDE)",
    "q.l15#4.o1" to "Des antibiotiques à large spectre",
    "q.l15#4.o2" to "Des antalgiques ordinaires",
    "q.l15#4.o3" to "Des compléments vitaminiques",
    "q.l15#4.e" to "Les deux classes abaissent la pression artérielle pulmonaire et servent à prévenir l'OPHA chez les personnes à haut risque, après évaluation médicale. Elles agissent à un autre niveau que l'acétazolamide et ne peuvent pas le remplacer.",

    "q.l15#5.p" to "Pourquoi une ascension trop rapide est-elle l'un des facteurs de risque les plus forts du mal d'altitude ?",
    "q.l15#5.o0" to "Parce que c'est fatigant",
    "q.l15#5.o1" to "Parce que le corps n'a pas le temps de développer l'adaptation respiratoire et l'augmentation des globules rouges",
    "q.l15#5.o2" to "Parce qu'on porte plus de poids",
    "q.l15#5.o3" to "Parce que le temps change vite en montagne",
    "q.l15#5.e" to "L'acclimatation est l'accumulation d'une série de compensations physiologiques, et elle demande un temps qui se compte en jours. Quand l'ascension dépasse la compensation, l'écart se traduit par des symptômes — d'où viennent toutes les recommandations de vitesse d'ascension.",

    "q.l15#6.p" to "À quoi sert de boire suffisamment d'eau pour l'acclimatation ?",
    "q.l15#6.o0" to "Seulement à étancher la soif",
    "q.l15#6.o1" to "À maintenir la circulation et le métabolisme ; la déshydratation aggrave nettement les symptômes",
    "q.l15#6.o2" to "À prévenir l'œdème pulmonaire",
    "q.l15#6.o3" to "À remplacer les médicaments préventifs",
    "q.l15#6.e" to "L'air sec et la respiration plus rapide en altitude augmentent sensiblement les pertes hydriques, et la déshydratation épaissit le sang, ce qui aggrave la sensation d'hypoxie et la céphalée. À l'inverse, évitez de boire trop : l'objectif est une hydratation régulière et suffisante.",

    "q.l15#7.p" to "Pourquoi éviter le surmenage en altitude ?",
    "q.l15#7.o0" to "Parce qu'on se fatigue vite",
    "q.l15#7.o1" to "Le surmenage peut déclencher un OPHA, surtout avant l'acclimatation",
    "q.l15#7.o2" to "Parce que cela provoque une déshydratation",
    "q.l15#7.o3" to "Parce que cela ralentit la cordée",
    "q.l15#7.e" to "Un effort intense fait monter la pression artérielle pulmonaire et constitue un déclencheur net d'OPHA chez les personnes pas encore acclimatées. Contrôler son allure ne sert pas seulement à économiser l'énergie : cela réduit le risque de maladie.",

    "q.l15#8.p" to "Quand faut-il commencer et arrêter l'acétazolamide ?",
    "q.l15#8.o0" to "Commencer à l'arrivée en altitude et arrêter une fois acclimaté",
    "q.l15#8.o1" to "Commencer environ un jour avant l'ascension et arrêter environ deux jours après",
    "q.l15#8.o2" to "En prendre en continu pendant tout le séjour",
    "q.l15#8.o3" to "Seulement après l'apparition des symptômes",
    "q.l15#8.e" to "Commencer un jour avant signifie que le médicament agit déjà au moment de monter ; arrêter environ deux jours après l'ascension se justifie parce que le corps a commencé à s'acclimater seul. L'acétazolamide accélère l'acclimatation ; il ne la remplace pas.",

    "q.l15#9.p" to "L'arrêt de l'acétazolamide provoque-t-il un rebond des symptômes ?",
    "q.l15#9.o0" to "Oui, il faut diminuer la dose progressivement",
    "q.l15#9.o1" to "Non, l'acclimatation revient simplement à sa vitesse normale",
    "q.l15#9.o2" to "Oui, les symptômes reviennent doublés",
    "q.l15#9.o3" to "Cela dépend de l'altitude",
    "q.l15#9.e" to "Le manuel indique clairement que l'arrêt ne provoque pas de rebond : la vitesse d'acclimatation revient simplement à la normale. Ce point compte : il montre que le médicament ne supprime rien, il accélère seulement le processus pendant un temps.",

    "q.l15#10.p" to "Comment l'aspirine est-elle utilisée pour soulager la céphalée d'altitude ?",
    "q.l15#10.o0" to "500 mg une fois, après le début de la céphalée",
    "q.l15#10.o1" to "Commencer un jour avant l'ascension, 320 mg trois fois par jour jusqu'à ce que l'acclimatation soit terminée",
    "q.l15#10.o2" to "100 mg une fois par jour",
    "q.l15#10.o3" to "Seulement au coucher",
    "q.l15#10.e" to "Il s'agit d'un usage préventif et non d'une prise au moment de la douleur : commencer tôt, doser régulièrement, poursuivre jusqu'à la fin du processus d'acclimatation. À noter que l'aspirine comporte des risques digestifs et hémorragiques — c'est une décision médicale, à évaluer par un médecin.",

    "q.l15#11.p" to "Que penser de l'extrait de ginkgo pour prévenir le mal d'altitude ?",
    "q.l15#11.o0" to "Il est plus efficace que l'acétazolamide et peut le remplacer",
    "q.l15#11.o1" to "Il a un certain effet préventif, mais les essais contrôlés montrent qu'il est bien moins efficace que l'acétazolamide",
    "q.l15#11.o2" to "Il est totalement inefficace",
    "q.l15#11.o3" to "Il n'agit que sur l'œdème cérébral",
    "q.l15#11.e" to "Le manuel reste prudent : certains essais montrent un soulagement des symptômes, mais les doses et les conditions varient trop pour établir une posologie fiable, et les essais comparatifs le montrent bien plus faible que l'acétazolamide. Attention aussi à son interaction avec les anticoagulants.",

    // ---------- l16 Hypothermie et gelures ----------
    "q.l16#0.p" to "Que signifie l'arrêt des frissons ?",
    "q.l16#0.o0" to "Le corps s'est adapté au froid",
    "q.l16#0.o1" to "L'hypothermie s'aggrave — c'est un signe de danger",
    "q.l16#0.o2" to "On peut continuer à avancer",
    "q.l16#0.o3" to "Il faut boire de l'eau immédiatement",
    "q.l16#0.e" to "Les frissons sont le dernier moyen du corps de produire de la chaleur. Quand ils s'arrêtent, la production de chaleur a échoué et la température centrale baisse plus vite — c'est la frontière clé entre hypothermie légère et modérée ou sévère, et une raison d'agir immédiatement.",

    "q.l16#1.p" to "Quelle est la bonne méthode de réchauffement d'une gelure sur le terrain ?",
    "q.l16#1.o0" to "Frotter la zone avec de la neige",
    "q.l16#1.o1" to "Plonger dans de l'eau à 37–40 °C pendant environ 30 minutes, jusqu'à ce que la peau rougisse et se ramollisse",
    "q.l16#1.o2" to "Réchauffer près d'un feu",
    "q.l16#1.o3" to "Appliquer directement une bouillotte",
    "q.l16#1.e" to "Les tissus gelés contiennent des cristaux de glace, et le frottement provoque des lésions cellulaires secondaires ; une chaleur forte brûle une peau qui a perdu sa sensibilité. Le réchauffement rapide en eau tiède est la seule méthode de référence — la main saine ou l'aisselle peuvent servir de mesure d'urgence.",

    "q.l16#2.p" to "Dans quel cas ne faut-il pas réchauffer une gelure sur le terrain ?",
    "q.l16#2.o0" to "Il faut toujours réchauffer toute gelure",
    "q.l16#2.o1" to "Quand il existe un risque de recongélation, car gel-dégel-recongélation cause des lésions pires",
    "q.l16#2.o2" to "Il ne faut jamais réchauffer de jour",
    "q.l16#2.o3" to "Seules les gelures légères doivent être réchauffées",
    "q.l16#2.e" to "Un cycle réchauffement-recongélation détruit bien plus de tissus que de rester gelé. Donc quand une nouvelle exposition au froid est probable et que la chaleur ne peut pas être garantie, protégez la zone, évitez le frottement et redescendez là où un réchauffement durable est possible avant de réchauffer.",

    "q.l16#3.p" to "Pourquoi éviter de mobiliser vigoureusement les membres en hypothermie modérée ou plus grave ?",
    "q.l16#3.o0" to "Parce que cela consomme de l'énergie",
    "q.l16#3.o1" to "Parce que le muscle cardiaque refroidi entre facilement en arythmie",
    "q.l16#3.o2" to "Parce que cela rend le patient irritable",
    "q.l16#3.o3" to "Parce que cela aggrave les gelures",
    "q.l16#3.e" to "C'est le point le plus contre-intuitif de la prise en charge de l'hypothermie : faire marcher le patient est souvent fatal. Dans un cœur froid, le myocarde est très irritable, et une mobilisation brusque des membres ou une manipulation rude peuvent déclencher une fibrillation ventriculaire.",

    "q.l16#4.p" to "Quelle température d'eau est correcte pour réchauffer une gelure ?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Plus de 60 °C",
    "q.l16#4.e" to "Trop froid, le réchauffement échoue ; trop chaud, on brûle une peau sans sensibilité. 37–40 °C font fondre rapidement les cristaux de glace sans lésion thermique. Le réchauffement est très douloureux et nécessite une analgésie.",

    "q.l16#5.p" to "Pourquoi réchauffer le tronc avant les membres en hypothermie ?",
    "q.l16#5.o0" to "Parce que les membres n'ont pas d'importance",
    "q.l16#5.o1" to "Réchauffer les membres renvoie du sang périphérique froid vers le centre et fait encore baisser la température centrale",
    "q.l16#5.o2" to "Parce que le tronc est plus facile à traiter",
    "q.l16#5.o3" to "Parce que les membres sont peut-être déjà gelés",
    "q.l16#5.e" to "C'est l'un des principes clés de la prise en charge de l'hypothermie. Traiter les membres d'abord chasse le sang périphérique froid vers le centre, ce qui peut faire chuter davantage la température centrale et provoquer une arythmie — le tronc d'abord, les membres ensuite.",

    "q.l16#6.p" to "Quelle est la conduite sur le terrain en cas d'hypothermie légère ?",
    "q.l16#6.o0" to "L'envoyer immédiatement à l'hôpital",
    "q.l16#6.o1" to "Sortir du vent et du froid, changer les vêtements mouillés, apporter de la chaleur et continuer à surveiller l'aggravation",
    "q.l16#6.o2" to "Le faire marcher pour produire de la chaleur",
    "q.l16#6.o3" to "Frotter le corps avec de la neige pour stimuler la circulation",
    "q.l16#6.e" to "Une personne en hypothermie légère peut encore produire de la chaleur : la priorité est donc de stopper la perte de chaleur et d'apporter de l'énergie. Mais continuez à surveiller : l'arrêt des frissons signale généralement un passage en hypothermie modérée, pas une amélioration.",

    "q.l16#7.p" to "Peut-on appliquer une bouillotte directement sur des tissus gelés ?",
    "q.l16#7.o0" to "Oui, plus le réchauffement est rapide mieux c'est",
    "q.l16#7.o1" to "Non — une peau sans sensibilité se brûle facilement ; n'utilisez que de l'eau à 37–40 °C",
    "q.l16#7.o2" to "Oui, à condition de l'envelopper dans une serviette",
    "q.l16#7.o3" to "Oui, à condition que la température ne soit pas trop élevée",
    "q.l16#7.e" to "Une peau gelée a perdu à la fois la sensibilité à la douleur et à la température : elle ne peut pas signaler que quelque chose est trop chaud. Une source de chaleur directe ajoute facilement une brûlure et peut détruire des tissus qui auraient pu récupérer.",

    "q.l16#8.p" to "[Choix multiple] Lesquels de ces gestes sont faux dans les premiers secours en hypothermie ?",
    "q.l16#8.o0" to "Donner de l'alcool au patient pour le réchauffer",
    "q.l16#8.o1" to "Faire marcher un patient en hypothermie sévère pour produire de la chaleur",
    "q.l16#8.o2" to "Frotter vigoureusement les membres gelés",
    "q.l16#8.o3" to "Réchauffer les membres avant le tronc",
    "q.l16#8.o4" to "Mettre le patient à l'abri du vent et changer ses vêtements mouillés",
    "q.l16#8.e" to "Les quatre premiers sont tous faux, chacun pour sa raison : l'alcool dilate les vaisseaux périphériques et accélère la perte de chaleur ; faire marcher peut déclencher une arythmie en hypothermie sévère ; le frottement provoque des lésions secondaires sur les tissus gelés ; et réchauffer les membres renvoie du sang froid au centre et fait baisser encore la température centrale.",

    "q.l16#9.p" to "Quel est l'ordre de priorité essentiel dans la prise en charge de l'hypothermie ?",
    "q.l16#9.o0" to "Réchauffer d'abord les membres, puis le tronc",
    "q.l16#9.o1" to "Réchauffer d'abord le tronc, tout en évitant les manipulations rudes et la mobilisation vigoureuse des membres",
    "q.l16#9.o2" to "Donner d'abord de l'eau chaude au patient",
    "q.l16#9.o3" to "Retirer d'abord tous les vêtements",
    "q.l16#9.e" to "Le tronc d'abord est le premier principe : une fois le tronc réchauffé, le cœur et le cerveau peuvent fonctionner à nouveau et le sang peut être envoyé aux membres sans danger. Inverser l'ordre fait directement baisser la température centrale.",

    "q.l16#10.p" to "Quels sont les bons soins après le réchauffement d'une gelure ?",
    "q.l16#10.o0" to "Perforer les phlyctènes pour soulager la pression",
    "q.l16#10.o1" to "Ne pas percer les phlyctènes ; protéger sans serrer avec un matériau stérile et éviter l'appui",
    "q.l16#10.o2" to "Masser vigoureusement pour améliorer la circulation",
    "q.l16#10.o3" to "Placer immédiatement la zone près d'une source de chaleur",
    "q.l16#10.e" to "Les tissus réchauffés sont extrêmement fragiles : les phlyctènes sont un pansement naturel et les percer invite l'infection, le massage provoque des lésions mécaniques, et la chaleur brûle une peau sans sensibilité. Protégez, gardez au sec, évitez l'appui et rejoignez une prise en charge médicale.",

    "q.l16#11.p" to "Quelles séquelles à long terme une gelure peut-elle laisser ?",
    "q.l16#11.o0" to "En général une guérison complète sans séquelle",
    "q.l16#11.o1" to "Une sensibilité au froid, des troubles de la sensibilité et une sudation anormale, pouvant mettre des mois ou plus à se stabiliser",
    "q.l16#11.o2" to "Uniquement des effets esthétiques",
    "q.l16#11.o3" to "Uniquement une perte de capacité sportive",
    "q.l16#11.e" to "La gelure atteint les tissus profonds et les terminaisons nerveuses : même quand la peau paraît guérie, une sensibilité au froid, un engourdissement, des fourmillements et une sudation anormale peuvent persister longtemps. C'est exactement pourquoi prévenir une gelure compte bien plus que la traiter.",
    // ---------- l17 Escalade sur glace ----------
    "q.l17#0.p" to "Comment faut-il frapper avec un piolet-glace ?",
    "q.l17#0.o0" to "Frapper fort avec le haut du bras",
    "q.l17#0.o1" to "Frapper du poignet pour que la pointe entre verticalement dans la glace",
    "q.l17#0.o2" to "Marteler la surface avec le pan",
    "q.l17#0.o3" to "Entailler la glace horizontalement",
    "q.l17#0.e" to "Un coup de poignet enfonce la pointe verticalement, vite : elle mord plus facilement et coûte moins d'énergie. Frapper avec tout le bras fait généralement arriver la pointe en biais et brise la surface en une croûte qui ne tient plus.",

    "q.l17#1.p" to "En escalade sur glace, que signifie le contact en trois points ?",
    "q.l17#1.o0" to "Deux mains et un pied (ou deux pieds et une main) tiennent trois appuis stables pendant que le quatrième se déplace",
    "q.l17#1.o1" to "Trois personnes grimpent ensemble",
    "q.l17#1.o2" to "Trois nœuds partagent la charge",
    "q.l17#1.o3" to "Le baudrier doit avoir trois points d'attache",
    "q.l17#1.e" to "Le contact en trois points est la règle de progression commune à la glace et au rocher : gardez toujours trois appuis fiables et n'en déplacez qu'un seul. Ainsi, si un appui lâche, il en reste encore.",

    "q.l17#2.p" to "Qu'est-ce qui caractérise WI4 ?",
    "q.l17#2.o0" to "De la glace en pente faible que l'on remonte en marchant",
    "q.l17#2.o1" to "Presque vertical, avec de courts passages verticaux, et une protection qui peut être médiocre",
    "q.l17#2.o2" to "Uniquement des surplombs",
    "q.l17#2.o3" to "Un seul bâton de marche suffit",
    "q.l17#2.e" to "WI4 signifie un terrain proche de la verticale avec de courts passages verticaux, et des endroits où placer une broche qui ne sont pas forcément bons. Cela demande une meilleure technique et un meilleur jugement. WI1–WI2 est un terrain d'apprentissage.",

    "q.l17#3.p" to "Pourquoi économiser ses coups en escalade sur glace ?",
    "q.l17#3.o0" to "Pour économiser son énergie",
    "q.l17#3.o1" to "La glace martelée se transforme en croûte qui ne tient plus",
    "q.l17#3.o2" to "Parce que le matériel s'use",
    "q.l17#3.o3" to "Parce que cela dérange les compagnons",
    "q.l17#3.e" to "Chaque coup manqué laisse un cratère. Marteler sans cesse détruit la glace porteuse sur tout un panneau et vous oblige à tenir sur les bras — un cercle vicieux.",

    "q.l17#4.p" to "Pourquoi l'escalade sur glace est-elle plus dangereuse que l'escalade sportive ?",
    "q.l17#4.o0" to "Parce qu'il fait plus froid",
    "q.l17#4.o1" to "Les broches peuvent arracher sous charge, et la glace change d'un jour à l'autre",
    "q.l17#4.o2" to "Parce qu'il n'y a pas de protection",
    "q.l17#4.o3" to "Parce qu'on ne peut pas utiliser de corde",
    "q.l17#4.e" to "Un coinceur ou un point bien placé dans le rocher reste fiable ; une broche dépend de la glace elle-même, et la glace fond, devient cassante et développe des vides — un placement solide hier peut ne plus rien valoir aujourd'hui.",

    "q.l17#5.p" to "Pourquoi stabiliser les pieds avant de frapper avec le piolet ?",
    "q.l17#5.o0" to "Parce que les bras se fatiguent plus vite que les jambes",
    "q.l17#5.o1" to "Les pieds portent le poids et permettent le repos ; les bras ne font qu'aider",
    "q.l17#5.o2" to "Parce que les piolets-glace coûtent cher",
    "q.l17#5.o3" to "Parce que cela fait plus professionnel",
    "q.l17#5.e" to "La force des bras s'épuise très vite sur glace ; ce sont les pieds qui peuvent porter du poids pendant des heures. Frapper avant d'avoir posé les pieds grille les bras trop tôt et augmente en réalité le risque de chute.",

    "q.l17#6.p" to "Dans quelles conditions la glace se dégrade-t-elle typiquement ?",
    "q.l17#6.o0" to "Après une nuit froide",
    "q.l17#6.o1" to "Après un fort ensoleillement ou une hausse de température, quand la glace ramollit et devient alvéolée",
    "q.l17#6.o2" to "Juste après une chute de neige fraîche",
    "q.l17#6.o3" to "Quand le vent se lève",
    "q.l17#6.e" to "La glace est fonction de la température. La glace dure du matin demande des placements précis ; la soupe de l'après-midi paraît facile mais ses broches arrachent plus facilement. Juger la glace, c'est peser l'heure, l'exposition, la température et l'ensoleillement des jours précédents.",

    "q.l17#7.p" to "Avant de placer une broche à glace, que faut-il vérifier ?",
    "q.l17#7.o0" to "Si la broche a une couleur bien visible",
    "q.l17#7.o1" to "Si la glace à cet endroit est compacte, sans vide ni alvéoles",
    "q.l17#7.o2" to "Si elle rend bien en photo",
    "q.l17#7.o3" to "À quelle distance elle est du sol",
    "q.l17#7.e" to "La résistance d'une broche vient de la glace, pas de la technique. Une broche dans un vide ou dans de la glace alvéolée tient à peine une chute — c'est la différence la plus fondamentale entre la protection sur glace et sur rocher.",

    "q.l17#8.p" to "Vos avant-bras se congestionnent dans une longueur de glace. Que faire ?",
    "q.l17#8.o0" to "Grimper plus vite pour passer",
    "q.l17#8.o1" to "Rejoindre une stance au plus vite, mettre son poids sur les pieds et secouer les bras",
    "q.l17#8.o2" to "Serrer plus fort pour rester stable",
    "q.l17#8.o3" to "Redescendre immédiatement",
    "q.l17#8.e" to "La congestion est une ischémie de l'avant-bras ; continuer et vous perdez complètement la prise. La bonne réaction est de reporter son poids sur les pieds tant qu'on contrôle encore et de laisser le sang revenir — c'est exactement ce que signifie en pratique « ne pas laisser ses pieds paresseux ».",

    "q.l17#9.p" to "[Association] Associez chaque cotation WI de glace à son caractère typique.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.r0" to "Glace soutenue autour de 60° avec des bombements possibles ; bonne protection",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.r1" to "Soutenue à 60–75° ; protection généralement bonne mais éprouvante",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.r2" to "Presque vertical avec de courts passages verticaux ; protection parfois médiocre",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r3" to "Vertical soutenu ; protection médiocre et très exigeant",
    "q.l17#9.e" to "Une cotation WI combine trois variables : l'angle, la qualité de la protection et le coût physique. Plus la cotation est élevée, moins il reste de marge pour reculer ou s'autosauver — c'est pourquoi la cotation n'est qu'une référence et que la glace du jour et l'état de la cordée décident du résultat.",

    "q.l17#10.p" to "[Choix multiple] Quel matériel doit être sur le baudrier, à portée de main, en escalade sur glace ?",
    "q.l17#10.o0" to "Plusieurs broches à glace",
    "q.l17#10.o1" to "Mousquetons et dégaines",
    "q.l17#10.o2" to "Cordelette de prussik",
    "q.l17#10.o3" to "Un dispositif d'assurage",
    "q.l17#10.o4" to "Un sac de couchage de rechange",
    "q.l17#10.e" to "L'escalade sur glace consiste à construire sa protection en avançant : tout ce qui est enfoui dans le sac n'existe pas. La liste de matériel de sauvetage du manuel — broches, mousquetons, sangles, poulie, prussiks, bloqueur — suit la même logique : tout ce dont on peut avoir besoin reste à portée de main.",

    "q.l17#11.p" to "Pourquoi une broche à glace peut-elle arracher ?",
    "q.l17#11.o0" to "Parce que la broche est trop courte",
    "q.l17#11.o1" to "Parce que la glace elle-même peut contenir des vides, être alvéolée ou fondre, et ne pas tenir",
    "q.l17#11.o2" to "Parce qu'on y accroche trop de choses",
    "q.l17#11.o3" to "Parce que la broche est émoussée",
    "q.l17#11.e" to "La résistance vient de la glace, pas du placement. Une broche dans un vide ou dans de la glace alvéolée tient à peine une chute — la différence essentielle avec la protection sur rocher, et la raison pour laquelle on vérifie la glace avant de placer.",

    "q.l17#12.p" to "Pourquoi une cotation de glace n'est-elle qu'une référence ?",
    "q.l17#12.o0" to "Parce que les cotations sont arbitraires",
    "q.l17#12.o1" to "Parce que la glace change chaque jour — soleil, température et saison peuvent modifier nettement un même itinéraire",
    "q.l17#12.o2" to "Parce que les cotations diffèrent selon les pays",
    "q.l17#12.o3" to "Parce que les cotations ne décrivent que la longueur",
    "q.l17#12.e" to "La glace est fonction de la température : la glace dure du matin exige des placements précis, tandis que la glace molle de l'après-midi paraît facile mais ses broches arrachent plus facilement. Un même itinéraire peut varier de plus d'une cotation — ce que vous voyez devant vous prime donc toujours sur le chiffre du topo.",

    "q.l17#13.p" to "[Ordre] Remettez dans l'ordre le rythme de progression en trois points sur glace.",
    "q.l17#13.o0" to "Lire la glace et choisir où iront le piolet et les pieds",
    "q.l17#13.o1" to "Planter les pointes avant pour établir les deux pieds",
    "q.l17#13.o2" to "Une fois les pieds stables, frapper avec le piolet et vérifier qu'il tient",
    "q.l17#13.o3" to "Avec trois points stables, déplacer le quatrième",
    "q.l17#13.e" to "Cet ordre explique pourquoi « ne pas laisser ses pieds paresseux » est la discipline centrale de l'escalade sur glace : les pieds portent le poids pendant des heures, les bras ne font qu'aider. Frapper avant d'avoir posé les pieds épuise les bras trop tôt — sur glace raide, c'est fatal.",

    // ---------- l18 Avalanches ----------
    "q.l18#0.p" to "Sur quelles pentes les avalanches se concentrent-elles le plus ?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "La glace verticale",
    "q.l18#0.e" to "Les statistiques montrent que la grande majorité des avalanches se produisent entre 34° et 45° (96 % entre 30° et 50°). C'est juste assez raide pour glisser tout en permettant à la neige de s'accumuler — la fenêtre de danger, et l'angle que les itinéraires d'alpinisme traversent le plus souvent.",

    "q.l18#1.p" to "Pourquoi la plupart des accidents arrivent-ils au degré 3, marqué ?",
    "q.l18#1.o0" to "Parce que le manteau neigeux est alors le plus instable",
    "q.l18#1.o1" to "Parce que les conditions paraissent acceptables et sont le plus facilement sous-estimées",
    "q.l18#1.o2" to "Parce que tout le monde reste chez soi",
    "q.l18#1.o3" to "Parce que le bulletin est inexact",
    "q.l18#1.e" to "Le paradoxe du degré 3 est que les avalanches sont réellement possibles alors que le terrain paraît « correct » : beaucoup de gens entrent donc en terrain avalancheux. Aux degrés 4 et 5, la plupart restent à l'écart, et la part des accidents baisse. La situation la plus dangereuse n'est jamais l'extrême — c'est la modérée que l'on sous-estime.",

    "q.l18#2.p" to "Qu'est-ce que le trio avalanche ?",
    "q.l18#2.o0" to "DVA (détecteur de victimes d'avalanche), sonde et pelle",
    "q.l18#2.o1" to "Casque, corde et baudrier",
    "q.l18#2.o2" to "Piolet, crampons et broches à glace",
    "q.l18#2.o3" to "Tente, sac de couchage et matelas",
    "q.l18#2.e" to "Le DVA localise, la sonde précise et la pelle déblaie. Les trois sont nécessaires, et les trois doivent être pratiqués si l'on veut réussir un sauvetage dans la fenêtre d'or d'une dizaine de minutes.",

    "q.l18#3.p" to "Pourquoi les pentes qui ne paraissent pas raides sont-elles souvent les plus dangereuses ?",
    "q.l18#3.o0" to "Parce que la neige y est plus profonde",
    "q.l18#3.o1" to "Parce que c'est entre 34 et 45° que les avalanches se concentrent, et que l'on sous-estime systématiquement l'angle",
    "q.l18#3.o2" to "Parce qu'on y circule plus vite",
    "q.l18#3.o3" to "Parce que le soleil y est plus fort",
    "q.l18#3.e" to "En dessous d'environ 30°, la pente est trop faible pour les avalanches de plaque ; au-dessus d'environ 50°, la neige ne s'accumule pas. La fenêtre de danger tombe exactement dans la plage qui paraît praticable — c'est précisément pour cela qu'elle est sous-estimée.",

    "q.l18#4.p" to "Quelle est la bonne façon de traverser un terrain avalancheux ?",
    "q.l18#4.o0" to "Faire passer toute la cordée rapidement, ensemble",
    "q.l18#4.o1" to "S'espacer, passer un par un, poster un guetteur et prévoir un itinéraire de dégagement",
    "q.l18#4.o2" to "Prendre la ligne la plus courte au fond du vallon",
    "q.l18#4.o3" to "Rester là où la neige est la plus profonde",
    "q.l18#4.e" to "Passer un par un limite le risque à une seule personne, et un guetteur peut localiser et organiser le sauvetage immédiatement. Traverser tous ensemble signifie qu'un seul déclenchement ensevelit toute la cordée — le pire résultat possible.",

    "q.l18#5.p" to "Vous entendez un « whumpf » : le manteau s'affaisse. Qu'est-ce que cela signifie ?",
    "q.l18#5.o0" to "Vous avez simplement mis le pied dans un trou",
    "q.l18#5.o1" to "Il y a une couche faible facilement déclenchable et le manteau est instable",
    "q.l18#5.o2" to "La neige est profonde et la progression est bonne",
    "q.l18#5.o3" to "Le manteau s'est stabilisé",
    "q.l18#5.e" to "Un « whumpf » est le bruit du manteau qui s'affaisse quand une couche faible cède. C'est un signal de stabilité très direct — continuer sur cette pente revient à se servir de soi-même pour tester si elle va partir en plaque.",

    "q.l18#6.p" to "Pourquoi les avalanches de plaque sont-elles plus meurtrières que les avalanches de neige meuble ?",
    "q.l18#6.o0" to "Parce qu'elles sont plus froides",
    "q.l18#6.o1" to "Toute une plaque part d'un coup et vous ensevelit, ne laissant presque aucune chance d'auto-sauvetage",
    "q.l18#6.o2" to "Parce qu'elles font plus de bruit",
    "q.l18#6.o3" to "Parce qu'elles sont plus fréquentes",
    "q.l18#6.e" to "Une plaque casse sur toute la pente d'un seul coup : vous perdez votre appui alors que vous êtes encore sur la face. Une fois enseveli, le poids de la neige et sa prise en masse rapide rendent l'auto-sauvetage presque impossible — d'où la nécessité d'un sauvetage immédiat par les compagnons.",

    "q.l18#7.p" to "Comment porter et utiliser un DVA ?",
    "q.l18#7.o0" to "N'importe où dans le sac, cela suffit",
    "q.l18#7.o1" to "Vérifier mutuellement le mode émission avant de partir, et répéter régulièrement les routines de recherche",
    "q.l18#7.o2" to "Le porter uniquement sur le chef de cordée",
    "q.l18#7.o3" to "L'éteindre pour économiser la batterie",
    "q.l18#7.e" to "Un DVA dans le sac est presque inutile — sous la neige, vos bras peuvent ne plus bouger du tout : il doit donc être porté sur le corps, généralement sur la poitrine. La routine de recherche doit aussi être répétée, sinon vous ne localiserez personne dans les dix minutes d'or.",

    "q.l18#8.p" to "Avant d'entrer en terrain avalancheux, quelle est la préparation la plus importante ?",
    "q.l18#8.o0" to "Avoir tout le matériel suffit",
    "q.l18#8.o1" to "Lire le bulletin d'avalanche du jour et ajuster en continu l'itinéraire et le plan selon les observations de terrain",
    "q.l18#8.o2" to "Faire entièrement confiance à son expérience personnelle",
    "q.l18#8.o3" to "Suivre les traces laissées par d'autres",
    "q.l18#8.e" to "Le bulletin donne un jugement régional, l'observation de terrain donne une preuve à l'échelle de la pente : il faut les deux. Suivre d'anciennes traces est particulièrement dangereux — elles peuvent dater de plusieurs heures, et le manteau a déjà changé.",

    "q.l18#9.p" to "Selon les statistiques, quelle cause provoque le plus de décès en alpinisme ?",
    "q.l18#9.o0" to "L'avalanche d'abord, puis les chutes",
    "q.l18#9.o1" to "Les chutes d'abord, puis l'avalanche",
    "q.l18#9.o2" to "La maladie d'abord, puis les chutes de pierres",
    "q.l18#9.o3" to "L'hypothermie d'abord, puis l'avalanche",
    "q.l18#9.e" to "Le manuel est explicite : les chutes d'abord, l'avalanche ensuite. Cet ordre compte — l'avalanche fait le plus peur, mais c'est la glissade ordinaire qui tue le plus. Classez les risques par les données, pas par l'impression.",

    "q.l18#10.p" to "Après un ensevelissement, combien de temps dure environ la fenêtre d'or ?",
    "q.l18#10.o0" to "Environ dix à quinze minutes",
    "q.l18#10.o1" to "Deux heures",
    "q.l18#10.o2" to "Six heures",
    "q.l18#10.o3" to "24 heures",
    "q.l18#10.e" to "Dix à quinze minutes — une échelle de temps qui implique que le sauvetage doit être fait par les compagnons, car les secours organisés arriveront bien trop tard. C'est pourquoi le trio doit être porté et pratiqué, et pas seulement rangé dans le sac.",

    "q.l18#11.p" to "[Choix multiple] Quels signaux de terrain faut-il surveiller pour évaluer le risque d'avalanche ?",
    "q.l18#11.o0" to "Un « whumpf » quand le manteau s'affaisse",
    "q.l18#11.o1" to "Des fissures fraîches qui apparaissent sur la pente",
    "q.l18#11.o2" to "De la neige fraîche récente ou une accumulation évidente par le vent",
    "q.l18#11.o3" to "Des bruits d'affaissement et un enfoncement sous les pas à la montée",
    "q.l18#11.o4" to "Des cirrus et une excellente visibilité",
    "q.l18#11.e" to "Ce sont des preuves directes que la stabilité baisse en ce moment même. Leur valeur est l'immédiateté : le bulletin donne une image régionale, ces signaux décrivent la pente sous vos pieds à cet instant. Il faut les deux.",

    "q.l18#12.p" to "L'image montre trois parties de la même montagne. Touchez la partie au risque d'avalanche le plus élevé.",
    "q.l18#12.e" to "Les avalanches se concentrent entre 34° et 45°. La pente douce de gauche (environ 16°) est trop plate pour les avalanches de plaque ; celle de droite, raide (environ 60°), est trop inclinée pour que la neige forme une plaque épaisse. Seule la pente du milieu, à environ 40°, se trouve dans la fenêtre où la neige s'accumule et peut glisser — et c'est exactement l'angle que les itinéraires d'alpinisme traversent le plus souvent, d'où la facilité à le sous-estimer.",
    // ---------- l19 Planification et demi-tour ----------
    "q.l19#0.p" to "À quoi sert de fixer une heure de demi-tour ?",
    "q.l19#0.o0" to "À faire demi-tour sans condition à cette heure-là et à éviter d'être pris en otage par l'objectif",
    "q.l19#0.o1" to "À calculer sa vitesse d'ascension",
    "q.l19#0.o2" to "À décider de la quantité de nourriture à emporter",
    "q.l19#0.o3" to "À une formalité",
    "q.l19#0.e" to "Une heure de demi-tour retire la décision à l'émotion du moment : une règle fixée quand vous étiez rationnel impose le jugement à votre place quand vous êtes fatigué et réticent. C'est l'outil le plus efficace contre la fièvre du sommet.",

    "q.l19#1.p" to "Qu'est-ce qui provoque typiquement la fièvre du sommet ?",
    "q.l19#1.o0" to "Un temps très favorable",
    "q.l19#1.o1" to "Le poids des efforts déjà investis, plus la pression du groupe, qui déforment le jugement",
    "q.l19#1.o2" to "Un matériel insuffisant",
    "q.l19#1.o3" to "Une altitude trop basse",
    "q.l19#1.e" to "Le temps, l'argent et l'énergie déjà engagés rendent difficile d'admettre qu'il faut s'arrêter ; le silence ou les encouragements mutuels dans la cordée étouffent encore le doute. Comprendre ce mécanisme est la condition pour fixer à l'avance des règles objectives.",

    "q.l19#2.p" to "Quand une cordée doit-elle fixer sa décision de repli ?",
    "q.l19#2.o0" to "Avant le départ, en convenant de déclencheurs objectifs et de qui décide",
    "q.l19#2.o1" to "Au sommet",
    "q.l19#2.o2" to "Quand le danger apparaît, en improvisant",
    "q.l19#2.o3" to "Sur place, par la personne la plus en forme",
    "q.l19#2.e" to "Débattre du repli quand on est fatigué, en hypoxie et sous le coup de l'émotion penche presque toujours vers la poursuite. Convenez à l'avance de déclencheurs objectifs — une heure, un changement de météo, un type d'état de la cordée — et nommez qui a le dernier mot.",

    "q.l19#3.p" to "Pourquoi tant d'accidents arrivent-ils à la descente ?",
    "q.l19#3.o0" to "Parce que le terrain descendant est plus dur",
    "q.l19#3.o1" to "Parce que la vigilance baisse une fois l'objectif atteint, alors que le corps est déjà près de ses limites",
    "q.l19#3.o2" to "Parce que le temps est toujours plus mauvais à la descente",
    "q.l19#3.o3" to "Parce que le matériel lâche",
    "q.l19#3.e" to "« Le sommet n'est que la moitié du chemin » signifie en réalité que le risque de la course se libère à la descente. On ne peut pas relâcher l'encordement, l'assurage et l'allure à la descente simplement parce qu'on a atteint le sommet.",

    "q.l19#4.p" to "Quelle est la valeur de fixer la décision de repli à l'avance ?",
    "q.l19#4.o0" to "Cela fait gagner du temps",
    "q.l19#4.o1" to "Cela retire la décision à la fatigue et à l'émotion et laisse s'appliquer le jugement d'avant le départ",
    "q.l19#4.o2" to "Cela donne plus d'autorité au chef de cordée",
    "q.l19#4.o3" to "Cela évite les disputes",
    "q.l19#4.e" to "Décider en hypoxie, fatigué et réticent penche presque toujours vers la poursuite. Convenir à l'avance de déclencheurs objectifs et de qui décide, c'est laisser la version calme de vous-même décider pour la version épuisée.",

    "q.l19#5.p" to "Pourquoi un plan de repli doit-il figurer dans le plan de course ?",
    "q.l19#5.o0" to "Pour que le plan paraisse complet",
    "q.l19#5.o1" to "Le repli demande du matériel, un itinéraire et un budget de temps ; une décision improvisée ne laisse pas le temps de se préparer",
    "q.l19#5.o2" to "Pour satisfaire un contrôle",
    "q.l19#5.o3" to "Parce que la réglementation l'exige",
    "q.l19#5.e" to "Le repli est une véritable opération technique : il peut demander un ancrage, un rappel et une progression de nuit. Si le plan n'a jamais prévu de temps ni de matériel pour cela, le repli devient une improvisation à haut risque.",

    "q.l19#6.p" to "Quand les membres de la cordée ne sont pas d'accord sur l'itinéraire ou la météo, quelle est la bonne approche ?",
    "q.l19#6.o0" to "Le vote à la majorité",
    "q.l19#6.o1" to "Retenir l'avis le plus prudent jusqu'à ce que de nouveaux éléments convainquent tout le monde",
    "q.l19#6.o2" to "Laisser décider la personne la plus en forme",
    "q.l19#6.o3" to "Voter, puis arrêter d'en parler",
    "q.l19#6.e" to "Dans un contexte à haut risque, l'avis le plus prudent doit peser. Le vote majoritaire étouffe l'inquiétude légitime d'une minorité — et la phrase la plus fréquente dans les rapports d'accident est « quelqu'un sentait que ça n'allait pas, mais personne n'a rien dit ».",

    "q.l19#7.p" to "Quelle vision de « avec un guide, on est en sécurité » est correcte ?",
    "q.l19#7.o0" to "Un guide vous rend absolument en sécurité",
    "q.l19#7.o1" to "Un guide réduit le risque mais ne supprime pas les dangers objectifs ; les membres doivent continuer à juger",
    "q.l19#7.o2" to "Les guides ne montrent que le chemin ; la sécurité est votre affaire",
    "q.l19#7.o3" to "Les membres n'ont plus rien à évaluer",
    "q.l19#7.e" to "La valeur d'un guide, c'est l'expérience et la qualité des décisions, mais les avalanches, les chutes de pierres et la météo ne disparaissent pas parce que quelqu'un mène. Des membres qui comprennent le risque, repèrent les signes de danger et s'expriment font eux-mêmes partie de la capacité de sécurité de la cordée.",

    "q.l19#8.p" to "Qu'est-ce que la dérive des objectifs en alpinisme ?",
    "q.l19#8.o0" to "Abaisser la cotation de difficulté de l'itinéraire",
    "q.l19#8.o1" to "Relâcher peu à peu les critères de sécurité que l'on s'était fixés, pour atteindre le sommet",
    "q.l19#8.o2" to "Changer de sommet en cours de course",
    "q.l19#8.o3" to "Réduire la taille de la cordée",
    "q.l19#8.e" to "La dérive des objectifs est la signature classique de la fièvre du sommet : l'heure de demi-tour glisse sans cesse, la fenêtre météo acceptable s'élargit sans cesse, les symptômes sont supportés sans cesse. La seule défense est de chiffrer les critères à l'avance, pour que les relâcher devienne explicite et doive être justifié devant ses compagnons.",

    "q.l19#9.p" to "[Choix multiple] Que doit contenir un plan de course complet ?",
    "q.l19#9.o0" to "L'itinéraire et le programme, dont l'heure de demi-tour",
    "q.l19#9.o1" to "Le plan de repli et les itinéraires de substitution",
    "q.l19#9.o2" to "L'évaluation de l'état de la cordée et la répartition des rôles",
    "q.l19#9.o3" to "Le moyen de communication, la personne de contact et la procédure d'urgence",
    "q.l19#9.o4" to "Un plan média et de communication",
    "q.l19#9.e" to "Les quatre premiers sont tous nécessaires. Les plus souvent oubliés sont le deuxième et le quatrième — parce qu'on n'en a pas besoin quand tout va bien. Or un plan prend toute sa valeur précisément quand les choses vont mal, et à ce moment-là il n'y a plus le temps de l'écrire.",

    "q.l19#10.p" to "Pourquoi prévoir des jours de marge dans un itinéraire ?",
    "q.l19#10.o0" to "Pour absorber les retards : fenêtre météo plus tardive, membre de la cordée indisposé",
    "q.l19#10.o1" to "Pour se reposer davantage",
    "q.l19#10.o2" to "Pour économiser de l'argent",
    "q.l19#10.o3" to "Pour que l'itinéraire paraisse confortable",
    "q.l19#10.e" to "Les courses en haute altitude glissent presque toujours : la météo refuse de coopérer, quelqu'un a besoin d'un jour d'acclimatation supplémentaire, l'approche est plus lente que prévu. Sans marge, tout retard oblige à rogner sur l'acclimatation ou à allonger les étapes — deux choix qui augmentent nettement le risque.",

    "q.l19#11.p" to "[Ordre] Remettez dans un ordre logique les étapes de construction d'un plan de course.",
    "q.l19#11.o0" to "Fixer l'objectif et l'itinéraire ; rassembler les informations et l'historique météo",
    "q.l19#11.o1" to "Évaluer les capacités et le temps de la cordée ; programmer le rythme d'acclimatation",
    "q.l19#11.o2" to "Fixer l'heure de demi-tour et des déclencheurs de repli quantifiables",
    "q.l19#11.o3" to "Écrire le plan de repli et la procédure d'urgence, et briefer le contact à la maison",
    "q.l19#11.e" to "L'ordre dit : fixer l'objectif, vérifier les capacités, tracer la ligne rouge, puis garder la sortie. Beaucoup font l'inverse — objectif d'abord, sortie en dernier — et c'est pourquoi la sortie finit en bas de la liste et n'est jamais vraiment conçue.",

    "q.l19#12.p" to "Pourquoi le temps de descente est-il si souvent sous-estimé ?",
    "q.l19#12.o0" to "Parce que descendre est plus rapide",
    "q.l19#12.o1" to "Parce qu'on est épuisé, que la neige peut être pire, et qu'il faut encore assurer et récupérer le matériel",
    "q.l19#12.o2" to "Parce que les cartes sont imprécises",
    "q.l19#12.o3" to "Parce que les guides vous pressent",
    "q.l19#12.e" to "L'ascension a peut-être pris six heures, mais la descente en prend souvent plus : moins d'énergie, neige plus molle ou plus glacée, visibilité moins bonne, et parfois des rappels et la récupération du matériel. Estimer la descente à partir du temps de montée est l'une des erreurs de planification les plus courantes.",

    "q.l19#13.p" to "Pourquoi détailler les dispositions de communication et de contact dans le plan ?",
    "q.l19#13.o0" to "Pour la traçabilité",
    "q.l19#13.o1" to "Parce que si vous disparaissez, ceux qui restent doivent savoir où chercher et quand commencer",
    "q.l19#13.o2" to "Pour rendre compte à l'entreprise",
    "q.l19#13.o3" to "Pour satisfaire aux exigences de permis",
    "q.l19#13.e" to "Le plus difficile en recherche et sauvetage, c'est de ne pas savoir où se trouve la personne. Itinéraire, voie, variantes et heures de pointage sont ce qui comprime une recherche de plusieurs jours à quelques heures — et ces informations ne peuvent être fournies qu'avant le départ.",

    "q.l19#14.p" to "Comment la taille de la cordée influe-t-elle sur le plan ?",
    "q.l19#14.o0" to "La taille n'a aucun rapport avec la planification",
    "q.l19#14.o1" to "Plus de personnes signifie progression plus lente, logistique plus lourde et acclimatation plus difficile à synchroniser",
    "q.l19#14.o2" to "Plus de personnes est plus sûr, donc aucun ajustement n'est nécessaire",
    "q.l19#14.o3" to "Plus de personnes est plus rapide",
    "q.l19#14.e" to "Une cordée nombreuse partage les forces et les ressources, au prix de la vitesse et de la souplesse : chacun a son rythme, et le groupe ne peut avancer qu'au rythme du plus lent. La taille de la cordée fait partie de l'estimation du temps — pas des reproches ultérieurs.",

    "q.l19#15.p" to "Complétez : les itinéraires en haute altitude prévoient en général environ ( ) % de jours de marge.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "vingt",
    "q.l19#15.e" to "La recommandation habituelle est une marge de 20 à 30 %. Une course de dix jours, par exemple, doit être planifiée sur douze ou treize jours pour les vivres, les congés et les permis — ce qui paraît excessif jusqu'à ce qu'on le compare à la fréquence réelle des retards.",

    // ---------- l20 Secours et premiers secours ----------
    "q.l20#0.p" to "Quel est le premier principe du sauvetage ?",
    "q.l20#0.o0" to "Déplacer la victime le plus vite possible",
    "q.l20#0.o1" to "Sécuriser la scène pour ne pas créer une seconde victime",
    "q.l20#0.o2" to "Photographier la scène d'abord",
    "q.l20#0.o3" to "Donner d'abord à boire à la victime",
    "q.l20#0.e" to "Autour de chutes de pierres, d'avalanches, de crevasses ou de terrain raide, se précipiter vers la victime transforme souvent le sauveteur en seconde victime et réduit de moitié la main-d'œuvre disponible. Évaluer la scène est la première étape, celle qu'on ne peut pas sauter.",

    "q.l20#1.p" to "Par où commence la bonne séquence d'urgence ?",
    "q.l20#1.o0" to "Sécuriser d'abord la scène, puis évaluer les blessures",
    "q.l20#1.o1" to "Déplacer d'abord la victime en lieu sûr",
    "q.l20#1.o2" to "Chercher de la nourriture et de l'eau",
    "q.l20#1.o3" to "Construire un système de corde",
    "q.l20#1.e" to "La séquence standard est : sécurité, évaluation, appel à l'aide, traitement, transfert. Sauter l'évaluation de sécurité et aller droit à la victime est l'erreur de sauvetage la plus courante.",

    "q.l20#2.p" to "Pourquoi la prévention compte-t-elle bien plus que le sauvetage en altitude ?",
    "q.l20#2.o0" to "Parce que le sauvetage coûte cher",
    "q.l20#2.o1" to "Parce que le sauvetage est limité par la météo, l'oxygène et les effectifs, et n'arrive souvent pas à temps",
    "q.l20#2.o2" to "Parce que les équipes de secours ne veulent pas venir",
    "q.l20#2.o3" to "Parce qu'il n'y a pas de réseau téléphonique",
    "q.l20#2.e" to "L'altitude dégrade les deux côtés : les hélicoptères sont limités par les turbulences et l'altitude, les équipes au sol mettent des heures à arriver, et une victime se dégrade plus vite en hypoxie et au froid. Cet écart de temps est la seule ressource de sauvetage dont vous disposez vraiment.",

    "q.l20#3.p" to "Pourquoi un secours en montagne prend-il souvent des heures ou des jours ?",
    "q.l20#3.o0" to "Parce que les équipes ne veulent pas partir",
    "q.l20#3.o1" to "Des limites strictes tenant à la météo, à l'oxygène, aux communications et aux effectifs ; les hélicoptères sont contraints par les turbulences et l'altitude",
    "q.l20#3.o2" to "Parce que les distances sont trop grandes",
    "q.l20#3.o3" to "Parce que cela coûte trop cher",
    "q.l20#3.e" to "En altitude, un hélicoptère peine avec la portance et les turbulences, et une équipe au sol a besoin de plusieurs heures pour vous rejoindre. Cet écart signifie une chose : là-haut, vous êtes votre propre première équipe de secours.",

    "q.l20#4.p" to "À quoi sert de laisser un itinéraire et une personne de contact ?",
    "q.l20#4.o0" to "À une formalité",
    "q.l20#4.o1" to "Si vous disparaissez, les secours savent où chercher, ce qui raccourcit nettement la recherche",
    "q.l20#4.o2" to "À faciliter les notes de frais",
    "q.l20#4.o3" to "À respecter les règles",
    "q.l20#4.e" to "Le plus difficile en recherche et sauvetage, c'est de ne pas savoir où se trouve la personne. Itinéraire, voie, plans de repli et dispositions de contact sont ce qui comprime une recherche de plusieurs jours à quelques heures.",

    "q.l20#5.p" to "Dans l'évaluation d'une victime, qu'est-ce qui est traité en premier ?",
    "q.l20#5.o0" to "L'immobilisation des fractures",
    "q.l20#5.o1" to "Les problèmes mettant la vie en jeu, comme les voies aériennes et la respiration",
    "q.l20#5.o2" to "La description détaillée des lésions",
    "q.l20#5.o3" to "Le nettoyage des plaies visibles",
    "q.l20#5.e" to "L'évaluation suit l'ordre des menaces vitales : voies aériennes, respiration et circulation avant les fractures et les plaies qui ne tuent pas immédiatement. Si l'ordre est faux, tout le reste compte beaucoup moins.",

    "q.l20#6.p" to "En altitude, pourquoi l'isolation est-elle une part critique des premiers secours ?",
    "q.l20#6.o0" to "Parce que cela met la victime à l'aise",
    "q.l20#6.o1" to "Parce qu'une victime immobilisée perd vite sa chaleur, ce qui aggrave la lésion",
    "q.l20#6.o2" to "Parce que la réglementation l'exige",
    "q.l20#6.o3" to "Pour faciliter le transport",
    "q.l20#6.e" to "Dans le froid et l'hypoxie, une victime qui ne peut pas bouger perd vite sa production de chaleur. L'hypothermie aggrave l'état de choc et masque les symptômes : isoler du sol, couper le vent et changer les vêtements mouillés comptent autant que d'arrêter un saignement.",

    "q.l20#7.p" to "Que doit prévoir le plan d'urgence de la cordée en cas de perte des communications ?",
    "q.l20#7.o0" to "Attendre sur place que le contact revienne",
    "q.l20#7.o1" to "Convenir à l'avance d'un point de rendez-vous, d'une heure limite sans nouvelles et des actions qui suivent",
    "q.l20#7.o2" to "Se séparer et chercher immédiatement",
    "q.l20#7.o3" to "Que tout le monde redescende tout de suite",
    "q.l20#7.e" to "Perdre les communications en montagne est normal, pas exceptionnel. Convenir à l'avance de ce qui se passe si vous n'avez pas donné de nouvelles à une certaine heure évite la panique en bas et indique au contact à la maison quand donner l'alerte.",

    "q.l20#8.p" to "Quelle est la bonne attitude vis-à-vis de la formation aux premiers secours et au sauvetage ?",
    "q.l20#8.o0" to "Regarder un tutoriel et mémoriser les étapes suffit",
    "q.l20#8.o1" to "Il faut s'entraîner en pratique régulièrement ; la lecture seule ne tient pas face à une scène réelle",
    "q.l20#8.o2" to "Seul le chef de cordée en a besoin",
    "q.l20#8.o3" to "Cela ne concerne que les secouristes professionnels",
    "q.l20#8.e" to "Les premiers secours et le sauvetage sont des compétences très procédurales, et sous pression on retombe au niveau où l'on s'est réellement entraîné. Lire construit le cadre ; seule une répétition régulière garde les gestes justes quand on a peur.",

    "q.l20#9.p" to "[Ordre] Remettez dans l'ordre la séquence standard d'évaluation et de traitement d'une victime.",
    "q.l20#9.o0" to "Sécuriser la scène pour ne pas créer une seconde victime",
    "q.l20#9.o1" to "Évaluer la conscience, les voies aériennes, la respiration et la circulation",
    "q.l20#9.o2" to "Traiter les menaces vitales immédiates : saignement, isolation, immobilisation",
    "q.l20#9.o3" to "Appeler à l'aide et organiser le transfert, ou attendre un secours professionnel",
    "q.l20#9.e" to "Les étapes un et quatre sont les plus souvent sautées — sous stress, on court droit vers la victime. Or une scène non sécurisée transforme le sauveteur en seconde victime et divise par deux la main-d'œuvre, et sans appel à l'aide il n'y a aucun renfort pour la suite.",

    "q.l20#10.p" to "[Choix multiple] Quelles informations clés un appel à l'aide doit-il contenir ?",
    "q.l20#10.o0" to "La localisation exacte (coordonnées ou repère identifiable)",
    "q.l20#10.o1" to "Le nombre de victimes, la conscience et l'état respiratoire",
    "q.l20#10.o2" to "Le terrain et la météo sur place",
    "q.l20#10.o3" to "Le moyen de communication disponible et les heures de pointage",
    "q.l20#10.o4" to "Le palmarès d'alpinisme de la victime",
    "q.l20#10.e" to "Ces quatre éléments décident de ce qui est envoyé, en quelle quantité et par quelle voie. Une localisation vague fait perdre des heures, des lésions inconnues signifient du matériel inadapté, et une météo inconnue peut mettre l'équipe de secours en danger à son tour. L'appel à l'aide est une compétence de communication qui mérite d'être répétée.",

    "q.l20#11.p" to "Pourquoi un sauvetage par hélicoptère est-il souvent impossible en altitude ?",
    "q.l20#11.o0" to "Parce que c'est trop cher",
    "q.l20#11.o1" to "Parce que l'air raréfié réduit la portance et la charge utile, que les turbulences sont fortes et les fenêtres météo courtes",
    "q.l20#11.o2" to "Parce que les pilotes refusent d'y voler",
    "q.l20#11.o3" to "Parce qu'il n'y a pas de couloirs aériens en altitude",
    "q.l20#11.e" to "La portance d'un hélicoptère vient de l'air, et l'air est raréfié là-haut — ce qui limite directement ce qu'il peut soulever et jusqu'où il peut opérer. Ajoutez un air montagneux turbulent et une météo qui change vite : la fenêtre de vol peut se réduire à quelques dizaines de minutes. C'est pourquoi le sauvetage ne peut pas être votre plan.",

    "q.l20#12.p" to "[Association] Associez chaque geste de premiers secours au moment où il s'applique.",
    "q.l20#12.l0" to "Isolation",
    "q.l20#12.r0" to "Priorité pour toute victime en altitude, pour éviter que l'hypothermie aggrave l'état de choc",
    "q.l20#12.l1" to "Contrôle d'un saignement",
    "q.l20#12.r1" to "Première réponse à une plaie ouverte ou à un saignement de membre",
    "q.l20#12.l2" to "Immobilisation",
    "q.l20#12.r2" to "Suspicion de fracture ou de lésion articulaire, pour éviter d'aggraver en déplaçant",
    "q.l20#12.l3" to "Oxygène",
    "q.l20#12.r3" to "Difficulté respiratoire, saturation manifestement basse ou suspicion d'œdème pulmonaire",
    "q.l20#12.e" to "Ces quatre gestes sont des actions de base en altitude, pas des procédures de spécialiste. Ce qu'ils ont en commun : ils ne demandent aucun matériel complexe mais exigent le bon ordre — l'isolation, par exemple, arrive souvent tard dans les premiers secours généraux, alors qu'elle est prioritaire là-haut.",

    "q.l20#13.p" to "Pourquoi évaluer le risque du sauvetage lui-même ?",
    "q.l20#13.o0" to "Parce que secourir est fatigant",
    "q.l20#13.o1" to "Parce que le sauvetage peut mettre plus de personnes en danger et réduire les chances globales de survie",
    "q.l20#13.o2" to "Parce que l'assurance l'exige",
    "q.l20#13.o3" to "Parce que la réglementation l'exige",
    "q.l20#13.e" to "Une décision de sauvetage est une allocation de ressources : si atteindre la victime blesse deux sauveteurs, on passe d'une victime et deux sauveteurs à trois victimes et personne. Ce n'est pas de la froideur, c'est l'arithmétique qui maximise la survie globale.",

    "q.l20#14.p" to "Quand faut-il arrêter l'auto-sauvetage et attendre un secours professionnel ?",
    "q.l20#14.o0" to "Continuer l'auto-sauvetage tant qu'on a des forces",
    "q.l20#14.o1" to "Quand l'auto-sauvetage risque d'aggraver les lésions, ou que les conditions dépassent les capacités de la cordée",
    "q.l20#14.o2" to "Seulement quand on est complètement épuisé",
    "q.l20#14.o3" to "Ne jamais arrêter l'auto-sauvetage",
    "q.l20#14.e" to "L'auto-sauvetage sert à gagner du temps, pas à prendre des risques. Quand continuer pourrait blesser plus gravement la victime ou les sauveteurs, ou quand une tempête rend le déplacement plus risqué que l'immobilité, tenir la situation et attendre des renforts est la meilleure réponse.",

    "q.l20#15.p" to "Complétez : dans l'évaluation SAMPLE, le E correspond à ( ).",
    "q.l20#15.a0" to "événement",
    "q.l20#15.a1" to "Événement",
    "q.l20#15.a2" to "l'événement",
    "q.l20#15.a3" to "incident",
    "q.l20#15.e" to "E signifie Event — ce qui s'est passé. Cet item est souvent sous-estimé : le mécanisme (comment la chute s'est produite, si la tête a été heurtée, combien de temps a duré l'ensevelissement) oriente directement vers les lésions probables et constitue un indice clé de l'évaluation.",
    // ---------- l21 Équipement : système trois couches ----------
    "q.l21#0.p" to "Dans un système trois couches, quel est le rôle principal de la première couche ?",
    "q.l21#0.o0" to "Bloquer le vent et la neige",
    "q.l21#0.o1" to "Évacuer la sueur loin de la peau et vous garder au sec",
    "q.l21#0.o2" to "Fournir l'essentiel de la chaleur",
    "q.l21#0.o3" to "Ranger les objets de rechange",
    "q.l21#0.e" to "La fonction essentielle de la première couche est le transfert de l'humidité. Elle est au contact de la peau, et si elle reste humide, peu importe le nombre de couches portées par-dessus : la chaleur continue d'être évacuée — d'où son surnom de seconde peau.",

    "q.l21#1.p" to "Pourquoi la polaire est-elle plus fiable que le duvet en conditions humides ?",
    "q.l21#1.o0" to "Parce que la polaire est plus épaisse",
    "q.l21#1.o1" to "Parce que la fibre de polyester est naturellement hydrophobe et isole encore mouillée",
    "q.l21#1.o2" to "Parce que la polaire coûte moins cher",
    "q.l21#1.o3" to "Parce que le duvet ne peut pas se porter en première couche",
    "q.l21#1.e" to "La polaire est faite de fibre plastique (polyester), qui n'absorbe presque rien : elle emprisonne donc encore une couche d'air et isole lorsqu'elle est humide. Le duvet s'affaisse et perd son gonflant dès qu'il est mouillé — c'est pourquoi il doit rester strictement au sec.",

    "q.l21#2.p" to "Quel pouvoir gonflant est recommandé pour une doudoune destinée au grand froid de haute altitude ?",
    "q.l21#2.o0" to "Moins de 500",
    "q.l21#2.o1" to "Autour de 600",
    "q.l21#2.o2" to "800 de pouvoir gonflant ou plus",
    "q.l21#2.o3" to "Le pouvoir gonflant n'a pas d'importance",
    "q.l21#2.e" to "Plus le pouvoir gonflant est élevé, plus un même poids de duvet emprisonne d'air et plus l'isolation est efficace. 800 et plus est la recommandation habituelle pour les courses en haute altitude, avec une capuche et sans garnissage synthétique.",

    "q.l21#3.p" to "Quelle est la fonction essentielle d'une veste coquille ?",
    "q.l21#3.o0" to "Fournir l'essentiel de la chaleur",
    "q.l21#3.o1" to "Être imperméable, coupe-vent et respirante, avec une capuche qui passe par-dessus le casque",
    "q.l21#3.o2" to "Évacuer la sueur",
    "q.l21#3.o3" to "Ajouter du poids pour l'entraînement",
    "q.l21#3.e" to "La coquille arrête le vent, la pluie et la neige tout en laissant sortir l'humidité que vous produisez. Si la respirabilité est mauvaise, la vapeur de sueur se condense sur les couches internes — vous finissez par créer votre propre environnement humide.",

    "q.l21#4.p" to "Quel gant du système est spécialement prévu pour utiliser un écran tactile ?",
    "q.l21#4.o0" to "Des gants fins en polaire",
    "q.l21#4.o1" to "Un gant coupe-vent et résistant à l'abrasion, avec une bonne sensibilité tactile",
    "q.l21#4.o2" to "D'épais gants de guide isolés",
    "q.l21#4.o3" to "Des gants de sommet",
    "q.l21#4.e" to "Utiliser un téléphone, un GPS ou un appareil photo en altitude exige un gant à la fois coupe-vent et compatible avec l'écran tactile. Retirer ses gants pour manipuler un appareil est l'un des déclencheurs de gelure les plus fréquents — mieux vaut emporter une paire de plus exactement pour cela.",

    "q.l21#5.p" to "Quelle affirmation sur les chaufferettes pour mains et pieds est correcte ?",
    "q.l21#5.o0" to "On peut les coller n'importe où à l'extérieur des chaussettes",
    "q.l21#5.o1" to "Ne les utiliser que dans des espaces clos comme les gants ou l'intérieur des chaussures ; exposées à l'air ventilé elles peuvent atteindre environ 74 °C",
    "q.l21#5.o2" to "Le plus près de la peau est le mieux",
    "q.l21#5.o3" to "On peut les coller à l'extérieur d'un bonnet",
    "q.l21#5.e" to "Les chaufferettes comptent sur un air limité pour réguler leur température. Exposées à l'air ventilé, elles réagissent violemment et peuvent atteindre environ 74 °C, de quoi provoquer des brûlures. Elles se placent donc dans des espaces clos — gants, intérieur des chaussures — et jamais directement contre la peau ni sur une surface exposée.",

    "q.l21#6.p" to "Pourquoi recommande-t-on des vestes isolantes et des doudounes à capuche ?",
    "q.l21#6.o0" to "Parce qu'elles sont plus seyantes",
    "q.l21#6.o1" to "Parce qu'elles sont plus polyvalentes et réduisent nettement les pertes de chaleur par la tête",
    "q.l21#6.o2" to "Parce qu'elles se rangent plus facilement",
    "q.l21#6.o3" to "Parce que les versions à capuche sont plus légères",
    "q.l21#6.e" to "La tête est une source majeure de perte de chaleur, et une capuche est l'isolation la plus légère disponible directement sur le cœur du corps. Une veste à capuche s'engage instantanément au camp, aux pauses ou quand la température chute brusquement ; sans capuche, il faut emporter un bonnet séparé, plus contraignant et plus lourd.",

    "q.l21#7.p" to "[Choix multiple] Quelles pratiques sont correctes pour l'usage et le rangement d'une doudoune ?",
    "q.l21#7.o0" to "La garder strictement au sec ; une fois humide, elle perd vite son isolation",
    "q.l21#7.o1" to "La ranger sèche",
    "q.l21#7.o2" to "Par grand froid, choisir une version à capuche sans garnissage synthétique",
    "q.l21#7.o3" to "Plus le pouvoir gonflant est élevé, plus c'est chaud à poids égal",
    "q.l21#7.o4" to "La stocker à long terme dans un sac de compression pour gagner de la place",
    "q.l21#7.e" to "Le duvet isole en emprisonnant de l'air et s'affaisse une fois mouillé. C'est aussi pourquoi la polaire (polyester hydrophobe) est préférée comme couche intermédiaire de travail en conditions humides, le duvet restant l'isolation du cœur pour les environnements secs.",

    "q.l21#8.p" to "Quelle spécification est raisonnable pour une crème solaire de haute altitude ?",
    "q.l21#8.o0" to "FPS 15, une lotion ordinaire suffit",
    "q.l21#8.o1" to "Forte teneur en oxyde de zinc, niveau FPS 50",
    "q.l21#8.o2" to "En dessous de FPS 30, c'est plus respirant",
    "q.l21#8.o3" to "N'importe quel produit contenant un filtre, quel que soit l'indice",
    "q.l21#8.e" to "Les UV sont intenses en altitude et le reflet de la neige ajoute une seconde dose : une crème ordinaire cesse vite de suffire. Une forte teneur en oxyde de zinc et un FPS 50 sont la recommandation habituelle — et il faut en remettre régulièrement, car la sueur, les essuyages et les frottements dégradent tous la protection.",

    "q.l21#9.p" to "Qu'est-ce qui compte dans le choix d'un stick à lèvres pour le grand air ?",
    "q.l21#9.o0" to "Moins cher est mieux",
    "q.l21#9.o1" to "Riche en zinc, un peu résistant à la sueur, avec un FPS 30–50",
    "q.l21#9.o2" to "Hydratant, cela suffit",
    "q.l21#9.o3" to "Le menthol donne une sensation plus fraîche",
    "q.l21#9.e" to "La peau des lèvres est fine et n'a presque aucune protection mélanique : elle brûle et se fissure facilement en altitude. Le zinc apporte une protection physique, et la résistance à la sueur le maintient en place à travers la transpiration, les repas et les boissons — le plus petit équipement, le plus souvent négligé, et celui qui pèse le plus sur le confort du séjour.",

    // ---------- l22 Équipement technique et communications ----------
    "q.l22#0.p" to "Quel est l'équipement le plus fondamental pour monter un système de sauvetage en crevasse ?",
    "q.l22#0.o0" to "Des boucles de prussik (cordelette)",
    "q.l22#0.o1" to "Des jumelles",
    "q.l22#0.o2" to "Un sac de couchage de rechange",
    "q.l22#0.o3" to "Des bâtons de marche",
    "q.l22#0.e" to "Les boucles de prussik servent à nouer les nœuds autobloquants et constituent le cœur d'un système de hissage 3:1. Sans elles, il ne reste que la traction 1:1 à mains nues — et une seule personne n'arrive presque jamais à sortir son compagnon d'une crevasse à la force des bras.",

    "q.l22#1.p" to "En haute montagne, quel est généralement le moyen le plus fiable d'appeler à l'aide ?",
    "q.l22#1.o0" to "Le réseau de téléphonie mobile",
    "q.l22#1.o1" to "Un téléphone satellite ou un traceur GPS",
    "q.l22#1.o2" to "Crier",
    "q.l22#1.o3" to "Allumer un feu fumigène",
    "q.l22#1.e" to "La plupart des zones de montagne n'ont aucune couverture mobile. Un téléphone satellite permet appels et messages directs, et un traceur GPS permet à l'extérieur de suivre votre position — deux choses à régler avant le départ, pas sur la montagne.",

    "q.l22#2.p" to "Quelle luminosité est recommandée pour une lampe frontale de secours ?",
    "q.l22#2.o0" to "Moins de 100 lumens",
    "q.l22#2.o1" to "200 lumens suffisent",
    "q.l22#2.o2" to "400 lumens ou plus",
    "q.l22#2.o3" to "La luminosité n'a pas d'importance",
    "q.l22#2.e" to "Une lampe frontale sert à se déplacer autour de la tente la nuit et aux départs d'avant l'aube (les courses au sommet commencent généralement dans les premières heures). Dans le vent, la neige, le brouillard, et quand il faut identifier l'itinéraire, une luminosité suffisante influe directement sur la qualité du jugement. Les modèles étanches sont nettement meilleurs par mauvais temps.",

    "q.l22#3.p" to "Quelle est l'exigence clé dans le choix d'un baudrier d'alpinisme ?",
    "q.l22#3.o0" to "Le plus léger possible, quelle que soit la taille",
    "q.l22#3.o1" to "Assez grand à la taille et aux cuisses pour se porter par-dessus la couche la plus externe",
    "q.l22#3.o2" to "Il doit avoir plusieurs porte-matériel",
    "q.l22#3.o3" to "Une couleur bien visible",
    "q.l22#3.e" to "En altitude, on porte généralement des vêtements volumineux, et le baudrier doit encore se fermer correctement par-dessus. Un baudrier tendu à son réglage maximal juste pour fermer sur des couches épaisses est une configuration courante et dangereuse.",

    "q.l22#4.p" to "Sur quoi repose l'alarme de tempête d'une montre altimètre pour détecter les tempêtes ?",
    "q.l22#4.o0" to "L'imagerie satellite des nuages",
    "q.l22#4.o1" to "Une chute rapide de la pression atmosphérique sur une courte période",
    "q.l22#4.o2" to "La mesure de la vitesse du vent",
    "q.l22#4.o3" to "Une chute brutale de température",
    "q.l22#4.e" to "Une chute rapide de pression est le signal précurseur d'une dégradation du temps. Une montre altimètre alerte en surveillant en continu la variation de pression, ce qui est très utile en altitude — car la façon dont la fenêtre météo se décale est souvent la variable décisive d'une course.",

    "q.l22#5.p" to "[Association] Associez chaque forme de mousqueton à son usage le plus adapté.",
    "q.l22#5.l0" to "HMS en poire",
    "q.l22#5.r0" to "Grande ouverture ; reçoit un demi-cabestan pour la descente en rappel, le plus polyvalent",
    "q.l22#5.l1" to "En D",
    "q.l22#5.r1" to "Souvent associé à une poulie dans les systèmes de sauvetage",
    "q.l22#5.l2" to "En X",
    "q.l22#5.r2" to "Symétrique, verrouillage simple, facile à mousquetonner",
    "q.l22#5.l3" to "En B",
    "q.l22#5.r3" to "Le mousqueton de base pour toutes sortes de connexions temporaires",
    "q.l22#5.e" to "Chaque forme a sa force : le HMS s'ouvre assez large pour un nœud et un rappel, le D est résistant et reçoit bien une poulie, le X est symétrique et facile à manipuler, le B est la base polyvalente. Choisir un mousqueton ne consiste pas à savoir lequel est « le plus solide », mais si son mécanisme correspond au travail.",

    "q.l22#6.p" to "Lors de l'utilisation d'un bloqueur, contre quoi le manuel met-il explicitement en garde ?",
    "q.l22#6.o0" to "L'utiliser par temps humide",
    "q.l22#6.o1" to "Pousser le bloqueur trop près du point fixe (un nœud)",
    "q.l22#6.o2" to "Le manœuvrer d'une seule main",
    "q.l22#6.o3" to "L'utiliser sur la neige",
    "q.l22#6.e" to "Coller le bloqueur juste contre un nœud ou un point fixe le rend incapable d'avancer davantage tout en étant difficile à libérer rapidement : vous restez coincé là, sans pouvoir monter ni vous dégager. Ce type de blocage est très dangereux quand il faut s'ajuster vite — traitez-le tant que vous avez encore de la marge.",

    "q.l22#7.p" to "Quelle affirmation sur le choix entre corde fixe et progression en cordée est correcte ?",
    "q.l22#7.o0" to "La corde fixe est toujours plus sûre que la progression en cordée",
    "q.l22#7.o1" to "Les grosses cordées utilisent plutôt la corde fixe ; les petites cordées ou les sommets techniques sont plus efficaces encordés",
    "q.l22#7.o2" to "La progression en cordée ne convient qu'aux pentes de neige",
    "q.l22#7.o3" to "La corde fixe ne sert qu'à descendre",
    "q.l22#7.e" to "La corde fixe augmente la sécurité globale mais demande plus de monde et de matériel et prend plus de temps à installer. Une petite cordée efficace, ou un sommet technique, est souvent mieux servie par la progression encordée. C'est le cas d'école du « pas de meilleure réponse unique, seulement une adéquation ».",

    "q.l22#8.p" to "[Choix multiple] Lesquels de ces appareils servent à la communication et à la navigation en haute altitude ?",
    "q.l22#8.o0" to "Téléphone satellite",
    "q.l22#8.o1" to "Radio émetteur-récepteur",
    "q.l22#8.o2" to "Traceur GPS",
    "q.l22#8.o3" to "Montre altimètre avec baromètre",
    "q.l22#8.o4" to "Jumelles",
    "q.l22#8.e" to "Les quatre premiers font des choses différentes : le téléphone satellite pour appeler à l'aide vers l'extérieur, la radio pour coordonner dans la cordée, le traceur GPS pour que l'extérieur sache où vous êtes, et la montre altimètre pour suivre la pression et l'altitude. Les risques en altitude sont précisément de ne pas pouvoir appeler et de ne pas savoir où l'on est — ces appareils répondent directement à ces deux points.",

    "q.l22#9.p" to "Pourquoi un casque doit-il accepter un support de lampe frontale ?",
    "q.l22#9.o0" to "Pour l'harmonie visuelle",
    "q.l22#9.o1" to "Parce que les courses au sommet commencent généralement avant le lever du soleil, et que la lampe doit tenir stable sur la tête",
    "q.l22#9.o2" to "Pour réduire le poids de la lampe",
    "q.l22#9.o3" to "Pour augmenter la solidité du casque",
    "q.l22#9.e" to "Le jour du sommet commence généralement aux petites heures, et la lampe frontale est la seule source de lumière ; avec un casque, elle doit être fixée dessus pour éclairer de façon stable. Une lampe qui vacille ou se détache en marche signifie que vous ne voyez plus vos appuis — un vrai risque en terrain technique.",
    // ---------- m01 Science de la haute altitude ----------
    "q.m01#0.p" to "De combien la température de l'air baisse-t-elle environ tous les 1 000 m de montée ?",
    "q.m01#0.o0" to "Environ 1,5 °C",
    "q.m01#0.o1" to "Environ 3 °C",
    "q.m01#0.o2" to "Environ 6,5 °C",
    "q.m01#0.o3" to "Environ 10 °C",
    "q.m01#0.e" to "La température chute d'environ 6,5 °C par 1 000 m — c'est le gradient thermique de l'atmosphère. Cela explique l'altitude de la limite des neiges et pourquoi un sommet de 5 000 m reste enneigé même en été.",

    "q.m01#1.p" to "Quelle est la cause fondamentale de l'hypoxie en altitude ?",
    "q.m01#1.o0" to "La proportion d'oxygène dans l'air est plus faible",
    "q.m01#1.o1" to "La pression atmosphérique baisse, donc la pression partielle d'oxygène de chaque inspiration diminue",
    "q.m01#1.o2" to "Les ultraviolets décomposent l'oxygène",
    "q.m01#1.o3" to "L'air se raréfie et l'oxygène est remplacé par d'autres gaz",
    "q.m01#1.e" to "C'est une idée fausse très répandue. L'oxygène représente toujours environ 21 % de l'air en altitude — la proportion ne change pas. Ce qui change, c'est la pression : à pression plus basse, il y a moins de molécules d'oxygène dans le même volume, donc la pression partielle baisse et le corps reçoit moins d'oxygène.",

    "q.m01#2.p" to "[Choix multiple] Lesquels de ces éléments caractérisent typiquement un environnement de haute altitude ?",
    "q.m01#2.o0" to "Basse pression et faible pression partielle d'oxygène",
    "q.m01#2.o1" to "Basse température avec une forte amplitude jour-nuit",
    "q.m01#2.o2" to "Rayonnement ultraviolet nettement plus fort",
    "q.m01#2.o3" to "Air extrêmement sec",
    "q.m01#2.o4" to "Proportion d'oxygène dans l'air nettement plus faible",
    "q.m01#2.e" to "Les quatre premiers sont exacts, et ils s'amplifient mutuellement : froid plus hypoxie signifie que le corps peine à la fois à produire de la chaleur et à obtenir de l'oxygène ; sécheresse plus UV forts abîment plus vite les voies respiratoires, la peau et les yeux. L'équipement et l'itinéraire doivent couvrir les quatre à la fois.",

    "q.m01#3.p" to "La pression au niveau de la mer est d'environ 1 013 hPa. Quelle est la pression à 5 000 m ?",
    "q.m01#3.o0" to "Environ 900 hPa",
    "q.m01#3.o1" to "Environ 700 hPa",
    "q.m01#3.o2" to "Environ 540 hPa",
    "q.m01#3.o3" to "Environ 300 hPa",
    "q.m01#3.e" to "À 5 000 m, la pression est à peu près la moitié de celle du niveau de la mer. Chaque inspiration contient donc environ moitié moins de molécules d'oxygène — le corps compense en augmentant la fréquence respiratoire et cardiaque, ce qui est la raison physique pour laquelle on est essoufflé et plus lent là-haut.",

    "q.m01#4.p" to "Complétez : la température baisse d'environ ( ) °C tous les 1 000 m de montée.",
    "q.m01#4.a0" to "6,5",
    "q.m01#4.a1" to "6,5",
    "q.m01#4.e" to "6,5 °C par 1 000 m. Ce chiffre est réellement utile pour planifier : passer d'un camp de base à 3 000 m à 5 000 m signifie environ 13 °C de moins, ce qui décide directement de l'épaisseur nécessaire de votre doudoune et de votre sac de couchage.",

    "q.m01#5.p" to "[Ordre] Remettez dans l'ordre la chaîne causale de l'hypoxie d'altitude.",
    "q.m01#5.o0" to "La pression baisse, ce qui abaisse la pression partielle d'oxygène inspirée",
    "q.m01#5.o1" to "La saturation artérielle en oxygène chute",
    "q.m01#5.o2" to "Le corps compense en augmentant la fréquence respiratoire et cardiaque",
    "q.m01#5.o3" to "Une hypoxie prolongée peut évoluer vers un mal d'altitude",
    "q.m01#5.e" to "Cette chaîne est la charpente de la médecine d'altitude : environnement, physiologie, compensation, décompensation. Une fois qu'on la voit, le MAM, l'OCHA et l'OPHA cessent d'être des faits séparés pour devenir des étapes différentes d'une même chaîne.",

    "q.m01#6.p" to "Quel est le pouvoir réfléchissant de la neige fraîche ?",
    "q.m01#6.o0" to "Environ 20 %",
    "q.m01#6.o1" to "Environ 40 %",
    "q.m01#6.o2" to "Environ 60 %",
    "q.m01#6.o3" to "Environ 80–90 %",
    "q.m01#6.e" to "La neige fraîche réfléchit environ 80 à 90 % du rayonnement solaire. L'exposition aux UV sur un champ de neige est donc presque doublée — directe d'en haut plus réfléchie par la surface. C'est pourquoi la cécité des neiges et les coups de soleil graves sont si fréquents en montagne.",

    "q.m01#7.p" to "Pourquoi la protection solaire en altitude est-elle indispensable et non facultative ?",
    "q.m01#7.o0" to "Parce que le soleil est plus proche de la terre là-haut",
    "q.m01#7.o1" to "Parce que les UV augmentent avec l'altitude et que la neige les renvoie sur votre visage",
    "q.m01#7.o2" to "Parce que la couche d'ozone est plus fine, donc la lumière visible est plus forte",
    "q.m01#7.o3" to "Parce que le froid affaiblit la résistance de la peau",
    "q.m01#7.e" to "L'intensité des UV augmente d'environ 10 à 12 % par 1 000 m, et la neige ajoute 80 à 90 % de réflexion. Ensemble, la dose dépasse de loin celle d'un site de basse altitude à la même latitude. Crème solaire, stick à lèvres et lunettes UV400 sont de l'équipement, pas des accessoires.",

    "q.m01#8.p" to "L'air sec en altitude a une conséquence facile à négliger. Laquelle ?",
    "q.m01#8.o0" to "Une meilleure peau",
    "q.m01#8.o1" to "Une perte d'eau insensible par la respiration et la transpiration, qui aggrave la déshydratation et les symptômes d'altitude",
    "q.m01#8.o2" to "Un plus grand appétit",
    "q.m01#8.o3" to "Un sommeil plus profond",
    "q.m01#8.e" to "L'air sec et la respiration plus rapide retirent en continu de l'humidité aux voies respiratoires, et souvent on ne ressent aucune soif. La déshydratation épaissit le sang et aggrave la sensation d'hypoxie et la céphalée — boire régulièrement fait donc partie de l'acclimatation, ce n'est pas un détail.",

    "q.m01#9.p" to "[Choix multiple] Lesquelles de ces atteintes sont causées directement par l'environnement de haute altitude ?",
    "q.m01#9.o0" to "Le coup de soleil",
    "q.m01#9.o1" to "La cécité des neiges",
    "q.m01#9.o2" to "La déshydratation",
    "q.m01#9.o3" to "Les lèvres gercées",
    "q.m01#9.o4" to "Une entorse de la cheville",
    "q.m01#9.e" to "Les quatre premières sont des atteintes environnementales, et elles partagent un trait : elles sont presque entièrement évitables. Contrairement aux avalanches, elles ne sont pas difficiles à prévoir — elles dépendent uniquement de l'équipement et des habitudes, donc les voir dans une cordée signifie généralement que quelque chose a raté dans la préparation.",

    "q.m01#10.p" to "Quelle affirmation sur la composition de l'air en altitude est correcte ?",
    "q.m01#10.o0" to "La proportion d'oxygène baisse à mesure qu'on monte",
    "q.m01#10.o1" to "La proportion reste à peu près la même ; la pression plus basse réduit la pression partielle",
    "q.m01#10.o2" to "La proportion d'azote augmente avec l'altitude",
    "q.m01#10.o3" to "L'oxygène est chassé par les autres gaz en altitude",
    "q.m01#10.e" to "Dans la troposphère, le mélange est essentiellement constant (environ 21 % d'oxygène, 78 % d'azote). Ce qui varie avec l'altitude, c'est la pression — combien de molécules contient cette même inspiration. Une fois cette distinction claire, beaucoup de questions d'équipement et de physiologie deviennent simples.",

    "q.m01#11.p" to "Pourquoi les sommets de 5 000 m restent-ils enneigés en été ?",
    "q.m01#11.o0" to "Parce que les lieux élevés sont plus loin du soleil",
    "q.m01#11.o1" to "Parce que l'air de haute altitude est bien plus froid que les plaines à la même latitude, donc les précipitations tombent en neige",
    "q.m01#11.o2" to "Parce que les vents forts au sommet empêchent la fonte",
    "q.m01#11.o3" to "Parce que la neige tassée se transforme en glace et ne fond plus jamais",
    "q.m01#11.e" to "La règle des 6,5 °C par 1 000 m maintient les températures d'été à 5 000 m sous zéro. Elle explique aussi pourquoi la même montagne est plus difficile selon la saison — la limite des neiges se déplace, et l'itinéraire avec elle.",

    "q.m01#12.p" to "D'un camp de base à 3 000 m à un camp à 5 000 m, en utilisant le gradient moyen, combien de degrés de moins environ ?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. Le calcul : 2 000 m de gain à 6,5 °C par 1 000 m font 2 × 6,5 = 13 °C. Cette estimation est très pratique avant une course — elle décide de l'épaisseur nécessaire de l'isolation et du sac de couchage.",

    // ---------- m02 Condition physique et nutrition ----------
    "q.m02#0.p" to "Quel type de condition physique compte le plus pour l'alpinisme de haute altitude ?",
    "q.m02#0.o0" to "La puissance explosive et les sprints courts",
    "q.m02#0.o1" to "L'endurance aérobie tenue pendant des heures",
    "q.m02#0.o2" to "La force de préhension maximale",
    "q.m02#0.o3" to "La souplesse",
    "q.m02#0.e" to "L'alpinisme de haute altitude est un travail long et peu intense : six à dix heures par jour, jamais raide mais sans répit. L'hypoxie limite fortement la capacité anaérobie, donc ce qui vous porte, c'est une base aérobie et la capacité à tenir une allure régulière.",

    "q.m02#1.p" to "Comment organiser l'entraînement avant le départ ?",
    "q.m02#1.o0" to "Tout caser dans un gros bloc la semaine précédente",
    "q.m02#1.o1" to "Faire un affûtage sur les deux à trois dernières semaines et partir reposé",
    "q.m02#1.o2" to "S'entraîner à intensité maximale jusqu'à la veille",
    "q.m02#1.o3" to "Ne pas s'entraîner du tout et compter sur l'acclimatation sur place",
    "q.m02#1.e" to "Les gains d'entraînement se font pendant la récupération. Arriver fatigué compromet à la fois la performance et l'acclimatation — et s'acclimater coûte lui-même de l'énergie. L'affûtage est ce qui transforme l'entraînement en forme.",

    "q.m02#2.p" to "En altitude, sur quoi l'alimentation doit-elle être basée ?",
    "q.m02#2.o0" to "Des aliments riches en graisses",
    "q.m02#2.o1" to "Les glucides",
    "q.m02#2.o2" to "Des aliments riches en protéines",
    "q.m02#2.o3" to "Uniquement des liquides",
    "q.m02#2.e" to "Les glucides sont métabolisés plus efficacement et consomment moins d'oxygène en conditions hypoxiques, et le corps les préfère instinctivement là-haut. Cela va contre l'intuition selon laquelle l'altitude exigerait des graisses très énergétiques — la contrainte, c'est l'efficacité en oxygène.",

    "q.m02#3.p" to "Quel est un indicateur pratique d'une hydratation suffisante ?",
    "q.m02#3.o0" to "La soif ressentie",
    "q.m02#3.o1" to "Des urines qui restent claires",
    "q.m02#3.o2" to "Boire exactement 1 litre par jour",
    "q.m02#3.o3" to "Les variations de poids corporel",
    "q.m02#3.e" to "La soif n'est pas fiable en altitude — le froid et l'hypoxie l'émoussent tous les deux. La couleur et l'odeur des urines sont un repère quotidien plus direct : claires signifie à peu près suffisant, plus foncées et plus fortes signifient qu'il faut boire davantage.",

    "q.m02#4.p" to "Pourquoi éviter l'alcool en altitude ?",
    "q.m02#4.o0" to "Parce qu'il fait grossir",
    "q.m02#4.o1" to "Parce qu'il déprime la commande respiratoire et aggrave l'hypoxie nocturne",
    "q.m02#4.o2" to "Parce qu'il accélère les dommages des UV",
    "q.m02#4.o3" to "Parce qu'il n'y a pas de réfrigérateur",
    "q.m02#4.e" to "L'alcool et les sédatifs dépriment tous deux le centre respiratoire. Les nuits en altitude tendent déjà vers la respiration périodique, et ajouter une dépression respiratoire fait nettement chuter la saturation — l'un des mécanismes clés par lesquels le mal d'altitude s'aggrave pendant la nuit.",

    "q.m02#5.p" to "[Choix multiple] Quelles sont les bonnes façons de prendre de l'énergie en marchant en altitude ?",
    "q.m02#5.o0" to "De petites quantités souvent, avant d'avoir très faim",
    "q.m02#5.o1" to "Préférer des aliments faciles à digérer et modérément riches en eau",
    "q.m02#5.o2" to "Faire reposer l'apport sur les glucides",
    "q.m02#5.o3" to "Faire un seul gros repas pour réduire le nombre de prises",
    "q.m02#5.e" to "Petites quantités et fréquence facilitent la digestion et stabilisent la glycémie. Un gros repas en hypoxie provoque plutôt ballonnements et nausées — et comme la perte d'appétit est elle-même un symptôme courant, se forcer à un gros repas se retourne contre soi.",

    "q.m02#6.p" to "L'appétit baisse en altitude. Quelle est la bonne réaction ?",
    "q.m02#6.o0" to "Arrêter de manger et attendre la faim",
    "q.m02#6.o1" to "Manger volontairement, en choisissant des aliments riches en glucides et faciles à digérer",
    "q.m02#6.o2" to "Boire beaucoup de café à la place de manger",
    "q.m02#6.o3" to "Ne prendre que des électrolytes",
    "q.m02#6.e" to "La perte d'appétit fait partie du mal d'altitude, et le fait de trop peu manger affaiblit l'acclimatation — un cercle vicieux. Mangez volontairement, en petites quantités et souvent : la question n'est pas de savoir si vous avez faim, c'est une mesure nécessaire.",

    "q.m02#7.p" to "Quelle affirmation sur la condition physique et l'altitude est correcte ?",
    "q.m02#7.o0" to "Si on est en forme, on n'aura pas de mal d'altitude",
    "q.m02#7.o1" to "La condition physique améliore la performance mais ne remplace pas l'acclimatation",
    "q.m02#7.o2" to "Les personnes peu entraînées ne devraient pas aller en altitude",
    "q.m02#7.o3" to "Plus on est en forme, moins on a besoin de s'acclimater",
    "q.m02#7.e" to "Condition physique et acclimatation sont deux courbes distinctes. Une personne entraînée sera peut-être plus à l'aise à la même altitude, mais la physiologie a toujours besoin d'un temps qui se compte en jours — traiter « je suis en forme » comme « je ne tomberai pas malade » est la logique derrière beaucoup d'accidents.",

    "q.m02#8.p" to "[Ordre] Remettez dans l'ordre chronologique une préparation sensée avant une course.",
    "q.m02#8.o0" to "Entraînement de base (deux à trois mois avant)",
    "q.m02#8.o1" to "Affûtage et protection de la récupération (deux à trois semaines avant)",
    "q.m02#8.o2" to "Vérification du matériel, de l'itinéraire et de l'assurance (une semaine avant)",
    "q.m02#8.o3" to "Acclimatation selon le programme (pendant la course)",
    "q.m02#8.e" to "L'ordre, c'est la méthode : s'entraîner tôt, laisser de la place à la récupération, préparer en détail, s'acclimater lentement. Les étapes les plus souvent perturbées sont les deux dernières — beaucoup vérifient minutieusement le matériel, puis courent après le programme en montagne et raccourcissent l'acclimatation.",

    "q.m02#9.p" to "Quel problème un excès de boisson (un grand volume en peu de temps) peut-il causer en altitude ?",
    "q.m02#9.o0" to "Aucun",
    "q.m02#9.o1" to "Il dilue les électrolytes du sang et, dans les cas graves, provoque une hyponatrémie",
    "q.m02#9.o2" to "Il prévient efficacement l'œdème pulmonaire",
    "q.m02#9.o3" to "Il peut remplacer le fait de manger",
    "q.m02#9.e" to "« Boire suffisamment » ne veut pas dire « boire désespérément ». Un grand volume en peu de temps sans électrolytes peut diluer le sodium sanguin et provoquer céphalée, nausées et troubles de la conscience — des symptômes qui imitent de près le mal d'altitude et se lisent facilement de travers. La réponse est une hydratation régulière et suffisante.",
    // ---------- m03 Principes du moindre impact (LNT) ----------
    "q.m03#0.p" to "Quel est le sens central du principe du moindre impact ?",
    "q.m03#0.o0" to "Emporter du matériel plus léger pour moins solliciter son corps",
    "q.m03#0.o1" to "Réduire au minimum l'impact de l'activité humaine sur le milieu montagnard",
    "q.m03#0.o2" to "Abaisser la difficulté de la course pour rester en sécurité",
    "q.m03#0.o3" to "Réduire le nombre de personnes dans la cordée",
    "q.m03#0.e" to "Le principe du moindre impact est l'éthique environnementale portée par la randonnée et l'alpinisme. Il ne s'agit pas de voyager léger, mais de mesurer combien la montagne est changée par votre présence — déchets, piétinement, feu et dérangement de la faune comptent tous.",

    "q.m03#1.p" to "En quittant le camp, quelle est la bonne approche des déchets ?",
    "q.m03#1.o0" to "Les restes de nourriture peuvent être enterrés sur place",
    "q.m03#1.o1" to "Tout redescendre, y compris le papier toilette et les articles d'hygiène",
    "q.m03#1.o2" to "Ne prendre que le plastique",
    "q.m03#1.o3" to "Les brûler dans un trou",
    "q.m03#1.e" to "Le manuel est explicite : emballer tout ce que vous produisez et le redescendre, contrôler le camp et la zone d'activité, et redescendre les articles d'hygiène comme le papier toilette. Enterrer et brûler laissent tous deux des traces, et dans le froid de la haute altitude les déchets se décomposent extrêmement lentement.",

    "q.m03#2.p" to "Quel principe guide l'emplacement des toilettes en pleine nature ?",
    "q.m03#2.o0" to "Le plus caché possible — l'intimité d'abord",
    "q.m03#2.o1" to "Loin des points d'eau, des camps et des sentiers",
    "q.m03#2.o2" to "Là où la neige est la plus plate",
    "q.m03#2.o3" to "Près d'un ruisseau pour que tout soit emporté",
    "q.m03#2.e" to "Le but est d'éviter de contaminer l'eau et d'éviter que la cordée suivante tombe dessus. En pratique : une distance définie par rapport à l'eau et aux sentiers, un trou peu profond, et redescendre le papier utilisé — et au-dessus de la limite des neiges, tout redescendre, car cela ne se décompose presque pas.",

    "q.m03#3.p" to "Pourquoi enfermer hermétiquement la nourriture et les déchets ?",
    "q.m03#3.o0" to "Pour éviter qu'ils prennent l'humidité",
    "q.m03#3.o1" to "Pour empêcher les animaux de les piller et de s'y habituer",
    "q.m03#3.o2" to "Pour gagner de la place dans le sac",
    "q.m03#3.o3" to "Pour faciliter la pesée",
    "q.m03#3.e" to "Les animaux qui pillent la nourriture ont généralement été dressés à le faire par des cordées : une fois qu'ils associent le camp à la nourriture, le risque sur cet itinéraire augmente définitivement. Bien fermer protège votre nourriture, les animaux et tous ceux qui viendront après vous.",

    "q.m03#4.p" to "À quoi renvoie principalement la période sensible pour la faune ?",
    "q.m03#4.o0" to "Les heures d'alimentation en journée",
    "q.m03#4.o1" to "Les saisons de reproduction et d'allaitement",
    "q.m03#4.o2" to "La saison de migration",
    "q.m03#4.o3" to "La dormance hivernale",
    "q.m03#4.e" to "Les animaux sont particulièrement sensibles au dérangement pendant la reproduction et l'élevage des petits, et une mère qui défend sa progéniture peut être agressive. Au-delà d'éviter leur domaine vital, évitez les heures et les lieux d'abreuvement fixes — cela les protège et vous protège.",

    "q.m03#5.p" to "Pourquoi rester sur les sentiers établis ?",
    "q.m03#5.o0" to "Parce que le règlement l'exige",
    "q.m03#5.o1" to "Parce que le piétinement crée de nouveaux sentiers durables et déclenche l'érosion",
    "q.m03#5.o2" to "Parce que les sentiers sont plus faciles à suivre",
    "q.m03#5.o3" to "Parce que les guides les balisent",
    "q.m03#5.e" to "La végétation de haute altitude pousse extrêmement lentement ; une seule empreinte peut persister des années. Des « raccourcis » parallèles coupent la végétation et concentrent l'écoulement de l'eau, finissant par creuser des ravines — c'est ainsi qu'un itinéraire commence à se dégrader.",

    "q.m03#6.p" to "[Choix multiple] Lesquels de ces déchets doivent être redescendus de la montagne ?",
    "q.m03#6.o0" to "Les emballages alimentaires",
    "q.m03#6.o1" to "Les épluchures de fruits et les restes de nourriture",
    "q.m03#6.o2" to "Le papier toilette usagé",
    "q.m03#6.o3" to "Les mégots de cigarettes",
    "q.m03#6.o4" to "Le ruban adhésif et la cordelette peuvent être brûlés sur place",
    "q.m03#6.e" to "Les quatre premiers redescendent avec vous. Le malentendu le plus courant concerne les épluchures et les restes — ils semblent biodégradables, mais dans les conditions froides et sèches de l'altitude ils se décomposent très lentement, attirent les animaux et modifient leur comportement.",

    "q.m03#7.p" to "Quelle est la bonne attitude face au ramassage d'objets naturels (pierres, plantes, fossiles) comme souvenirs ?",
    "q.m03#7.o0" to "Les petits objets peuvent être emportés",
    "q.m03#7.o1" to "Ne rien prendre de naturel — prendre des photographies à la place",
    "q.m03#7.o2" to "C'est acceptable tant qu'on n'abîme pas l'environnement",
    "q.m03#7.o3" to "La collecte d'échantillons sert la science",
    "q.m03#7.e" to "« Ne prendre que des photos, ne laisser que des empreintes » est la formule classique. Les objets naturels font partie de l'écologie et du paysage local, et dès que chaque cordée en prend un peu, l'effet cumulé devient considérable.",

    "q.m03#8.p" to "Comment l'alpinisme affecte-t-il principalement les milieux montagnards ?",
    "q.m03#8.o0" to "Uniquement par les déchets",
    "q.m03#8.o1" to "Dégradation de la végétation, réduction du domaine vital de la faune, déchets, et impact culturel des visiteurs extérieurs sur les communautés locales",
    "q.m03#8.o2" to "Surtout par le bruit",
    "q.m03#8.o3" to "L'impact est négligeable",
    "q.m03#8.e" to "Le manuel sépare l'impact écologique et l'impact social : dégradation de la végétation, déplacement de la faune et déchets d'un côté, pression culturelle sur les modes de vie locaux de l'autre. Comprendre cela explique pourquoi l'étiquette fait partie de la formation d'alpiniste.",

    "q.m03#9.p" to "[Ordre] Remettez dans le bon ordre la routine de départ du camp à faible impact.",
    "q.m03#9.o0" to "Ranger le matériel personnel et collectif",
    "q.m03#9.o1" to "Trier et emballer tous les déchets",
    "q.m03#9.o2" to "Traiter les déjections humaines (enterrer ou redescendre)",
    "q.m03#9.o3" to "Parcourir le camp et la zone d'activité et confirmer qu'il ne reste rien",
    "q.m03#9.e" to "La dernière étape — le tour d'inspection — est la plus souvent sautée et la plus importante : on prend instinctivement « ses propres affaires », et c'est exactement ainsi que des sardines, des bouts de corde et des emballages tombés restent sur place. Regarder en arrière ne coûte presque rien.",

    // ---------- m04 Météo et cartes ----------
    "q.m04#0.p" to "Quel est le signe le plus fiable d'un changement de temps ?",
    "q.m04#0.o0" to "S'il y a du soleil à cet instant",
    "q.m04#0.o1" to "L'évolution de la pression, des nuages et du vent",
    "q.m04#0.o2" to "La prévision d'avant le départ",
    "q.m04#0.o3" to "Le ressenti de vos compagnons",
    "q.m04#0.e" to "Le présent est une photographie ; la tendance est la direction. La pression qui baisse régulièrement, les nuages qui s'épaississent et descendent, le vent qui forcit — quand les trois apparaissent ensemble, le temps tourne. C'est l'intérêt pratique d'emporter un baromètre, dans une montre ou séparément.",

    "q.m04#1.p" to "Qu'est-ce qui caractérise un cumulonimbus, et que signifie-t-il ?",
    "q.m04#1.o0" to "Fin et uniforme — temps stable",
    "q.m04#1.o1" to "Développement vertical avec sommet en enclume — orages et fortes précipitations",
    "q.m04#1.o2" to "Étalé en couches — seulement de la bruine",
    "q.m04#1.o3" to "Filaments légers — beau temps",
    "q.m04#1.e" to "La croissance verticale traduit une forte convection, et l'enclume signifie qu'il a atteint sa maturité. En rencontrer un en altitude signifie que foudre, grêle et fortes précipitations sont possibles — quittez immédiatement les crêtes et les points hauts exposés.",

    "q.m04#2.p" to "Quelles échelles de carte sont couramment utilisées en alpinisme ?",
    "q.m04#2.o0" to "1:1 000 et 1:5 000",
    "q.m04#2.o1" to "1:50 000 et 1:10 000",
    "q.m04#2.o2" to "1:250 000 et 1:500 000",
    "q.m04#2.o3" to "N'importe quelle échelle convient",
    "q.m04#2.e" to "1:50 000 et 1:10 000 forment le couple habituel : la première couvre une grande zone et convient à la planification d'itinéraire, la seconde porte le détail et convient au terrain technique. 1:200 000 est utilisé occasionnellement, et 1:10 000 plus rarement — la feuille couvre si peu de terrain qu'on en sort vite.",

    "q.m04#3.p" to "Des courbes de niveau serrées sur une carte topographique signifient quoi ?",
    "q.m04#3.o0" to "Une pente douce",
    "q.m04#3.o1" to "Une pente raide",
    "q.m04#3.o2" to "Une vallée",
    "q.m04#3.o3" to "Un glacier",
    "q.m04#3.e" to "Plus les courbes sont rapprochées, plus on gagne de dénivelé sur la même distance horizontale — autrement dit, plus c'est raide. C'est une compétence de lecture utile en planification : on peut repérer les passages raides, les replats et les emplacements de tente possibles avant de partir.",

    "q.m04#4.p" to "Qu'indique une courbe de niveau fermée sur une carte topographique ?",
    "q.m04#4.o0" to "Un lac",
    "q.m04#4.o1" to "Un sommet indépendant",
    "q.m04#4.o2" to "Un glacier",
    "q.m04#4.o3" to "Une falaise",
    "q.m04#4.e" to "Une courbe fermée signifie que le relief redescend de tous les côtés — c'est la définition même d'un sommet indépendant. Plusieurs boucles concentriques signifient que la montagne s'élève par paliers, la boucle la plus interne marquant la zone sommitale.",

    "q.m04#5.p" to "[Choix multiple] À quoi faut-il faire attention en utilisant une boussole ?",
    "q.m04#5.o0" to "La garder aussi horizontale que possible",
    "q.m04#5.o1" to "Rester à l'écart des objets magnétiques",
    "q.m04#5.o2" to "Ne pas confondre le S de l'aiguille avec le nord",
    "q.m04#5.o3" to "Corriger la déclinaison magnétique locale",
    "q.m04#5.o4" to "La tenir près des boucles métalliques du sac pour la stabiliser",
    "q.m04#5.e" to "Les quatre premiers points sont explicitement cités dans le manuel. L'erreur du S inversé produit à elle seule une erreur de direction de 180° — en terrain complexe, cela peut vous envoyer dans la direction opposée sans que vous le remarquiez.",

    "q.m04#6.p" to "Qu'est-ce que la déclinaison magnétique ?",
    "q.m04#6.o0" to "Un défaut de fabrication de la boussole",
    "q.m04#6.o1" to "L'écart entre le nord magnétique et le nord géographique, qu'il faut corriger",
    "q.m04#6.o2" to "Une variation d'angle causée par l'altitude",
    "q.m04#6.o3" to "Une distorsion due à la projection de la carte",
    "q.m04#6.e" to "L'aiguille pointe vers le nord magnétique tandis que les cartes sont référencées au nord géographique, et les deux diffèrent. La déclinaison varie selon la région : il faut donc la corriger quand on travaille carte et boussole ensemble — sinon tout l'itinéraire se décale.",

    "q.m04#7.p" to "Que représentent les lignes de carroyage régulier sur une carte topographique ?",
    "q.m04#7.o0" to "Les lignes de latitude et de longitude",
    "q.m04#7.o1" to "Un carroyage UTM (Universal Transverse Mercator)",
    "q.m04#7.o2" to "Les courbes de niveau",
    "q.m04#7.o3" to "Les limites administratives",
    "q.m04#7.e" to "Le carroyage n'est pas la latitude et la longitude mais l'UTM. Cela compte parce que la Terre est un ellipsoïde : les mailles lat/long n'ont pas la même taille selon la latitude, alors que les carrés UTM si — ce qui rend la mesure des distances et des coordonnées simple.",

    "q.m04#8.p" to "Pourquoi ne pas se fier au GPS seul ?",
    "q.m04#8.o0" to "Parce que le GPS n'est pas assez précis",
    "q.m04#8.o1" to "Parce que l'appareil peut tomber en panne de batterie, prendre l'eau, casser ou perdre le signal",
    "q.m04#8.o2" to "Parce que le GPS ne fonctionne qu'en ville",
    "q.m04#8.o3" to "Parce que le GPS exige un abonnement",
    "q.m04#8.e" to "Le GPS est une excellente aide, mais il suppose un appareil qui fonctionne. Les batteries faiblissent vite dans le froid d'altitude, et l'eau et les chutes sont courantes. Carte et boussole n'ont besoin d'aucune énergie — c'est pourquoi elles restent obligatoires dans la formation d'alpinisme.",

    "q.m04#9.p" to "Quand la visibilité s'effondre (brouillard, voile blanc), que faut-il faire d'abord ?",
    "q.m04#9.o0" to "Accélérer pour passer",
    "q.m04#9.o1" to "Confirmer immédiatement sa position et son cap, et attendre sur place si nécessaire",
    "q.m04#9.o2" to "Continuer tout droit selon le plan initial",
    "q.m04#9.o3" to "Se séparer pour chercher l'itinéraire",
    "q.m04#9.e" to "Le danger d'un voile blanc est de perdre tout repère visuel, et on marche instinctivement dans la mauvaise direction. Fixez votre position, notez le cap et attendez si besoin — bien plus sûr que de forcer, et se séparer est la pire des options.",
    // ---------- m05 Sommets d'initiation ----------
    "q.m05#0.p" to "Quelle est la différence essentielle entre un sommet de randonnée et un sommet technique ?",
    "q.m05#0.o0" to "L'altitude",
    "q.m05#0.o1" to "Le fait qu'un matériel technique et une gestuelle technique soient nécessaires",
    "q.m05#0.o2" to "Le pays où il se trouve",
    "q.m05#0.o3" to "La nécessité d'un permis",
    "q.m05#0.e" to "La ligne de partage est l'exigence technique, pas la hauteur. Le Kilimandjaro, à 5 895 m, ne demande aucun matériel technique, tandis que le Haba Xue Shan, à 5 396 m, exige crampons et piolet au-dessus de la limite des neiges. L'altitude n'est qu'une dimension de la difficulté.",

    "q.m05#1.p" to "Comment s'appelle le point culminant du Kilimandjaro ?",
    "q.m05#1.o0" to "Pic Uhuru",
    "q.m05#1.o1" to "Kibo",
    "q.m05#1.o2" to "Mawenzi",
    "q.m05#1.o3" to "Shira",
    "q.m05#1.e" to "Le sommet est le pic Uhuru, à 5 895 m. Le Kilimandjaro est un volcan endormi formé de trois cônes — Kibo, Mawenzi et Shira — et Uhuru est le point le plus haut du Kibo.",

    "q.m05#2.p" to "Qu'est-ce qui rend le Kilimandjaro unique ?",
    "q.m05#2.o0" to "C'est le sommet de 5 000 m le moins gravi au monde",
    "q.m05#2.o1" to "Il est proche de l'équateur et porte pourtant des glaciers, en traversant les zones climatiques de la forêt tropicale au désert alpin",
    "q.m05#2.o2" to "Il exige un matériel très technique",
    "q.m05#2.o3" to "On ne peut le gravir qu'un mois par an",
    "q.m05#2.e" to "Équateur plus glaciers font du Kilimandjaro un corridor climatique vertical : de la forêt tropicale à la glace en une seule course. Cela crée aussi un problème pratique — un grand écart d'altitude avec une montée rapide, si bien que l'acclimatation devient le défi principal.",

    "q.m05#3.p" to "À quel groupe de sommets appartient l'Aotaina ?",
    "q.m05#3.o0" to "Siguniang",
    "q.m05#3.o1" to "Les monts San'ao",
    "q.m05#3.o2" to "Gongga",
    "q.m05#3.o3" to "Le Meili Xue Shan",
    "q.m05#3.e" to "Le groupe San'ao, à Heishui dans le Sichuan, se compose de l'Aotaiji (père des montagnes), de l'Aotaimei (mère) et de l'Aotaina (fils). L'Aotaina est le plus facile des trois et est souvent choisi comme premier sommet enneigé.",

    "q.m05#4.p" to "Quelle description de l'altitude de l'Aotaina est exacte ?",
    "q.m05#4.o0" to "Toutes les sources s'accordent sur 4 800 m",
    "q.m05#4.o1" to "Altitude officielle 5 211 m, mais mesurée autour de 4 800 m — les sources divergent",
    "q.m05#4.o2" to "Officielle 4 800 m, mesurée 5 211 m",
    "q.m05#4.o3" to "L'altitude n'a jamais été contestée",
    "q.m05#4.e" to "Ces écarts sont courants dans les données de sommets : chiffres officiels, valeurs mesurées et normes de relevé différentes varient tous. La leçon pratique est de citer la source chaque fois qu'on donne une altitude, plutôt que de traiter un chiffre comme une vérité absolue.",

    "q.m05#5.p" to "Quelles sont les altitudes du Da Feng et du Er Feng du Siguniang ?",
    "q.m05#5.o0" to "5 025 m et 5 276 m",
    "q.m05#5.o1" to "5 276 m et 5 025 m",
    "q.m05#5.o2" to "5 025 m et 5 355 m",
    "q.m05#5.o3" to "4 850 m et 5 276 m",
    "q.m05#5.e" to "Le Da Feng culmine à 5 025 m et le Er Feng à 5 276 m. On les associe souvent en progression d'entrée : d'abord le Da Feng pour l'expérience de l'altitude, puis le Er Feng, dont le passage final demande une assistance technique simple — une marche naturelle vers l'escalade technique.",

    "q.m05#6.p" to "[Choix multiple] Pour un premier sommet enneigé, quels facteurs méritent le plus d'être comparés ?",
    "q.m05#6.o0" to "Le degré de balisage de l'itinéraire et son taux de réussite au sommet",
    "q.m05#6.o1" to "La fiabilité de l'encadrement et du dispositif de secours",
    "q.m05#6.o2" to "Le rythme de gain d'altitude est-il raisonnable",
    "q.m05#6.o3" to "Votre condition physique actuelle et le temps dont vous disposez",
    "q.m05#6.o4" to "La popularité du sommet sur les réseaux sociaux",
    "q.m05#6.e" to "Les quatre premiers répondent ensemble à la question « cette montagne est-elle adaptée à moi, maintenant ». Ne regarder que le chiffre d'altitude trompe : un sommet de 5 000 m avec un rythme raisonnable et un bon encadrement peut être plus sûr qu'un 5 500 m qui impose trois jours précipités.",

    "q.m05#7.p" to "Qu'est-ce qui provoque le plus souvent l'échec sur un sommet d'initiation ?",
    "q.m05#7.o0" to "La difficulté technique",
    "q.m05#7.o1" to "Le mal d'altitude et la météo, pas la difficulté technique",
    "q.m05#7.o2" to "Un matériel insuffisant",
    "q.m05#7.o3" to "Une cordée trop petite",
    "q.m05#7.e" to "C'est le point le plus sous-estimé : sur les sommets d'initiation, l'échec est presque toujours « on n'avait plus de jambes » ou « le temps n'a pas attendu », jamais « on n'a pas passé le passage clé ». Le vrai travail à ce niveau, ce sont donc l'acclimatation, l'allure et la condition physique — pas les mouvements techniques.",

    "q.m05#8.p" to "Pourquoi le taux de réussite au sommet est-il un chiffre utile pour choisir un sommet ?",
    "q.m05#8.o0" to "Parce qu'il reflète la beauté du sommet",
    "q.m05#8.o1" to "Parce qu'il intègre la difficulté de l'itinéraire, le rythme et le niveau réel d'encadrement",
    "q.m05#8.o2" to "Parce qu'il détermine le coût",
    "q.m05#8.o3" to "Parce qu'il n'a aucun rapport avec la sécurité",
    "q.m05#8.e" to "Le taux de réussite est le produit de beaucoup de choses : la difficulté de l'itinéraire, le caractère raisonnable du gain d'altitude, la largeur des fenêtres météo, la fiabilité de la logistique. Il en dit plus sur ce que vous affronterez réellement que l'altitude seule.",

    "q.m05#9.p" to "Quelle est la bonne attitude face à un premier sommet enneigé ?",
    "q.m05#9.o0" to "Initiation signifie aucun risque",
    "q.m05#9.o1" to "Initiation signifie seulement une exigence technique plus faible ; les risques d'altitude et de météo restent réels",
    "q.m05#9.o2" to "Les sommets d'initiation ne demandent pas de guide",
    "q.m05#9.o3" to "Les sommets d'initiation ne demandent aucune préparation physique",
    "q.m05#9.e" to "« Initiation » décrit le seuil technique, pas le risque total. L'altitude elle-même, une météo qui se dégrade et l'épuisement peuvent tuer à n'importe quelle hauteur. Traiter l'initiation comme « facile » est précisément là où commence une mauvaise préparation.",

    // ---------- m06 Initiation technique ----------
    "q.m06#0.p" to "Quels sont les trois systèmes de base de l'escalade technique ?",
    "q.m06#0.o0" to "Matériel, condition physique, météo",
    "q.m06#0.o1" to "Arrêt, protection, progression",
    "q.m06#0.o2" to "Montée, descente, repos",
    "q.m06#0.o3" to "Crampons, piolet, corde",
    "q.m06#0.e" to "L'arrêt répond à « que faire après avoir perdu pied », la protection à « qui me retient si je tombe », et la progression à « comment avancer sur un terrain dangereux ». Ensemble, ils bouclent le système — retirez-en un et l'escalade technique ne fonctionne plus.",

    "q.m06#1.p" to "Quel est le but fondamental de l'apprentissage de l'escalade technique ?",
    "q.m06#1.o0" to "Gravir des itinéraires plus durs",
    "q.m06#1.o1" to "Transformer une glissade incontrôlée en risque maîtrisé",
    "q.m06#1.o2" to "Obtenir un certificat",
    "q.m06#1.o3" to "Se déplacer plus vite",
    "q.m06#1.e" to "La technique n'abaisse pas la montagne : elle change ce qui se passe après une erreur. Avec l'arrêt, une glissade cesse d'être une catastrophe irréversible ; avec la protection, une erreur ne signifie plus automatiquement une chute. C'est là sa vraie valeur.",

    "q.m06#2.p" to "Quel est le moyen le plus efficace de maîtriser un geste technique ?",
    "q.m06#2.o0" to "Regarder plusieurs fois des vidéos pédagogiques",
    "q.m06#2.o1" to "Le répéter sur un terrain protégé jusqu'à ce qu'il devienne un réflexe",
    "q.m06#2.o2" to "Lire le manuel et mémoriser les points clés",
    "q.m06#2.o3" to "L'apprendre d'un coup sur une vraie pente raide",
    "q.m06#2.e" to "Les gestes techniques doivent être exécutés sous pression, et la pression vous ramène au niveau où vous vous êtes réellement entraîné. Pente douce, neige molle, dégagement net et un encadrant à l'assurage — quand les quatre sont réunis, c'est là qu'une compétence s'apprend vraiment.",

    "q.m06#3.p" to "Pourquoi ne peut-on pas apprendre l'auto-arrêt par une vidéo ?",
    "q.m06#3.o0" to "Parce que la qualité de la vidéo est mauvaise",
    "q.m06#3.o1" to "Parce que c'est un réflexe qui doit se construire par une pratique répétée sur le terrain",
    "q.m06#3.o2" to "Parce que la technique montrée est fausse",
    "q.m06#3.o3" to "Parce que l'auto-arrêt est en réalité simple",
    "q.m06#3.e" to "Après une glissade, vous avez une ou deux secondes, sans place pour réfléchir. La mémoire musculaire s'achète en répétitions — c'est pourquoi toute formation sérieuse insiste pour que vous le répétiez jusqu'à pouvoir le faire sans y penser.",

    "q.m06#4.p" to "Quels sont les trois éléments de départ du matériel technique ?",
    "q.m06#4.o0" to "Casque, gants, lunettes de protection",
    "q.m06#4.o1" to "Des crampons adaptés à vos chaussures, un piolet et un baudrier",
    "q.m06#4.o2" to "Tente, sac de couchage, matelas",
    "q.m06#4.o3" to "GPS, radio, lampe frontale",
    "q.m06#4.e" to "Les crampons donnent l'adhérence, le piolet donne l'arrêt et l'appui, le baudrier vous relie au système de protection. Leur point commun : ils ne créent de la sécurité que s'ils sont adaptés et utilisés comme un système avec un partenaire — aucun élément ne protège à lui seul.",

    "q.m06#5.p" to "Une fois les compétences techniques acquises, quelle devient la capacité la plus importante ?",
    "q.m06#5.o0" to "La vitesse d'ascension",
    "q.m06#5.o1" to "Juger quand on n'a pas du tout besoin du matériel technique",
    "q.m06#5.o2" to "L'entretien du matériel",
    "q.m06#5.o3" to "De nouveaux gains de condition physique",
    "q.m06#5.e" to "C'est le point le plus contre-intuitif de l'escalade technique : la compétence permet d'entrer dans un terrain plus dur, alors que les vrais experts s'en servent pour s'offrir l'option de ne pas y aller. Le jugement prime toujours sur l'exécution.",

    "q.m06#6.p" to "[Choix multiple] Lesquels de ces cas relèvent de l'escalade technique ?",
    "q.m06#6.o0" to "Progresser sur une pente de glace et s'arrêter",
    "q.m06#6.o1" to "Traverser un glacier encordé",
    "q.m06#6.o2" to "Construire un ancrage d'assurage",
    "q.m06#6.o3" to "Descendre en rappel",
    "q.m06#6.o4" to "Randonner sur un sentier bien établi",
    "q.m06#6.e" to "Les quatre premiers sont techniques : chacun demande du matériel, des systèmes et une formation spécifique. Marcher simplement sur la neige ou suivre un sentier établi ne l'est pas — la distinction tient à la nécessité de ces systèmes.",

    "q.m06#7.p" to "Pourquoi la compétence technique ne peut-elle jamais remplacer le jugement ?",
    "q.m06#7.o0" to "Parce que la compétence technique ne peut pas s'entraîner",
    "q.m06#7.o1" to "Parce qu'un mauvais jugement vous met dans un terrain où vous n'auriez jamais dû entrer, et où la technique ne peut pas vous sauver",
    "q.m06#7.o2" to "Parce que le jugement est plus facile à apprendre",
    "q.m06#7.o3" to "Parce que la technique ne s'applique qu'au rocher",
    "q.m06#7.e" to "La technique sert une fois que vous êtes déjà en danger ; le jugement décide si vous entrez dans le danger. Les rapports d'accident concluent rarement « le geste était faux » — bien plus souvent « ils n'auraient pas dû être là ».",

    "q.m06#8.p" to "[Ordre] Remettez dans un ordre logique la séquence d'apprentissage de l'escalade technique.",
    "q.m06#8.o0" to "Comprendre le matériel : comment fonctionnent crampons, piolet et baudrier",
    "q.m06#8.o1" to "Répéter les gestes de base sur un terrain sûr (l'auto-arrêt, par exemple)",
    "q.m06#8.o2" to "Apprendre les systèmes de corde : nœuds, encordement, ancrages",
    "q.m06#8.o3" to "Tout appliquer sur des itinéraires réels mais contrôlés",
    "q.m06#8.e" to "La logique est : se protéger d'abord, puis se relier aux autres, puis entrer en terrain réel. Sauter une étape laisse un trou dans les compétences — s'encorder sur un glacier avec un auto-arrêt mal maîtrisé, par exemple, multiplie le risque pour toute la cordée.",

    "q.m06#9.p" to "Qu'a permis d'accomplir cette unité ?",
    "q.m06#9.o0" to "Terminer toute la formation de haute altitude",
    "q.m06#9.o1" to "Poser les fondations en environnement, science et matériel, prêt à commencer la gestuelle technique",
    "q.m06#9.o2" to "Terminer la préparation aux 8 000 m",
    "q.m06#9.o3" to "Obtenir une certification de secourisme",
    "q.m06#9.e" to "L'unité d'initiation à 5 000 m sert à poser la base : science de l'environnement, matériel, vêtements, condition physique, pratique du moindre impact, météo et orientation, et enfin escalade technique. L'unité suivante commence vraiment par les crampons, le piolet, l'arrêt et le travail sur corde.",
    // ---------- m07 Principes de l'ancrage ----------
    "q.m07#0.p" to "Quelle est l'idée centrale du dimensionnement d'un ancrage ?",
    "q.m07#0.o0" to "Utiliser le moins de matériel possible",
    "q.m07#0.o1" to "La rupture d'un seul point de protection ne doit pas faire s'effondrer le système",
    "q.m07#0.o2" to "Construire l'ancrage le plus haut possible",
    "q.m07#0.o3" to "N'utiliser que des protections naturelles",
    "q.m07#0.e" to "Un ancrage sur rocher ou sur neige n'est jamais absolument certain : le système est donc conçu pour tolérer l'erreur plutôt que pour être absolument solide. Tout le reste — redondance, égalisation, absence d'extension — n'est que cette idée explicitée.",

    "q.m07#1.p" to "Avec deux points de protection à 90° l'un de l'autre, quelle part de la charge chacun porte-t-il environ ?",
    "q.m07#1.o0" to "Environ 50 %",
    "q.m07#1.o1" to "Environ 58 %",
    "q.m07#1.o2" to "Environ 71 %",
    "q.m07#1.o3" to "Environ 100 %",
    "q.m07#1.e" to "Ce sont les chiffres clés du tableau du manuel : à 0°, chaque point porte environ 50 % ; à 60°, environ 58 % ; à 90°, environ 71 %. Plus l'angle est ouvert, plus chaque point ressent de force de la part de la même personne — ce qui détermine directement le choix et la disposition des points.",

    "q.m07#2.p" to "Du point de vue de la charge, comment doit-on traiter l'angle entre les points de protection ?",
    "q.m07#2.o0" to "Le plus petit possible, pour que les directions de charge soient presque parallèles",
    "q.m07#2.o1" to "Le plus grand possible, pour répartir la charge dans différentes directions",
    "q.m07#2.o2" to "Il doit être de 90°",
    "q.m07#2.o3" to "L'angle n'influence pas la charge",
    "q.m07#2.e" to "Plus l'angle est petit, plus la répartition s'approche de 50/50 ; l'ouvrir augmente la charge sur chaque point. La règle courante « rester sous 60° d'angle de sangle » vient directement de ces chiffres.",

    "q.m07#3.p" to "[Choix multiple] Quelles dimensions faut-il considérer pour évaluer un ancrage ?",
    "q.m07#3.o0" to "Solide : chaque point est assez résistant",
    "q.m07#3.o1" to "Redondant : plusieurs points indépendants",
    "q.m07#3.o2" to "Égalisé : la charge est répartie de façon sensée",
    "q.m07#3.o3" to "Sans extension : une rupture ne crée pas d'allongement choquant",
    "q.m07#3.o4" to "Symétrique : une disposition nette et visuellement équilibrée",
    "q.m07#3.e" to "Ces quatre points forment le cadre de base. L'absence d'extension est le plus souvent oubliée : laissez du mou entre les points et une rupture choque les points restants. Les charges de choc sont bien supérieures aux charges statiques, ce que beaucoup ignorent.",

    "q.m07#4.p" to "[Association] Associez chaque type de protection à son milieu et sa méthode.",
    "q.m07#4.l0" to "Protection naturelle",
    "q.m07#4.r0" to "Pilier rocheux, grand arbre, gros bloc — vérifier qu'ils sont intacts et stables",
    "q.m07#4.l1" to "Protection sur neige",
    "q.m07#4.r1" to "Piquets, ancrages enterrés, tranchées en T — la fiabilité dépend fortement de la qualité de la neige et de l'enterrement",
    "q.m07#4.l2" to "Protection sur glace",
    "q.m07#4.r2" to "Broches à glace — vérifier que la glace est compacte, sans vides ni alvéoles",
    "q.m07#4.e" to "Trois milieux, trois jeux de critères complètement différents. L'une des causes d'accident les plus fréquentes est de juger la neige ou la glace avec des réflexes de rocher — « ça a l'air solide » ne veut presque rien dire dans un manteau neigeux.",

    "q.m07#5.p" to "Lequel de ces cas est une fausse redondance ?",
    "q.m07#5.o0" to "Utiliser deux pièces de résistances différentes",
    "q.m07#5.o1" to "Deux points de protection qui dépendent en fait de la même fissure ou du même bloc",
    "q.m07#5.o2" to "Relier les points avec des sangles",
    "q.m07#5.o3" to "Placer trois points de protection",
    "q.m07#5.e" to "La redondance exige une rupture indépendante. Si deux points partagent une fissure, l'ouverture de celle-ci les emporte tous les deux d'un coup — cela ressemble à deux points mais fonctionne comme un seul. La fausse redondance est courante et mortelle.",

    "q.m07#6.p" to "Pourquoi pré-tendre le système afin d'obtenir l'absence d'extension ?",
    "q.m07#6.o0" to "Pour un aspect net",
    "q.m07#6.o1" to "Pour empêcher qu'une rupture choque les points restants",
    "q.m07#6.o2" to "Pour économiser de la sangle",
    "q.m07#6.o3" to "Pour rendre le démontage plus rapide",
    "q.m07#6.e" to "Une charge de choc est bien supérieure à une charge statique — la même personne chargeant brusquement un point génère beaucoup plus de force que suspendue immobile. Un ancrage avec du mou paraît « plus souple » mais amplifie en réalité une rupture en choc sur tout le système.",

    "q.m07#7.p" to "[Ordre] Remettez dans un ordre logique les étapes de construction d'un ancrage.",
    "q.m07#7.o0" to "Observer autour et choisir des emplacements utilisables et mutuellement indépendants",
    "q.m07#7.o1" to "Placer chaque point et vérifier qu'il est solide par lui-même",
    "q.m07#7.o2" to "Relier les points avec sangle ou corde, contrôler l'angle et pré-tendre",
    "q.m07#7.o3" to "Vérifier l'ensemble du système : fausse redondance et extension",
    "q.m07#7.e" to "L'ordre est : choisir les emplacements, construire les points un à un, relier le système, puis le relire. La relecture n'est pas une formalité — pendant la construction on se concentre sur chaque placement et on manque facilement la relation d'ensemble, par exemple deux points partageant un même élément.",

    "q.m07#8.p" to "Lorsqu'on utilise une protection naturelle, que faut-il vérifier en priorité ?",
    "q.m07#8.o0" to "Si elle est assez grosse",
    "q.m07#8.o1" to "Si elle est intacte — ni branlante, ni altérée, ni détachée de la masse principale",
    "q.m07#8.o2" to "Si elle est esthétique",
    "q.m07#8.o3" to "Si elle est facile à sangler",
    "q.m07#8.e" to "Le danger d'une protection naturelle est généralement qu'elle paraisse grosse mais soit déjà descellée. Ce qui compte, c'est qu'elle fasse réellement partie de la masse principale, et qu'il n'y ait ni fissures ni signes d'altération. Gros, épais et évident ne signifient pas solide.",

    "q.m07#9.p" to "Pourquoi construire un ancrage aussi vite que raisonnablement possible ?",
    "q.m07#9.o0" to "Pour économiser de l'énergie",
    "q.m07#9.o1" to "Parce que le temps passé à le construire est du temps d'exposition au risque",
    "q.m07#9.o2" to "Parce que les compagnons vont vous presser",
    "q.m07#9.o3" to "Parce que le matériel se perd",
    "q.m07#9.e" to "Pendant la construction d'un ancrage, on est souvent non protégé ou mal protégé : cette exposition doit donc être courte. C'est pourquoi l'évaluation ne regarde pas seulement solide, redondant et égalisé, mais aussi l'efficacité et la rapidité.",

    "q.m07#10.p" to "De quoi dépend principalement la fiabilité d'un ancrage sur neige ?",
    "q.m07#10.o0" to "De la marque du matériel",
    "q.m07#10.o1" to "De la qualité de la neige et de la qualité de l'enterrement",
    "q.m07#10.o2" to "De l'altitude",
    "q.m07#10.o3" to "De la couleur de la corde",
    "q.m07#10.e" to "Le même piquet ou le même ancrage enterré tient des charges très différentes en neige profonde, en neige humide ou au bord d'un pont de neige. Un ancrage sur neige exige de lire le manteau sur place, ce qui fait aussi de la protection sur neige l'une des compétences les plus exigeantes.",

    "q.m07#11.p" to "Si un ancrage ne comporte qu'un seul point de protection, quel est le plus gros problème ?",
    "q.m07#11.o0" to "La charge est trop élevée",
    "q.m07#11.o1" to "Il n'y a aucune marge — si ce point lâche, le système lâche",
    "q.m07#11.o2" to "C'est peu pratique à manœuvrer",
    "q.m07#11.o3" to "C'est laid",
    "q.m07#11.e" to "Un ancrage à point unique confie votre vie à un seul facteur incertain. Parfois c'est réellement la seule option — une bonne broche à glace, par exemple — et l'attitude est alors de rendre ce point aussi bon que possible et de réduire au minimum la durée pendant laquelle le système en dépend.",

    // ---------- m08 Sommets de 5 000 m ----------
    "q.m08#0.p" to "Quelle est l'altitude du sommet principal du Gangshika ?",
    "q.m08#0.o0" to "5 005 m",
    "q.m08#0.o1" to "5 150 m",
    "q.m08#0.o2" to "5 254,5 m",
    "q.m08#0.o3" to "5 396 m",
    "q.m08#0.e" to "Le sommet principal culmine à 5 254,5 m. Notez la hiérarchie : troisième sommet 5 005 m < sommet secondaire 5 150 m < sommet principal 5 254,5 m — trois hauteurs, trois niveaux de difficulté, ce qui explique pourquoi le Gangshika sert souvent d'objectif progressif.",

    "q.m08#1.p" to "Quelles sont l'altitude et le caractère du troisième sommet du Gangshika ?",
    "q.m08#1.o0" to "5 005 m, technique niveau débutant, environ 95 % de réussite pour des débutants",
    "q.m08#1.o1" to "5 254 m, très technique",
    "q.m08#1.o2" to "5 150 m, pure randonnée",
    "q.m08#1.o3" to "5 396 m, itinéraire glaciaire",
    "q.m08#1.e" to "Le troisième sommet est à 5 005 m et de niveau technique débutant. Un taux de réussite d'environ 95 % pour des débutants indique un itinéraire gérable et une logistique mature — bien adapté à une première utilisation du matériel technique.",

    "q.m08#2.p" to "Quelle est la signification géographique du Gangshika ?",
    "q.m08#2.o0" to "Le plus haut sommet de la chaîne du Kunlun",
    "q.m08#2.o1" to "Le plus haut sommet de la partie orientale de la chaîne du Qilian",
    "q.m08#2.o2" to "Le plus haut sommet du plateau tibétain",
    "q.m08#2.o3" to "Le plus haut sommet de la chaîne du Hengduan",
    "q.m08#2.e" to "Le Gangshika est le plus haut sommet de la partie orientale du Qilian, dans le district de Menyuan, préfecture de Haibei, au Qinghai. C'est aussi l'un des hauts sommets enneigés les plus proches d'une ville en Chine — l'accessibilité détermine directement la popularité d'un sommet comme objectif de formation.",

    "q.m08#3.p" to "Quelle est la distance d'approche et le temps typique pour le troisième sommet du Gangshika ?",
    "q.m08#3.o0" to "Environ 3 km / 2 heures",
    "q.m08#3.o1" to "Environ 10 km / 6 heures",
    "q.m08#3.o2" to "Environ 25 km / deux jours",
    "q.m08#3.o3" to "Environ 1 km / 30 minutes",
    "q.m08#3.e" to "Environ 10 km et six heures. Cette charge est exactement adaptée à une première course technique : on ne gagne pas en endurant une longue marche, mais en se concentrant sur la technique et le jugement.",

    "q.m08#4.p" to "Quelle est l'altitude du Haba Xue Shan ?",
    "q.m08#4.o0" to "5 005 m",
    "q.m08#4.o1" to "5 254 m",
    "q.m08#4.o2" to "5 396 m",
    "q.m08#4.o3" to "5 642 m",
    "q.m08#4.e" to "Le Haba culmine à 5 396 m, à Shangri-La, au Yunnan. Son intérêt est qu'au-dessus de la limite des neiges il y a de la vraie glace, exigeant crampons et piolet, sans pour autant la pression d'acclimatation stricte d'un sommet de 6 000 m.",

    "q.m08#5.p" to "Où le Haba Xue Shan exige-t-il une compétence technique ?",
    "q.m08#5.o0" to "Il demande des capacités d'escalade rocheuse",
    "q.m08#5.o1" to "Au-dessus de la limite des neiges, une pente de glace exige crampons et piolet",
    "q.m08#5.o2" to "Il demande des capacités de plongée",
    "q.m08#5.o3" to "Il ne demande aucun matériel technique",
    "q.m08#5.e" to "Le mot clé du Haba est « de la glace au-dessus de la limite des neiges ». Il faut savoir progresser régulièrement sur glace en crampons et utiliser le piolet pour l'appui et l'arrêt — exactement ce que couvrent les leçons précédentes de cette unité de progression à 5 000 m.",

    "q.m08#6.p" to "Quelles sont l'altitude et le statut de l'Elbrouz ?",
    "q.m08#6.o0" to "5 642 m, le plus haut sommet d'Europe",
    "q.m08#6.o1" to "5 895 m, le plus haut d'Afrique",
    "q.m08#6.o2" to "5 254 m, le plus haut du Qilian",
    "q.m08#6.o3" to "6 178 m, un haut sommet du Kunlun",
    "q.m08#6.e" to "L'Elbrouz culmine à 5 642 m, le plus haut sommet d'Europe, dans le Caucase russe. Sa place dans la progression est particulière : classe 5 000 m en altitude, mais exigeant une progression glaciaire et l'encordement — un pont classique entre sommets de randonnée et sommets techniques.",

    "q.m08#7.p" to "Quelles sont les exigences de base pour gravir l'Elbrouz ?",
    "q.m08#7.o0" to "La condition physique seule",
    "q.m08#7.o1" to "Crampons et piolet ; la progression glaciaire et l'encordement sont des exigences de base",
    "q.m08#7.o2" to "De l'oxygène supplémentaire",
    "q.m08#7.o3" to "Des capacités d'escalade rocheuse",
    "q.m08#7.e" to "L'itinéraire de l'Elbrouz traverse des glaciers : l'encordement, la vigilance aux crevasses et l'usage des crampons sont donc le socle. On le compare souvent au Kilimandjaro : tous deux de classe 5 000 m, l'un pure randonnée, l'autre exigeant un vrai travail technique.",

    "q.m08#8.p" to "[Choix multiple] En passant des sommets de randonnée aux sommets techniques, quelles capacités faut-il construire d'abord ?",
    "q.m08#8.o0" to "Le bon usage du matériel technique (crampons, piolet, baudrier)",
    "q.m08#8.o1" to "Les gestes techniques de base, comme l'arrêt d'une chute",
    "q.m08#8.o2" to "La progression glaciaire encordée et les systèmes de protection de base",
    "q.m08#8.o3" to "Le jugement sur le moment où il ne faut pas continuer",
    "q.m08#8.o4" to "Acheter du matériel plus cher",
    "q.m08#8.e" to "Les trois premiers sont des capacités ; le quatrième est une contrainte. Beaucoup ne construisent que les trois premiers et finissent par être plus confiants à mesure qu'ils deviennent plus compétents — ce qui augmente le risque. Formation technique et formation au jugement doivent avancer ensemble, et c'est pourquoi cette unité associe leçons de technique et leçons de sommets.",

    "q.m08#9.p" to "[Ordre] Classez ces objectifs par difficulté croissante.",
    "q.m08#9.o0" to "Aotaina (randonnée, aucune difficulté technique)",
    "q.m08#9.o1" to "Troisième sommet du Gangshika (technique niveau débutant)",
    "q.m08#9.o2" to "Haba / Elbrouz (mixte, crampons et encordement)",
    "q.m08#9.o3" to "Versant sud du Yuzhu (6 000 m mixte)",
    "q.m08#9.e" to "La clé est d'ajouter une seule variable nouvelle à la fois : pas de technique, puis matériel technique, puis son usage sur de la vraie glace, puis l'altitude. L'erreur habituelle n'est pas de sauter une étape mais de maximiser difficulté et altitude en même temps, si bien qu'on ne sait plus à laquelle on n'était pas préparé.",

    "q.m08#10.p" to "Pourquoi passer du troisième sommet au sommet principal est-il une progression sensée ?",
    "q.m08#10.o0" to "Parce que le troisième sommet est le plus proche du sommet principal",
    "q.m08#10.o1" to "Parce que différents itinéraires d'une même montagne séparent la difficulté technique de la difficulté environnementale",
    "q.m08#10.o2" to "Parce que le sommet principal coûte moins cher",
    "q.m08#10.o3" to "Parce qu'il est plus facile de se perdre sur le troisième sommet",
    "q.m08#10.e" to "Progresser sur la même montagne garde les variables environnementales — météo, accès, logistique, guides — à peu près constantes, ce qui permet de sentir clairement d'où vient la difficulté supplémentaire. En changeant de montagne à chaque fois, on ne sait jamais si la limite venait de la technique ou de l'acclimatation.",

    "q.m08#11.p" to "Quelle est la bonne attitude pour choisir un objectif de progression à 5 000 m ?",
    "q.m08#11.o0" to "Prendre le plus haut et sauter les étapes",
    "q.m08#11.o1" to "Ajouter une difficulté nouvelle à la fois, et privilégier un encadrement fiable",
    "q.m08#11.o2" to "Prendre le moins cher",
    "q.m08#11.o3" to "Ne regarder que le taux de réussite, pas les exigences techniques",
    "q.m08#11.e" to "Les capacités se construisent cumulativement, et chaque étape sautée multiplie le risque. Un encadrement fiable — guides, secours, plan de repli — est la base de sécurité commune à tous les niveaux d'entrée : il ne peut pas empêcher une erreur, mais il empêche qu'une erreur soit fatale.",
    // ---------- m09 Médicaments d'altitude ----------
    "q.m09#0.p" to "Quels sont les deux objectifs de base des médicaments en altitude ?",
    "q.m09#0.o0" to "Guérir le mal d'altitude et remplacer la descente",
    "q.m09#0.o1" to "Accélérer l'acclimatation et gagner du temps pour la descente",
    "q.m09#0.o2" to "Améliorer la condition physique et l'endurance",
    "q.m09#0.o3" to "Prévenir les rhumes et améliorer le sommeil",
    "q.m09#0.e" to "Distinguer ces deux objectifs est essentiel : l'acétazolamide relève du premier (acclimatation plus rapide), la dexaméthasone et la nifédipine du second (gagner du temps). Traiter un médicament qui fait gagner du temps comme une preuve de guérison est l'erreur la plus dangereuse dans la prise en charge de l'altitude.",

    "q.m09#1.p" to "La dexaméthasone agit-elle sur l'acclimatation ?",
    "q.m09#1.o0" to "Oui, elle l'accélère",
    "q.m09#1.o1" to "Non, elle n'a aucun effet sur l'acclimatation",
    "q.m09#1.o2" to "Oui, elle la ralentit",
    "q.m09#1.o3" to "Seulement en usage prolongé",
    "q.m09#1.e" to "Le manuel est direct : la dexaméthasone soulage les symptômes de l'œdème cérébral, n'a aucun effet sur l'acclimatation et ne traite pas l'œdème pulmonaire. Elle ne fait que gagner du temps — et le temps gagné doit être employé à descendre.",

    "q.m09#2.p" to "Quel effet indésirable de la nifédipine demande le plus de prudence ?",
    "q.m09#2.o0" to "La somnolence",
    "q.m09#2.o1" to "Une chute rapide de la tension, si bien que se lever brusquement peut provoquer une syncope",
    "q.m09#2.o2" to "Des acouphènes",
    "q.m09#2.o3" to "Une perte d'appétit",
    "q.m09#2.e" to "C'est dangereux dans la réalité : une syncope par hypotension orthostatique sur une pente raide ou en sortant de la tente la nuit peut avoir des conséquences plus immédiates que le mal d'altitude lui-même. Le manuel note aussi que la nifédipine peut aider les trekkeurs mais n'est pas le meilleur choix pour les alpinistes.",

    "q.m09#3.p" to "Quelle est la bonne attitude face aux médicaments d'altitude ?",
    "q.m09#3.o0" to "Mémoriser la dose et l'utiliser soi-même",
    "q.m09#3.o1" to "C'est une décision médicale — évaluer avec un médecin et suivre ses instructions",
    "q.m09#3.o2" to "Les membres de la cordée peuvent se les partager librement",
    "q.m09#3.o3" to "Les effets indésirables n'empêchent pas l'usage",
    "q.m09#3.e" to "Chaque médicament a des indications, des contre-indications et des effets indésirables précis (la nifédipine baisse la tension, l'aspirine comporte un risque hémorragique, la dexaméthasone est un corticoïde). Ce ne sont pas des « évidences d'altitude » mais des interventions médicales — d'où l'insistance répétée sur l'avis médical.",

    "q.m09#4.p" to "Les symptômes s'atténuent après la dexaméthasone. Que faut-il faire ?",
    "q.m09#4.o0" to "Continuer l'ascension comme prévu",
    "q.m09#4.o1" to "Ne toujours pas monter ; redescendre dès que possible",
    "q.m09#4.o2" to "Augmenter la dose et continuer",
    "q.m09#4.o3" to "Arrêter immédiatement le médicament et observer",
    "q.m09#4.e" to "Le médicament supprime les symptômes, mais la cause de l'œdème cérébral — l'hypoxie — demeure. La conclusion du manuel est claire : même avec un soulagement, ne pas continuer à gagner de l'altitude. La descente est la seule action qui supprime la cause.",

    "q.m09#5.p" to "Comment l'aspirine est-elle utilisée contre la céphalée d'altitude ?",
    "q.m09#5.o0" to "On la prend quand la douleur commence",
    "q.m09#5.o1" to "En préventif : commencer tôt et doser régulièrement",
    "q.m09#5.o2" to "Seulement au coucher",
    "q.m09#5.o3" to "Seulement après la descente",
    "q.m09#5.e" to "Le manuel indique 320 mg trois fois par jour, en commençant la veille de l'ascension, jusqu'à ce que l'acclimatation soit terminée — un schéma préventif régulier, pas une prise au moment de la douleur. Les deux approches reposent sur des logiques totalement différentes.",

    "q.m09#6.p" to "Quelle est la différence fondamentale entre l'acétazolamide et la dexaméthasone ?",
    "q.m09#6.o0" to "L'un est bon marché, l'autre cher",
    "q.m09#6.o1" to "L'un accélère l'acclimatation, l'autre ne fait que soulager les symptômes",
    "q.m09#6.o2" to "L'un se prend par voie orale, l'autre par injection",
    "q.m09#6.o3" to "Ils agissent de la même façon",
    "q.m09#6.e" to "Cette distinction décide de tout ce qui suit : avec l'acétazolamide, l'amélioration peut se lire comme une acclimatation réelle du corps ; avec la dexaméthasone, l'amélioration n'est qu'un masque — et la question de savoir si l'on peut continuer à monter a des réponses opposées dans les deux cas.",

    "q.m09#7.p" to "[Choix multiple] Quelles affirmations sur les médicaments d'altitude sont correctes ?",
    "q.m09#7.o0" to "Un médicament ne peut pas remplacer la descente",
    "q.m09#7.o1" to "La dose et le moment de prise demandent un avis médical",
    "q.m09#7.o2" to "Des médicaments différents visent des atteintes différentes et ne doivent pas être confondus",
    "q.m09#7.o3" to "Une fois que le médicament masque les symptômes, le jugement devient plus difficile",
    "q.m09#7.o4" to "Dès que les symptômes s'atténuent, on peut continuer à monter sans risque",
    "q.m09#7.e" to "Les quatre premiers sont essentiels. Le plus négligé est que le masquage rend le jugement plus difficile : les symptômes disparus, vous perdez votre repère le plus direct et devez vous fier à des signes plus objectifs — la marche, la conscience, la respiration. Donc après avoir donné le médicament, surveillez ces trois points encore plus attentivement.",

    "q.m09#8.p" to "Pourquoi « pas de médicament, on descend maintenant » est-il souvent le choix le plus fiable ?",
    "q.m09#8.o0" to "Parce que les médicaments ne fonctionnent pas",
    "q.m09#8.o1" to "Parce que la descente supprime la cause, alors que les médicaments n'agissent qu'indirectement",
    "q.m09#8.o2" to "Parce que les médicaments coûtent cher",
    "q.m09#8.o3" to "Parce que les médicaments sont encombrants à porter",
    "q.m09#8.e" to "La cause du mal d'altitude est l'hypoxie, et l'hypoxie vient directement de l'altitude. La descente supprime la cause ; les médicaments ne changent que la façon dont le corps y répond. Chaque fois que les conditions le permettent, la descente est l'action la plus prioritaire.",

    "q.m09#9.p" to "[Ordre] Un membre de la cordée présente des signes de mal d'altitude sévère. Quelle est la bonne séquence ?",
    "q.m09#9.o0" to "Arrêter immédiatement de monter ; évaluer la conscience, la marche et la respiration",
    "q.m09#9.o1" to "Organiser la descente (au moins 1 000 m), avec de l'oxygène si disponible",
    "q.m09#9.o2" to "Donner le médicament adapté (par exemple la dexaméthasone) sous surveillance médicale",
    "q.m09#9.o3" to "Si la descente est impossible, utiliser un caisson hyperbare et appeler les secours",
    "q.m09#9.e" to "L'ordre est la priorité : évaluer, descendre, soutenir par les médicaments, et seulement ensuite recourir aux mesures qui font gagner du temps. L'erreur la plus fréquente sur le terrain est d'inverser — chercher le médicament d'abord et oublier que la descente est le traitement définitif.",

    "q.m09#10.p" to "Pourquoi discuter à l'avance d'un plan médicamenteux avec un médecin est-il si important pour un séjour en altitude ?",
    "q.m09#10.o0" to "Parce qu'on ne peut pas acheter de médicaments sur la montagne",
    "q.m09#10.o1" to "Parce qu'aucun avis professionnel n'est disponible là-haut, et que des vomissements peuvent changer la voie d'administration",
    "q.m09#10.o2" to "Parce que les médicaments périment",
    "q.m09#10.o3" to "Parce que les guides l'exigent",
    "q.m09#10.e" to "En altitude, il n'y a ni médecin ni examens ; pire, le patient peut vomir et ne rien pouvoir prendre par voie orale. Le plan — dose, moment, voie et contre-indications — doit être arrêté avant le départ.",

    "q.m09#11.p" to "[Association] Associez chaque médicament à son action principale.",
    "q.m09#11.l0" to "Acétazolamide",
    "q.m09#11.r0" to "Accélère l'acclimatation ; utilisé en préventif",
    "q.m09#11.l1" to "Dexaméthasone",
    "q.m09#11.r1" to "Abaisse la pression intracrânienne et atténue l'œdème cérébral",
    "q.m09#11.l2" to "Nifédipine",
    "q.m09#11.r2" to "Lève la vasoconstriction pulmonaire ; utilisée pour l'œdème pulmonaire",
    "q.m09#11.e" to "Trois cartes, trois rôles : l'acétazolamide pour l'acclimatation, la dexaméthasone pour le cerveau, la nifédipine pour les poumons. Identifiez d'abord de quel problème souffre le patient, puis choisissez la carte — plutôt que de traiter chaque médicament comme un « cachet d'altitude » générique.",

    // ---------- m10 Fenêtre météo ----------
    "q.m10#0.p" to "Qu'est-ce qu'une fenêtre météo ?",
    "q.m10#0.o0" to "Le jour où la probabilité de précipitation est la plus faible dans la prévision",
    "q.m10#0.o1" to "La période pendant laquelle vous pouvez accomplir l'objectif en sécurité",
    "q.m10#0.o2" to "Les heures où il y a le plus de jour",
    "q.m10#0.o3" to "Le moment où il y a le moins de vent",
    "q.m10#0.e" to "Une fenêtre météo est une notion combinée : elle satisfait à la fois « la météo le permet » et « la cordée en est capable ». Donc sous une météo identique, la fenêtre d'une cordée forte et celle d'une cordée faible ont des largeurs totalement différentes — les fenêtres sont relatives, pas absolues.",

    "q.m10#1.p" to "Pourquoi les prévisions météo en montagne sont-elles relativement imprécises ?",
    "q.m10#1.o0" to "Parce qu'il y a trop peu de stations météo",
    "q.m10#1.o1" to "Parce que le relief complexe crée une énorme variabilité locale — des altitudes et des expositions différentes peuvent avoir une météo totalement différente",
    "q.m10#1.o2" to "Parce que les prévisionnistes sont négligents",
    "q.m10#1.o3" to "Parce qu'il n'y a pas de données en altitude",
    "q.m10#1.e" to "La levée orographique, le blocage et l'écoulement autour des crêtes fractionnent la météo à petite échelle — à quelques kilomètres, c'est un autre monde. Une prévision régionale n'est qu'un contexte ; c'est l'observation de terrain qui décide.",

    "q.m10#2.p" to "Des nuages qui s'épaississent et une base qui descend indiquent généralement quoi ?",
    "q.m10#2.o0" to "Une amélioration du temps",
    "q.m10#2.o1" to "Une dégradation du temps, avec une visibilité qui va probablement chuter vite",
    "q.m10#2.o2" to "Une éclaircie imminente",
    "q.m10#2.o3" to "Rien de particulier",
    "q.m10#2.e" to "Une base qui descend signifie une humidité en hausse et un niveau de condensation qui baisse — souvent le précurseur d'un système précipitant. En montagne, cela signifie aussi que votre visibilité va se réduire, ce qui est un risque en soi.",

    "q.m10#3.p" to "Pourquoi la tendance de pression compte-t-elle plus que la valeur de pression ?",
    "q.m10#3.o0" to "Parce que la valeur est toujours fausse",
    "q.m10#3.o1" to "Parce que la météo est pilotée par la variation de pression, et que les valeurs de référence diffèrent de toute façon avec l'altitude",
    "q.m10#3.o2" to "Parce que les tendances sont plus faciles à mémoriser",
    "q.m10#3.o3" to "Parce que les valeurs fluctuent trop",
    "q.m10#3.e" to "Une même pression lue signifie des choses totalement différentes selon l'altitude et le lieu : un chiffre isolé n'a pas de repère. Une baisse soutenue, en revanche, pointe partout vers la même chose : le temps tourne.",

    "q.m10#4.p" to "Quelle est la valeur pratique de l'échelle de Beaufort ?",
    "q.m10#4.o0" to "Elle rend le vent plus professionnel",
    "q.m10#4.o1" to "Elle convertit la vitesse du vent en une échelle observable et communicable, pour juger la mobilité et se parler",
    "q.m10#4.o2" to "Elle mesure les précipitations",
    "q.m10#4.o3" to "Elle estime la température",
    "q.m10#4.e" to "Le vent est une information qui doit se dire : une cordée a besoin d'un langage commun pour « peut-on continuer ». Beaufort transforme une vitesse abstraite en signes observables — feuilles, neige soufflée, ressenti — pour que le jugement circule vite dans le groupe.",

    "q.m10#5.p" to "[Choix multiple] Lesquels de ces signes de terrain indiquent une dégradation du temps ?",
    "q.m10#5.o0" to "Une pression qui baisse régulièrement",
    "q.m10#5.o1" to "Des nuages qui s'épaississent vite et une base qui descend",
    "q.m10#5.o2" to "Un vent qui forcit nettement et change souvent de direction",
    "q.m10#5.o3" to "Des cumulonimbus qui se construisent au loin",
    "q.m10#5.o4" to "Une pression qui monte régulièrement et un vent qui faiblit",
    "q.m10#5.e" to "Les quatre premiers sont les principaux signaux de dégradation du manuel. Ils décrivent tous une tendance plutôt qu'un instant — d'où l'importance d'observer régulièrement et à heure fixe. Une tendance ne signifie quelque chose que si l'on a un point de comparaison.",

    "q.m10#6.p" to "Pendant un orage, quel comportement est le plus dangereux ?",
    "q.m10#6.o0" to "S'arrêter et descendre",
    "q.m10#6.o1" to "Rester sur une crête, un sommet ou une étendue d'eau — partout où l'on est exposé",
    "q.m10#6.o2" to "Ranger le matériel métallique",
    "q.m10#6.o3" to "S'accroupir bas et attendre",
    "q.m10#6.e" to "Le pire pendant un orage est d'être l'objet le plus haut alentour. Les crêtes et les sommets sont exactement les endroits les plus exposés : partez dès que la foudre menace. Gardez le matériel métallique regroupé et à distance du corps.",

    "q.m10#7.p" to "Pourquoi les courses au sommet partent-elles généralement avant l'aube ?",
    "q.m10#7.o0" to "Pour éviter la foule",
    "q.m10#7.o1" to "Parce que le petit matin est généralement la partie la plus stable de la journée, alors que la convection de l'après-midi augmente et que les probabilités se dégradent",
    "q.m10#7.o2" to "Parce qu'on a le plus d'énergie à 3 heures du matin",
    "q.m10#7.o3" to "Parce qu'il fait trop chaud dans la journée",
    "q.m10#7.e" to "Cela suit le cycle quotidien : le réchauffement diurne alimente la convection, donc les chances de nuages et de précipitations augmentent l'après-midi. Placer la partie la plus dure et la plus critique de la course avant l'aube, c'est s'offrir une fenêtre plus clémente.",

    "q.m10#8.p" to "Quel est le rapport entre l'heure de demi-tour et la fenêtre météo ?",
    "q.m10#8.o0" to "Ils n'ont aucun rapport",
    "q.m10#8.o1" to "L'heure de demi-tour doit être déduite de la fenêtre météo ; une fenêtre qui se resserre la fait avancer",
    "q.m10#8.o2" to "L'heure de demi-tour est toujours fixe",
    "q.m10#8.o3" to "Par beau temps, aucune heure de demi-tour n'est nécessaire",
    "q.m10#8.e" to "L'heure de demi-tour n'est pas un chiffre fixe : elle se calcule à partir de la fenêtre du jour. Combien de temps jusqu'au sommet, combien de temps pour descendre, quand la fenêtre commence à se fermer — en raisonnant à rebours, on obtient le dernier moment où il faut faire demi-tour.",

    "q.m10#9.p" to "[Ordre] Remettez dans un ordre logique les étapes d'une évaluation météo de routine.",
    "q.m10#9.o0" to "Avant le départ, consulter la prévision régionale et la tendance de pression",
    "q.m10#9.o1" to "En marchant, observer nuages, vent et visibilité à intervalles réguliers",
    "q.m10#9.o2" to "Comparer les observations de terrain à la prévision pour juger la direction de la tendance",
    "q.m10#9.o3" to "Ajuster le plan ou faire demi-tour tôt selon cette tendance",
    "q.m10#9.e" to "La troisième étape est le nœud — beaucoup s'arrêtent à la deuxième, en sentant que le temps change sans transformer cela en décision. Une observation qui ne devient jamais une action n'est pas une observation.",

    "q.m10#10.p" to "Quand la fenêtre météo se resserre, à quoi faut-il renoncer en premier ?",
    "q.m10#10.o0" to "Au matériel de sécurité",
    "q.m10#10.o1" to "À l'objectif du sommet lui-même",
    "q.m10#10.o2" to "Aux membres de la cordée",
    "q.m10#10.o3" to "Au matériel de communication",
    "q.m10#10.e" to "C'est une question de priorité : quand la fenêtre ne peut pas contenir à la fois le sommet et une descente sûre, ce que l'on garde c'est la descente et ce que l'on abandonne c'est le sommet. Décidez-le avant de partir, pas sur la montagne.",

    "q.m10#11.p" to "Quelle vision des conditions de voile blanc est correcte ?",
    "q.m10#11.o0" to "Juste une mauvaise visibilité, aucun danger",
    "q.m10#11.o1" to "On perd tout repère visuel et on marche instinctivement dans la mauvaise direction — fixer sa position d'abord",
    "q.m10#11.o2" to "Cela apporte des précipitations",
    "q.m10#11.o3" to "Cela n'arrive que la nuit",
    "q.m10#11.e" to "Le danger du voile blanc n'est pas de ne pas voir — c'est de croire que l'on voit. Sans repères, le sens de l'orientation dérive systématiquement : le premier travail est donc de fixer sa position et de noter le cap, pas de continuer à marcher.",
    // ---------- m11 Sommets de 6 000 m ----------
    "q.m11#0.p" to "Quelles sont l'altitude et la localisation du Yuzhu ?",
    "q.m11#0.o0" to "6 178 m, Golmud, Qinghai, partie orientale du Kunlun",
    "q.m11#0.o1" to "6 206 m, Damxung, Tibet, chaîne du Nyainqêntanglha",
    "q.m11#0.o2" to "6 119 m, Khumbu, Népal",
    "q.m11#0.o3" to "6 189 m, Khumbu, Népal",
    "q.m11#0.e" to "Le Yuzhu culmine à 6 178 m, dans la partie orientale du Kunlun, sur le territoire de Golmud au Qinghai. Son itinéraire du versant sud est relativement doux et l'accès est bon, ce qui en fait le premier 6 000 m de beaucoup de monde.",

    "q.m11#1.p" to "Quelles sont l'altitude et la chaîne du Qizi ?",
    "q.m11#1.o0" to "6 178 m, chaîne du Kunlun",
    "q.m11#1.o1" to "6 206 m, chaîne du Nyainqêntanglha",
    "q.m11#1.o2" to "6 119 m, Himalaya",
    "q.m11#1.o3" to "6 189 m, Karakoram",
    "q.m11#1.e" to "Le Qizi culmine à 6 206 m, dans la chaîne du Nyainqêntanglha, à Damxung au Tibet. Son signe distinctif : des pentes de neige stables et un accès facile — des pentes stables signifient un risque d'avalanche et de crevasse relativement maîtrisable, ce qui le destine à la formation progressive.",

    "q.m11#2.p" to "Quelles sont l'altitude et la localisation du Lobuche Est ?",
    "q.m11#2.o0" to "6 119 m, Khumbu, Népal",
    "q.m11#2.o1" to "6 189 m, Khumbu, Népal",
    "q.m11#2.o2" to "6 206 m, Damxung, Tibet",
    "q.m11#2.o3" to "6 178 m, Golmud, Qinghai",
    "q.m11#2.e" to "Le Lobuche Est culmine à 6 119 m dans la région du Khumbu au Népal, juste à côté de l'itinéraire de trekking de l'Everest. Cette position signifie une acclimatation et une logistique bien établies, et ses pentes de neige plus raides en font un bon marchepied vers la haute altitude.",

    "q.m11#3.p" to "Quel est le trait technique le plus typique de l'Island Peak (Imja Tse) ?",
    "q.m11#3.o0" to "Aucun matériel technique nécessaire",
    "q.m11#3.o1" to "L'encordement et la progression sur crevasses",
    "q.m11#3.o2" to "Oxygène supplémentaire obligatoire",
    "q.m11#3.o3" to "Capacités d'escalade rocheuse obligatoires",
    "q.m11#3.e" to "L'Island Peak, à 6 189 m, est un 6 000 m technique classique : on s'encorde et on gère les crevasses. C'est aussi pourquoi il sert de préparation aux 7 000 m — il met réellement en œuvre le système progression glaciaire plus cordée.",

    "q.m11#4.p" to "Comparé aux 5 000 m, quel risque augmente le plus à 6 000 m ?",
    "q.m11#4.o0" to "Les chutes de pierres",
    "q.m11#4.o1" to "La pression d'acclimatation et le risque de mal d'altitude",
    "q.m11#4.o2" to "Les insectes",
    "q.m11#4.o3" to "Le poids du matériel",
    "q.m11#4.e" to "Au-dessus de 6 000 m, l'incidence et la gravité du mal d'altitude augmentent nettement — c'est pourquoi cette unité traite le mal d'altitude comme un chapitre central. Techniquement, l'étape peut être progressive, mais l'étape physiologique est bien réelle.",

    "q.m11#5.p" to "[Choix multiple] Que faut-il déjà maîtriser avant un sommet de 6 000 m ?",
    "q.m11#5.o0" to "L'usage de base des crampons et du piolet",
    "q.m11#5.o1" to "Les nœuds de base et la progression encordée",
    "q.m11#5.o2" to "Reconnaître et gérer le mal d'altitude",
    "q.m11#5.o3" to "Une compréhension de base du risque de crevasse",
    "q.m11#5.o4" to "Mener en tête une glace WI5 en autonomie",
    "q.m11#5.e" to "Les quatre premiers correspondent aux unités d'initiation et de progression à 5 000 m. L'unité 6 000 m ne les réenseigne pas : elle les met dans un environnement plus dur. Aller directement à 6 000 m avec des bases fragiles multiplie le risque.",

    "q.m11#6.p" to "Pourquoi le versant sud du Yuzhu est-il souvent le premier objectif à 6 000 m ?",
    "q.m11#6.o0" to "Parce que c'est le moins cher",
    "q.m11#6.o1" to "Parce que l'itinéraire est relativement doux et l'accès et la logistique bien établis, ce qui permet de se concentrer sur l'acclimatation",
    "q.m11#6.o2" to "Parce qu'il n'y a aucun danger",
    "q.m11#6.o3" to "Parce qu'il ne demande pas de guide",
    "q.m11#6.e" to "La valeur d'un premier objectif est de n'ajouter qu'une seule variable nouvelle. Le versant sud garde la difficulté technique dans une plage gérable pour se concentrer sur le vrai défi — l'acclimatation. Choisissez un 6 000 m techniquement exigeant et vous ne saurez plus ce qui a échoué.",

    "q.m11#7.p" to "[Ordre] Classez ces objectifs de l'altitude la plus basse à la plus haute.",
    "q.m11#7.o0" to "Lobuche Est (6 119 m)",
    "q.m11#7.o1" to "Yuzhu (6 178 m)",
    "q.m11#7.o2" to "Island Peak (6 189 m)",
    "q.m11#7.o3" to "Qizi (6 206 m)",
    "q.m11#7.e" to "L'écart d'altitude est minime — de 6 119 à 6 206 m, moins de 90 m. Ce qui illustre parfaitement le point : dans la tranche des 6 000 m, on choisit selon le type d'itinéraire, l'encadrement et ses propres points faibles, pas selon le chiffre de hauteur.",

    "q.m11#8.p" to "Pourquoi faut-il supposer des crevasses présentes à 6 000 m ?",
    "q.m11#8.o0" to "Parce que les crevasses font du bruit",
    "q.m11#8.o1" to "Parce que les ponts de neige peuvent être entièrement recouverts de neige fraîche et ressembler à un sol ordinaire",
    "q.m11#8.o2" to "Parce que les crevasses n'apparaissent que la nuit",
    "q.m11#8.o3" to "Parce que les crevasses sont faciles à identifier",
    "q.m11#8.e" to "C'est exactement ce qui rend les crevasses si meurtrières : contrairement aux chutes de pierres, elles n'avertissent pas clairement. Le bon état d'esprit à 6 000 m est « il y en a partout », en gérant le risque par les cordées et le matériel plutôt qu'en jugeant si cela paraît sûr.",

    "q.m11#9.p" to "Pour choisir un sommet de 6 000 m, qu'est-ce qui compte plus que l'altitude ?",
    "q.m11#9.o0" to "La célébrité du sommet",
    "q.m11#9.o1" to "Le type d'itinéraire (randonnée / mixte / technique), les conditions d'encadrement et le rythme d'ascension",
    "q.m11#9.o2" to "Le coût",
    "q.m11#9.o3" to "La popularité sur les réseaux sociaux",
    "q.m11#9.e" to "Des sommets d'altitude voisine peuvent différer énormément en exigence technique et en pression d'acclimatation. C'est en combinant type d'itinéraire, encadrement et rythme d'ascension qu'on répond à « cette montagne est-elle adaptée à moi, maintenant ».",

    "q.m11#10.p" to "Quelle vision du seuil technique des 6 000 m est correcte ?",
    "q.m11#10.o0" to "Il est très bas ; seule la condition physique compte",
    "q.m11#10.o1" to "Il n'est pas élevé, mais on ne part pas de zéro, et les compétences de progression glaciaire sont obligatoires",
    "q.m11#10.o2" to "Il faut avoir un passé d'escalade rocheuse",
    "q.m11#10.o3" to "Il faut savoir utiliser de l'oxygène supplémentaire",
    "q.m11#10.e" to "Le profil typique d'un 6 000 m : difficulté technique modérée, mais il faut déjà savoir s'encorder, juger le risque de crevasse et progresser en autonomie sur un glacier. C'est là que commence le « je sais me protéger avec un système » — pas là où l'on regarde les autres le faire.",

    "q.m11#11.p" to "Pourquoi la meilleure saison d'un sommet est-elle si déterminante pour le plan ?",
    "q.m11#11.o0" to "Parce que les permis sont moins chers hors saison",
    "q.m11#11.o1" to "Parce que la fenêtre praticable dépend fortement des schémas météo saisonniers ; la mauvaise saison peut n'offrir presque aucune fenêtre",
    "q.m11#11.o2" to "Parce que la saison change la couleur de la neige",
    "q.m11#11.o3" to "Parce que les guides ne travaillent qu'en haute saison",
    "q.m11#11.e" to "Les raisons diffèrent selon le sommet : certaines saisons évitent les précipitations de mousson, d'autres évitent le froid et le vent extrêmes de l'hiver. Comprendre pourquoi une saison fonctionne compte bien plus que mémoriser un mois — d'autant que le changement climatique déplace ces schémas.",

    // ---------- m12 Mouflage ----------
    "q.m12#0.p" to "Pourquoi un système en Z 3:1 multiplie-t-il la force de traction par trois ?",
    "q.m12#0.o0" to "Parce qu'il utilise une corde plus épaisse",
    "q.m12#0.o1" to "Parce que la combinaison prussik + poulie multiplie par trois la distance que vous tirez",
    "q.m12#0.o2" to "Parce que la gravité aide",
    "q.m12#0.o3" to "Parce que les poulies économisent l'effort automatiquement",
    "q.m12#0.e" to "Le mouflage consiste fondamentalement à échanger de la distance contre de la force : vous tirez trois mètres de corde et la charge monte d'un mètre. Le prix est la vitesse — et dans un sauvetage en crevasse, ce prix est parfaitement acceptable.",

    "q.m12#1.p" to "Quel est le rôle principal de la poulie dans un système de sauvetage ?",
    "q.m12#1.o0" to "Apporter de la résistance supplémentaire",
    "q.m12#1.o1" to "Réduire les pertes par frottement de la corde et améliorer l'efficacité du système",
    "q.m12#1.o2" to "Fixer la corde",
    "q.m12#1.o3" to "Protéger la corde de l'usure",
    "q.m12#1.e" to "Le frottement est l'ennemi caché du mouflage : chaque renvoi coûte de la force. Une poulie transforme le frottement de glissement en frottement de roulement, si bien que le 3:1 théorique s'approche d'un vrai 3:1.",

    "q.m12#2.p" to "Peut-on monter un système de sauvetage sans poulies ?",
    "q.m12#2.o0" to "Pas du tout",
    "q.m12#2.o1" to "Oui, avec des mousquetons — mais le frottement augmente nettement et l'efficacité chute",
    "q.m12#2.o2" to "Oui, avec la corde seule, à efficacité égale",
    "q.m12#2.o3" to "Non, il faut attendre du matériel",
    "q.m12#2.e" to "Les mousquetons peuvent remplacer les poulies, ce qui explique que beaucoup de cordées considèrent les mousquetons à vis de réserve comme obligatoires. La différence est que le mouflage réel tombe bien en dessous de la valeur théorique — le savoir permet de se préparer moralement et physiquement quand le matériel est incomplet.",

    "q.m12#3.p" to "[Choix multiple] Que cite le manuel comme matériel standard de sauvetage en cordée ?",
    "q.m12#3.o0" to "2 à 3 piquets à neige ou broches à glace",
    "q.m12#3.o1" to "2 à 5 mousquetons et 2 à 5 sangles",
    "q.m12#3.o2" to "1 poulie d'assurage",
    "q.m12#3.o3" to "2 à 3 prussiks et 1 bloqueur",
    "q.m12#3.o4" to "1 réchaud portable et une cartouche de gaz",
    "q.m12#3.e" to "La ligne clé de cette liste est que chaque membre de la cordée doit porter assez de matériel de sauvetage — autrement dit, c'est un équipement personnel, pas du matériel collectif partagé. Quand quelqu'un tombe, ce qui est sur votre baudrier est le seul matériel disponible.",

    "q.m12#4.p" to "Comment un bloqueur freine-t-il ?",
    "q.m12#4.o0" to "Par un ressort qui serre la corde",
    "q.m12#4.o1" to "Par frottement inverse entre les dents d'acier et la corde",
    "q.m12#4.o2" to "Par attraction magnétique",
    "q.m12#4.o3" to "Par le poids de la corde",
    "q.m12#4.e" to "Comprendre le mécanisme compte à l'usage : comme les dents d'acier mordent les fibres, une force excessive endommage la corde et peut couper des fibres au point chargé. C'est pourquoi le manuel insiste pour l'utiliser autant que possible avec une méthode d'assurage assisté.",

    "q.m12#5.p" to "Que se passe-t-il si l'on tire trop brutalement sur un bloqueur ?",
    "q.m12#5.o0" to "Rien du tout",
    "q.m12#5.o1" to "Les dents d'acier abîment la corde",
    "q.m12#5.o2" to "Le bloqueur se coince",
    "q.m12#5.o3" to "Le bloqueur se détache",
    "q.m12#5.e" to "Les dents freinent par frottement inverse : une force importante marque la gaine et, cumulativement, peut créer un point de rupture. On voit beaucoup de gens tirer ainsi par habitude — échanger une habitude contre un risque.",

    "q.m12#6.p" to "[Ordre] Remettez dans un ordre logique les étapes de construction d'un système en Z 3:1.",
    "q.m12#6.o0" to "Confirmer que l'ancrage est sain et y transférer le poids de la personne qui a chuté",
    "q.m12#6.o1" to "Installer le prussik principal sur la corde chargée et ajouter un prussik de sécurité",
    "q.m12#6.o2" to "Connecter une poulie ou un mousqueton au prussik pour former le trajet en Z",
    "q.m12#6.o3" to "Vérifier tout le système, puis hisser en retendant après chaque traction",
    "q.m12#6.e" to "La première étape est la fondation : sans transfert du poids, vos mains restent mobilisées à tenir l'arrêt. Et la dernière — retendre après chaque traction — est facilement oubliée, ce qui fait hisser pendant des lustres pour ensuite glisser en arrière.",

    "q.m12#7.p" to "[Association] Associez chaque élément de sauvetage à son rôle dans le système.",
    "q.m12#7.l0" to "Prussik",
    "q.m12#7.r0" to "Serrage à sens unique, pour que le système avance sans reculer",
    "q.m12#7.l1" to "Poulie",
    "q.m12#7.r1" to "Réduit les pertes par frottement et améliore l'efficacité",
    "q.m12#7.l2" to "Poulie d'assurage",
    "q.m12#7.r2" to "Se verrouille dans un sens ; sert à contrôler le filage et la tension",
    "q.m12#7.l3" to "Bloqueur",
    "q.m12#7.r3" to "Remonte le long de la corde ; utile aussi pour fixer le système",
    "q.m12#7.e" to "Quatre fonctions différentes : le prussik apporte le comportement unidirectionnel, la poulie réduit le frottement, le dispositif d'assurage apporte le contrôle, et le bloqueur apporte la mobilité. Perdez-en un et le système devient soit inefficace, soit incontrôlable.",

    "q.m12#8.p" to "Pourquoi ajouter un prussik de sécurité à côté du principal ?",
    "q.m12#8.o0" to "Pour l'esthétique",
    "q.m12#8.o1" to "Parce qu'un prussik peut lâcher à cause du givre, de la saleté ou de diamètres inadaptés, et que sa défaillance fait perdre instantanément le mouflage",
    "q.m12#8.o2" to "Parce que le règlement l'exige",
    "q.m12#8.o3" to "Pour éviter que la corde ne s'entortille",
    "q.m12#8.e" to "Un prussik fonctionne par frottement, et le frottement dépend de beaucoup de choses. Si le principal glisse, la personne qui a chuté retombe sans avertissement — le rôle du prussik de sécurité est de rattraper cet instant.",

    "q.m12#9.p" to "Comment choisir entre un système 2:1 et un système 3:1 ?",
    "q.m12#9.o0" to "Le 2:1 est toujours meilleur",
    "q.m12#9.o1" to "Selon le monde disponible, la longueur de corde et le terrain : plus de mouflage demande plus de corde et va plus lentement",
    "q.m12#9.o2" to "Le 3:1 est toujours meilleur",
    "q.m12#9.o3" to "Ils sont identiques",
    "q.m12#9.e" to "Le mouflage n'est pas inconditionnellement bon : le 3:1 demande plus de corde, et un sauvetage en crevasse dispose souvent de peu de corde. Le vrai choix est le système que vous pouvez monter avec la corde et les personnes disponibles — pas le système théoriquement optimal.",

    "q.m12#10.p" to "Pourquoi un système de mouflage ne peut-il jamais remplacer le jugement ?",
    "q.m12#10.o0" to "Parce que les systèmes cassent",
    "q.m12#10.o1" to "Parce qu'un système ne fait que multiplier la force ; il ne décide pas s'il faut hisser ni dans quelle direction",
    "q.m12#10.o2" to "Parce que les systèmes sont lourds",
    "q.m12#10.o3" to "Parce qu'ils demandent beaucoup de monde",
    "q.m12#10.e" to "La partie difficile d'un sauvetage n'est jamais la physique, c'est le jugement — par où, au-dessus de quel bord, et si la victime peut le supporter. Le système est un outil ; la direction vient des personnes. Mauvaise direction plus de force égale pire résultat.",

    "q.m12#11.p" to "Lequel de ces éléments ne fait pas échouer un prussik ?",
    "q.m12#11.o0" to "Des diamètres de corde inadaptés",
    "q.m12#11.o1" to "Le givre ou la saleté",
    "q.m12#11.o2" to "Un nombre de tours insuffisant",
    "q.m12#11.o3" to "Une corde principale d'une couleur plus claire",
    "q.m12#11.e" to "Le diamètre, la propreté et le nombre de tours influencent directement le frottement ; la couleur n'a aucun rapport avec la mécanique. Cela montre aussi que la fiabilité d'un prussik ne se juge pas à l'œil — seulement en vérifiant la combinaison à l'avance et en l'essayant sur le terrain.",

    "q.m12#12.p" to "Pourquoi utilise-t-on souvent une poulie d'assurage plutôt qu'une poulie simple ?",
    "q.m12#12.o0" to "Parce qu'elle est plus légère",
    "q.m12#12.o1" to "Parce qu'elle se verrouille dans un sens, ce qui permet de contrôler le mou sans que le système recule",
    "q.m12#12.o2" to "Parce qu'elle coûte moins cher",
    "q.m12#12.o3" to "Parce que sa couleur est plus visible",
    "q.m12#12.e" to "Un sauvetage implique souvent de hisser et d'ajuster en même temps, et une poulie simple tourne librement dans les deux sens — lâchez et vous perdez le progrès. Un composant qui se verrouille dans un sens fait du maintien en position une propriété du système. Un exemple clair de choix de matériel qui influence la sécurité opérationnelle.",

    "q.m12#13.p" to "Complétez : le mouflage du système en Z est de ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "trois",
    "q.m12#13.e" to "3:1. La valeur pratique de ce chiffre est l'estimation de la charge : un adulte équipé peut peser 80 à 100 kg, donc à 3:1 il faut encore tirer avec environ 30 kg de force — bien plus dur que ça en a l'air, d'où la nécessité de plusieurs personnes pour un sauvetage.",

    "q.m12#14.p" to "[Choix multiple] Que doit couvrir le contrôle après construction ?",
    "q.m12#14.o0" to "Les tours du prussik et la direction de charge sont corrects",
    "q.m12#14.o1" to "Les poulies et les mousquetons sont verrouillés",
    "q.m12#14.o2" to "Les points d'attache sont sur la bonne partie du baudrier",
    "q.m12#14.o3" to "Une sécurité est en place et la corde n'est pas coincée",
    "q.m12#14.o4" to "La corde et les vêtements des compagnons sont de la même couleur",
    "q.m12#14.e" to "Ces quatre contrôles correspondent à quatre erreurs classiques : prussik à l'envers, mousqueton non verrouillé, mousquetonné sur la mauvaise boucle, absence de sécurité. Les défaillances de système de sauvetage viennent rarement d'un manque de connaissances — mais d'une étape oubliée dans le noir et sous stress. Utilisez une liste de contrôle, pas la mémoire.",

    "q.m12#15.p" to "Pourquoi un système de sauvetage doit-il être répété avant le départ ?",
    "q.m12#15.o0" to "Pour réussir une évaluation",
    "q.m12#15.o1" to "Parce que le vrai sauvetage se déroule en altitude, dans le froid et l'obscurité, exécuté par instinct",
    "q.m12#15.o2" to "Pour se familiariser avec le matériel",
    "q.m12#15.o3" to "Parce que la réglementation impose des heures de répétition",
    "q.m12#15.e" to "Les conditions d'un vrai sauvetage sont presque toujours les pires possibles : du vent, des mains froides, une mauvaise lumière, un compagnon qui s'aggrave. Les seules actions qui se font dans ces conditions sont celles qu'on a répétées de nombreuses fois auparavant — apprendre sur place n'est pas une option.",
    // ---------- m13 Auto-sauvetage ----------
    "q.m13#0.p" to "Pourquoi l'auto-sauvetage est-il une exigence absolue à 7 000 m ?",
    "q.m13#0.o0" to "Parce que les compagnons ne veulent pas vous secourir",
    "q.m13#0.o1" to "Parce qu'en conditions de haute altitude, les compagnons peuvent ne pas vous atteindre à temps — vous devez savoir gérer votre propre situation",
    "q.m13#0.o2" to "Parce que le matériel de sauvetage est insuffisant",
    "q.m13#0.o3" to "Parce que le règlement l'exige",
    "q.m13#0.e" to "Plus on monte, plus le sauvetage coûte cher et devient lent. Un compagnon peut être lui-même en lutte contre le mal d'altitude, et la météo peut interdire tout déplacement. Se remettre entièrement aux secours extérieurs, c'est accepter une prémisse que personne ne peut garantir.",

    "q.m13#1.p" to "Quel est le principe de base de la remontée au prussik ?",
    "q.m13#1.o0" to "Se hisser à la force des bras",
    "q.m13#1.o1" to "Alterner deux prussiks : l'un porte le poids pendant que l'autre coulisse vers le haut",
    "q.m13#1.o2" to "Le faire seul avec un bloqueur",
    "q.m13#1.o3" to "Serrer la corde entre ses jambes",
    "q.m13#1.e" to "Un seul prussik ne fait que tenir une position — il ne peut pas se déplacer — d'où l'alternance de deux : pendant que celui du bas porte le poids, celui du haut remonte, et inversement. Ce mouvement alterné doit être répété en sécurité ; c'est lui qui décidera, au moment où vous en aurez le plus besoin, si vous remontez ou non.",

    "q.m13#2.p" to "Pourquoi au moins un prussik doit-il toujours rester chargé pendant la remontée ?",
    "q.m13#2.o0" to "Pour économiser l'effort",
    "q.m13#2.o1" to "Parce que les relâcher tous les deux en même temps vous fait redescendre au point de départ ou chuter franchement",
    "q.m13#2.o2" to "Pour garder la corde rangée",
    "q.m13#2.o3" to "Pour monter plus vite",
    "q.m13#2.e" to "C'est la règle des trois points appliquée à la corde : toujours garder un point d'appui fiable. Dans une crevasse, une glissade ne fait pas que vider de ses forces : elle peut laisser la corde scier davantage la lèvre de neige et augmenter la difficulté de tout le sauvetage.",

    "q.m13#3.p" to "[Ordre] Remettez dans le bon ordre les quatre étapes d'un sauvetage en cordée.",
    "q.m13#3.o0" to "S'arrêter immédiatement en auto-arrêt et se stabiliser",
    "q.m13#3.o1" to "Construire un ancrage indépendant",
    "q.m13#3.o2" to "Transférer la charge sur l'ancrage",
    "q.m13#3.o3" to "Hisser avec un système 3:1",
    "q.m13#3.e" to "Vous avez appris ces quatre étapes dans l'unité 6 000 m ; ce qui compte ici est de les exécuter sous pression. Le plus grand écart entre l'entraînement et la réalité : dans la réalité il faut boucler les trois premières étapes en quelques dizaines de secondes, alors qu'à l'entraînement on a pu y passer cinq minutes.",

    "q.m13#4.p" to "À quelle distance les membres de la cordée doivent-ils rester les uns des autres en cas d'orage ?",
    "q.m13#4.o0" to "Serrés les uns contre les autres",
    "q.m13#4.o1" to "Environ 50 m",
    "q.m13#4.o2" to "Environ 500 m",
    "q.m13#4.o3" to "Sans limite",
    "q.m13#4.e" to "Le manuel suggère environ 50 m — l'idée est d'éviter qu'un seul impact blesse plusieurs personnes à la fois, de sorte que quelqu'un reste capable de donner les premiers secours. Derrière le chiffre, une idée simple : ne jamais tout miser au même endroit.",

    "q.m13#5.p" to "Quel est le seul moyen efficace de réduire le danger pendant un orage ?",
    "q.m13#5.o0" to "Jeter le matériel métallique comme les piolets",
    "q.m13#5.o1" to "Quitter les points hauts et les terrains exposés le plus vite possible, en restant aussi bas que possible",
    "q.m13#5.o2" to "S'accroupir en serrant les genoux",
    "q.m13#5.o3" to "Ouvrir toutes ses fermetures",
    "q.m13#5.e" to "Le manuel rejette explicitement plusieurs pratiques courantes : rien ne prouve que de petits objets métalliques comme un piolet ou des arceaux de tente attirent la foudre, donc ne perdez pas de temps à les jeter. Ce qui marche réellement, c'est de changer de position — passer de l'objet le plus haut alentour à une partie discrète du paysage.",

    "q.m13#6.p" to "Si vous entendez le tonnerre, la foudre n'est pas plus loin que :",
    "q.m13#6.o0" to "3 km",
    "q.m13#6.o1" to "10–16 km",
    "q.m13#6.o2" to "30 km",
    "q.m13#6.o3" to "50 km",
    "q.m13#6.e" to "Entendre le tonnerre signifie que la foudre est à moins de 10–16 km, déjà dans la zone où il faut réagir. Voir un éclair signifie que la distance n'excède pas environ 24 km — deux chiffres, deux niveaux de réponse.",

    "q.m13#7.p" to "Comment estimer la distance de la foudre à partir du délai éclair-tonnerre ?",
    "q.m13#7.o0" to "Secondes × 0,34 = distance en km",
    "q.m13#7.o1" to "Secondes ÷ 0,34 = distance en km",
    "q.m13#7.o2" to "Secondes × 3,4 = distance en km",
    "q.m13#7.o3" to "Cela ne peut pas s'estimer",
    "q.m13#7.e" to "Le son se propage dans l'air à environ 0,34 km par seconde : chaque seconde comptée après l'éclair vaut donc à peu près 0,34 km. L'intérêt pratique : sans aucun matériel, vous pouvez dire si l'orage approche ou s'éloigne.",

    "q.m13#8.p" to "Les petits objets métalliques (piolet, arceaux de tente) attirent-ils la foudre ?",
    "q.m13#8.o0" to "Oui — il faut les jeter immédiatement",
    "q.m13#8.o1" to "Rien ne le prouve, donc ne perdez pas de temps à les jeter",
    "q.m13#8.o2" to "Oui, mais seulement en haute altitude",
    "q.m13#8.o3" to "Seulement lorsqu'ils sont mouillés",
    "q.m13#8.e" to "C'est un mythe classique de haute altitude. Le manuel est direct : aucun élément ne le soutient, donc ne consacrez pas un temps précieux à vous séparer du matériel. Ce qu'il faut, c'est quitter la position exposée le plus vite possible — c'est la variable décisive.",

    "q.m13#9.p" to "Quel est le meilleur abri pendant un orage ?",
    "q.m13#9.o0" to "Un sommet",
    "q.m13#9.o1" to "Le milieu d'un bois, loin du sommet et de la crête — mais jamais adossé à un arbre",
    "q.m13#9.o2" to "Le milieu d'une pente herbeuse",
    "q.m13#9.o3" to "Sous une tente",
    "q.m13#9.e" to "Le milieu d'un bois fonctionne parce qu'il y a des objets plus hauts autour de vous, sans être directement contre un conducteur. Le contre-exemple est de camper sur une crête dégagée — le manuel qualifie cela d'extrêmement stupide, car cela revient à s'installer délibérément au point le plus haut alentour.",

    "q.m13#10.p" to "Pourquoi ne pas camper sur une crête quand des cumulus se développent ?",
    "q.m13#10.o0" to "Parce que le vent est fort",
    "q.m13#10.o1" to "Parce que des cumulus évoluant en cumulonimbus signifient de la foudre, et qu'une crête est l'endroit le plus exposé qui soit",
    "q.m13#10.o2" to "Parce que la visibilité est mauvaise",
    "q.m13#10.o3" to "Parce que le sol est irrégulier",
    "q.m13#10.e" to "Le passage de cumulus à cumulonimbus ne prend souvent qu'une ou deux heures. Camper sur une crête vous place à l'avant exact de la trajectoire de l'orage — avec tout votre matériel et vos tentes, dans un état où une évacuation rapide est presque impossible.",

    "q.m13#11.p" to "Quelqu'un vient d'être frappé par la foudre. Quelle est la première priorité ?",
    "q.m13#11.o0" to "Vérifier d'abord les blessures externes",
    "q.m13#11.o1" to "Vérifier immédiatement la respiration et le pouls, commencer une réanimation si nécessaire, et obtenir une aide médicale au plus vite",
    "q.m13#11.o2" to "Le changer d'abord en vêtements secs",
    "q.m13#11.o3" to "Le déplacer d'abord vers un terrain plus bas",
    "q.m13#11.e" to "Un impact peut provoquer un arrêt cardiaque et des lésions internes sans laisser de signe visible. Vérifier la respiration et le pouls passe donc avant tout le reste — et même un patient conscient doit être évacué, car l'effet du courant sur le cœur peut apparaître plus tard.",

    "q.m13#12.p" to "[Choix multiple] Que comprend généralement la capacité d'auto-sauvetage ?",
    "q.m13#12.o0" to "La remontée au prussik",
    "q.m13#12.o1" to "L'auto-arrêt et l'auto-protection",
    "q.m13#12.o2" to "Construire un ancrage sans l'aide d'un compagnon",
    "q.m13#12.o3" to "Juger quand attendre sur place et quand se dégager soi-même",
    "q.m13#12.o4" to "L'escalade en solo sans protection",
    "q.m13#12.e" to "Les trois premiers sont des compétences, le quatrième est du jugement. Attention particulièrement à « juger quand attendre sur place et quand se dégager » : toute situation n'appelle pas l'auto-dégagement — si vous êtes blessé ou que la météo se dégrade, rester sur place et attendre les secours peut être plus sûr que de bouger précipitamment.",

    "q.m13#13.p" to "Pourquoi « attendre que mon compagnon me secoure » ne peut-il pas servir de stratégie de sécurité principale ?",
    "q.m13#13.o0" to "Parce que les compagnons peuvent ne pas vouloir",
    "q.m13#13.o1" to "Parce que le compagnon peut lui-même être en danger, blessé ou incapable de bouger",
    "q.m13#13.o2" to "Parce qu'il n'y a pas assez de matériel de sauvetage",
    "q.m13#13.o3" to "Parce que le règlement ne le permet pas",
    "q.m13#13.e" to "S'encorder sert à la protection mutuelle, mais on ne peut pas supposer que son compagnon a de la capacité en réserve. En altitude, un membre de la cordée qui gère les problèmes de deux personnes dépasse souvent le possible — l'auto-sauvetage est donc une exigence, et le sauvetage par le compagnon un bonus.",
    // ---------- m14 Jugement du danger et décision ----------
    "q.m14#0.p" to "Quelle question le jugement du danger cherche-t-il réellement à trancher ?",
    "q.m14#0.o0" to "Y a-t-il un danger ?",
    "q.m14#0.o1" to "Ce risque est-il acceptable, et sur quelle base ?",
    "q.m14#0.o2" to "Quelle est l'ampleur du danger ?",
    "q.m14#0.o3" to "Mes compagnons vont-ils avoir peur ?",
    "q.m14#0.e" to "« Y a-t-il un danger ? » appelle presque toujours « oui » — aucune activité en montagne n'est exempte de risque. La vraie question est de savoir si ce risque vaut la peine d'être pris au regard du bénéfice, et sur quoi nous fondons ce jugement. C'est exactement pourquoi il doit être formulable et discutable.",

    "q.m14#1.p" to "Qu'est-ce que la « chaîne d'accident » ?",
    "q.m14#1.o0" to "Le nombre de victimes dans un accident",
    "q.m14#1.o1" to "Un processus dans lequel plusieurs petites erreurs s'empilent successivement jusqu'à provoquer un accident",
    "q.m14#1.o2" to "La chronologie d'un sauvetage",
    "q.m14#1.o3" to "Une chaîne de défaillances du matériel",
    "q.m14#1.e" to "La valeur du concept est de transformer l'accident d'une malchance en un processus sur lequel on peut intervenir. Changez un choix à n'importe quel maillon et le résultat change.",

    "q.m14#2.p" to "Quel est le moyen le plus efficace de briser la chaîne d'accident ?",
    "q.m14#2.o0" to "Faire un choix plus prudent à n'importe quel maillon",
    "q.m14#2.o1" to "Se concentrer uniquement sur le dernier maillon",
    "q.m14#2.o2" to "Emporter plus de matériel",
    "q.m14#2.o3" to "Améliorer la condition physique de la cordée",
    "q.m14#2.e" to "N'importe quel maillon suffit — partir plus tôt, faire demi-tour à l'heure, ne pas réduire la protection pour gagner du temps. C'est aussi pourquoi la marge vaut mieux que le remède : la marge agit tôt dans la chaîne, le remède intervient généralement au dernier maillon.",

    "q.m14#3.p" to "[Choix multiple] Lesquels de ces biais de décision sont courants ?",
    "q.m14#3.o0" to "Le coût irrécupérable",
    "q.m14#3.o1" to "La pression du groupe",
    "q.m14#3.o2" to "La fixation sur l'objectif",
    "q.m14#3.o3" to "La normalisation du risque",
    "q.m14#3.o4" to "La confiance dans les marques de matériel",
    "q.m14#3.e" to "Les quatre agissent en combinaison : on a déjà beaucoup investi (coût irrécupérable), tout le monde continue de monter (pression du groupe), on y est presque (fixation sur l'objectif), et la dernière fois ça s'est bien passé (normalisation du risque). Quand les quatre apparaissent ensemble, le jugement penche presque inévitablement vers la prise de risque.",

    "q.m14#4.p" to "Comment le coût irrécupérable influence-t-il les décisions en alpinisme ?",
    "q.m14#4.o0" to "Il rend les gens plus prudents",
    "q.m14#4.o1" to "Ayant déjà investi tant de temps et d'argent, on rechigne à admettre qu'il faut arrêter",
    "q.m14#4.o2" to "Il améliore la condition physique",
    "q.m14#4.o3" to "Il n'a aucun effet",
    "q.m14#4.e" to "Ce qui définit le coût irrécupérable, c'est qu'il ne peut pas être récupéré — et pourtant, psychologiquement, il devient une raison de continuer à investir. En montagne, combiné à la fixation sur l'objectif, il transforme un repli rationnel en « abandon », et les gens ont une résistance naturelle à abandonner.",

    "q.m14#5.p" to "Qu'est-ce que la « normalisation du risque » ?",
    "q.m14#5.o0" to "Maintenir le danger dans une plage acceptable",
    "q.m14#5.o1" to "Après avoir passé plusieurs fois une condition donnée sans encombre, la reclasser inconsciemment comme « sûre »",
    "q.m14#5.o2" to "Apprendre des méthodes d'évaluation du risque",
    "q.m14#5.o3" to "Utiliser une cotation standardisée du risque",
    "q.m14#5.e" to "La normalisation du risque se fait lentement, c'est pourquoi la personne concernée la remarque à peine. Le même alpiniste peut être extrêmement prudent la première fois sur une pente raide et ne plus s'encorder à la dixième — la pente n'a pas changé, le jugement si.",

    "q.m14#6.p" to "Pourquoi la règle majoritaire pose-t-elle problème en environnement à haut risque ?",
    "q.m14#6.o0" to "Parce qu'elle est inefficace",
    "q.m14#6.o1" to "Parce que la règle majoritaire permet d'étouffer l'inquiétude légitime d'une minorité",
    "q.m14#6.o2" to "Parce que voter n'est pas toujours juste",
    "q.m14#6.o3" to "Parce que la taille des cordées diffère",
    "q.m14#6.e" to "Les signaux de danger ne sont souvent remarqués que par une ou deux personnes — quelqu'un a vu une fissure dans la couche de neige — et cette observation est une information détenue par une minorité, mais mortelle si elle est vraie. Trancher par vote revient à ignorer systématiquement les signaux de faible probabilité et de forte conséquence.",

    "q.m14#7.p" to "Pourquoi « l'avis le plus prudent l'emporte-t-il » ?",
    "q.m14#7.o0" to "Parce que les gens prudents sont plus expérimentés",
    "q.m14#7.o1" to "Parce qu'en situation d'incertitude, le coût d'une erreur sur l'option prudente est bien inférieur à celui d'une erreur sur l'option risquée",
    "q.m14#7.o2" to "Parce que le règlement l'exige",
    "q.m14#7.o3" to "Pour que tout le monde soit satisfait",
    "q.m14#7.e" to "C'est le cas d'école du coût asymétrique : être prudent peut signifier une course perdue, être risqué peut signifier la mort. Quand les coûts sont asymétriques, la décision doit pencher du côté dont le coût est maîtrisable — et ce penchant doit être convenu avant le départ, sinon il est très difficile à exécuter sur le terrain.",

    "q.m14#8.p" to "[Association] Associez chaque biais de décision à son expression typique.",
    "q.m14#8.l0" to "Coût irrécupérable",
    "q.m14#8.r0" to "On est venus jusqu'ici — faire demi-tour maintenant serait du gâchis",
    "q.m14#8.l1" to "Pression du groupe",
    "q.m14#8.r1" to "Tout le monde veut continuer ; je me sentirais gêné de dire qu'il faut arrêter",
    "q.m14#8.l2" to "Fixation sur l'objectif",
    "q.m14#8.r2" to "Ce n'est plus qu'un dernier tronçon",
    "q.m14#8.l3" to "Normalisation du risque",
    "q.m14#8.r3" to "La dernière fois, ça s'est bien passé",
    "q.m14#8.e" to "Curieusement, ces quatre phrases reviennent constamment dans les rapports d'accident — et ceux qui les prononcent sont souvent des alpinistes expérimentés. C'est précisément le point : ce ne sont pas des problèmes de débutants, ce sont des problèmes de construction de la cognition humaine.",

    "q.m14#9.p" to "Pourquoi « plus expérimenté » ne signifie-t-il pas « juge plus justement » ?",
    "q.m14#9.o0" to "Parce que l'expérience ralentit",
    "q.m14#9.o1" to "Parce que l'expérience élève peu à peu la tolérance au risque",
    "q.m14#9.o2" to "Parce que l'expérience n'a pas d'importance",
    "q.m14#9.o3" to "Parce que les anciens sont plus têtus",
    "q.m14#9.e" to "L'expérience apporte la familiarité, et la familiarité émousse la vigilance. Les cordées expérimentées ont donc besoin de davantage de contraintes externes, pas moins — heures de demi-tour fixes, seuils météo chiffrés — en utilisant des règles pour contrer une intuition déjà émoussée.",

    "q.m14#10.p" to "[Ordre] Quel est le processus sain d'une décision de repli ?",
    "q.m14#10.o0" to "Vérifier les signaux objectifs convenus avant le départ (heure, météo, état de la cordée)",
    "q.m14#10.o1" to "Vérifier si les conditions réelles en ont déclenché un",
    "q.m14#10.o2" to "Faire prononcer le repli par la personne désignée à l'avance",
    "q.m14#10.o3" to "Exécuter le repli et prévenir les personnes restées à la maison",
    "q.m14#10.e" to "La valeur du processus est de vérifier d'abord le critère et ensuite la situation — pas l'inverse. Inversez l'ordre et le critère se fait grignoter par l'ambiance du moment jusqu'à devenir « voyons encore un peu ».",

    "q.m14#11.p" to "Pourquoi désigner à l'avance qui a l'autorité de prononcer le repli ?",
    "q.m14#11.o0" to "Pour faciliter la répartition des responsabilités",
    "q.m14#11.o1" to "Parce qu'il est très difficile pour quiconque d'agir spontanément contre l'ambiance du groupe",
    "q.m14#11.o2" to "Pour renforcer l'autorité du chef",
    "q.m14#11.o3" to "Pour documenter le processus",
    "q.m14#11.e" to "Se replier, c'est démentir l'attente de toute la cordée, ce qui est très difficile à initier dans une ambiance de groupe. Faites de « prononcer le repli » une mission confiée à l'avance plutôt qu'un acte de courage personnel — c'est seulement alors que cela arrive réellement.",

    "q.m14#12.p" to "Quand faut-il envisager de mettre fin à la course ?",
    "q.m14#12.o0" to "Jamais, tant que le sommet reste possible",
    "q.m14#12.o1" to "Dès qu'un signal objectif convenu à l'avance est déclenché",
    "q.m14#12.o2" to "Seulement quand un membre de la cordée est blessé",
    "q.m14#12.o3" to "Dès que la personne la moins en forme le décide",
    "q.m14#12.e" to "Déclenché signifie arrêter : c'est tout l'intérêt de critères chiffrés. Cela transforme la décision de « faut-il » en « est-ce déclenché ». La première demande débat et persuasion ; la seconde ne demande que de vérifier des faits — et c'est pourquoi elle peut réellement s'exécuter sur le terrain.",

    "q.m14#13.p" to "Quel est le contrepoids le plus efficace à la fixation sur l'objectif ?",
    "q.m14#13.o0" to "La volonté personnelle",
    "q.m14#13.o1" to "Chiffrer les critères avant le départ, pour que « les assouplir » devienne un acte explicite qu'il faut justifier devant ses compagnons",
    "q.m14#13.o2" to "Ne fixer aucun objectif",
    "q.m14#13.o3" to "Emporter plus de matériel",
    "q.m14#13.e" to "On n'évite pas un biais psychologique en se rappelant de ne pas y céder. La méthode qui marche est de faire du « on fait demi-tour à l'heure » la règle par défaut, de sorte que celui qui veut continuer doive activement donner des raisons — renverser la charge de la preuve en un geste.",

    "q.m14#14.p" to "Pourquoi « personne n'a objecté » n'équivaut-il pas à « tout le monde était d'accord » ?",
    "q.m14#14.o0" to "Parce qu'ils n'ont peut-être pas entendu",
    "q.m14#14.o1" to "Parce que le silence peut seulement signifier la réticence à gâcher l'ambiance, les doutes réels restant tus",
    "q.m14#14.o2" to "Parce que quelqu'un dormait",
    "q.m14#14.o3" to "Parce que les objections ont été ignorées",
    "q.m14#14.e" to "C'est pourquoi les bonnes cordées fabriquent délibérément la contradiction — le chef demande franchement « qui pense qu'on ne devrait pas continuer », ou fait le tour en demandant à chacun de se positionner. Le silence en montagne ne signifie pas l'accord ; il signifie seulement que rien n'a été dit.",

    "q.m14#15.p" to "Complétez : en situation d'incertitude, l'avis le plus ( ) doit être retenu en premier.",
    "q.m14#15.a0" to "prudent",
    "q.m14#15.e" to "« Prudent d'abord » est une règle directement exécutable sur le terrain : il n'y a pas à juger quel argument est le plus fort, seulement quelle option est la plus prudente. Le prix est une course peut-être perdue — un prix qui vaut la peine d'être payé.",

    "q.m14#16.p" to "Situation : la météo se dégrade un jour de sommet à 7 000 m",
    "q.m14#16.c" to "C'est le jour du sommet à 7 000 m et vous êtes partis à 3 h du matin. À 8 h, vous atteignez un point situé à environ deux heures du sommet. Le vent a nettement forci, des nuages arrivent de l'ouest et la température baisse. Un membre de la cordée s'est mis à tousser de façon persistante et ralentit visiblement.",
    "q.m14#16.e" to "Le cœur de cette situation n'est aucune réponse isolée mais la séquence : vérifier les faits, identifier les signaux de danger, résister à l'attraction psychologique, puis exécuter proprement le repli. Les deux étapes les plus susceptibles d'échouer sont la première (sautée) et la troisième (détournée par l'émotion).",
    "q.m14#16.s0.p" to "Étape 1 : quel est le premier jugement à porter maintenant ?",
    "q.m14#16.s0.o0" to "Confirmer l'état de la cordée et la tendance météo, et les confronter aux signaux de demi-tour convenus avant le départ",
    "q.m14#16.s0.o1" to "Accélérer et atteindre le sommet avant que le temps se dégrade",
    "q.m14#16.s0.o2" to "Attendre sur place une amélioration",
    "q.m14#16.s0.o3" to "Renvoyer seul le membre le plus lent",
    "q.m14#16.s0.e" to "Toute décision doit commencer par vérifier les faits : comment va la cordée, le temps s'améliore-t-il ou se dégrade-t-il, un signal prévu a-t-il été déclenché. Sautez cela et laissez l'émotion décider à votre place.",
    "q.m14#16.s1.p" to "Étape 2 : un membre de la cordée tousse de façon persistante. Quelle est la réponse la plus raisonnable ?",
    "q.m14#16.s1.o0" to "C'est juste l'air froid qui irrite les voies respiratoires — continuer",
    "q.m14#16.s1.o1" to "En altitude, cela impose une forte suspicion d'œdème pulmonaire : arrêter de monter et redescendre dès que possible",
    "q.m14#16.s1.o2" to "Donner un sirop contre la toux et continuer",
    "q.m14#16.s1.o3" to "Le laisser se reposer 10 minutes puis continuer",
    "q.m14#16.s1.e" to "À 7 000 m, une toux persistante au repos ou au moindre effort est un signal qui impose une forte suspicion. À cette altitude, le coût de « surveiller encore un peu » peut dépasser de loin le coût d'une descente immédiate.",
    "q.m14#16.s2.p" to "Étape 3 : vous êtes à deux heures du sommet et décidez de faire demi-tour. Quelle est la plus grande résistance psychologique ?",
    "q.m14#16.s2.o0" to "Une condition physique insuffisante",
    "q.m14#16.s2.o1" to "Le coût irrécupérable et la fixation sur l'objectif — « on est venus jusqu'ici »",
    "q.m14#16.s2.o2" to "Des problèmes de matériel",
    "q.m14#16.s2.o3" to "Une méconnaissance de l'itinéraire",
    "q.m14#16.s2.e" to "C'est exactement pourquoi les heures de demi-tour existent : elles déplacent la décision à un moment où vous êtes encore rationnel. Quand « c'est juste un peu plus loin » apparaît, ce qu'il vous faut n'est pas un jugement neuf mais une confrontation à la règle convenue à l'avance.",
    "q.m14#16.s3.p" to "Étape 4 : comment organiser la cordée pendant la descente ?",
    "q.m14#16.s3.o0" to "Les plus en forme partent devant préparer le camp",
    "q.m14#16.s3.o1" to "Rester groupés, laisser la personne la plus forte ouvrir et donner l'allure, et informer les personnes restées à la maison de l'état de la cordée",
    "q.m14#16.s3.o2" to "Se séparer pour descendre plus vite",
    "q.m14#16.s3.o3" to "Laisser le membre le plus faible marcher lentement seul",
    "q.m14#16.s3.e" to "En altitude, dès qu'une cordée s'étire elle perd sa couverture mutuelle — et la descente est précisément la phase où les accidents sont les plus nombreux. Rester groupés, faire contrôler l'allure par quelqu'un et tenir l'extérieur informé : les trois sont indispensables.",
    // ---------- m15 Lecture des nuages et bulletins ----------
    "q.m15#0.p" to "Quelle est la valeur centrale de la lecture des nuages ?",
    "q.m15#0.o0" to "Cela rend l'alpinisme plus professionnel",
    "q.m15#0.o1" to "Cela vous donne de l'avance sur le changement de temps",
    "q.m15#0.o2" to "Cela remplace la prévision météo",
    "q.m15#0.o3" to "Cela mesure l'altitude",
    "q.m15#0.e" to "Une prévision peut vous dire la veille, mais la météo de montagne change vite à petite échelle. Les nuages sont la prévision juste au-dessus de votre tête — l'avance peut n'être que d'une ou deux heures, et cette heure ou deux est exactement la fenêtre où vous décidez de faire demi-tour.",

    "q.m15#1.p" to "Qu'indique un développement vertical des cumulus ?",
    "q.m15#1.o0" to "Un temps stable",
    "q.m15#1.o1" to "Une forte convection, pouvant évoluer en cumulonimbus",
    "q.m15#1.o2" to "Un refroidissement imminent",
    "q.m15#1.o3" to "Un vent de surface qui faiblit",
    "q.m15#1.e" to "Le cumulus en soi n'est pas dangereux, mais c'est un signal qui grandit. L'important n'est pas de noter qu'il s'agit d'un cumulus, mais de le voir grandir, s'élever et s'assombrir — ce processus est l'atmosphère qui accumule de l'énergie.",

    "q.m15#2.p" to "Que signifie un sommet en enclume sur un cumulonimbus ?",
    "q.m15#2.o0" to "Il est encore en formation",
    "q.m15#2.o1" to "Il a atteint sa maturité ; foudre, grêle et fortes précipitations sont possibles",
    "q.m15#2.o2" to "Il est sur le point de se dissiper",
    "q.m15#2.o3" to "Cela signifie seulement un vent fort en altitude",
    "q.m15#2.e" to "L'enclume est le sommet du nuage aplati par le vent d'altitude, ce qui signifie que le courant ascendant a atteint la tropopause et ne peut plus monter — la signature d'un orage à maturité. Quand vous voyez une enclume, votre temps de réaction est déjà court.",

    "q.m15#3.p" to "À quel moment de la journée la formation des cumulus se produit-elle surtout ?",
    "q.m15#3.o0" to "Tôt le matin",
    "q.m15#3.o1" to "En milieu de matinée",
    "q.m15#3.o2" to "L'après-midi",
    "q.m15#3.o3" to "Tard dans la nuit",
    "q.m15#3.e" to "La cause est le réchauffement solaire : le sol se réchauffe au fil de la journée et génère des courants ascendants et de la convection. C'est le mécanisme physique derrière « partir tôt, redescendre à temps » — pas seulement un dicton.",

    "q.m15#4.p" to "Qu'indiquent généralement les nuages lenticulaires (en forme de champignon ou de disque) ?",
    "q.m15#4.o0" to "Un temps calme",
    "q.m15#4.o1" to "Un vent fort",
    "q.m15#4.o2" to "Une pluie imminente",
    "q.m15#4.o3" to "Une température qui monte",
    "q.m15#4.e" to "Les lenticulaires sont des nuages d'onde stationnaire formés quand l'air franchit une crête — leur simple existence montre des vitesses de vent élevées en altitude. En montagne, cela signifie que les crêtes exposées peuvent recevoir de très fortes rafales, et les rafales sont la cause directe des pertes d'équilibre.",

    "q.m15#5.p" to "Des cirrus (nuages élevés en filaments) nettement plus nombreux indiquent généralement :",
    "q.m15#5.o0" to "L'approche d'un système météo",
    "q.m15#5.o1" to "La fin de la vague de froid",
    "q.m15#5.o2" to "Un vent sur le point de tomber",
    "q.m15#5.o3" to "Des UV qui vont faiblir",
    "q.m15#5.e" to "Les cirrus sont souvent l'avant-garde d'un système météo — le temps n'a pas encore changé quand ils apparaissent, mais le changement est en route. C'est une avance précieuse, surtout pour un itinéraire qui doit rentrer tôt.",

    "q.m15#6.p" to "Un stratus qui descend, avec une base qui baisse nettement, a quel effet le plus direct ?",
    "q.m15#6.o0" to "La température monte",
    "q.m15#6.o1" to "La visibilité se dégrade vite et le jugement du terrain devient difficile",
    "q.m15#6.o2" to "Le vent faiblit",
    "q.m15#6.o3" to "Les précipitations s'arrêtent",
    "q.m15#6.e" to "Un stratus qui descend n'apporte pas de pluie mais la perte de la vue — et perdre la vue est un risque en soi : vous êtes peut-être déjà hors itinéraire, peut-être près d'une corniche, ou vous risquez de manquer l'échappatoire du repli.",

    "q.m15#7.p" to "[Choix multiple] Quels changements de nuages signalent une dégradation du temps ?",
    "q.m15#7.o0" to "Une couverture nuageuse qui augmente rapidement et une couche qui s'épaissit",
    "q.m15#7.o1" to "Une base qui continue de descendre",
    "q.m15#7.o2" to "Des nuages qui s'assombrissent avec un développement vertical évident",
    "q.m15#7.o3" to "L'apparition d'un sommet en enclume",
    "q.m15#7.o4" to "Une couverture qui commence à diminuer et un ciel qui se dégage",
    "q.m15#7.e" to "Ces quatre points sont les étapes d'un même processus : la couverture augmente, la base descend, le corps s'assombrit et s'élève, une enclume apparaît. Les reconnaître dans l'ordre transforme « le temps a tourné » d'un instant en un processus dont on peut être averti à l'avance.",

    "q.m15#8.p" to "Pourquoi les nuages se développent-ils plus violemment en montagne qu'en plaine ?",
    "q.m15#8.o0" to "Parce que c'est plus haut et plus froid",
    "q.m15#8.o1" to "Parce que le relief force l'air vers le haut, ce qui intensifie la convection",
    "q.m15#8.o2" to "Parce que les UV sont plus forts",
    "q.m15#8.o3" to "Parce que l'air est raréfié",
    "q.m15#8.e" to "Le vent qui heurte une montagne est forcé de monter comme s'il était poussé sur une rampe — la levée produit directement refroidissement et condensation, si bien que les nuages se forment plus vite et plus localement qu'au-dessus d'une plaine. C'est pourquoi la météo de montagne peut changer complètement en très peu de temps.",

    "q.m15#9.p" to "Comment distinguer un nuage qui se développe d'un nuage qui se dissipe ?",
    "q.m15#9.o0" to "Par sa couleur",
    "q.m15#9.o1" to "En observant en continu si son volume, sa hauteur et le contour de ses bords augmentent et se durcissent",
    "q.m15#9.o2" to "Par la température",
    "q.m15#9.o3" to "Par l'épaisseur de neige",
    "q.m15#9.e" to "L'essentiel est l'observation continue — un regard donne un état, deux regards donnent une tendance. Un nuage qui se développe grossit en volume, son sommet monte et ses bords se durcissent ; un nuage qui se dissipe fait l'inverse. Lever les yeux à intervalles fixes ne coûte presque rien et vaut beaucoup.",

    "q.m15#10.p" to "[Association] Associez chaque type de nuage à sa signification météo.",
    "q.m15#10.l0" to "Cumulonimbus (sommet en enclume)",
    "q.m15#10.r0" to "Orage, grêle et fortes précipitations",
    "q.m15#10.l1" to "Nuage lenticulaire",
    "q.m15#10.r1" to "Vent fort en altitude, rafales violentes sur les crêtes",
    "q.m15#10.l2" to "Cirrus",
    "q.m15#10.r2" to "Un système météo approche",
    "q.m15#10.l3" to "Stratus bas",
    "q.m15#10.r3" to "Visibilité en chute, jugement du terrain difficile",
    "q.m15#10.e" to "Ces quatre types couvrent les quatre sortes d'informations météo que l'on rencontre le plus souvent en montagne. Une réserve : lire les nuages demande un entraînement visuel, et cette application ne propose pour l'instant que des questions texte — l'identification de nuages sur image sera ajoutée une fois la chaîne d'images en place.",

    "q.m15#11.p" to "Pourquoi la lecture des nuages doit-elle être combinée à la tendance de pression ?",
    "q.m15#11.o0" to "Pour la complétude des données",
    "q.m15#11.o1" to "Parce que les nuages montrent l'état présent, tandis que la tendance de pression montre la direction du changement",
    "q.m15#11.o2" to "Parce qu'un baromètre est plus précis",
    "q.m15#11.o3" to "Pour calculer l'altitude",
    "q.m15#11.e" to "Ce sont deux dimensions différentes : les nuages disent ce qu'il y a maintenant, la pression dit vers quoi cela va. Les nuages seuls font facilement lire « ça se dégrade » comme « c'est juste couvert pour l'instant » — ajoutez la tendance et le tableau est complet.",

    "q.m15#12.p" to "Qu'est-ce qui provoque principalement les conditions de voile blanc ?",
    "q.m15#12.o0" to "Des chutes de neige excessives",
    "q.m15#12.o1" to "Des nuages, du brouillard et une surface neigeuse de couleur voisine, si bien que la limite entre le sol et le ciel disparaît",
    "q.m15#12.o2" to "Une température extrêmement basse",
    "q.m15#12.o3" to "Des UV excessifs",
    "q.m15#12.e" to "Un voile blanc n'est pas une forte neige, c'est une absence de contraste. Quand la neige et le nuage ont une luminosité proche, l'horizon disparaît et la perception des distances et de la pente s'effondre — ce qui explique pourquoi c'est bien plus dangereux qu'une chute de neige ordinaire.",

    "q.m15#13.p" to "Pourquoi une prévision du type « averses isolées » est-elle peu utile en montagne ?",
    "q.m15#13.o0" to "Parce que les prévisions sont inexactes",
    "q.m15#13.o1" to "Parce que l'échelle de variation de la météo en montagne est bien plus petite que la maille de prévision, si bien que les conditions sur place peuvent être totalement différentes",
    "q.m15#13.o2" to "Parce que les alpinistes ne lisent pas les prévisions",
    "q.m15#13.o3" to "Parce que les précipitations n'ont pas d'importance",
    "q.m15#13.e" to "La maille de prévision peut faire des dizaines de kilomètres, alors que les deux versants d'une même crête peuvent avoir une météo totalement différente. Une prévision donne le risque de fond ; le jugement sur place décide si vous pouvez bouger aujourd'hui. Ni l'un ni l'autre ne remplace l'autre.",

    "q.m15#14.p" to "La prévision annonce « ensoleillé » mais vous voyez des cumulus se développer verticalement très vite. À quoi vous fier ?",
    "q.m15#14.o0" to "À la prévision — continuer comme prévu",
    "q.m15#14.o1" to "À votre propre observation — décider en supposant que cela peut se dégrader",
    "q.m15#14.o2" to "Faire la moyenne des deux",
    "q.m15#14.o3" to "Continuer à observer une heure de plus",
    "q.m15#14.e" to "Une prévision est grossière en avance comme en échelle, alors que l'observation est ici et maintenant. Quand elles se contredisent, la preuve de terrain l'emporte — c'est la posture de base de tout le système de jugement météo : la prévision fixe le contexte, le terrain fixe l'action.",

    "q.m15#15.p" to "Complétez : après avoir vu un éclair, chaque seconde comptée correspond à environ ( ) kilomètre.",
    "q.m15#15.a0" to "0,34",
    "q.m15#15.a1" to "0,34",
    "q.m15#15.a2" to "zéro virgule trois quatre",
    "q.m15#15.e" to "0,34 km par seconde est la vitesse du son dans l'air. Cette conversion transforme le comptage des secondes en outil utilisable — sans aucun matériel, vous pouvez dire si l'orage approche ou s'éloigne.",

    "q.m15#16.p" to "[Choix multiple] Dans quelles situations faut-il sérieusement envisager de redescendre immédiatement ?",
    "q.m15#16.o0" to "Des cumulus ont évolué en cumulonimbus avec sommet en enclume",
    "q.m15#16.o1" to "Un bruit d'affaissement « whumpf » dans le manteau neigeux",
    "q.m15#16.o2" to "Une visibilité qui chute vite et une position que vous ne pouvez plus fixer",
    "q.m15#16.o3" to "Un membre de la cordée dont les symptômes d'altitude s'aggravent progressivement",
    "q.m15#16.o4" to "Un membre de la cordée qui dit être un peu fatigué et veut dix minutes de repos",
    "q.m15#16.e" to "Ces quatre cas viennent de quatre dimensions — météo, manteau neigeux, orientation et physiologie — et leur point commun est d'être progressifs, ce qui signifie que le coût maintenant est bien inférieur au coût dans dix minutes. Plus tôt vous décidez de descendre, moins cela coûte cher.",

    "q.m15#17.p" to "Touchez sur le graphique la courbe qui représente l'isotherme 0 °C.",
    "q.m15#17.e" to "La courbe de l'isotherme 0 °C est l'une des informations les plus utiles de cette prévision : elle marque l'altitude où les précipitations passent de la pluie à la neige. Une courbe qui monte signifie l'arrivée d'air plus doux et plus humide et une bascule des précipitations vers la pluie ; une courbe qui descend signifie de l'air froid et un passage à la neige en altitude. Pour savoir si vous rencontrerez de la neige à votre altitude, elle bat la lecture des températures.",

    "q.m15#18.p" to "Voici la prévision de la même montagne pour une saison d'alpinisme terminée prématurément. Quel est le cumul de neige, en centimètres, sur les trois périodes du vendredi 25 (matin / après-midi / nuit) ? Saisissez la somme.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm. Près de 2,8 m de neige en une seule journée signifie que l'itinéraire est entièrement enseveli, que le danger d'avalanche grimpe brutalement et que les camps risquent d'être écrasés. À cette échelle, la question n'est plus de savoir si l'on peut atteindre le sommet mais si l'on peut évacuer en sécurité — c'est la façon typique dont un cyclone met fin à une saison.",

    "q.m15#19.p" to "Situation : lire une prévision météo de haute altitude",
    "q.m15#19.c" to "Un guide pose devant vous deux prévisions du Manaslu — l'une d'une fenêtre d'ascension normale, l'autre des relevés d'une saison terminée prématurément. Les comprendre compte plus que mémoriser un chiffre.",
    "q.m15#19.e" to "Le jugement météo ne débouche jamais vraiment sur « quel temps fera-t-il demain » mais sur « pouvons-nous bouger dans cette fenêtre ». La même interface, l'une disant de continuer et l'autre d'arrêter — la différence n'est pas dans la lecture du graphique mais dans la connaissance des conditions auxquelles il faut s'arrêter.",
    "q.m15#19.s0.p" to "Étape 1 : dans la prévision de fenêtre normale, que représentent les blocs roses de la ligne d'altitude sommitale (8 163 m) ?",
    "q.m15#19.s0.o0" to "La neige attendue pour cette période",
    "q.m15#19.s0.o1" to "La pluie pour cette période",
    "q.m15#19.s0.o2" to "La température ressentie pour cette période",
    "q.m15#19.s0.o3" to "La vitesse du vent pour cette période",
    "q.m15#19.s0.e" to "Le rose est la neige et le bleu la pluie — la prévision marque le type de précipitation séparément à chaque altitude précisément parce que sa question centrale est : neigera-t-il ou pleuvra-t-il à votre altitude. Les blocs de la ligne du haut sont petits et épars : le sommet reçoit donc des neiges faibles occasionnelles, sans grande ampleur.",
    "q.m15#19.s1.p" to "Étape 2 : comparée à la prévision de fin de saison, quel est le changement le plus frappant ?",
    "q.m15#19.s1.o0" to "Seule la température baisse",
    "q.m15#19.s1.o1" to "La neige et la vitesse du vent augmentent fortement toutes deux, et les précipitations couvrent toutes les tranches d'altitude",
    "q.m15#19.s1.o2" to "La pluie remplace la neige",
    "q.m15#19.s1.o3" to "L'isotherme 0 °C monte beaucoup",
    "q.m15#19.s1.e" to "La neige passe de 1 à 4 cm épars à 280 cm en une journée, le vent de 25–30 km/h à 55–60 km/h, et la bande de précipitations traverse tous les niveaux de 8 163 m à 1 500 m. Les trois à la fois, c'est la signature d'un système météo qui passe droit sur vous.",
    "q.m15#19.s2.p" to "Étape 3 : si votre cordée se trouvait dans une telle fenêtre de prévision, quelle est la bonne décision ?",
    "q.m15#19.s2.o0" to "Accélérer la course au sommet avant que le temps ne se dégrade complètement",
    "q.m15#19.s2.o1" to "Arrêter immédiatement la tentative de sommet, redescendre selon le plan et se préparer à évacuer",
    "q.m15#19.s2.o2" to "Attendre au camp haut une amélioration",
    "q.m15#19.s2.o3" to "Se séparer en deux groupes, l'un tentant le sommet et l'autre restant",
    "q.m15#19.s2.e" to "Quand une prévision montre un système qui passe droit sur vous plutôt qu'une brève fluctuation, « attendre que ça passe » signifie généralement plusieurs jours de plus exposé en altitude, ce que ni les vivres ni les tentes ne peuvent soutenir. C'est pourquoi tant de saisons ne se terminent pas par « on a fini » mais par « il fallait sortir » — et l'information nécessaire à cette décision est exactement ce que fournissent ces deux graphiques.",

    "q.m15#20.p" to "Situation : lire une prévision horaire",
    "q.m15#20.c" to "Voici une prévision horaire d'une journée au Gongga Shan (7 556 m). Sa densité d'information est bien supérieure à un aperçu à 16 jours, mais il est aussi plus facile de lire la mauvaise ligne — l'essentiel est de savoir ce que dit réellement chaque ligne.",
    "q.m15#20.e" to "Une prévision horaire répond à ce qu'un aperçu ne peut pas : quelle période précise est praticable. L'isotherme 0 °C fixe le type de précipitation, la température ressentie fixe ce qu'une personne peut endurer, et la vitesse du vent et l'ensoleillement fixent la largeur de la fenêtre. Lues ensemble, elles donnent une décision exécutable.",
    "q.m15#20.s0.p" to "Étape 1 : la ligne Freeze donne un isotherme 0 °C entre 4 895 et 5 304 m, alors que le sommet du Gongga est à 7 556 m. Que signifie cette combinaison ?",
    "q.m15#20.s0.o0" to "Toutes les précipitations sur la montagne tombent en neige",
    "q.m15#20.s0.o1" to "Il pleuvra au sommet",
    "q.m15#20.s0.o2" to "Il neigera aussi sous l'isotherme 0 °C",
    "q.m15#20.s0.o3" to "Le type de précipitation ne peut pas être déduit de cela",
    "q.m15#20.s0.e" to "L'isotherme 0 °C est la limite pluie/neige. Elle se tient autour de 4 900–5 300 m alors que tous les itinéraires sont au-dessus. Autrement dit, tout l'itinéraire est au-dessus de l'isotherme : toute précipitation arrive donc en neige. Un seul chiffre répond à « sous quelle forme rencontrerai-je les précipitations » — c'est pourquoi l'isotherme 0 °C est plus utile qu'une température.",
    "q.m15#20.s1.p" to "Étape 2 : la ligne Feels °C indique −18 à −21, alors que Max / Min °C ne donne que −10 à −11. Qu'est-ce qui explique principalement cet écart ?",
    "q.m15#20.s1.o0" to "Une erreur de prévision",
    "q.m15#20.s1.o1" to "Le refroidissement éolien — plus le vent est fort, plus la température ressentie baisse",
    "q.m15#20.s1.o2" to "Un écart de température causé par l'altitude",
    "q.m15#20.s1.o3" to "L'effet d'un changement d'humidité",
    "q.m15#20.s1.e" to "La vitesse du vent sur la même période est de 20–30 km/h. Le vent sur une peau nue accélère la perte de chaleur, si bien que la température ressentie se situe près de 10 °C sous la température de l'air mesurée. En altitude, c'est la température ressentie qui décide si l'on peut rester dehors, pas la température de l'air. Le même −10 °C est une toute autre affaire avec ou sans vent.",
    "q.m15#20.s2.p" to "Étape 3 : avec cette prévision (vent 20–30 km/h, neige éparse 2/1/1 cm, ressenti autour de −20 °C, jour 6:56–19:15), quel est votre jugement sur la fenêtre ?",
    "q.m15#20.s2.o0" to "Les conditions sont sévères — renoncer à tout déplacement",
    "q.m15#20.s2.o1" to "C'est une fenêtre relativement praticable ; le vrai défi est le froid et le refroidissement éolien, pas les précipitations",
    "q.m15#20.s2.o2" to "Trop de précipitations — il y a un risque d'avalanche",
    "q.m15#20.s2.o3" to "Pas assez de données pour juger",
    "q.m15#20.s2.e" to "Un vent de 20–30 km/h reste dans la plage praticable, et la neige n'est que de quelques centimètres. La vraie pression vient d'un ressenti autour de −20 °C : ce sont donc les gelures et l'hypothermie qu'il faut prévenir. La logique de ce type de fenêtre : précipitations et vent vont bien, la température et la durée posent problème. Donc raccourcissez l'exposition, renforcez l'isolation des extrémités et avancez l'heure de demi-tour.",

    "q.m15#21.p" to "Dans la même prévision du Gongga, la température de l'air mesurée est d'environ −11 °C alors que le ressenti minimal est de −21 °C. Quel est l'écart en degrés Celsius ?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C : −11 − (−21) = 10. Cet écart est en soi une information de décision — habillez-vous pour la température ressentie, pas pour la température de l'air. Cela explique aussi comment on prend des gelures à −10 °C : on s'est habillé pour le chiffre du graphique.",

    "q.m15#22.p" to "Cette prévision affiche la vitesse du vent sous forme de cercles verts. Que signifie le plus probablement cette couleur ?",
    "q.m15#22.o0" to "La vitesse du vent sur cette période est dans la plage propice à la progression",
    "q.m15#22.o1" to "La vitesse du vent sur cette période a atteint un niveau dangereux",
    "q.m15#22.o2" to "Il pleut sur cette période",
    "q.m15#22.o3" to "Les données de vent manquent pour cette période",
    "q.m15#22.e" to "Les services météo de montagne professionnels codent généralement la vitesse du vent selon son effet sur la progression. 20–30 km/h affiché en vert signifie que l'on est dans la plage « on peut bouger » ; au-delà, la couleur passe au jaune ou au rouge.\nMais la couleur est une suggestion du fournisseur, pas votre critère. Des itinéraires différents et des cordées différentes tolèrent différemment le même vent. Lire le chiffre compte plus que lire la couleur.",

    "q.m15#23.p" to "Cette interface professionnelle affiche les températures à 8000 / 6000 / 4000 / 2000 m sur quatre lignes parallèles. Quel est le principal intérêt de cette conception ?",
    "q.m15#23.o0" to "On peut lire directement la prévision pour sa propre altitude, sans extrapoler depuis les données de plaine",
    "q.m15#23.o1" to "Cela rend la page plus riche",
    "q.m15#23.o2" to "Cela montre que les quatre lignes sont sans rapport",
    "q.m15#23.o3" to "Seulement pour faciliter l'impression papier",
    "q.m15#23.e" to "Une prévision ordinaire donne les données d'un seul lieu, généralement la ville ou l'aéroport le plus proche. Il faut ensuite extrapoler vers la montagne avec un gradient thermique — une étape facile à rater et qui jette le détail du relief.\nUn service de montagne professionnel fait l'inverse : il découpe d'abord la montagne par altitude, puis prévoit chaque tranche. Il ne reste qu'à trouver la ligne de l'altitude où vous serez demain et à la lire. C'est aussi un test simple pour savoir si un service météo est adapté : découpe-t-il par altitude ?",

    "q.m15#24.p" to "Dans le tableau, la ligne « Cloud base (m) » affiche un tiret (—) pour la plupart des périodes. Quelle est la lecture correcte ?",
    "q.m15#24.o0" to "La base des nuages est nulle sur cette période, autrement dit le nuage touche le sol",
    "q.m15#24.o1" to "Aucune donnée de base nuageuse n'est fournie pour cette période ; il ne faut pas la lire comme « base = 0 »",
    "q.m15#24.o2" to "Cela signifie qu'il n'y a aucun nuage sur cette période",
    "q.m15#24.o3" to "Cela signifie que la base des nuages est au-dessus du sommet",
    "q.m15#24.e" to "Dans un tableau météo, « vide » et « zéro » sont deux choses totalement différentes. Un vide signifie qu'il n'y a pas de donnée pour cet item sur cette période — il peut ne pas être couvert, ou aucune estimation significative ne peut être donnée. Cela ne signifie pas que la valeur est nulle.\nTraiter un vide comme un zéro mène à des conclusions du type « nuage au sol, visibilité épouvantable » qui n'ont rien à voir avec les faits. Avec n'importe quel tableau météo, séparez d'abord les deux. C'est l'erreur la plus facile en lecture de prévision, et la moins souvent signalée.",

    "q.m15#25.p" to "Dans la ligne du vent de cette interface, les chiffres sont accompagnés de flèches. Qu'indiquent le plus probablement ces flèches ?",
    "q.m15#25.o0" to "La tendance de la vitesse du vent",
    "q.m15#25.o1" to "La direction du vent",
    "q.m15#25.o2" to "La probabilité de précipitation",
    "q.m15#25.o3" to "Une température qui monte ou descend",
    "q.m15#25.e" to "Vitesse et direction doivent se lire ensemble en altitude. Le même 30 km/h est complètement différent au vent et sous le vent, et n'affecte pas le manteau neigeux de la même façon : le vent transporte la neige sur les pentes sous le vent et l'accumule en plaques. C'est l'une des informations les plus importantes pour juger le danger d'avalanche.\nLire seulement le chiffre et pas la direction, c'est jeter la moitié de l'information. Les interfaces professionnelles placent la flèche à côté du chiffre précisément parce que les deux ne se lisent pas séparément.",

    "q.m15#26.p" to "Sur ce graphique à 16 jours, les marqueurs rouges (Snow) se concentrent autour de la tranche 6 000 m tandis que les bleus (Rain) apparaissent sous 5 000 m. Qu'est-ce que cela indique ?",
    "q.m15#26.o0" to "La limite pluie/neige se situe à peu près entre 5 500 et 6 000 m",
    "q.m15#26.o1" to "Il ne tombe que de la neige sur la montagne, jamais de pluie",
    "q.m15#26.o2" to "La pluie continue jusqu'au sommet",
    "q.m15#26.o3" to "Cela ne peut pas être jugé à partir de ce graphique",
    "q.m15#26.e" to "Ce graphique ne dit pas ce qui tombe à une heure donnée ; il répond directement dans quelle tranche d'altitude les précipitations arrivent. Pour un alpiniste, c'est exactement l'information qui compte.\nDu rouge dans la tranche 6 000 m et du bleu seulement sous 5 000 m placent la limite pluie/neige à peu près entre 5 500 et 6 000 m. Combiné à la courbe violette de l'isotherme 0 °C de la légende (qui descend d'environ 6 000 m à environ 4 800 m), on voit aussi que la limite continuera de descendre pendant la période : les tranches qui reçoivent de la pluie passeront peu à peu à la neige.\nLa même quantité de précipitations n'a pas du tout le même effet sur une course selon qu'elle tombe en pluie ou en neige.",

    "q.m15#27.p" to "Dans la prévision horaire du même graphique, une icône d'éclair apparaît à 17 h. Que signifie ce signal en altitude ?",
    "q.m15#27.o0" to "Ce n'est qu'une icône — aucun traitement particulier",
    "q.m15#27.o1" to "Risque d'orage : programmer les déplacements le matin et quitter crêtes et terrains exposés l'après-midi",
    "q.m15#27.o2" to "De fortes pluies arrivent — il suffit de prendre un imperméable",
    "q.m15#27.o3" to "La vitesse du vent va augmenter jusqu'à un niveau dangereux",
    "q.m15#27.e" to "Les orages d'après-midi sont courants en altitude et réellement dangereux. La levée due au relief fait grandir les cumulus rapidement l'après-midi. Donc « partir tôt » ne concerne pas seulement la neige plus dure — c'est aussi quitter les terrains exposés avant que les orages ne se forment.\nPoints clés pendant un orage : rester à l'écart des sommets, des crêtes, des arbres isolés et de l'eau ; ne pas s'allonger à plat sur le sol ; espacer la cordée d'environ 50 m pour qu'un seul impact ne blesse pas plusieurs personnes. La distance de la foudre s'estime en kilomètres par le nombre de secondes entre l'éclair et le tonnerre × 0,34.",

    "q.m15#28.p" to "Sur la question de savoir si une source de données de terrain comporte un marqueur de sommet, quel est le bon compromis ?",
    "q.m15#28.o0" to "Un marqueur signifie toujours une meilleure précision ; ne se fier qu'aux cartes qui en ont",
    "q.m15#28.o1" to "Les marqueurs sont pratiques pour se repérer et communiquer vite, mais un jugement précis du terrain exige encore les courbes de niveau",
    "q.m15#28.o2" to "Une carte sans marqueur est inutilisable",
    "q.m15#28.o3" to "Les marqueurs gênent seulement la lecture ; il faut les ignorer",
    "q.m15#28.e" to "Sur cette carte Google du Muztagh Ata, le sommet est marqué directement par une punaise rouge. C'est très utile pour s'orienter et communiquer : on sait immédiatement où est l'objectif et on peut dire à un compagnon exactement de quel point on parle.\nMais un marqueur ne répond pas à la question de la raideur de cette pente ni de l'endroit où un camp peut s'installer. Le jugement précis du terrain dépend encore des courbes de niveau, et le marqueur n'y joue aucun rôle.\nL'approche pratique : utiliser le marqueur pour se repérer vite, puis des courbes de niveau à haute résolution (la version SRTM, par exemple) pour lire l'angle de la pente et le détail du terrain. Chacun fait son travail.",
    // ---------- m16 Jugement avancé du risque d'avalanche ----------
    "q.m16#0.p" to "Quelles trois échelles le jugement avancé du risque d'avalanche doit-il combiner ?",
    "q.m16#0.o0" to "Température, vitesse du vent, précipitations",
    "q.m16#0.o1" to "Prévision régionale, terrain, manteau neigeux",
    "q.m16#0.o2" to "Altitude, angle de pente, ensoleillement",
    "q.m16#0.o3" to "Taille de la cordée, matériel, temps",
    "q.m16#0.e" to "Les trois répondent à trois questions différentes : la prévision dit à quel point la journée est risquée dans l'ensemble, le terrain dit si cette pente peut porter de la neige et glisser, le manteau dit s'il est stable en ce moment. Avec la prévision seule, vous jugez la pente sous vos pieds par une moyenne régionale.",

    "q.m16#1.p" to "À quel degré de danger d'avalanche la plupart des accidents surviennent-ils ?",
    "q.m16#1.o0" to "1 (faible)",
    "q.m16#1.o1" to "3 (marqué)",
    "q.m16#1.o2" to "5 (extrême)",
    "q.m16#1.o3" to "Aucune différence",
    "q.m16#1.e" to "Au degré 5, les gens restent à l'écart, donc les accidents sont en fait moins nombreux ; au degré 3, le terrain « paraît praticable », donc beaucoup de monde entre en terrain avalancheux. La condition la plus dangereuse n'est jamais l'extrême, mais la modérée que l'on sous-estime.",

    "q.m16#2.p" to "Dans quelle plage de pente la plupart des avalanches se produisent-elles ?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "Il n'y a pas de régularité",
    "q.m16#2.e" to "Environ 96 % des avalanches se produisent entre 30° et 50°, la plupart se concentrant entre 34° et 45°. C'est exactement la plage que les itinéraires d'alpinisme traversent le plus souvent — assez raide pour glisser, assez douce pour retenir la neige.",

    "q.m16#3.p" to "[Choix multiple] Quelles pratiques sont correctes pour traverser un terrain avalancheux ?",
    "q.m16#3.o0" to "Garder l'espacement et passer une personne à la fois",
    "q.m16#3.o1" to "Poster un guetteur en position sûre",
    "q.m16#3.o2" to "Prévoir l'itinéraire de dégagement à l'avance",
    "q.m16#3.o3" to "Faire traverser toute la cordée rapidement et ensemble pour réduire l'exposition",
    "q.m16#3.e" to "Les deux premiers limitent le risque à une personne ; le troisième garantit une issue si quelque chose arrive. « Tous ensemble » fait l'inverse — cela transforme le risque d'ensevelir peut-être une personne en risque d'ensevelir toute la cordée, d'où son statut de pire choix.",

    "q.m16#4.p" to "Où le guetteur doit-il se placer ?",
    "q.m16#4.o0" to "Sur la pente traversée",
    "q.m16#4.o1" to "Là où il voit clairement la personne qui traverse et où il est lui-même en sécurité",
    "q.m16#4.o2" to "Tout en haut de la pente",
    "q.m16#4.o3" to "Au fond du vallon",
    "q.m16#4.e" to "Un guetteur a deux missions : garder la personne en vue (pour savoir où elle est ensevelie) et agir immédiatement en cas de problème. Se placer sur la pente ou au fond du vallon fait de lui la seconde victime — sa propre sécurité est une condition pour faire le travail.",

    "q.m16#5.p" to "À quoi sert de creuser une fosse à neige ?",
    "q.m16#5.o0" to "À se reposer",
    "q.m16#5.o1" to "À regarder directement la structure des couches, la position de la couche faible et les différences de dureté",
    "q.m16#5.o2" to "À mesurer la température",
    "q.m16#5.o3" to "À prendre des photos",
    "q.m16#5.e" to "Une avalanche exige une couche faible plus une plaque au-dessus, et cette structure ne devient visible que lorsqu'on entaille le manteau. Une fosse transforme une structure interne invisible en preuve visible — le pas décisif entre déduire le risque et l'observer.",

    "q.m16#6.p" to "Pourquoi « suivre les traces de ceux qui sont passés » est-il dangereux ?",
    "q.m16#6.o0" to "Parce que les traces sont peu lisibles",
    "q.m16#6.o1" to "Parce que les traces peuvent dater de plusieurs heures, et que le manteau a depuis longtemps changé",
    "q.m16#6.o2" to "Parce qu'on risque de prendre le mauvais itinéraire",
    "q.m16#6.o3" to "Parce que les traces gênent la marche",
    "q.m16#6.e" to "Les conditions du manteau ne cessent de changer avec la température, le vent et les chutes de neige — quelques heures suffisent pour passer de « à peine stable » à « prêt à déclencher ». Les traces prouvent seulement que quelqu'un est passé à ce moment-là ; elles ne disent rien de la sécurité maintenant.",

    "q.m16#7.p" to "Comment l'accumulation par le vent influence-t-elle le danger d'avalanche ?",
    "q.m16#7.o0" to "Le vent aplatit la neige et réduit le risque",
    "q.m16#7.o1" to "Le vent transporte la neige sur les pentes sous le vent, construisant des plaques supplémentaires et des couches faibles qui augmentent fortement le risque",
    "q.m16#7.o2" to "Le vent n'a aucun rapport avec les avalanches",
    "q.m16#7.o3" to "Le vent n'affecte que la visibilité",
    "q.m16#7.e" to "Le vent est le facteur d'avalanche le plus sous-estimé : en peu de temps, il peut déplacer beaucoup de neige sur les pentes sous le vent, construire des plaques épaisses et créer des couches faibles à l'intérieur. Donc même sans aucune chute de neige, un danger nouveau peut apparaître après un coup de vent.",

    "q.m16#8.p" to "Quel est le principal danger d'une corniche ?",
    "q.m16#8.o0" to "Elle bouche la vue",
    "q.m16#8.o1" to "Elle peut s'effondrer d'elle-même à tout moment, et son effondrement peut déclencher une avalanche sur la pente en dessous",
    "q.m16#8.o2" to "Sa couleur diffère de la surface neigeuse",
    "q.m16#8.o3" to "Elle bloque l'itinéraire",
    "q.m16#8.e" to "Une corniche est doublement dangereuse : montez dessus et vous pouvez partir avec elle ; passez dessous et elle peut vous tomber dessus avec beaucoup de neige. L'approche habituelle est de contourner du côté opposé au bord de la corniche, et de ne jamais s'y arrêter.",

    "q.m16#9.p" to "[Ordre] Quelle est la procédure complète pour traverser un terrain avalancheux ?",
    "q.m16#9.o0" to "Consulter le bulletin d'avalanche du jour avant de partir et repérer les pentes à éviter",
    "q.m16#9.o1" to "Observer les signaux de terrain à l'approche (fissures, bruits d'affaissement, surfaces chargées par le vent)",
    "q.m16#9.o2" to "Désigner le guetteur, l'ordre de passage et l'itinéraire de dégagement",
    "q.m16#9.o3" to "Traverser un par un en gardant l'espacement, et se regrouper en un point sûr",
    "q.m16#9.e" to "Les trois premières étapes se font avant d'entrer — c'est là que réside réellement le travail de sécurité avalanche. Une fois sur la pente, il reste très peu de choix, et la plupart des accidents renvoient à l'omission des deux premières étapes.",

    "q.m16#10.p" to "Pourquoi un sauvetage d'avalanche doit-il être mené immédiatement par les compagnons ?",
    "q.m16#10.o0" to "Parce que le sauvetage professionnel coûte cher",
    "q.m16#10.o1" to "Parce que la fenêtre de survie d'une personne ensevelie n'est que d'une quinzaine de minutes",
    "q.m16#10.o2" to "Parce que les équipes professionnelles ne montent pas",
    "q.m16#10.o3" to "Parce que les compagnons connaissent mieux le terrain",
    "q.m16#10.e" to "Une fenêtre de survie de quinze minutes signifie que les seules personnes qui peuvent vous sauver sont celles qui sont à côté de vous. C'est aussi pourquoi le trio avalanche doit être porté et pratiqué — porter du matériel qu'on ne sait pas utiliser revient à ne rien porter.",

    "q.m16#11.p" to "[Association] Associez chaque degré de danger d'avalanche à sa signification.",
    "q.m16#11.l0" to "Degré 1",
    "q.m16#11.r0" to "Faible : déclenchement naturel et humain peu probables",
    "q.m16#11.l1" to "Degré 3",
    "q.m16#11.r1" to "Marqué : déclenchement humain possible, et le plus facilement sous-estimé",
    "q.m16#11.l2" to "Degré 4",
    "q.m16#11.r2" to "Fort : déclenchement naturel probable ; éviter le terrain avalancheux",
    "q.m16#11.l3" to "Degré 5",
    "q.m16#11.r3" to "Extrême : avalanches naturelles généralisées très probables",
    "q.m16#11.e" to "Derrière chaque chiffre se cache une combinaison de probabilité de déclenchement et d'ampleur des conséquences. L'erreur classique du débutant est de traiter le degré 3 comme « ça va » — or c'est précisément le degré où les accidents se concentrent.",

    "q.m16#12.p" to "Quelles sont la fonction et les limites d'un airbag d'avalanche ?",
    "q.m16#12.o0" to "Il empêche totalement l'ensevelissement ; il n'a aucune limite",
    "q.m16#12.o1" to "Il améliore la chance de rester plus près de la surface ; mais il ne remplace ni DVA, ni sonde, ni pelle, et n'empêche pas les traumatismes",
    "q.m16#12.o2" to "Il ne sert qu'en station de ski",
    "q.m16#12.o3" to "Il appelle les secours automatiquement",
    "q.m16#12.e" to "Le principe est un volume plus grand, donc une probabilité plus élevée de rester près de la surface — cela augmente les chances de survie mais ne les garantit pas. Et une part substantielle des décès par avalanche vient de traumatismes plutôt que d'asphyxie, ce qui explique pourquoi un airbag ne peut jamais être votre unique recours.",

    "q.m16#13.p" to "Pourquoi les pentes qui « ne paraissent pas si raides » sont-elles souvent les plus dangereuses ?",
    "q.m16#13.o0" to "Parce que la neige y est plus profonde",
    "q.m16#13.o1" to "Parce que c'est entre 34° et 45° que les avalanches se concentrent, et que l'œil humain sous-estime l'angle",
    "q.m16#13.o2" to "Parce que peu de gens y vont",
    "q.m16#13.o3" to "Parce que l'angle change vite",
    "q.m16#13.e" to "Sans référence, on estime l'angle d'une pente avec une grande erreur, et on lit souvent 35° comme 25°. Or 30°–35° est exactement la plage qui « paraît praticable mais peut glisser ». Un clinomètre et une carte à courbes de niveau sont le remède à ce biais.",

    "q.m16#14.p" to "[Choix multiple] Que doit accomplir une cordée avant d'entrer en terrain avalancheux ?",
    "q.m16#14.o0" to "Confirmer que chacun sait utiliser DVA, sonde et pelle",
    "q.m16#14.o1" to "Convenir de l'ordre de passage et du guetteur",
    "q.m16#14.o2" to "Convenir d'un point de regroupement et d'un itinéraire de dégagement",
    "q.m16#14.o3" to "Vérifier que les DVA sont en émission",
    "q.m16#14.o4" to "Taper fort à plusieurs reprises pour tester la stabilité du manteau",
    "q.m16#14.e" to "Les quatre sont des vérifications finales avant l'entrée et ne prennent que quelques minutes. Elles comptent parce qu'une fois sur la pente, la seule option qui reste est d'espérer que ça n'arrive pas.",

    "q.m16#15.p" to "Le manteau neigeux émet un bruit d'affaissement « whumpf ». Quelle est la bonne réaction ?",
    "q.m16#15.o0" to "Continuer — c'est juste la neige qui se tasse",
    "q.m16#15.o1" to "S'arrêter immédiatement et réévaluer ; une couche faible a commencé à céder",
    "q.m16#15.o2" to "Traverser plus vite",
    "q.m16#15.o3" to "Se reposer sur place dix minutes",
    "q.m16#15.e" to "Un whumpf est la preuve directe qu'une couche faible s'effondre — cela signifie qu'une charge très légère vient de déclencher une rupture locale. Continuer revient à demander si un peu plus fera tout descendre.",

    "q.m16#16.p" to "Complétez : environ 96 % des avalanches se produisent sur des pentes de 30°–50°, la plupart se concentrant entre 34° et ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "quarante-cinq",
    "q.m16#16.e" to "34°–45°. Cette plage vaut la peine d'être retenue car c'est à la fois le point chaud des avalanches et le gradient que les itinéraires d'alpinisme traversent le plus — c'est le recouvrement de ces deux faits qui fait de l'avalanche l'un des dangers objectifs dominants en alpinisme.",

    "q.m16#17.p" to "Situation : traverser un passage en terrain avalancheux",
    "q.m16#17.c" to "L'itinéraire doit traverser une pente de neige d'environ 35°, longue d'environ 200 m. Le bulletin du jour est Marqué (degré 3), avec 30 cm de neige fraîche récente, du vent de nord-ouest, et la pente exposée au sud-est.",
    "q.m16#17.e" to "Cette situation teste tout le flux de travail avalanche : lire le terrain et le manteau, accomplir les préparatifs avant l'entrée, puis utiliser la formation pour maîtriser les conséquences. Aucune étape n'est difficile ; ce qui est difficile est de les exécuter toutes devant une pente qui paraît praticable.",
    "q.m16#17.s0.p" to "Étape 1 : qu'est-ce qui mérite le plus de prudence sur cette pente ?",
    "q.m16#17.s0.o0" to "Les chutes de pierres",
    "q.m16#17.s0.o1" to "Les plaques accumulées par le vent et l'angle de la pente lui-même",
    "q.m16#17.s0.o2" to "Une température élevée",
    "q.m16#17.s0.o3" to "La végétation au sol",
    "q.m16#17.s0.e" to "35° tombe en plein dans le point chaud 34°–45° ; le vent de nord-ouest transporte la neige sur la pente sous le vent (ici la face sud-est) et construit une plaque supplémentaire. Deux facteurs qui s'additionnent, c'est la combinaison classique du « paraît praticable, peut glisser ».",
    "q.m16#17.s1.p" to "Étape 2 : à l'approche de la pente, que faut-il faire d'abord ?",
    "q.m16#17.s1.o0" to "Commencer à traverser tout de suite",
    "q.m16#17.s1.o1" to "Observer d'abord les signaux de terrain, puis fixer le guetteur, l'ordre de passage et l'itinéraire de dégagement",
    "q.m16#17.s1.o2" to "Taper fort sur la pente pour la tester",
    "q.m16#17.s1.o3" to "Faire traverser toute la cordée rapidement",
    "q.m16#17.s1.e" to "Toute la préparation se fait avant l'entrée. Taper fort ne vérifie pas la stabilité — cela peut directement déclencher un manteau déjà proche de son point critique.",
    "q.m16#17.s2.p" to "Étape 3 : comment disposer la cordée pendant la traversée ?",
    "q.m16#17.s2.o0" to "Un par un, les autres attendant en un point sûr",
    "q.m16#17.s2.o1" to "Tous ensemble en se tenant la main",
    "q.m16#17.s2.o2" to "À deux de front pour se surveiller",
    "q.m16#17.s2.o3" to "En file indienne, serrés",
    "q.m16#17.s2.e" to "Un par un limite le risque à une personne et permet au guetteur de se concentrer sur une seule. Exposer toute la cordée en même temps amplifie la conséquence : peut-être une personne ensevelie devient peut-être tout le monde.",

    "q.m16#18.p" to "Touchez sur la carte la zone approximative du sommet du Manaslu.",
    "q.m16#18.e" to "Un sommet est identifiable sans ambiguïté sur une carte à courbes de niveau : les courbes fermées se resserrent anneau après anneau tandis que les étiquettes montent (7600 → 7750 → 7900 → 7950 …). Trouvez le point entouré de petits anneaux fermés et vous avez le point le plus haut.\nÀ l'inverse, là où les courbes s'évasent vers l'extérieur et où les étiquettes descendent, c'est la descente — ce qui vous indique au passage de quel côté passe l'itinéraire.",

    "q.m16#19.p" to "Sur la même carte, les courbes du flanc nord-est à est sont extrêmement serrées. Qu'est-ce que cela indique ?",
    "q.m16#19.o0" to "Que ce flanc est très raide et constitue un point chaud de chutes de séracs et de pierres",
    "q.m16#19.o1" to "Que ce flanc est doux et propice au camping",
    "q.m16#19.o2" to "Que ce flanc est plus bas et donc moins risqué",
    "q.m16#19.o3" to "Que des courbes serrées signifient un terrain plat",
    "q.m16#19.e" to "Plus les courbes sont serrées, plus le dénivelé est important sur la même distance horizontale — autrement dit, plus la pente est raide. Sur cette carte, le flanc nord-est chute de 7 950 m à 5 750 m avec des dizaines de courbes comprimées sur une courte distance horizontale : une face raide classique.\nEn planifiant un itinéraire, cette compétence de lecture joue directement sur deux choses : si vous traversez des zones de chutes de séracs et de pierres, et s'il existe un terrain de repli utilisable en cas de problème. Les zones plus douces et peu courbées sont celles où un camp a le plus de chances de s'installer.",

    "q.m16#20.p" to "Situation : comparer deux sources de données de terrain",
    "q.m16#20.c" to "Un guide vous donne deux cartes de terrain de la même montagne : l'une issue de Google Maps, l'autre générée à partir des données d'élévation SRTM de la NASA. Aucune n'est fausse, mais elles ne sont pas également capables de répondre à vos questions.",
    "q.m16#20.e" to "La différence essentielle entre jeux de données de terrain n'est pas la précision mais l'équidistance, car c'est elle qui fixe la finesse de variation de pente que vous pouvez voir. L'intuition a de la valeur — elle construit vite une impression d'ensemble — mais décider si un passage est raide ou praticable revient toujours à la densité des courbes, qui peut être quantifiée et comparée.",
    "q.m16#20.s0.p" to "Étape 1 : sur cette carte Google, les étiquettes indiquent 6200, 6400, 6600, 6800… Quelle est l'équidistance ?",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "Les étiquettes voisines diffèrent de 200 m : ce système monte donc de 200 m entre deux courbes. Une équidistance de 200 m convient pour la forme d'ensemble, mais le détail du terrain entre les courbes — un ressaut rocheux de 40 m, par exemple — disparaît simplement de la carte.",
    "q.m16#20.s1.p" to "Étape 2 : la carte SRTM utilise une équidistance de 50 m. Comparée à la carte Google à 200 m, quel est son avantage le plus substantiel ?",
    "q.m16#20.s1.o0" to "Elle est plus jolie",
    "q.m16#20.s1.o1" to "Les courbes sont plus denses sur la même distance horizontale, ce qui résout la variation de pente quatre fois plus finement",
    "q.m16#20.s1.o2" to "Les couleurs sont plus vives",
    "q.m16#20.s1.o3" to "Les étiquettes sont en plus gros caractères",
    "q.m16#20.s1.e" to "Plus l'équidistance est petite, plus on résout de détail. Juger si une pente est praticable repose précisément sur la densité des courbes : à 200 m d'espacement, un ressaut raide de 150 m est lissé en pente douce, alors qu'à 50 m il est dessiné tel qu'il est.\nC'est pourquoi l'évaluation du terrain sur les itinéraires techniques s'appuie sur des sources à haute résolution comme SRTM.",
    "q.m16#20.s2.p" to "Étape 3 : la version Google présente des ombres marquées et paraît en trois dimensions. Comment traiter ces ombres pour juger la raideur ?",
    "q.m16#20.s2.o0" to "Plus l'ombre est sombre, plus la pente est raide — l'utiliser directement comme preuve",
    "q.m16#20.s2.o1" to "L'ombrage ne reflète que l'éclairement et l'exposition ; il ne peut pas servir directement de mesure de pente",
    "q.m16#20.s2.o2" to "L'ombrage marque les zones de couverture neigeuse",
    "q.m16#20.s2.o3" to "L'ombrage marque le terrain au-dessus de 7 000 m",
    "q.m16#20.s2.e" to "L'ombrage simule la façon dont une pente est éclairée par le soleil depuis une direction donnée. Sombre signifie que la pente tourne le dos à la lumière, pas qu'elle est raide. Une pente douce exposée au nord peut être plus sombre qu'une pente raide exposée au sud.\nUtiliser l'ombrage comme approximation de la raideur est une erreur de lecture courante et réellement dangereuse. L'ombrage est bon pour l'impression d'ensemble ; pour quantifier la pente, lisez la densité des courbes, et si possible recoupez avec des données à haute résolution portant les altitudes.",

    "q.m16#21.p" to "À propos de l'affirmation « Google Maps est intuitif mais imprécis, SRTM est précis mais peu intuitif », quelle est la bonne compréhension ?",
    "q.m16#21.o0" to "SRTM est plus précis, donc Google Maps n'a aucune valeur",
    "q.m16#21.o1" to "Il faut les utiliser ensemble : construire l'impression d'ensemble avec la carte intuitive, puis faire des jugements quantifiés avec les courbes à haute résolution",
    "q.m16#21.o2" to "Google Maps est plus intuitif, donc il faut s'y fier d'abord pour juger les pentes",
    "q.m16#21.o3" to "Elles ne diffèrent que par la couleur ; l'information est la même",
    "q.m16#21.e" to "Les deux sources résolvent des problèmes différents. L'ombrage et les noms de lieux de Google construisent vite le sens de l'espace : où est la montagne, sa forme générale, par où passe l'itinéraire. Les courbes à 50 m de SRTM permettent un jugement quantifié : combien de degrés fait cette pente, y a-t-il un endroit pour un camp.\nRepérer avec la carte intuitive, confirmer avec la carte haute résolution — c'est la répartition pratique. N'en utiliser qu'une rend soit lent, soit faux.",

    "q.m16#22.p" to "Touchez sur la carte la zone approximative du sommet de l'Everest.",
    "q.m16#22.e" to "Pour trouver un sommet, cherchez la courbe fermée étiquetée la plus haute. Ici les étiquettes proches de cette zone montent à 8600 et 8700 m avec des anneaux qui se resserrent vers l'intérieur ; le plus interne est le sommet (8 848 m).\nAttention à distinguer haut et raide : le terrain sommital n'est souvent pas la partie la plus raide de la montagne — le terrain le plus raide est là où les courbes sont les plus denses. Cette distinction compte pour le risque de l'itinéraire : atteindre le sommet teste l'acclimatation et la condition physique, tandis que le risque technique se situe surtout sur quelques pentes à la montée et à la descente.",

    "q.m16#23.p" to "Entre les courbes fermées denses de l'Everest et du Lhotse, sur la même carte, il y a une zone où les courbes s'espacent nettement et où le terrain s'abaisse légèrement. Qu'est-ce que c'est, en termes de terrain ?",
    "q.m16#23.o0" to "La source d'un glacier",
    "q.m16#23.o1" to "Le col entre les deux sommets",
    "q.m16#23.o2" to "Le point le plus haut de la crête",
    "q.m16#23.o3" to "Une falaise raide",
    "q.m16#23.e" to "Entre deux points hauts fermés et denses, là où les courbes s'espacent et où le terrain s'abaisse, vous avez un col. Celui entre l'Everest et le Lhotse est le col Sud, à environ 7 900 m, où se trouve le quatrième camp de l'itinéraire du versant sud — le dernier arrêt avant la course au sommet.\nReconnaître les cols sur une carte à courbes est très pratique. Ils signifient généralement du vent fort et de l'exposition, mais un terrain relativement doux : bon pour un camp, mauvais pour s'attarder — d'où le fait que les camps de sommet sont souvent sur un col et sont abandonnés la nuit même.",

    "q.m16#24.p" to "Touchez sur la carte la zone approximative du sommet du Muztagh Ata.",
    "q.m16#24.e" to "La forme du sommet du Muztagh Ata est représentative : un dôme, large et doux au sommet, où la courbe fermée la plus haute est largement étalée plutôt que finement emboîtée comme sur une pointe acérée. Pour trouver ce type de sommet, cherchez l'étiquette d'altitude la plus haute (7 500 m ici) et l'anneau fermé dans lequel elle se trouve.\nLa forme se traduit directement dans l'expérience de l'ascension. Un dôme signifie que la section sommitale n'est pas raide mais prend beaucoup de temps ; avec peu de relief et aucun repère évident, il est facile de perdre le sens de l'orientation sur le névé pendant la descente. C'est un risque souvent évoqué à propos du Muztagh Ata.",
    // ---------- m17 Gestion du camp ----------
    "q.m17#0.p" to "Quel est l'objectif central de la gestion d'un camp de haute altitude ?",
    "q.m17#0.o0" to "Rendre le camp confortable",
    "q.m17#0.o1" to "Maintenir la capacité d'action au coût le plus bas possible",
    "q.m17#0.o2" to "Économiser le carburant",
    "q.m17#0.o3" to "Faire de bonnes photos",
    "q.m17#0.e" to "En altitude, chaque unité d'énergie est une ressource limitée, et le camp est le seul endroit qui la restitue. Chaque décision de camp doit donc répondre à la même question : cela laissera-t-il la cordée en meilleur état demain ?",

    "q.m17#1.p" to "Quelle est la première chose à considérer dans le choix d'un emplacement de camp ?",
    "q.m17#1.o0" to "La vue",
    "q.m17#1.o1" to "Éviter les couloirs d'avalanche, les zones de chutes de séracs, le terrain sous les corniches et les crevasses",
    "q.m17#1.o2" to "Être près de l'eau",
    "q.m17#1.o3" to "Être près du départ de l'itinéraire",
    "q.m17#1.e" to "La première règle de l'emplacement est de ne pas être exposé à un danger objectif — car le camp est l'endroit où l'on reste des heures ou une journée entière et où l'on ne peut presque pas se déplacer vite. La vue et la commodité sont des variables secondaires.",

    "q.m17#2.p" to "Pourquoi ne faut-il pas camper sous une corniche ?",
    "q.m17#2.o0" to "Parce que le sol est irrégulier",
    "q.m17#2.o1" to "Parce qu'une corniche peut se détacher à tout moment et envoyer une masse de neige et de glace droit sur le camp",
    "q.m17#2.o2" to "Parce qu'il y a du vent",
    "q.m17#2.o3" to "Parce qu'on ne voit pas le paysage",
    "q.m17#2.e" to "Un effondrement de corniche ne prévient pas : il peut survenir dans la chaleur de l'après-midi ou à l'heure la plus froide avant l'aube. Installer le camp dessous, c'est accepter une menace continue que l'on ne peut ni surveiller ni anticiper.",

    "q.m17#3.p" to "[Choix multiple] Quelles zones un emplacement de camp doit-il éviter ?",
    "q.m17#3.o0" to "Sous un couloir d'avalanche",
    "q.m17#3.o1" to "Juste sous ou juste au-dessus d'une corniche",
    "q.m17#3.o2" to "Les champs de crevasses évidents",
    "q.m17#3.o3" to "À portée des chutes de séracs",
    "q.m17#3.o4" to "Un point de vue dégagé avec un beau panorama",
    "q.m17#3.e" to "Les quatre premiers sont des cas où un danger objectif tombe exactement sur le camp. Leur point commun : ils sont difficiles à surveiller et, s'ils se produisent, la conséquence est à l'échelle de toute la cordée — d'où des critères d'emplacement plus prudents que pour un itinéraire.",

    "q.m17#4.p" to "Comment répartir le carburant et la nourriture ?",
    "q.m17#4.o0" to "Tout confier à une seule personne",
    "q.m17#4.o1" to "Conditionner par jour, en mettant de côté une réserve d'urgence",
    "q.m17#4.o2" to "Tout garder à l'entrée de la tente",
    "q.m17#4.o3" to "Répartir à parts égales par personne, sans marge",
    "q.m17#4.e" to "Le conditionnement par jour rend la consommation suivable, et la réserve garantit qu'il reste toujours assez d'énergie pour descendre en sécurité. En montagne, le carburant ne sert pas qu'à cuisiner — c'est aussi ce qui fait fondre la neige pour l'eau, sécher les vêtements et maintenir la température du corps.",

    "q.m17#5.p" to "Pourquoi garder une réserve d'urgence ?",
    "q.m17#5.o0" to "Parce que la nourriture s'abîme",
    "q.m17#5.o1" to "Pour garantir carburant et nourriture pour une descente sûre en toutes circonstances",
    "q.m17#5.o2" to "Parce que le magasin l'exige",
    "q.m17#5.o3" to "Pour alléger la charge au retour",
    "q.m17#5.e" to "La réserve vise le pire cas : temps qui tourne, obligation de rester un jour de plus, quelqu'un blessé nécessitant une descente lente. Si toutes les ressources sont affectées à un scénario idéal, le moindre retard vous laisse sans vivres et sans capacité de mouvement.",

    "q.m17#6.p" to "Comment gérer les appareils électroniques (téléphone, appareil photo, batteries de lampe frontale) pendant la nuit ?",
    "q.m17#6.o0" to "Les laisser dehors devant la tente",
    "q.m17#6.o1" to "Les garder contre le corps ou dans le sac de couchage, au chaud",
    "q.m17#6.o2" to "Les garder dans la poche extérieure du sac",
    "q.m17#6.o3" to "Aucune précaution particulière",
    "q.m17#6.e" to "Les batteries au lithium perdent beaucoup de capacité au froid et peuvent s'arrêter complètement. Les garder au chaud ne sert pas à protéger l'appareil — cela sert à ce que la lampe frontale s'allume et que le GPS démarre demain. Ce sont des équipements de sécurité, pas des objets personnels.",

    "q.m17#7.p" to "Que faire des vêtements mouillés ?",
    "q.m17#7.o0" to "Les suspendre dehors pour un séchage par le gel",
    "q.m17#7.o1" to "Les garder contre le corps ou dans le sac de couchage pour les sécher à la chaleur du corps",
    "q.m17#7.o2" to "Les entasser dans un coin de la tente",
    "q.m17#7.o3" to "Les fourrer directement dans le sac",
    "q.m17#7.e" to "Les températures nocturnes en altitude sont extrêmement basses : des vêtements mouillés suspendus dehors gèlent en dur. Sécher contre le corps n'est pas parfait, mais au moins ce ne sera pas de la glace demain matin — un cas classique où la chaleur corporelle est traitée comme une ressource.",

    "q.m17#8.p" to "Pourquoi le camp doit-il toujours rester dans un état permettant de plier et partir immédiatement ?",
    "q.m17#8.o0" to "Pour rendre le départ pratique",
    "q.m17#8.o1" to "Parce que la météo ou l'état d'un membre de la cordée peut imposer une évacuation d'urgence à tout moment",
    "q.m17#8.o2" to "Pour gagner du temps au rangement",
    "q.m17#8.o3" to "Pour que tout reste en ordre",
    "q.m17#8.e" to "La fenêtre météo au camp haut peut se fermer brusquement, et un membre de la cordée peut développer soudainement des symptômes d'altitude. À ce moment-là, le temps nécessaire pour se mettre en route décide du risque que vous portez — et du matériel éparpillé dans toute la tente peut coûter une demi-heure de plus.",

    "q.m17#9.p" to "Lequel n'est PAS une cause principale de mauvais sommeil en altitude ?",
    "q.m17#9.o0" to "Une respiration périodique provoquant des micro-réveils répétés",
    "q.m17#9.o1" to "L'hypoxie et un rythme cardiaque élevé",
    "q.m17#9.o2" to "Le froid et l'inconfort",
    "q.m17#9.o3" to "Une tente d'une couleur trop claire",
    "q.m17#9.e" to "Les trois premiers sont de vraies causes physiologiques, et la respiration périodique est la plus typique : en altitude, la respiration nocturne devient involontairement intermittente et vous ramène sans cesse au sommeil léger. La qualité du sommeil influe ensuite directement sur l'acclimatation — mal dormir n'est donc pas un détail.",

    "q.m17#10.p" to "[Ordre] Quelle est une séquence saine pour installer puis quitter un camp ?",
    "q.m17#10.o0" to "Avant d'arriver, examiner les environs pour les menaces d'avalanche, de séracs et de corniches",
    "q.m17#10.o1" to "Choisir l'emplacement de la tente, égaliser le sol et arrimer la tente",
    "q.m17#10.o2" to "Répartir les vivres, faire fondre de la neige pour l'eau, et planifier le programme et le sommeil du lendemain",
    "q.m17#10.o3" to "Avant de partir, inventorier le matériel et les déchets et remettre le site en état",
    "q.m17#10.e" to "La première étape est la plus souvent sautée — surtout quand on est fatigué, où n'importe quelle surface plate ressemble à un emplacement. Or une fois le camp monté, le déplacer coûte extrêmement cher : regarder autour avant de choisir doit donc devenir une habitude fixe.",

    "q.m17#11.p" to "Pourquoi un camp est-il aussi un pivot pour le repli ?",
    "q.m17#11.o0" to "Parce que les camps contiennent des vivres",
    "q.m17#11.o1" to "Parce que se replier signifie généralement revenir d'abord au camp, puis décider de continuer à descendre ou d'attendre la météo",
    "q.m17#11.o2" to "Parce que les camps ont du matériel de communication",
    "q.m17#11.o3" to "Parce que le guide est au camp",
    "q.m17#11.e" to "Redescendre depuis le haut n'est rarement qu'une seule course continue : on revient au camp le plus proche pour récupérer, observer et décider. Cela signifie que le camp doit lui-même être une destination fiable — pas un endroit où l'on craindrait de revenir.",

    "q.m17#12.p" to "Pourquoi une tente doit-elle être ventilée ?",
    "q.m17#12.o0" to "Pour rester au frais",
    "q.m17#12.o1" to "Pour éviter l'accumulation de monoxyde de carbone et le givre intérieur, et prévenir l'asphyxie et l'intoxication",
    "q.m17#12.o2" to "Pour faciliter les entrées et sorties",
    "q.m17#12.o3" to "Pour réduire la prise au vent",
    "q.m17#12.e" to "Cuisiner au réchaud en altitude peut faire monter vite le monoxyde de carbone dans une tente fermée, et cette intoxication survient plutôt pendant le sommeil avec des symptômes — céphalée, fatigue — presque impossibles à distinguer du mal d'altitude. Ensemble, ces éléments font de la ventilation une exigence absolue.",

    "q.m17#13.p" to "Quelle est la plus grande préoccupation lorsqu'on utilise un réchaud sous la tente ?",
    "q.m17#13.o0" to "Les fuites de carburant",
    "q.m17#13.o1" to "L'intoxication au monoxyde de carbone",
    "q.m17#13.o2" to "Faire fondre la tente",
    "q.m17#13.o3" to "Le bruit",
    "q.m17#13.e" to "Le monoxyde de carbone est incolore et inodore, et ses premiers symptômes — céphalée, somnolence — recouvrent largement ceux du mal d'altitude. C'est exactement ce qui le rend dangereux : on s'endort en croyant à un simple MAM. L'usage du réchaud exige toujours une ventilation.",

    "q.m17#14.p" to "[Choix multiple] Quels points de santé faut-il entretenir activement au camp ?",
    "q.m17#14.o0" to "Boire suffisamment d'eau (faire fondre de la neige)",
    "q.m17#14.o1" to "Manger assez, même sans appétit",
    "q.m17#14.o2" to "Garder les vêtements secs",
    "q.m17#14.o3" to "Surveiller l'état et la démarche les uns des autres",
    "q.m17#14.o4" to "Remplacer les repas par du café et des boissons énergétiques",
    "q.m17#14.e" to "Les trois premiers relèvent du soin de soi, le quatrième du soin de la cordée — et il est souvent plus efficace que les trois premiers : les signes précoces du mal d'altitude (démarche instable, réponses lentes) sont difficiles à remarquer sur soi mais évidents pour un compagnon d'un seul regard.",

    "q.m17#15.p" to "Complétez : au-dessus du camp haut, le carburant et la nourriture sont généralement conditionnés par ( ) avec une réserve d'urgence mise de côté.",
    "q.m17#15.a0" to "jour",
    "q.m17#15.a1" to "le jour",
    "q.m17#15.a2" to "jours",
    "q.m17#15.a3" to "chaque jour",
    "q.m17#15.e" to "Conditionnés par jour. Cela rend le progrès de la consommation visible d'un coup d'œil et permet de voir « combien de jours il reste » dès qu'un programme glisse — plutôt que de le constater quand tout est épuisé.",
    // ---------- m18 Sommets de 7 000 m ----------
    "q.m18#0.p" to "Quelle est l'altitude du Muztagh Ata ?",
    "q.m18#0.o0" to "6 812 m",
    "q.m18#0.o1" to "7 126 m",
    "q.m18#0.o2" to "7 134 m",
    "q.m18#0.o3" to "7 509 m",
    "q.m18#0.e" to "Le Muztagh Ata culmine à 7 509 m, dans le comté d'Akto au Xinjiang. C'est le premier choix pour un objectif chinois de 7 000 m et le plus haut des quatre sommets de cette leçon.",

    "q.m18#1.p" to "Pourquoi le Muztagh Ata est-il appelé le « Père des montagnes de glace » ?",
    "q.m18#1.o0" to "Parce que c'est le plus haut sommet du monde",
    "q.m18#1.o1" to "Parce que ses glaciers et son volume de neige sont énormes, si bien que de loin il ressemble à une vaste calotte glaciaire",
    "q.m18#1.o2" to "Parce que c'est le premier 7 000 m gravi",
    "q.m18#1.o3" to "Parce que c'est une montagne sacrée de la légende locale",
    "q.m18#1.e" to "Le nom vient de son aspect : le sommet est couvert d'une immense calotte de glace et les pentes de neige s'étendent très largement, si bien que de loin il se lit comme un massif blanc. Cette image explique aussi son caractère : de longues pentes de neige, un angle modéré, mais beaucoup de temps.",

    "q.m18#2.p" to "Quelles sont les caractéristiques techniques de l'ascension du Muztagh Ata ?",
    "q.m18#2.o0" to "Surtout des parois de glace verticales, extrêmement techniques",
    "q.m18#2.o1" to "D'interminables pentes de neige, difficulté technique modérée, mais très exigeantes en acclimatation et en condition physique",
    "q.m18#2.o2" to "Presque aucun matériel technique nécessaire",
    "q.m18#2.o3" to "Surtout du terrain d'escalade rocheuse",
    "q.m18#2.e" to "C'est le profil classique d'un 7 000 m : l'itinéraire en soi peut ne pas être dur, mais de longues journées de portage en altitude grossissent chaque petit problème. Le vrai axe de préparation est donc l'acclimatation et la condition physique, pas la technique de haut niveau.",

    "q.m18#3.p" to "Quelle est l'altitude réelle de l'Ama Dablam ?",
    "q.m18#3.o0" to "6 812 m",
    "q.m18#3.o1" to "7 126 m",
    "q.m18#3.o2" to "7 509 m",
    "q.m18#3.o3" to "8 027 m",
    "q.m18#3.e" to "L'Ama Dablam culmine à 6 812 m, dans la région du Khumbu au Népal. Par l'altitude c'est un 6 000 m, mais il figure dans l'unité 7 000 m parce que sa difficulté technique est du niveau des sommets au-dessus de 7 000 m.",

    "q.m18#4.p" to "Pourquoi l'Ama Dablam, à seulement 6 812 m, est-il placé dans l'unité 7 000 m ?",
    "q.m18#4.o0" to "Parce qu'il est administrativement classé comme 7 000 m",
    "q.m18#4.o1" to "Parce que son terrain mixte rocher-neige raide et sa forte exposition mettent sa difficulté au niveau des sommets au-dessus de 7 000 m",
    "q.m18#4.o2" to "Parce que son taux de réussite est très faible",
    "q.m18#4.o3" to "Parce qu'il se trouve dans une chaîne de 7 000 m",
    "q.m18#4.e" to "C'est le point le plus important de la leçon : la difficulté d'une montagne n'est pas son altitude. L'Ama Dablam en est la preuve classique — plus bas que beaucoup de 7 000 m, mais son seuil technique et sa charge psychologique peuvent être plus élevés. Choisir une montagne à l'altitude seule est dangereux.",

    "q.m18#5.p" to "Quelles sont l'altitude et la localisation du pic Lénine ?",
    "q.m18#5.o0" to "7 126 m, Népal",
    "q.m18#5.o1" to "7 134 m, plateau du Pamir",
    "q.m18#5.o2" to "7 509 m, Xinjiang",
    "q.m18#5.o3" to "6 812 m, Khumbu, Népal",
    "q.m18#5.e" to "Le pic Lénine culmine à 7 134 m sur le plateau du Pamir. Il fait partie des options 7 000 m les plus douces et sert donc souvent de premier objectif à cette altitude.",

    "q.m18#6.p" to "Quelle est l'altitude du Himlung Himal ?",
    "q.m18#6.o0" to "7 126 m",
    "q.m18#6.o1" to "7 134 m",
    "q.m18#6.o2" to "7 509 m",
    "q.m18#6.o3" to "6 812 m",
    "q.m18#6.e" to "Le Himlung Himal culmine à 7 126 m, au Népal. Son itinéraire mêle pentes de neige et parois de glace, ce qui le rend populaire parmi les 7 000 m népalais.",

    "q.m18#7.p" to "[Ordre] Classez ces montagnes de l'altitude la plus basse à la plus haute.",
    "q.m18#7.o0" to "Ama Dablam (6 812 m)",
    "q.m18#7.o1" to "Himlung Himal (7 126 m)",
    "q.m18#7.o2" to "Pic Lénine (7 134 m)",
    "q.m18#7.o3" to "Muztagh Ata (7 509 m)",
    "q.m18#7.e" to "Cet ordre révèle une erreur fréquente : classé par altitude, l'Ama Dablam passe avant le Muztagh Ata — alors que la difficulté technique réelle peut être l'inverse. Encore une fois : l'altitude n'est qu'une variable parmi d'autres.",

    "q.m18#8.p" to "[Choix multiple] Qu'est-ce qui change principalement à 7 000 m par rapport à 6 000 m ?",
    "q.m18#8.o0" to "Une acclimatation plus longue, avec davantage de rotations par les camps hauts",
    "q.m18#8.o1" to "Des fenêtres météo plus étroites, donc un timing qui compte davantage",
    "q.m18#8.o2" to "Un repli plus difficile, ce qui fait de l'auto-sauvetage une exigence absolue",
    "q.m18#8.o3" to "Un terrain généralement plus technique et plus exposé",
    "q.m18#8.o4" to "L'oxygène supplémentaire devient un équipement standard",
    "q.m18#8.e" to "Ces quatre éléments se multiplient plutôt qu'ils ne s'additionnent : une mauvaise acclimatation fait manquer la fenêtre, manquer la fenêtre impose un repli dans de moins bonnes conditions, et ce repli est amplifié par l'altitude et le terrain technique. C'est pourquoi 7 000 m est appelé le bassin versant.",

    "q.m18#9.p" to "Pourquoi 7 000 m est-il appelé un « bassin versant » ?",
    "q.m18#9.o0" to "Parce qu'on n'a besoin de piolet qu'au-dessus de 7 000 m",
    "q.m18#9.o1" to "Parce qu'à partir de là, technique, jugement, condition physique et logistique agissent tous en même temps, et aucune qualité isolée ne peut compenser",
    "q.m18#9.o2" to "Parce que les glaciers ne sont visibles qu'au-dessus de 7 000 m",
    "q.m18#9.o3" to "Parce que les expéditions commerciales n'opèrent qu'au-dessus de 7 000 m",
    "q.m18#9.e" to "Les échecs à 5 000 m ont tendance à avoir une seule cause (acclimatation ou condition physique), à 6 000 m les causes commencent à s'empiler, et à 7 000 m tout doit être en place. C'est aussi pourquoi cette unité réunit technique, jugement, météo, auto-sauvetage et gestion du camp — ils ont toujours formé un seul système.",

    "q.m18#10.p" to "Qu'est-ce qui compte le plus dans le choix d'un objectif de 7 000 m ?",
    "q.m18#10.o0" to "L'altitude",
    "q.m18#10.o1" to "Une bonne adéquation d'ensemble entre type d'itinéraire, logistique, programme d'acclimatation et possibilités de repli",
    "q.m18#10.o2" to "Le coût",
    "q.m18#10.o3" to "Le taux de réussite",
    "q.m18#10.e" to "Aucun élément isolé ne suffit : plus haut n'est pas forcément plus dur, un fort taux de réussite n'est pas forcément plus sûr, bon marché n'est pas forcément une bonne affaire. Le vrai jugement est de savoir si la combinaison de ces quatre éléments est quelque chose que moi, tel que je suis maintenant, je peux porter.",

    "q.m18#11.p" to "Sur le Muztagh Ata, pourquoi les « interminables pentes de neige » sont-elles en soi un risque ?",
    "q.m18#11.o0" to "Parce que les pentes sont trop glissantes",
    "q.m18#11.o1" to "Parce qu'une longue exposition à l'altitude érode progressivement la condition physique et le jugement, et que la distance de repli est longue",
    "q.m18#11.o2" to "Parce que les pentes produisent souvent des avalanches",
    "q.m18#11.o3" to "Parce qu'on ne peut pas s'encorder sur une pente de neige",
    "q.m18#11.e" to "« Pas dur mais très long » est le modèle de risque classique du 7 000 m : aucun passage clé, mais une érosion continue. Une longue exposition signifie que la forme, l'attention et la qualité des décisions glissent lentement — et cette marge perdue est exactement votre marge de sécurité.",

    "q.m18#12.p" to "[Association] Associez chaque montagne à son caractère typique.",
    "q.m18#12.l0" to "Muztagh Ata",
    "q.m18#12.r0" to "Père des montagnes de glace : interminables pentes de neige, un test d'acclimatation et de condition physique",
    "q.m18#12.l1" to "Ama Dablam",
    "q.m18#12.r1" to "Rocher et neige mixte raide, forte exposition, un révélateur pour les 8 000 m",
    "q.m18#12.l2" to "Pic Lénine",
    "q.m18#12.r2" to "Plateau du Pamir ; comparativement doux parmi les 7 000 m",
    "q.m18#12.l3" to "Himlung Himal",
    "q.m18#12.r3" to "Au Népal ; un mélange de pentes de neige et de parois de glace",
    "q.m18#12.e" to "Ces quatre profils correspondent à quatre priorités de préparation : le Muztagh Ata pour l'acclimatation, l'Ama Dablam pour la technique et le psychologique, le pic Lénine comme marchepied, le Himlung comme test complet. Les voir ensemble permet de choisir selon son propre point faible.",

    "q.m18#13.p" to "Si l'objectif est un 8 000 m, quelle est la façon la plus sensée de choisir parmi les options de 7 000 m ?",
    "q.m18#13.o0" to "Prendre le plus haut",
    "q.m18#13.o1" to "Prendre celui qui couvre son propre point faible (technique, acclimatation ou exposition)",
    "q.m18#13.o2" to "Prendre le moins cher",
    "q.m18#13.o3" to "Prendre le taux de réussite le plus élevé",
    "q.m18#13.e" to "Traiter le 7 000 m comme un terrain d'entraînement pour ses points faibles vaut plus que le traiter comme un passage de niveau. Faible en technique : choisir l'Ama Dablam ; mauvais acclimateur : choisir le Muztagh Ata et ses longues pentes avec des rotations établies par les camps hauts.",

    "q.m18#14.p" to "Quelle est la bonne vision de la période de préparation pour un 7 000 m ?",
    "q.m18#14.o0" to "Environ la même que pour un 6 000 m",
    "q.m18#14.o1" to "Nettement plus longue, avec assez de rotations par les camps hauts et de temps d'acclimatation",
    "q.m18#14.o2" to "Seul un entraînement physique est nécessaire",
    "q.m18#14.o3" to "Elle peut commencer juste après la course précédente",
    "q.m18#14.e" to "L'acclimatation est cumulative, et un 7 000 m demande généralement plusieurs rotations par les camps hauts. Construire un programme serré sans prévoir de temps d'acclimatation est la raison directe pour laquelle beaucoup de cordées de 7 000 m n'atteignent pas le sommet — ou ont un accident.",

    "q.m18#15.p" to "Pourquoi cette unité place-t-elle le « jugement du danger » après les leçons techniques ?",
    "q.m18#15.o0" to "Parce que le jugement est plus facile que la technique",
    "q.m18#15.o1" to "Parce que la compétence technique donne la confiance pour entrer dans un terrain plus dur, ce qui rend le jugement d'autant plus nécessaire pour la contenir",
    "q.m18#15.o2" to "Pour des raisons de place dans le programme",
    "q.m18#15.o3" to "Parce que la technique n'a pas d'importance",
    "q.m18#15.e" to "C'est une conception réaliste : plus vous êtes compétent, plus les itinéraires que vous pouvez tenter sont durs, donc le besoin de vous limiter augmente réellement. Placer le jugement après la technique reproduit cet ordre dans la réalité — d'abord la capacité, ensuite la retenue.",
    // ---------- m19 Zone de la mort ----------
    "q.m19#0.p" to "La « zone de la mort » désigne généralement :",
    "q.m19#0.o0" to "Au-dessus de 7 000 m",
    "q.m19#0.o1" to "Au-dessus de 8 000 m",
    "q.m19#0.o2" to "Au-dessus de 5 500 m",
    "q.m19#0.o3" to "Au-dessus de 6 000 m",
    "q.m19#0.e" to "Au-dessus de 8 000 m s'appelle la zone de la mort pour une raison simple : la pression partielle d'oxygène est si basse qu'aucune acclimatation ne permet au corps de maintenir son équilibre longtemps. Ce n'est pas une image mais un fait physiologique — et c'est la ligne de partage la plus fondamentale entre 8 000 m et 7 000 m.",

    "q.m19#1.p" to "À 8 000 m, la pression atmosphérique représente environ quelle fraction du niveau de la mer ?",
    "q.m19#1.o0" to "La moitié",
    "q.m19#1.o1" to "Deux tiers",
    "q.m19#1.o2" to "Un tiers",
    "q.m19#1.o3" to "Un cinquième",
    "q.m19#1.e" to "Environ un tiers. Cela signifie que chaque inspiration n'apporte qu'environ trente pour cent des molécules d'oxygène disponibles au niveau de la mer — alors que l'ascension exige plusieurs fois l'oxygène du repos. Cet écart entre l'offre et la demande est la source de tous les risques à 8 000 m.",

    "q.m19#2.p" to "Pourquoi le corps humain ne peut-il pas rester longtemps au-dessus de 8 000 m ?",
    "q.m19#2.o0" to "Parce qu'il fait trop froid",
    "q.m19#2.o1" to "Parce que la pression partielle d'oxygène est sous le seuil nécessaire au métabolisme, si bien que le corps se dégrade régulièrement",
    "q.m19#2.o2" to "Parce qu'il n'y a pas assez de nourriture",
    "q.m19#2.o3" to "Parce que le vent est trop fort",
    "q.m19#2.e" to "Rester longtemps signifie consommer plus que l'on ne répare : même au repos, le corps perd du muscle et du poids et les performances cognitives baissent. C'est pourquoi un itinéraire à 8 000 m doit être rapide à la montée comme à la descente — il n'y a pas d'option consistant à attendre une amélioration.",

    "q.m19#3.p" to "Quelle capacité l'hypoxie affecte-t-elle généralement en premier ?",
    "q.m19#3.o0" to "La force des jambes",
    "q.m19#3.o1" to "Le jugement et la cognition",
    "q.m19#3.o2" to "La vision",
    "q.m19#3.o3" to "L'audition",
    "q.m19#3.e" to "C'est le mécanisme le plus dangereux à 8 000 m : celui dont le jugement a baissé ne peut pas juger que son jugement a baissé. À l'inverse, des jambes faibles se remarquent tout de suite, tandis que la pensée « je peux continuer » peut elle-même déjà être un produit de l'hypoxie.",

    "q.m19#4.p" to "Pourquoi la baisse du jugement est-elle particulièrement dangereuse à 8 000 m ?",
    "q.m19#4.o0" to "Parce qu'on peut se perdre",
    "q.m19#4.o1" to "Parce qu'il faut utiliser un jugement déjà altéré pour décider de continuer ou de se replier",
    "q.m19#4.o2" to "Parce que cela affecte les compagnons",
    "q.m19#4.o3" to "Parce que cela ralentit",
    "q.m19#4.e" to "C'est un piège récursif : précisément au moment où une décision critique est nécessaire — continuer ou se replier — votre capacité de décision est la moins fiable. « On avance encore un peu pour voir » peut être raisonnable à 4 000 m ; à 8 000 m, c'est peut-être déjà une erreur dictée par l'hypoxie.",

    "q.m19#5.p" to "[Choix multiple] Quels sont les signes typiques d'un déclin cognitif dû à l'hypoxie ?",
    "q.m19#5.o0" to "Réactions plus lentes, élocution embarrassée",
    "q.m19#5.o1" to "Erreurs de calcul et de jugement",
    "q.m19#5.o2" to "Une évaluation du risque devenue trop optimiste",
    "q.m19#5.o3" to "Sautes d'humeur, irritabilité ou apathie",
    "q.m19#5.o4" to "Une sensation de gelure réduite aux doigts et aux orteils",
    "q.m19#5.e" to "Les quatre premiers sont typiques, et ils partagent un trait : la personne concernée les remarque à peine. L'approche fiable est donc l'externalisation — des listes de contrôle au lieu de la mémoire, des heures fixes au lieu du « ça a l'air d'aller », et des compagnons qui se surveillent au lieu de l'auto-évaluation.",

    "q.m19#6.p" to "Quel est le contrepoids le plus efficace au déclin du jugement ?",
    "q.m19#6.o0" to "Utiliser sa volonté pour rester alerte",
    "q.m19#6.o1" to "Externaliser les décisions dans des listes de contrôle écrites à l'avance et des règles fixes (heure, oxygène restant, seuils météo)",
    "q.m19#6.o2" to "Boire plus d'eau chaude",
    "q.m19#6.o3" to "Ralentir",
    "q.m19#6.e" to "La volonté est précisément ce que l'hypoxie érode en premier. La méthode fiable est d'écrire les règles pendant que vous fonctionnez encore : à quelle heure il faut faire demi-tour, quelle quantité d'oxygène restante déclenche la descente — il ne reste alors qu'à vérifier des faits, sans rejuger.",

    "q.m19#7.p" to "Pourquoi un itinéraire à 8 000 m insiste-t-il sur « partir tôt, rentrer tôt » ?",
    "q.m19#7.o0" to "Pour éviter la foule",
    "q.m19#7.o1" to "Parce que la probabilité de dégradation météo augmente l'après-midi, et que le froid et le vent drainent vite l'énergie et l'oxygène",
    "q.m19#7.o2" to "Parce que l'itinéraire est plus court le matin",
    "q.m19#7.o3" to "Par habitude des guides",
    "q.m19#7.e" to "À 8 000 m, le coût de « tard » est amplifié : le même terrain demande deux fois plus d'effort l'après-midi, et une fois la nuit tombée, la température et le jugement baissent ensemble. « Redescendre trop tard » est presque toujours le point de départ commun de cette chaîne d'accident.",

    "q.m19#8.p" to "Pourquoi 8 000 m impose-t-il de « simplifier la prise de décision » ?",
    "q.m19#8.o0" to "Pour gagner du temps",
    "q.m19#8.o1" to "Parce que les ressources cognitives sont limitées et doivent être réservées aux décisions qui comptent vraiment",
    "q.m19#8.o2" to "Parce qu'on n'a pas envie de réfléchir en altitude",
    "q.m19#8.o3" to "Parce que les compagnons décideront à votre place",
    "q.m19#8.e" to "En pratique : des places et un ordre fixes pour le matériel, des procédures transformées en listes de contrôle, un programme arrêté à l'avance. Faire de « quoi porter aujourd'hui, par quoi commencer » une évidence qui ne demande aucune réflexion, c'est ce qui préserve le jugement pour des décisions comme continuer ou se replier.",

    "q.m19#9.p" to "Pourquoi même des alpinistes expérimentés ont-ils besoin de listes de contrôle à 8 000 m ?",
    "q.m19#9.o0" to "Parce que la mémoire n'est pas fiable",
    "q.m19#9.o1" to "Parce que l'hypoxie abîme d'abord la mémoire de travail, et qu'une liste de contrôle ne dépend pas de la mémoire",
    "q.m19#9.o2" to "Parce que la réglementation l'exige",
    "q.m19#9.o3" to "Pour aider les débutants à apprendre",
    "q.m19#9.e" to "La logique est la même qu'en aviation : dans un environnement à forte charge et à fortes conséquences, on ne peut pas compter sur « je ne vais probablement pas oublier ». Une liste de contrôle n'est pas un outil pédagogique pour débutants mais une assurance contre les erreurs que même les experts commettent.",

    "q.m19#10.p" to "Qu'est-ce qui provoque principalement une perte de poids continue en altitude ?",
    "q.m19#10.o0" to "Parce que la nourriture a mauvais goût",
    "q.m19#10.o1" to "Parce que le corps ne cesse de dégrader ses propres tissus en hypoxie, tandis que la baisse d'appétit signifie des apports insuffisants",
    "q.m19#10.o2" to "À cause de la quantité d'exercice",
    "q.m19#10.o3" to "À cause d'un manque d'eau",
    "q.m19#10.e" to "Deux facteurs agissent ensemble : l'hypoxie place le corps dans un état où la dégradation dépasse la synthèse, et le mal d'altitude lui-même coupe l'appétit. C'est pourquoi savoir manger en altitude est une capacité, pas un plaisir.",

    "q.m19#11.p" to "Pourquoi dort-on mal à 8 000 m ?",
    "q.m19#11.o0" to "Parce que la tente est inconfortable",
    "q.m19#11.o1" to "Parce que le manque d'oxygène provoque une respiration périodique, avec des pauses répétées qui vous sortent du sommeil",
    "q.m19#11.o2" to "Parce qu'il y a du vent",
    "q.m19#11.o3" to "Parce qu'on a trop dormi dans la journée",
    "q.m19#11.e" to "La respiration périodique est le phénomène classique du sommeil en altitude : une commande respiratoire instable produit des cycles répétés d'apnée puis de sursaut. La qualité du sommeil influe ensuite directement sur l'acclimatation et l'énergie du lendemain — savoir dormir est donc une compétence centrale au camp haut.",

    "q.m19#12.p" to "[Ordre] Classez les effets de l'hypoxie sur les fonctions du corps dans leur ordre habituel d'apparition.",
    "q.m19#12.o0" to "Respiration plus rapide et rythme cardiaque élevé (compensation)",
    "q.m19#12.o1" to "Endurance en baisse à l'effort prolongé",
    "q.m19#12.o2" to "Baisse du jugement et des capacités de calcul",
    "q.m19#12.o3" to "Troubles de la conscience, ataxie",
    "q.m19#12.e" to "Les deux premiers sont le corps qui tente de s'adapter ; les deux derniers sont le corps qui défaille. Le dangereux est le troisième — il apparaît avant tout changement évident de conscience, donc « il a l'air normal » ne signifie pas « il pense clairement ».",

    "q.m19#13.p" to "Quel est le moyen le plus direct et le plus fiable de contrer l'hypoxie à 8 000 m ?",
    "q.m19#13.o0" to "Manger davantage",
    "q.m19#13.o1" to "Utiliser de l'oxygène supplémentaire",
    "q.m19#13.o2" to "Se reposer davantage",
    "q.m19#13.o3" to "Ralentir",
    "q.m19#13.e" to "Les autres agissent en réduisant la consommation ou en accélérant l'acclimatation, tandis que l'oxygène supplémentaire augmente directement la pression partielle d'oxygène inspirée — il change la variable racine. C'est pourquoi l'oxygène est un équipement de sécurité standard à 8 000 m.",

    "q.m19#14.p" to "Quelle est la bonne compréhension de la « limite de l'acclimatation » ?",
    "q.m19#14.o0" to "L'acclimatation peut se poursuivre indéfiniment",
    "q.m19#14.o1" to "L'acclimatation a un plafond ; au-dessus d'une certaine altitude, aucune quantité ne compense pleinement",
    "q.m19#14.o2" to "L'acclimatation prend un jour",
    "q.m19#14.o3" to "L'acclimatation n'a aucun rapport avec l'altitude",
    "q.m19#14.e" to "L'acclimatation est un processus avec une limite, pas une courbe qui monte sans fin. C'est la raison fondamentale pour laquelle 8 000 m dépend de l'oxygène et d'une stratégie rapide à la montée comme à la descente — non par défaut de préparation, mais parce qu'il n'existe physiologiquement pas d'option « s'acclimater puis rester ».",

    "q.m19#15.p" to "Pourquoi la cause d'un accident à 8 000 m est-elle rarement un événement unique ?",
    "q.m19#15.o0" to "À cause de la malchance",
    "q.m19#15.o1" to "Parce que l'hypoxie affaiblit simultanément le jugement, l'énergie et la coordination, rendant plusieurs maillons fragiles en même temps",
    "q.m19#15.o2" to "Parce que le matériel est insuffisant",
    "q.m19#15.o3" to "Parce qu'il y a trop de monde",
    "q.m19#15.e" to "En basse altitude, une erreur laisse généralement une marge pour se rattraper ; à 8 000 m, jugement, énergie et contrôle moteur baissent ensemble, si bien que de petites erreurs s'enchaînent directement en accident. La stratégie de sécurité à 8 000 m doit donc multiplier les couches de protection, pas simplement être plus prudent.",

    "q.m19#16.p" to "[Choix multiple] Quelles sont les principales causes de décès à 8 000 m ?",
    "q.m19#16.o0" to "Avalanche et chutes de séracs",
    "q.m19#16.o1" to "Les chutes",
    "q.m19#16.o2" to "L'hypothermie",
    "q.m19#16.o3" to "Le mal d'altitude et ses complications",
    "q.m19#16.o4" to "Les atteintes environnementales comme la cécité des neiges et les coups de soleil",
    "q.m19#16.e" to "Les quatre sont courantes, et elles s'empilent souvent : une chute vous laisse incapable de vous auto-secourir, puis l'attente dans le froid, puis l'hypothermie, puis l'aggravation du mal d'altitude. C'est pourquoi la préparation à 8 000 m ne peut pas se concentrer sur le seul mal d'altitude mais doit inclure technique, jugement et systèmes.",

    "q.m19#17.p" to "Complétez : au-dessus de 8 000 m s'appelle la « zone de la ( ) ».",
    "q.m19#17.a0" to "mort",
    "q.m19#17.a1" to "morts",
    "q.m19#17.e" to "La zone de la mort. La valeur pratique du terme est la contrainte absolue qu'il transmet : ici, il n'y a pas d'option d'attendre ou de lever le pied. Chaque plan, chaque calcul de vivres et chaque décision doit être conçu autour du passage le plus rapide possible.",

    "q.m19#18.p" to "À 8 000 m, vous remarquez que vous « voulez vraiment continuer vers le sommet ». Que faut-il faire ?",
    "q.m19#18.o0" to "Faire confiance à son instinct et continuer",
    "q.m19#18.o1" to "Le traiter comme un possible signe de sous-estimation du risque due à l'hypoxie et vérifier immédiatement les conditions de demi-tour fixées à l'avance",
    "q.m19#18.o2" to "Accélérer et atteindre le sommet",
    "q.m19#18.o3" to "Laisser les compagnons décider",
    "q.m19#18.e" to "C'est une situation très représentative : une forte envie de continuer peut n'être qu'un désir en basse altitude, mais à 8 000 m elle peut être le signal d'un jugement altéré. La seule référence fiable est alors non pas ce que vous ressentez, mais les conditions objectives écrites avant le départ.",
    // ---------- m20 Oxygène supplémentaire ----------
    "q.m20#0.p" to "Quel est le rôle principal de l'oxygène supplémentaire à 8 000 m ?",
    "q.m20#0.o0" to "Remplacer l'entraînement physique",
    "q.m20#0.o1" to "Augmenter l'oxygène sanguin, réduire le risque de mal d'altitude et améliorer la mobilité et le jugement",
    "q.m20#0.o2" to "Tenir chaud",
    "q.m20#0.o3" to "Réduire le poids du sac",
    "q.m20#0.e" to "L'élément le plus souvent négligé — et le plus critique pour la sécurité — est l'amélioration du jugement, car il contrecarre directement le facteur le plus dangereux à 8 000 m. C'est aussi pourquoi l'oxygène est un équipement de sécurité standard à cette altitude et non un simple confort.",

    "q.m20#1.p" to "Quels sont les composants d'un système d'oxygène supplémentaire ?",
    "q.m20#1.o0" to "Bouteille, détendeur, débitmètre, masque ou lunettes nasales",
    "q.m20#1.o1" to "Bouteille et sac à dos",
    "q.m20#1.o2" to "Masque et couche isolante",
    "q.m20#1.o3" to "Détendeur et casque",
    "q.m20#1.e" to "Chaque pièce a son rôle : la bouteille stocke, le détendeur abaisse la haute pression à une plage sûre, le débitmètre fixe le débit, et le masque ou les lunettes nasales le délivrent. Une défaillance quelque part vous fait inspirer moins que vous ne croyez — d'où la vérification du système à chaque étape.",

    "q.m20#2.p" to "Quel débit est typique en usage alpin ?",
    "q.m20#2.o0" to "0,5–1 L/min",
    "q.m20#2.o1" to "2–4 L/min",
    "q.m20#2.o2" to "8–10 L/min",
    "q.m20#2.o3" to "Plus de 15 L/min",
    "q.m20#2.e" to "2 à 4 L/min est la plage habituelle en course ; le chiffre exact dépend de l'altitude, de l'effort et de la réponse individuelle. Un débit plus élevé est plus confortable mais consomme plus vite — un arbitrage qui détermine directement combien de temps vous pouvez rester à 8 000 m.",

    "q.m20#3.p" to "Pourquoi faut-il calculer une réserve d'urgence séparément dans la planification de l'oxygène ?",
    "q.m20#3.o0" to "Pour emporter un peu de marge",
    "q.m20#3.o1" to "Parce que des retards, l'assistance à un compagnon ou une défaillance du système peuvent tous consommer de l'oxygène en plus",
    "q.m20#3.o2" to "Parce que les bouteilles fuient",
    "q.m20#3.o3" to "Parce que la réglementation l'exige",
    "q.m20#3.e" to "L'erreur classique de planification de l'oxygène est « juste assez pour atteindre le sommet ». Les programmes réels sont presque toujours plus lents que prévu, et les compagnons peuvent manquer ou le système fuir. Sans réserve, la moindre déviation vous laisse jouer votre vie à l'altitude la plus dangereuse.",

    "q.m20#4.p" to "Que peut-il arriver quand l'oxygène s'épuise ?",
    "q.m20#4.o0" to "Rien du tout",
    "q.m20#4.o1" to "L'état peut se dégrader rapidement, parce que le corps s'est adapté à une concentration inspirée plus élevée",
    "q.m20#4.o2" to "Le mal d'altitude frappe instantanément",
    "q.m20#4.o3" to "Le système bascule automatiquement sur l'air ambiant",
    "q.m20#4.e" to "Passer brutalement d'un oxygène enrichi à la pression partielle ambiante équivaut à gagner d'un coup un morceau d'altitude à 8 000 m. Si vous êtes loin du camp et déjà épuisé, cela peut devenir dangereux très vite — d'où la nécessité de garder une marge d'oxygène prudente.",

    "q.m20#5.p" to "[Choix multiple] Quelle discipline s'applique à l'usage d'un système d'oxygène ?",
    "q.m20#5.o0" to "Vérifier le débit et les raccords à chaque étape",
    "q.m20#5.o1" to "Utiliser le débit prévu ; ne pas l'augmenter à volonté",
    "q.m20#5.o2" to "Noter ce qui reste et l'autonomie estimée",
    "q.m20#5.o3" to "Convenir à l'avance du niveau restant auquel il faut descendre",
    "q.m20#5.o4" to "Mettre le débit au maximum quand on ne se sent pas bien",
    "q.m20#5.e" to "Le quatrième est le plus important : faire de « descendre à ce niveau restant » un chiffre fixé à l'avance plutôt qu'une discussion sur place. Au moment où cela compte, la personne qui a besoin de cette règle peut déjà avoir perdu la capacité de juger correctement.",

    "q.m20#6.p" to "Pourquoi utiliser de l'oxygène n'est-il pas de la « triche » ?",
    "q.m20#6.o0" to "Parce que le règlement l'autorise",
    "q.m20#6.o1" to "Parce qu'au-dessus de 8 000 m le corps sort de la plage physiologique qu'il peut compenser durablement, et que l'oxygène est la réponse standard à ce fait",
    "q.m20#6.o2" to "Parce que tout le monde le fait",
    "q.m20#6.o3" to "Parce que cela améliore le taux de réussite",
    "q.m20#6.e" to "Le mot triche suppose qu'un peu plus d'effort permet de franchir la limite — or la limite à 8 000 m relève de la physique et de la physiologie, pas d'une règle. L'oxygène élève un peu le plafond physiologique ; il ne change pas le fait que l'on ne peut pas rester longtemps.",

    "q.m20#7.p" to "Quelle est la principale différence entre un masque et des lunettes nasales ?",
    "q.m20#7.o0" to "Un masque délivre une concentration plus stable mais il est plus étouffant et gêne la vision en marche",
    "q.m20#7.o1" to "Les lunettes nasales délivrent une concentration plus élevée",
    "q.m20#7.o2" to "Ils sont identiques",
    "q.m20#7.o3" to "Un masque est plus léger",
    "q.m20#7.e" to "Un masque étanche mieux et maintient une concentration stable, mais ajoute une résistance respiratoire, s'embue facilement et est inconfortable en mouvement ; les lunettes nasales sont confortables avec une vue dégagée, mais la concentration réellement inspirée dépend beaucoup de la façon de respirer. Le choix dépend du terrain, de l'intensité et de la tolérance personnelle — ce n'est pas simplement lequel est le meilleur.",

    "q.m20#8.p" to "Quel arbitrage accompagne l'augmentation ou la baisse du débit ?",
    "q.m20#8.o0" to "Le confort contre la durée d'autonomie",
    "q.m20#8.o1" to "Le poids contre le prix",
    "q.m20#8.o2" to "Il n'y a pas d'arbitrage",
    "q.m20#8.o3" to "L'altitude contre la température",
    "q.m20#8.e" to "Un débit plus élevé signifie un corps plus à l'aise et un jugement mieux préservé, mais moins de temps avant l'épuisement. Un plan d'oxygène est donc en pratique un budget de temps passé en altitude — ce qui fixe directement la fenêtre du jour de sommet et l'heure de demi-tour.",

    "q.m20#9.p" to "Pourquoi le poids des bouteilles devient-il un problème logistique ?",
    "q.m20#9.o0" to "Parce qu'elles sont encombrantes",
    "q.m20#9.o1" to "Parce que la bouteille et le gaz sont lourds, et qu'au-dessus du camp haut tout doit être porté à dos d'homme",
    "q.m20#9.o2" to "Parce qu'elles ne passent pas en soute",
    "q.m20#9.o3" to "Parce qu'elles cassent facilement",
    "q.m20#9.e" to "En altitude, le coût de chaque kilogramme est amplifié, et une bouteille est lourde et incompressible. C'est pourquoi la planification de l'oxygène doit être conçue avec l'implantation des camps et les effectifs — ce n'est pas une question de matériel isolée.",

    "q.m20#10.p" to "Pourquoi l'oxygène doit-il être stocké au camp haut à l'avance ?",
    "q.m20#10.o0" to "Pour alléger le jour du sommet et garantir que l'oxygène est disponible à ce moment-là",
    "q.m20#10.o1" to "Pour éviter le vol",
    "q.m20#10.o2" to "Parce qu'il fait plus froid là-haut",
    "q.m20#10.o3" to "Pour économiser de l'argent",
    "q.m20#10.e" to "Le jour du sommet est celui où vous êtes le plus sollicité et le moins en forme ; vous ne pouvez pas aussi monter l'oxygène. Il doit donc être acheminé par portages successifs à l'avance — ce qui lie quantité d'oxygène, effectifs et fenêtre météo dès la planification.",

    "q.m20#11.p" to "Que faire si le système d'oxygène tombe en panne en route ?",
    "q.m20#11.o0" to "Continuer à monter et le réparer à la maison",
    "q.m20#11.o1" to "Évaluer immédiatement l'oxygène restant et son altitude, puis suivre le plan : descendre ou passer au système de secours",
    "q.m20#11.o2" to "Augmenter le débit pour essayer de le réparer",
    "q.m20#11.o3" to "Le démonter et le réparer",
    "q.m20#11.e" to "Une panne d'oxygène signifie que vous vous retrouvez soudain dans les conditions d'une altitude plus élevée, sans protection. La traiter passe avant tout le reste : décidez d'abord si le secours permet de continuer, sinon descendez. À 8 000 m, redescendre est un choix sensé, pas un échec.",

    "q.m20#12.p" to "[Ordre] Quelle est la séquence de contrôle du système d'oxygène le jour du sommet ?",
    "q.m20#12.o0" to "Confirmer la pression de la bouteille et l'autonomie estimée",
    "q.m20#12.o1" to "Vérifier le détendeur, le tuyau et le masque ou les lunettes nasales",
    "q.m20#12.o2" to "Ouvrir le débit et confirmer que le gaz passe réellement",
    "q.m20#12.o3" to "Noter ce qui reste et informer les compagnons et les personnes restées à la maison",
    "q.m20#12.e" to "Les trois premiers sont des contrôles techniques, le quatrième est de la communication d'équipe — et ce dernier compte particulièrement en altitude : si vos compagnons connaissent votre marge d'oxygène, ils peuvent repérer un déclin chez vous avant vous.",

    "q.m20#13.p" to "Pourquoi l'oxygène ne peut-il pas remplacer l'acclimatation ?",
    "q.m20#13.o0" to "Parce que l'oxygène coûte trop cher",
    "q.m20#13.o1" to "Parce que l'acclimatation est la compensation physiologique du corps lui-même, alors que l'oxygène ne fait qu'élever la concentration inspirée",
    "q.m20#13.o2" to "Parce que l'oxygène cesse de fonctionner",
    "q.m20#13.o3" to "Parce que l'oxygène n'aide que contre le mal d'altitude",
    "q.m20#13.e" to "L'acclimatation change la façon dont le corps utilise l'oxygène ; l'oxygène change la quantité qui entre. On ne peut pas obtenir la première avec le second. La descente, l'ascension progressive et un temps d'acclimatation suffisant restent donc des prérequis non négociables à 8 000 m.",

    "q.m20#14.p" to "[Choix multiple] Quelles sont les défaillances courantes d'un système d'oxygène ?",
    "q.m20#14.o0" to "Givre ou bouchage au niveau du raccord",
    "q.m20#14.o1" to "Fuites de tuyau",
    "q.m20#14.o2" to "Défauts de détendeur donnant un débit inexact",
    "q.m20#14.o3" to "Difficulté à ouvrir le robinet de bouteille",
    "q.m20#14.o4" to "Une bouteille plus lourde que prévu",
    "q.m20#14.e" to "Les quatre premières tiennent au froid, au givre et à la manipulation malaisée — et toutes surviennent en altitude, dans la fatigue, au moment où elles sont le plus difficiles à gérer. C'est pourquoi un système de secours ne suffit pas ; il faut aussi un plan de décision en cas de panne.",

    "q.m20#15.p" to "Pourquoi le plan d'oxygène doit-il figurer dans l'itinéraire ?",
    "q.m20#15.o0" to "Pour l'apparence",
    "q.m20#15.o1" to "Parce que la quantité d'oxygène détermine directement l'heure de demi-tour réalisable et la durée maximale de séjour",
    "q.m20#15.o2" to "Pour noter les dépenses",
    "q.m20#15.o3" to "Pour faciliter le remboursement",
    "q.m20#15.e" to "L'oxygène n'est pas « on en prend un peu et ça va » — c'est un budget chiffré : combien de bouteilles, à quel débit, pendant combien d'heures. Ces chiffres fixent ensuite l'heure de demi-tour : ils doivent donc être planifiés avec le programme, pas sur une liste séparée.",

    "q.m20#16.p" to "Complétez : le débit typique en course est d'environ 2 à ( ) L/min.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "quatre",
    "q.m20#16.e" to "2–4 L/min. Cette plage est l'équilibre entre maintenir une oxygénation sanguine suffisante et économiser le gaz. Gérer l'oxygène est finalement un problème continu d'allocation de ressources.",

    "q.m20#17.p" to "Que faire si l'oxygène d'un compagnon commence à manquer ?",
    "q.m20#17.o0" to "Continuer vers le sommet ; chacun pour soi",
    "q.m20#17.o1" to "Partager immédiatement l'information et les quantités restantes, puis suivre le plan : descendre ensemble ou redistribuer l'oxygène",
    "q.m20#17.o2" to "Le laisser se débrouiller",
    "q.m20#17.o3" to "Lui donner tout son propre oxygène",
    "q.m20#17.e" to "Un manque est un événement d'équipe, pas individuel : il affecte la vitesse de descente et la couverture mutuelle. Les pires options sont les deux extrêmes — continuer vers le sommet, ou renoncer entièrement à sa propre réserve. La réponse sensée est de redistribuer les ressources et de prioriser la descente de tous.",

    "q.m20#18.p" to "Une bouteille utilisable contient 1 200 litres. À un débit de 3 L/min, combien de minutes durera-t-elle environ ?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "Environ 400 minutes (à peu près 6,7 heures) : 1200 ÷ 3 = 400. Ce type de calcul compte directement le jour du sommet — il détermine combien de temps vous pouvez rester à 8 000 m, et donc l'heure à laquelle il faut fixer le demi-tour.",

    "q.m20#19.p" to "Plan de sommet : 5 heures à la montée, 3 heures à la descente, débit 2 L/min, plus 60 minutes de réserve d'urgence. Quel volume total d'oxygène faut-il, en litres ?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 litres : (5 + 3) heures × 60 min × 2 L/min = 960 litres, plus 60 × 2 = 120 litres de réserve, soit 1080 au total. Calculer montée, descente et réserve comme trois parties séparées est la discipline la plus élémentaire de la planification d'oxygène — ne vérifier que « s'il y en a assez pour monter » est l'erreur la plus courante.",
    // ---------- m21 Panorama des 8 000 m ----------
    "q.m21#0.p" to "Combien de sommets de plus de 8 000 m existe-t-il dans le monde ?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Quatorze, tous situés dans l'Himalaya et le Karakoram. Ce nombre est à l'origine de l'objectif alpiniste connu sous le nom des « quatorze 8 000 ».",

    "q.m21#1.p" to "Quels pays abritent les quatorze 8 000 ?",
    "q.m21#1.o0" to "Chine, Népal, Inde, Pakistan",
    "q.m21#1.o1" to "Chine, Népal, Bhoutan, Inde",
    "q.m21#1.o2" to "Népal, Pakistan, Afghanistan, Tadjikistan",
    "q.m21#1.o3" to "Chine, Inde, Pakistan, Myanmar",
    "q.m21#1.e" to "Quatre pays : Chine, Népal, Inde et Pakistan. Comprendre cette répartition compte — elle détermine les permis, la logistique, les secours et le risque politique, qui font tous partie de la planification à 8 000 m.",

    "q.m21#2.p" to "Quelle est l'altitude de l'Everest ?",
    "q.m21#2.o0" to "8 611 m",
    "q.m21#2.o1" to "8 848 m",
    "q.m21#2.o2" to "8 586 m",
    "q.m21#2.o3" to "8 516 m",
    "q.m21#2.e" to "8 848 m (le relevé conjoint Chine–Népal de 2020 donne 8 848,86 m). Étant le plus haut du monde, il a aussi l'infrastructure commerciale la plus développée — mais mature signifie logistique et itinéraires matures, pas risque faible : la congestion, le coût et la difficulté à juger correctement sont aussi de vrais dangers.",

    "q.m21#3.p" to "Quelle est la place de l'Annapurna I dans l'histoire des 8 000 ?",
    "q.m21#3.o0" to "Le dernier gravi",
    "q.m21#3.o1" to "Le premier 8 000 jamais gravi",
    "q.m21#3.o2" to "Le taux de mortalité le plus bas",
    "q.m21#3.o3" to "Le plus facile à gravir",
    "q.m21#3.e" to "L'Annapurna I culmine à 8 091 m et a été gravi pour la première fois en 1950 — le premier 8 000 de l'histoire humaine. Son taux de mortalité figure depuis longtemps parmi les plus élevés. Être gravi en premier n'a rien à voir avec être facile.",

    "q.m21#4.p" to "Qu'est-ce qui distingue le Shishapangma ?",
    "q.m21#4.o0" to "Il se trouve au Népal",
    "q.m21#4.o1" to "C'est le seul 8 000 entièrement situé en Chine, et le dernier des quatorze à avoir été gravi",
    "q.m21#4.o2" to "C'est le plus haut",
    "q.m21#4.o3" to "C'est le plus facile",
    "q.m21#4.e" to "Le Shishapangma culmine à 8 027 m au Tibet : c'est le seul 8 000 entièrement situé en Chine ; il a été gravi pour la première fois en 1964 par une cordée chinoise et il est le dernier des quatorze à avoir été conquis.",

    "q.m21#5.p" to "Quel est le rapport entre le Lhotse et l'Everest ?",
    "q.m21#5.o0" to "Ils sont très éloignés",
    "q.m21#5.o1" to "Le Lhotse est contigu à l'Everest et partage souvent le même itinéraire d'approche",
    "q.m21#5.o2" to "Le Lhotse est plus haut que l'Everest",
    "q.m21#5.o3" to "Ils sont dans des chaînes différentes",
    "q.m21#5.e" to "Le Lhotse culmine à 8 516 m, juste à côté de l'Everest, et depuis le sud les deux partagent la majeure partie de l'itinéraire et des camps. C'est pourquoi ils sont souvent envisagés dans un même programme pour la logistique et l'acclimatation.",

    "q.m21#6.p" to "Quelle est l'évaluation habituelle du Cho Oyu ?",
    "q.m21#6.o0" to "Le 8 000 le plus technique",
    "q.m21#6.o1" to "Généralement considéré comme l'un des 8 000 les moins techniques",
    "q.m21#6.o2" to "Le 8 000 au taux de mortalité le plus élevé",
    "q.m21#6.o3" to "Aucune expédition commerciale ne le gravit",
    "q.m21#6.e" to "Le Cho Oyu culmine à 8 188 m et, avec un itinéraire relativement doux et une logistique mature, est souvent regardé comme l'un des 8 000 les moins techniques. Mais « relativement facile » signifie encore opérer plusieurs jours en zone de la mort — l'ampleur ne doit pas être sous-estimée.",

    "q.m21#7.p" to "Pour quoi le Nanga Parbat est-il connu ?",
    "q.m21#7.o0" to "Des itinéraires doux",
    "q.m21#7.o1" to "Un relief vertical énorme et un risque d'avalanche sévère",
    "q.m21#7.o2" to "Les permis les moins chers",
    "q.m21#7.o3" to "La meilleure logistique",
    "q.m21#7.e" to "Le Nanga Parbat culmine à 8 126 m et est surnommé la « Montagne nue » — il s'élève d'un seul jet sur une hauteur immense depuis la vallée, avec un risque marqué d'avalanches et de chutes de pierres. Son coût historique en vies humaines est élevé, même pour un 8 000.",

    "q.m21#8.p" to "[Association] Associez chaque sommet à son altitude.",
    "q.m21#8.l0" to "Everest",
    "q.m21#8.r0" to "8 848 m",
    "q.m21#8.l1" to "Kangchenjunga",
    "q.m21#8.r1" to "8 586 m",
    "q.m21#8.l2" to "Lhotse",
    "q.m21#8.r2" to "8 516 m",
    "q.m21#8.l3" to "Makalu",
    "q.m21#8.r3" to "8 485 m",
    "q.m21#8.e" to "Ce sont les premier, troisième, quatrième et cinquième sommets du monde. N'apprenez pas seulement les chiffres — retenez l'ordre et la chaîne de chacun. Les chiffres se consultent ; la vue d'ensemble doit être dans la tête.",

    "q.m21#9.p" to "Pourquoi « les quatorze » sont-ils devenus un objectif alpiniste reconnu ?",
    "q.m21#9.o0" to "Parce que c'est un chiffre rond",
    "q.m21#9.o1" to "Parce qu'ils forment par hasard une frontière complète de l'alpinisme de haute altitude, et que leur nombre reste atteignable en une vie",
    "q.m21#9.o2" to "Parce que des entreprises l'ont promu",
    "q.m21#9.o3" to "Parce que l'UIAA l'impose",
    "q.m21#9.e" to "Ce qui distingue les quatorze, c'est qu'ils ont une frontière objective et sans ambiguïté (au-dessus de 8 000 m), un nombre fini, et qu'on peut les énumérer un par un. Cela rend l'objectif à la fois clair et valable pour une vie — d'où son statut de référence.",

    "q.m21#10.p" to "[Choix multiple] Que faut-il normalement pour atteindre le sommet d'un 8 000 ?",
    "q.m21#10.o0" to "Un cycle d'acclimatation complet avec des rotations par les camps hauts",
    "q.m21#10.o1" to "Des compétences techniques et une expérience de progression glaciaire",
    "q.m21#10.o2" to "Un système fiable d'oxygène et de logistique",
    "q.m21#10.o3" to "Une condition physique et un jugement validés à 7 000 m",
    "q.m21#10.o4" to "Une équipe de tournage professionnelle",
    "q.m21#10.e" to "Les quatre premiers correspondent à quatre dimensions : physiologique (acclimatation), technique, logistique et expérience accumulée. Toutes agissent en même temps à 8 000 m — s'il en manque une, elle devient le maillon faible, et les maillons faibles sont vite amplifiés en altitude.",

    "q.m21#11.p" to "Le Dhaulagiri, le Manaslu et l'Annapurna se trouvent tous dans quel pays ?",
    "q.m21#11.o0" to "Chine",
    "q.m21#11.o1" to "Népal",
    "q.m21#11.o2" to "Pakistan",
    "q.m21#11.o3" to "Inde",
    "q.m21#11.e" to "Les trois sont au Népal. Le Népal détient le plus grand nombre de 8 000, ce qui explique le développement de son industrie de l'ascension — et aussi la pression persistante sur les permis, la gestion et la protection de l'environnement.",

    "q.m21#12.p" to "Pourquoi les « itinéraires commerciaux matures » d'un 8 000 restent-ils dangereux ?",
    "q.m21#12.o0" to "Parce qu'ils sont chers",
    "q.m21#12.o1" to "Parce que l'altitude elle-même ne peut pas être changée, et que la congestion, l'attente et des secours difficiles créent de nouveaux risques",
    "q.m21#12.o2" to "Parce que les guides ne sont pas professionnels",
    "q.m21#12.o3" to "Parce que le matériel est médiocre",
    "q.m21#12.e" to "La commercialisation résout la logistique et la connaissance de l'itinéraire, mais elle ne peut pas abaisser l'altitude. Au contraire, beaucoup de cordées parties dans la même fenêtre créent des files d'attente — et attendre à 8 000 m signifie brûler de l'oxygène et de la chaleur corporelle en plus.",

    "q.m21#13.p" to "[Ordre] Classez ces sommets du plus haut au plus bas.",
    "q.m21#13.o0" to "Everest (8 848)",
    "q.m21#13.o1" to "Kangchenjunga (8 586)",
    "q.m21#13.o2" to "Makalu (8 485)",
    "q.m21#13.o3" to "Annapurna I (8 091)",
    "q.m21#13.e" to "Derrière cet ordre se cache l'écart entre le numéro un et le numéro dix mondial. Retenir l'ordre est plus utile que retenir les chiffres exacts — quand on discute d'itinéraires, de logistique et de difficulté, on a surtout besoin de la position relative.",

    "q.m21#14.p" to "Pourquoi étudier l'histoire des premières ascensions quand on apprend les 8 000 ?",
    "q.m21#14.o0" to "Pour les examens",
    "q.m21#14.o1" to "Parce que les premières ascensions ont tendance à révéler les difficultés centrales et les types de risque d'un sommet",
    "q.m21#14.o2" to "Pour mémoriser des noms",
    "q.m21#14.o3" to "Cela n'a aucun rapport avec l'alpinisme",
    "q.m21#14.e" to "Les échecs et les pertes des premières cordées pointent précisément les difficultés principales d'un sommet — sections d'avalanche récurrentes, sections de vent violent, passages exposés. Lire l'histoire des premières ascensions comme un dossier de risque est bien plus utile que la lire comme un récit.",

    "q.m21#15.p" to "[Choix multiple] Lesquels de ces sommets sont des 8 000 de l'Himalaya ?",
    "q.m21#15.o0" to "Everest",
    "q.m21#15.o1" to "Annapurna I",
    "q.m21#15.o2" to "Shishapangma",
    "q.m21#15.o3" to "K2",
    "q.m21#15.e" to "Les trois premiers sont dans l'Himalaya ; le K2 est dans le Karakoram. Les deux chaînes sont géographiquement voisines mais géologiquement distinctes, et leurs saisons d'ascension et régimes météo diffèrent — d'où l'habitude de présenter les quatorze groupés par chaîne.",

    "q.m21#16.p" to "Comment le titre de « plus haut sommet du monde » influence-t-il la stratégie ?",
    "q.m21#16.o0" to "Pas du tout",
    "q.m21#16.o1" to "Il implique la plus grande attention médiatique et commerciale, donc la plus forte densité de cordées et le plus grand risque de congestion",
    "q.m21#16.o2" to "Il signifie l'itinéraire le plus facile",
    "q.m21#16.o3" to "Il signifie les secours les plus faciles",
    "q.m21#16.e" to "L'attention apporte des ressources et aussi de la foule. Quand un grand nombre de cordées se concentre dans une fenêtre, l'attente, la congestion et la pression psychologique de ne pas vouloir céder sa place dans la file deviennent des sources supplémentaires de risque — un problème stratégique propre au plus haut sommet.",

    "q.m21#17.p" to "Complétez : dans le monde, il y a ( ) sommets de plus de 8 000 m.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "quatorze",
    "q.m21#17.e" to "Quatorze. Un petit nombre, qui définit pourtant toute la frontière de l'alpinisme de haute altitude — c'est pourquoi « les quatorze » reste traité comme un objectif qui vaut une vie.",
    // ---------- m22 Karakoram et hiérarchie des 8 000 ----------
    "q.m22#0.p" to "Combien de 8 000 compte le Karakoram ?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Quatre : K2, Gasherbrum I, Gasherbrum II et Broad Peak. On les connaît aussi comme K2, K4, K5 et K3 — le K signifie Karakoram.",

    "q.m22#1.p" to "Quelles sont l'altitude et la place du K2 ?",
    "q.m22#1.o0" to "8 611 m, deuxième du monde, et parmi les 8 000 les plus techniques et les plus meurtriers",
    "q.m22#1.o1" to "8 848 m, le plus haut du monde",
    "q.m22#1.o2" to "8 586 m, troisième du monde",
    "q.m22#1.o3" to "8 051 m, l'un des plus faciles",
    "q.m22#1.e" to "Le K2 culmine à 8 611 m, deuxième du monde. Il est largement considéré comme l'un des 8 000 les plus durs et les plus dangereux, d'où son surnom de « montagne des alpinistes » — ici la technique et le jugement pèsent bien plus que le soutien logistique.",

    "q.m22#2.p" to "Pourquoi le Karakoram et l'Himalaya ont-ils souvent des saisons d'ascension différentes ?",
    "q.m22#2.o0" to "À cause de latitudes et longitudes différentes",
    "q.m22#2.o1" to "Parce qu'ils subissent des systèmes climatiques différents : le Karakoram est plus fortement influencé par les vents d'ouest",
    "q.m22#2.o2" to "À cause d'altitudes différentes",
    "q.m22#2.o3" to "À cause de réglementations différentes",
    "q.m22#2.e" to "La meilleure saison de l'Himalaya est pilotée surtout par le cycle de la mousson, tandis que le Karakoram est plus affecté par les vents d'ouest et les précipitations orographiques. Cela décide du moment où partir — et en choisissant la mauvaise saison, même la meilleure cordée ne verra jamais de fenêtre de sommet.",

    "q.m22#3.p" to "Comment appelle-t-on aussi le Broad Peak ?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "Le Broad Peak est aussi le K3, à 8 051 m. Son terrain est relativement ouvert, mais les chutes de neige sont abondantes et les vents forts fréquents — historiquement, il a connu plusieurs accidents après avoir été sous-estimé.",

    "q.m22#4.p" to "Comment appelle-t-on aussi le Gasherbrum I et le Gasherbrum II ?",
    "q.m22#4.o0" to "K4 et K5",
    "q.m22#4.o1" to "K5 et K4",
    "q.m22#4.o2" to "K2 et K3",
    "q.m22#4.o3" to "K3 et K4",
    "q.m22#4.e" to "Le Gasherbrum I est le K5 (8 080 m) et le Gasherbrum II le K4 (8 035 m) — la numérotation ne suit pas l'ordre des altitudes, et c'est exactement ce qui la rend déroutante. Retenez que les numéros K ne sont pas classés par hauteur et vous ne vous tromperez plus.",

    "q.m22#5.p" to "Les quatorze 8 000 se trouvent tous dans quelles deux chaînes ?",
    "q.m22#5.o0" to "Himalaya et Tian Shan",
    "q.m22#5.o1" to "Himalaya et Karakoram",
    "q.m22#5.o2" to "Karakoram et Alpes",
    "q.m22#5.o3" to "Nyainqêntanglha et Himalaya",
    "q.m22#5.e" to "Tous se trouvent dans l'Himalaya et le Karakoram — deux chaînes géographiquement voisines soumises à des systèmes climatiques différents. Ce qui montre encore qu'à 8 000 m, la géographie est elle-même une information clé.",

    "q.m22#6.p" to "[Association] Associez chaque sommet à son altitude.",
    "q.m22#6.l0" to "K2",
    "q.m22#6.r0" to "8 611 m",
    "q.m22#6.l1" to "Nanga Parbat",
    "q.m22#6.r1" to "8 126 m",
    "q.m22#6.l2" to "Gasherbrum I",
    "q.m22#6.r2" to "8 080 m",
    "q.m22#6.l3" to "Shishapangma",
    "q.m22#6.r3" to "8 027 m",
    "q.m22#6.e" to "Ce sont les deuxième, neuvième, onzième et quatorzième sommets du monde. Ils couvrent une large plage et partagent pourtant le même statut dans « au-dessus de 8 000 m » — c'est précisément ce qui fait la particularité de cette classe : une frontière nette avec une énorme variation interne.",

    "q.m22#7.p" to "Quelle est la bonne vision du rapport entre classement des 8 000 et difficulté ?",
    "q.m22#7.o0" to "Plus haut signifie toujours plus dur",
    "q.m22#7.o1" to "La difficulté est fixée surtout par le terrain technique, le climat et la logistique, et ne correspond pas directement au classement par altitude",
    "q.m22#7.o2" to "Plus bas signifie toujours plus facile",
    "q.m22#7.o3" to "La difficulté ne peut pas du tout être comparée",
    "q.m22#7.e" to "C'est l'enseignement le plus important de la vue d'ensemble des quatorze : le Cho Oyu à 8 188 m est considéré comme relativement facile, tandis que le K2 à 8 611 m est parmi les plus durs — moins de 500 m d'écart d'altitude, et un seuil réel à des années-lumière.",

    "q.m22#8.p" to "[Choix multiple] Qu'est-ce qui détermine la difficulté réelle d'un 8 000 ?",
    "q.m22#8.o0" to "Le terrain technique et l'exposition",
    "q.m22#8.o1" to "Le climat et les fenêtres météo",
    "q.m22#8.o2" to "La logistique et l'approche",
    "q.m22#8.o3" to "La faisabilité des secours",
    "q.m22#8.o4" to "Le classement du sommet par altitude",
    "q.m22#8.e" to "Les quatre premiers comptent. La faisabilité des secours est particulièrement souvent ignorée : une montagne où le secours est presque impossible présente un niveau de risque totalement différent même si l'itinéraire n'est pas dur, car il n'y a aucun filet quand quelque chose va mal.",

    "q.m22#9.p" to "[Ordre] Classez ces sommets du plus haut au plus bas.",
    "q.m22#9.o0" to "K2 (8 611)",
    "q.m22#9.o1" to "Nanga Parbat (8 126)",
    "q.m22#9.o2" to "Gasherbrum I (8 080)",
    "q.m22#9.o3" to "Shishapangma (8 027)",
    "q.m22#9.e" to "Cet ordre couvre la seconde moitié des quatorze. Combiné à l'ordre de la leçon précédente, vous avez maintenant la séquence complète des altitudes — la base pour juger à quel palier appartient une montagne donnée.",

    "q.m22#10.p" to "Pourquoi « les quatorze » sont-ils un objectif si exigeant ?",
    "q.m22#10.o0" to "Parce que c'est extrêmement cher",
    "q.m22#10.o1" to "Parce qu'il faut maintenir technique, condition physique, acclimatation et jugement sur de nombreuses années, à travers des systèmes logistiques de plusieurs pays",
    "q.m22#10.o2" to "Parce que cela prend trop de temps",
    "q.m22#10.o3" to "Parce que les permis sont difficiles à obtenir",
    "q.m22#10.e" to "Les quatorze prennent souvent plus d'une décennie, pendant laquelle le corps vieillit et les circonstances de vie changent. Cela teste non seulement la capacité d'escalade mais la constance de l'entretien à long terme et de la gestion du risque.",

    "q.m22#11.p" to "Pourquoi la réussite à 8 000 m dépend-elle souvent de la fenêtre météo plutôt que de la technique ?",
    "q.m22#11.o0" to "Parce que la technique n'a pas d'importance",
    "q.m22#11.o1" to "Parce que même avec une technique suffisante, attendre longtemps en altitude consomme votre marge de sécurité",
    "q.m22#11.o2" to "Parce que la technique peut s'apprendre sur la montagne",
    "q.m22#11.o3" to "Parce que les guides s'occupent de tout",
    "q.m22#11.e" to "C'est la réalité à 8 000 m : la technique n'est que le ticket d'entrée, tandis que la fenêtre décide si vous pouvez passer pendant qu'il vous reste des capacités. C'est pourquoi les itinéraires à 8 000 m prévoient généralement des jours de réserve généreux.",

    "q.m22#12.p" to "Si vous ne pouviez choisir qu'un seul 8 000 comme premier, quelle est l'approche la plus sensée ?",
    "q.m22#12.o0" to "Foncer sur le K2 et en finir",
    "q.m22#12.o1" to "En choisir un avec un itinéraire mature, une logistique fiable et des secours possibles, et employer sa « première fois » à accumuler de l'expérience",
    "q.m22#12.o2" to "Prendre simplement le plus bas",
    "q.m22#12.o3" to "Prendre n'importe lequel ; ils se valent",
    "q.m22#12.e" to "La valeur d'un premier 8 000 est d'apprendre son état réel en zone de la mort : comment on utilise l'oxygène, de combien le jugement baisse, quel est son rythme. Le dépenser sur une montagne plus dure revient à tester plusieurs inconnues à la fois.",

    "q.m22#13.p" to "[Choix multiple] Lesquels de ces sommets sont des 8 000 du Karakoram ?",
    "q.m22#13.o0" to "K2",
    "q.m22#13.o1" to "Gasherbrum I",
    "q.m22#13.o2" to "Gasherbrum II",
    "q.m22#13.o3" to "Broad Peak",
    "q.m22#13.o4" to "Manaslu",
    "q.m22#13.e" to "Les quatre premiers sont du Karakoram — ce sont d'ailleurs tous les 8 000 de cette chaîne. « Les quatre du Karakoram » est donc une formule fixe, et avec les dix de l'Himalaya cela fait exactement quatorze.",

    "q.m22#14.p" to "Quel est le bénéfice le plus pratique d'étudier les quatorze dans leur ensemble ?",
    "q.m22#14.o0" to "Pouvoir réciter toutes les altitudes",
    "q.m22#14.o1" to "Comprendre pourquoi difficulté et altitude ne sont pas la même chose, et s'en servir pour évaluer ses propres objectifs",
    "q.m22#14.o2" to "Pouvoir guider les autres",
    "q.m22#14.o3" to "Pouvoir écrire des topos",
    "q.m22#14.e" to "La vraie valeur est de construire une vision multidimensionnelle de la difficulté : technique, climat, logistique et secours déterminent ensemble le seuil réel d'une montagne. Le même cadre s'applique au choix parmi les 5 000 m et les 6 000 m.",

    "q.m22#15.p" to "Pourquoi l'approche d'un 8 000 peut-elle être en soi un facteur de risque ?",
    "q.m22#15.o0" to "Parce qu'elle prend longtemps",
    "q.m22#15.o1" to "Parce que l'approche traverse souvent glaciers et terrain avalancheux alors que la cordée n'est pas encore acclimatée",
    "q.m22#15.o2" to "Parce que le paysage est médiocre",
    "q.m22#15.o3" to "Parce qu'elle exige des permis",
    "q.m22#15.e" to "L'approche a généralement lieu pendant la phase de montée, quand l'acclimatation est la plus faible et le jugement le moins stable, tout en composant avec crevasses et terrain avalancheux. C'est cette période doublement vulnérable où surviennent beaucoup d'accidents.",

    "q.m22#16.p" to "Si vous construisiez votre propre liste d'objectifs 8 000, que faudrait-il déterminer d'abord ?",
    "q.m22#16.o0" to "Les noms des montagnes que vous voulez",
    "q.m22#16.o1" to "Vos propres points faibles (technique, acclimatation, jugement ou expérience logistique), puis choisir des sommets qui les traitent",
    "q.m22#16.o2" to "Le budget",
    "q.m22#16.o3" to "La durée de vos congés",
    "q.m22#16.e" to "Choisir par point faible traite les 8 000 comme un chemin de progression plutôt que comme une collection de trophées. La même montagne vaut des choses différentes selon les personnes — selon lequel de vos manques elle comble.",
    // ---------- m23 Mise en situation globale ----------
    "q.m23#0.p" to "[Situation] À 4 500 m, un compagnon a mal à la tête et des nausées et insiste : « encore un jour d'acclimatation et je pourrai monter ». Du point de vue de la science de l'environnement, quel est le bon jugement ?",
    "q.m23#0.o0" to "Un jour de plus réglera sûrement le problème — l'encourager à continuer",
    "q.m23#0.o1" to "Les symptômes signifient que la compensation est insuffisante ; ne pas continuer à monter tant que les symptômes persistent",
    "q.m23#0.o2" to "Donner un médicament et continuer à monter",
    "q.m23#0.o3" to "Redescendre de 100 m suffit",
    "q.m23#0.e" to "La chaîne part de la causalité la plus élémentaire : basse pression → faible pression partielle d'oxygène → le corps a besoin de temps. Les symptômes sont le signal que ce temps est insuffisant, et un jour de plus ne garantit pas d'amélioration — le bon geste est donc d'arrêter de monter, pas de parier sur demain.",

    "q.m23#1.p" to "[Choix multiple] Un membre de la cordée s'apprête à attaquer une pente de neige dure à 5 000 m. Quels éléments faut-il confirmer ?",
    "q.m23#1.o0" to "Des crampons strictement adaptés aux chaussures",
    "q.m23#1.o1" to "Un piolet dimensionné à sa taille",
    "q.m23#1.o2" to "Des lunettes de glacier UV400 et une crème solaire à indice élevé",
    "q.m23#1.o3" to "Une isolation et une coquille conformes au système de couches",
    "q.m23#1.o4" to "Un appareil photo et des batteries de rechange pour les photos de sommet",
    "q.m23#1.e" to "Les quatre premiers correspondent à quatre types de risque : glissade (crampons), arrêt (piolet), UV (lunettes et crème), hypothermie (couches). La bonne façon de vérifier son matériel est de construire la liste à partir des risques, pas de prendre des objets par habitude.",

    "q.m23#2.p" to "[Association] Associez chaque couche du système vestimentaire à son rôle.",
    "q.m23#2.l0" to "Première couche",
    "q.m23#2.r0" to "Évacue la sueur loin de la peau et vous garde au sec",
    "q.m23#2.l1" to "Couche intermédiaire",
    "q.m23#2.r1" to "Emprisonne une couche d'air pour la chaleur (la polaire isole même mouillée)",
    "q.m23#2.l2" to "Coquille",
    "q.m23#2.r2" to "Imperméable, coupe-vent et respirante ; vous protège des intempéries",
    "q.m23#2.l3" to "Couche en duvet (par grand froid)",
    "q.m23#2.r3" to "La chaleur la plus efficace en environnement sec",
    "q.m23#2.e" to "Chaque couche fait un travail. Une fois cette division vue, on comprend pourquoi « plus de couches, plus chaud » est faux : sautez la couche qui évacue l'humidité et vous portez votre propre microclimat humide, tandis qu'une coquille non respirante emprisonne la vapeur de sueur à l'intérieur.",

    "q.m23#3.p" to "[Situation] À la montée d'une pente de neige, la personne devant taille des marches irrégulières. Quelle est la conséquence la plus probable ?",
    "q.m23#3.o0" to "La cordée avance plus vite",
    "q.m23#3.o1" to "Ceux qui suivent doivent sans cesse réajuster leur équilibre, dépensent plus d'énergie et perdent en stabilité",
    "q.m23#3.o2" to "La pente va s'effondrer",
    "q.m23#3.o3" to "Aucun effet",
    "q.m23#3.e" to "Les marches sont la fondation de la cordée. Des marches irrégulières obligent chacun à chercher sans cesse un appui, en plus de la capacité d'équilibre déjà rare en altitude — le cas d'école de petits problèmes qui s'accumulent en risque majeur.",

    "q.m23#4.p" to "[Ordre] Remettez dans le bon ordre la séquence d'auto-arrêt au piolet.",
    "q.m23#4.o0" to "Saisir fermement le piolet en confirmant que la prise est correcte",
    "q.m23#4.o1" to "Se retourner sur le ventre, face à la neige",
    "q.m23#4.o2" to "Enfoncer la pointe dans la neige en utilisant le poids du corps",
    "q.m23#4.o3" to "Lever les pieds pour que les crampons n'accrochent pas et ne vous fassent pas basculer",
    "q.m23#4.e" to "Cette séquence est la fondation de tout le système technique. Elle doit s'exécuter sans réflexion — en cas de chute réelle, votre capacité de pensée dispose d'une ou deux secondes, et ces deux secondes sont entièrement occupées par la mémoire musculaire.",

    "q.m23#5.p" to "[Situation] Un alpiniste chute sur une pente de neige dure et l'arrêt échoue. Quelle est la cause la plus probable au débriefing ?",
    "q.m23#5.o0" to "Le piolet était trop court",
    "q.m23#5.o1" to "La pointe n'a pas pu mordre dans la neige dure — et une pente de neige dure aurait dû être protégée par une corde fixe",
    "q.m23#5.o2" to "Les chaussures n'étaient pas les bonnes",
    "q.m23#5.o3" to "Ils ne portaient pas de gants",
    "q.m23#5.e" to "La réussite de l'arrêt chute nettement sur neige dure et sur glace ; c'est la limite de la technique elle-même. La vraie question est donc généralement en amont — pourquoi étions-nous sur une pente de neige dure raide sans aucun système de protection ?",

    "q.m23#6.p" to "[Choix multiple] Quels risques sont facilement négligés à la descente ?",
    "q.m23#6.o0" to "Une condition physique qui baisse et affaiblit le contrôle des jambes",
    "q.m23#6.o1" to "Une vigilance qui chute une fois l'objectif atteint",
    "q.m23#6.o2" to "Une surface qui gèle ou ramollit, donc des conditions différentes de la montée",
    "q.m23#6.o3" to "Une lumière qui baisse, réduisant la visibilité et le jugement",
    "q.m23#6.o4" to "Des itinéraires de descente généralement plus courts que ceux de la montée",
    "q.m23#6.e" to "Empilez ces quatre éléments et vous avez l'explication de tant d'accidents à la descente. La descente n'est pas le retour à la maison une fois le travail fait ; c'est un tronçon qui demande son propre plan et porte un risque comparable.",

    "q.m23#7.p" to "[Situation] La valve de votre poche à eau gèle rapidement par le froid. Que faire ?",
    "q.m23#7.o0" to "Passer à une gourde isotherme à large ouverture, et souffler l'eau en arrière ou la ranger retournée après chaque boisson",
    "q.m23#7.o1" to "Continuer à s'en servir en attendant que ça dégèle",
    "q.m23#7.o2" to "Porter la poche à l'extérieur du sac",
    "q.m23#7.o3" to "Arrêter de boire",
    "q.m23#7.e" to "Une technique petite mais critique : la déshydratation en altitude n'est généralement pas « je n'avais pas apporté d'eau » mais « l'eau a gelé et je n'ai pas pu boire ». Concevoir un système de boisson qui ne peut pas geler, voilà ce que signifie réellement être préparé à s'hydrater.",

    "q.m23#8.p" to "Complétez : la température baisse d'environ ( ) °C tous les 1 000 m de montée.",
    "q.m23#8.a0" to "6,5",
    "q.m23#8.a1" to "6,5",
    "q.m23#8.e" to "6,5 °C. Ce chiffre traverse tout le cours : il explique la limite des neiges, fixe l'épaisseur nécessaire de votre isolation et détermine l'évolution des conditions d'avalanche et de glace. Le comprendre, c'est pouvoir raisonner avec.",

    "q.m23#9.p" to "[Situation] À 5 000 m, vos lunettes s'embuent fortement et vous ne lisez plus le terrain. Quel est le risque le plus important ?",
    "q.m23#9.o0" to "C'est simplement inconfortable",
    "q.m23#9.o1" to "Vous perdez la base de votre jugement du terrain et pouvez dériver vers une pente raide, une corniche ou un champ de crevasses",
    "q.m23#9.o2" to "Vous allez attraper une cécité des neiges",
    "q.m23#9.o3" to "Vos compagnons vont râler",
    "q.m23#9.e" to "« Ne pas voir » signifie en réalité perdre les preuves sur lesquelles vous jugez. Sur un terrain de neige complexe, un ou deux appuis mal choisis peuvent coûter très cher. « Est-ce que je vois clair » doit donc être traité comme un critère absolu de fiabilité du matériel.",

    "q.m23#10.p" to "[Choix multiple] Un membre de la cordée a une forte perte d'appétit en altitude. Que faut-il faire ?",
    "q.m23#10.o0" to "Manger activement, en petites quantités et souvent, en choisissant des aliments riches en glucides et faciles à digérer",
    "q.m23#10.o1" to "Assurer une hydratation régulière et suffisante",
    "q.m23#10.o2" to "Traiter la perte d'appétit comme un possible signal d'acclimatation à surveiller",
    "q.m23#10.o3" to "Remplacer les repas par de grandes quantités de café et de boissons énergétiques",
    "q.m23#10.e" to "Les trois premiers sont justes ; le quatrième est faux d'une manière très représentative : la caféine donne une sensation temporaire mais ne remplace pas l'énergie. En altitude, un apport énergétique insuffisant affaiblit directement l'acclimatation, ce qui crée un cercle vicieux.",

    "q.m23#11.p" to "[Situation] Sur une pente de neige à 5 000 m, votre téléphone passe de 40 % à l'extinction. Quelle est la réponse la plus sensée ?",
    "q.m23#11.o0" to "Le réchauffer contre son corps, puis le rallumer",
    "q.m23#11.o1" to "Le rallumer sans arrêt",
    "q.m23#11.o2" to "Renoncer à l'électronique",
    "q.m23#11.o3" to "Utiliser le reste de batterie pour envoyer un message de détresse",
    "q.m23#11.e" to "C'est le comportement typique d'une batterie au lithium dans le froid : la capacité s'effondre alors que la charge n'a pas disparu. Le réchauffer contre le corps rétablit généralement l'alimentation. La leçon : gérer l'électronique comme un équipement de sécurité qui peut tomber en panne sans prévenir.",

    "q.m23#12.p" to "[Ordre] Remettez dans un ordre logique un contrôle complet du matériel.",
    "q.m23#12.o0" to "Construire la liste à partir des risques (ce qu'exigent le terrain, la météo et l'altitude)",
    "q.m23#12.o1" to "Vérifier la présence et le bon état de chaque élément",
    "q.m23#12.o2" to "Enfiler et tester en fonctionnement les éléments critiques (crampons, baudrier, casque, lampe frontale)",
    "q.m23#12.o3" to "Noter et annoncer aux compagnons l'état de son matériel et son plan de secours",
    "q.m23#12.e" to "L'étape clé est la troisième, le test en fonctionnement : présent ne signifie pas fonctionnel. Une boucle de crampon mal engagée ou une pile usée dans la lampe frontale ne se révèlent qu'au moment où l'on enfile et utilise le matériel.",

    "q.m23#13.p" to "[Situation] La cordée décide de descendre à cause de la météo, mais un membre insiste pour continuer en arguant « on est venus jusqu'ici ». Quelle est la meilleure façon de gérer ?",
    "q.m23#13.o0" to "Respecter son choix et le laisser continuer seul",
    "q.m23#13.o1" to "Imposer la descente de toute la cordée — la progression en solitaire n'est pas admise en altitude, et l'entêtement là-haut peut être l'hypoxie elle-même",
    "q.m23#13.o2" to "Organiser un vote",
    "q.m23#13.o3" to "Le faire attendre une heure puis décider",
    "q.m23#13.e" to "Deux raisons : la progression en solitaire en altitude est extrêmement risquée, et « on est venus jusqu'ici » est la formulation type du coût irrécupérable — en altitude, cette émotion et la baisse du jugement ont tendance à s'entremêler, elle ne peut donc pas être traitée comme un avis fiable.",

    "q.m23#14.p" to "Sur la question de savoir si les personnes plus en forme sont plus sujettes au mal d'altitude, qu'est-ce qui est correct ?",
    "q.m23#14.o0" to "Plus on est en forme, moins on risque d'en souffrir",
    "q.m23#14.o1" to "Le mal d'altitude n'a pas de rapport direct avec la condition physique ; il dépend de la vitesse d'ascension, de l'altitude de sommeil et de la réponse individuelle",
    "q.m23#14.o2" to "Plus on est en forme, plus on risque d'en souffrir",
    "q.m23#14.o3" to "Seules les personnes peu entraînées en souffrent",
    "q.m23#14.e" to "Confondre condition physique et acclimatation est l'erreur de débutant la plus courante. En réalité, les personnes en forme peuvent rencontrer plus de problèmes précisément parce qu'elles marchent plus vite et montent plus haut — un piège bien réel.",

    "q.m23#15.p" to "[Choix multiple] Quelles pratiques réduisent efficacement le risque de chute ?",
    "q.m23#15.o0" to "S'auto-assurer au piolet en continu pendant la progression",
    "q.m23#15.o1" to "Tenir une allure régulière et soutenable, sans efforts brusques",
    "q.m23#15.o2" to "Progresser au rythme du membre le plus lent",
    "q.m23#15.o3" to "Installer des cordes fixes sur les pentes de neige dure et de glace",
    "q.m23#15.o4" to "Réduire le freinage et descendre plus vite",
    "q.m23#15.e" to "Les quatre premiers correspondent à la technique personnelle, à la gestion de l'allure, à la coordination de la cordée et à la protection par système. La prévention des chutes n'est jamais une action unique mais toute une couche d'assurances empilées.",

    "q.m23#16.p" to "[Situation] Pendant une pause sur une pente de neige, un membre de la cordée laisse son piolet planté dans la neige et s'éloigne. Quel risque cela crée-t-il ?",
    "q.m23#16.o0" to "Le piolet peut être perdu",
    "q.m23#16.o1" to "S'il chute, il n'a aucun outil d'arrêt du tout",
    "q.m23#16.o2" to "Quelqu'un peut marcher dessus",
    "q.m23#16.o3" to "Aucun risque",
    "q.m23#16.e" to "Les chutes surviennent extrêmement vite, et le piolet est votre seul moyen d'arrêt. Le laisser dans la neige revient à renoncer temporairement à cette capacité — et sur une pente de neige, « temporairement » est exactement l'intervalle le plus dangereux.",

    "q.m23#17.p" to "Quelle capacité centrale cette leçon évalue-t-elle ?",
    "q.m23#17.o0" to "Mémoriser tous les chiffres",
    "q.m23#17.o1" to "Combiner les connaissances d'environnement, de matériel, de vêtements et de progression pour juger correctement une situation concrète",
    "q.m23#17.o2" to "Réciter toute la terminologie",
    "q.m23#17.o3" to "Bien connaître les marques de matériel",
    "q.m23#17.e" to "C'est la logique de conception de tout le cours : les faits isolés sont faciles à mémoriser, mais sur la montagne on affronte des problèmes de combinaison. Savoir enchaîner plusieurs connaissances dans une situation concrète, voilà ce que signifie vraiment maîtriser.",
    // ---------- m24 Auto-évaluation finale ----------
    "q.m24#0.p" to "[Situation] Un compagnon est tombé dans une crevasse et votre corps soutient seul son poids. Que faire en premier ?",
    "q.m24#0.o0" to "Commencer à hisser immédiatement",
    "q.m24#0.o1" to "Construire un ancrage et transférer la charge d'abord, puis penser à hisser",
    "q.m24#0.o2" to "Appeler à l'aide d'abord",
    "q.m24#0.o3" to "Prendre une photo pour le rapport",
    "q.m24#0.e" to "Tant que le poids est sur vous, vous n'avez aucune capacité pour manœuvrer le système. Donc ancrage, puis transfert, puis hissage — l'ordre ne peut pas être inversé. C'est la règle la plus pratique de tout le système de sauvetage, et l'étape la plus souvent sautée sous stress.",

    "q.m24#1.p" to "[Association] Associez chaque nœud à son usage.",
    "q.m24#1.l0" to "Nœud de huit",
    "q.m24#1.r0" to "Relier le baudrier à un ancrage",
    "q.m24#1.l1" to "Pêcheur double",
    "q.m24#1.r1" to "Relier deux cordes ou former une boucle de cordelette",
    "q.m24#1.l2" to "Prussik",
    "q.m24#1.r2" to "Nœud de friction, qui mord dans un seul sens",
    "q.m24#1.l3" to "Nœud de chaise",
    "q.m24#1.r3" to "S'attacher à un ancrage ; courant en voile",
    "q.m24#1.e" to "Ces quatre nœuds couvrent l'essentiel de la progression glaciaire et de la protection de base. L'intérêt de les évaluer : il faut savoir les faire dans le noir, avec des gants.",

    "q.m24#2.p" to "[Situation] L'angle des sangles entre deux ancrages approche 100°. Qu'est-ce que cela signifie ?",
    "q.m24#2.o0" to "La charge est mieux répartie",
    "q.m24#2.o1" to "La charge sur chaque ancrage augmente nettement (plus l'angle est ouvert, plus la charge par ancrage est élevée)",
    "q.m24#2.o2" to "Aucun effet",
    "q.m24#2.o3" to "La corde s'équilibre toute seule",
    "q.m24#2.e" to "Les chiffres sont parlants : environ 50 % par ancrage à 0°, environ 58 % à 60°, environ 71 % à 90°. À 100°, chaque ancrage porte énormément — d'où la règle pratique de rester sous 60°.",

    "q.m24#3.p" to "[Choix multiple] Que doit comporter un système d'ancrage correct ?",
    "q.m24#3.o0" to "Chaque placement solide individuellement",
    "q.m24#3.o1" to "Une rupture indépendante entre les placements (pas de fausse redondance)",
    "q.m24#3.o2" to "Une répartition raisonnable de la charge, pré-tendue",
    "q.m24#3.o3" to "Une construction rapide, pour réduire l'exposition",
    "q.m24#3.o4" to "Le moins de placements possible pour économiser le matériel",
    "q.m24#3.e" to "Les trois premiers sont des exigences de sécurité, le quatrième une exigence d'efficacité — et l'efficacité est aussi de la sécurité, car la construction elle-même est du temps d'exposition au risque.",

    "q.m24#4.p" to "[Situation] Un compagnon devient instable sur ses jambes et confus. Quelle est la priorité ?",
    "q.m24#4.o0" to "Donner de l'oxygène et observer",
    "q.m24#4.o1" to "Redescendre immédiatement, et donner de la dexaméthasone sous surveillance médicale",
    "q.m24#4.o2" to "Continuer à monter pour atteindre le camp plus vite",
    "q.m24#4.o3" to "Donner des antalgiques et se reposer",
    "q.m24#4.e" to "L'ataxie et les troubles de la conscience sont les signes centraux de l'OCHA, une urgence médicale. La descente est le seul traitement définitif ; la dexaméthasone ne fait que gagner du temps pour la descente — les deux ne sont pas des alternatives.",

    "q.m24#5.p" to "[Choix multiple] Quelles affirmations sur les médicaments d'altitude sont correctes ?",
    "q.m24#5.o0" to "La dexaméthasone n'agit pas sur l'acclimatation et ne traite pas l'œdème pulmonaire",
    "q.m24#5.o1" to "L'acétazolamide accélère l'acclimatation ; commencer un jour avant l'ascension et arrêter environ deux jours après",
    "q.m24#5.o2" to "La nifédipine peut provoquer une chute rapide de la tension",
    "q.m24#5.o3" to "Un médicament ne peut pas remplacer la descente",
    "q.m24#5.o4" to "L'acétazolamide peut remplacer le processus d'acclimatation du corps",
    "q.m24#5.e" to "Les quatre premiers sont des points clés, et leur conclusion commune est qu'un médicament ne remplace pas la descente : quoi que l'on prenne, la descente reste le traitement fondamental. Les médicaments ne font que créer les conditions pour l'effectuer.",

    "q.m24#6.p" to "[Situation] Un membre de la cordée cesse de frissonner et articule mal. Que ne faut-il PAS faire ?",
    "q.m24#6.o0" to "Changer les vêtements mouillés et l'isoler",
    "q.m24#6.o1" to "Le faire marcher pour produire de la chaleur",
    "q.m24#6.o2" to "Réchauffer le tronc d'abord",
    "q.m24#6.o3" to "Éviter les manipulations rudes",
    "q.m24#6.e" to "« Ne frissonne plus » signifie une hypothermie modérée ou pire, et un cœur froid est très sensible aux arythmies. Faire marcher le patient ou le manipuler rudement peut la déclencher directement — la règle la plus contre-intuitive des premiers secours en hypothermie.",

    "q.m24#7.p" to "[Ordre] Remettez dans l'ordre les quatre étapes d'un sauvetage en cordée.",
    "q.m24#7.o0" to "S'arrêter en auto-arrêt et se stabiliser",
    "q.m24#7.o1" to "Construire un ancrage indépendant",
    "q.m24#7.o2" to "Transférer la charge sur l'ancrage",
    "q.m24#7.o3" to "Hisser avec un système 3:1",
    "q.m24#7.e" to "Ces quatre étapes ne peuvent pas être réordonnées. À un examen, on peut les réciter ; dans la réalité, il faut boucler les trois premières en quelques dizaines de secondes — c'est le vrai seuil de ce point de connaissance.",

    "q.m24#8.p" to "[Situation] La prévision annonce « nuageux » mais vous voyez des cumulus se développer verticalement très vite. Que faire ?",
    "q.m24#8.o0" to "Faire confiance à la prévision et suivre le plan",
    "q.m24#8.o1" to "Décider en supposant que cela peut se dégrader, et envisager de redescendre tôt",
    "q.m24#8.o2" to "Attendre une heure et regarder à nouveau",
    "q.m24#8.o3" to "Continuer à monter mais plus vite",
    "q.m24#8.e" to "Une prévision donne le contexte régional ; le nuage devant vous est une preuve d'ici et maintenant. Quand les deux se contredisent, le terrain l'emporte. D'autant que le développement de cumulus en altitude se compte souvent en minutes.",

    "q.m24#9.p" to "[Choix multiple] Quelles pratiques sont correctes pour traverser un terrain avalancheux ?",
    "q.m24#9.o0" to "Passer une personne à la fois en gardant l'espacement",
    "q.m24#9.o1" to "Poster un guetteur en position sûre",
    "q.m24#9.o2" to "Prévoir à l'avance l'itinéraire de dégagement et le point de regroupement",
    "q.m24#9.o3" to "Faire traverser toute la cordée rapidement et ensemble pour réduire l'exposition",
    "q.m24#9.e" to "Les trois premiers limitent le risque à une personne ; « tous ensemble » l'amplifie à l'échelle de la cordée — d'ensevelir peut-être un à ensevelir peut-être tous, d'où son statut d'option la moins acceptable.",

    "q.m24#10.p" to "[Situation] La cordée est à une heure du sommet mais l'heure de demi-tour est dépassée. Qu'est-ce qui est correct ?",
    "q.m24#10.o0" to "Continuer vers le sommet, ce n'est qu'une heure",
    "q.m24#10.o1" to "Faire demi-tour immédiatement — tout l'intérêt d'une heure de demi-tour est qu'elle fonctionne précisément à « juste un peu plus loin »",
    "q.m24#10.o2" to "La prolonger d'une demi-heure",
    "q.m24#10.o3" to "Laisser le plus en forme continuer",
    "q.m24#10.e" to "Cette question teste en réalité à quoi sert une heure de demi-tour. Si on ne la respecte que quand tout va bien, et qu'on peut l'assouplir à « juste un peu plus loin », alors elle n'a jamais existé — et c'est exactement là que surviennent les accidents.",

    "q.m24#11.p" to "[Choix multiple] Quelles pratiques de décision collective sont correctes en environnement à haut risque ?",
    "q.m24#11.o0" to "Chiffrer les signaux de repli avant le départ",
    "q.m24#11.o1" to "Faire prévaloir l'avis le plus prudent",
    "q.m24#11.o2" to "Provoquer délibérément la contradiction (par exemple en faisant le tour de chacun)",
    "q.m24#11.o3" to "Décider à la majorité",
    "q.m24#11.e" to "Les trois premiers forment ensemble le mécanisme contre l'erreur collective ; la règle majoritaire fait l'inverse — elle étouffe l'inquiétude légitime de la minorité, et c'est souvent cette minorité qui a repéré le signal de danger en premier.",

    "q.m24#12.p" to "[Situation] Les communications sont coupées et vous deviez pointer auprès des personnes restées à la maison il y a une heure. Que faire ?",
    "q.m24#12.o0" to "Continuer comme prévu et attendre le retour du signal",
    "q.m24#12.o1" to "Suivre le plan de perte de contact convenu avant le départ (par exemple attendre au point de rendez-vous)",
    "q.m24#12.o2" to "Se séparer pour chercher du réseau",
    "q.m24#12.o3" to "Faire redescendre tout le monde immédiatement",
    "q.m24#12.e" to "Perdre les communications en montagne est normal, pas accidentel — cela doit donc avoir un plan avant le départ. Avec un plan, la perte de contact est une branche connue ; sans plan, elle devient de la confusion en bas.",

    "q.m24#13.p" to "[Ordre] Remettez dans l'ordre la séquence complète de prise en charge d'une personne gravement blessée.",
    "q.m24#13.o0" to "Sécuriser la scène et éviter un second accident",
    "q.m24#13.o1" to "Évaluer la conscience, la respiration et la circulation ; traiter les menaces vitales",
    "q.m24#13.o2" to "Appeler à l'aide et signaler la localisation exacte et les blessures",
    "q.m24#13.o3" to "Isoler, immobiliser et continuer à surveiller en attendant l'évacuation ou les secours professionnels",
    "q.m24#13.e" to "L'ordre incarne la sécurité d'abord, puis le traitement, l'appel se faisant en parallèle et le maintien ensuite. L'erreur réelle la plus courante est de sauter la première étape et de se précipiter vers la victime — la voie classique vers une seconde victime.",

    "q.m24#14.p" to "[Choix multiple] Quelles compétences d'escalade technique doivent être pratiquées sur le terrain ?",
    "q.m24#14.o0" to "L'auto-arrêt au piolet",
    "q.m24#14.o1" to "Les prussiks et les systèmes de cordée",
    "q.m24#14.o2" to "La construction d'ancrages",
    "q.m24#14.o3" to "La séquence de sauvetage en crevasse",
    "q.m24#14.o4" to "Mémoriser les noms et altitudes des quatorze 8 000",
    "q.m24#14.e" to "Aucune des quatre premières ne s'acquiert en lisant. Leur point commun : elles doivent être exécutées sous pression, elles ne laissent presque aucune marge d'erreur, et elles dépendent de la mémoire musculaire. C'est pourquoi cette application les marque systématiquement comme nécessitant une évaluation par un encadrant.",

    "q.m24#15.p" to "[Situation] Vous avez réussi toutes les évaluations théoriques. Comment considérer votre niveau maintenant ?",
    "q.m24#15.o0" to "Vous êtes désormais capable de gravir un 8 000 en autonomie",
    "q.m24#15.o1" to "Vous avez une base théorique et un cadre de jugement, mais chaque compétence technique doit encore être validée sur le terrain par un encadrant avant usage",
    "q.m24#15.o2" to "Vous pouvez exercer comme guide",
    "q.m24#15.o3" to "Réussir la théorie signifie que la capacité est là",
    "q.m24#15.e" to "C'est l'affirmation la plus importante de tout le cours : comprendre la théorie n'est pas une capacité de terrain. Cette application construit un cadre cognitif et de jugement ; ce qui vous sauve réellement sur une face de glace, c'est le geste que vous avez répété plusieurs centaines de fois sur un terrain sûr.",

    "q.m24#16.p" to "Après avoir suivi tout le cours, quel est le capital central que vous avez construit ?",
    "q.m24#16.o0" to "Une liste de matériel",
    "q.m24#16.o1" to "Un cadre de pensée : reconnaître le risque, l'évaluer, décider — y compris savoir quand ne pas continuer",
    "q.m24#16.o2" to "Un brevet d'alpinisme",
    "q.m24#16.o3" to "Un tas de faits",
    "q.m24#16.e" to "Des bases à 5 000 m à l'évaluation finale à 8 000 m, le cours répète une seule chose : la sécurité n'est pas le produit de la technique mais du jugement — et la technique existe pour donner de la place au jugement.",

    "q.m24#17.p" to "Complétez : en situation d'incertitude, l'avis le plus ( ) doit être retenu en premier.",
    "q.m24#17.a0" to "prudent",
    "q.m24#17.e" to "« Prudent d'abord » est le principe de clôture de tout le cours : assez simple pour s'appliquer sur place, assez fort pour contrer la plupart des biais cognitifs. La montagne est toujours là ; vous, non.",
    // ---------- m25 Gérer son état et celui du groupe ----------
    "q.m25#0.p" to "Après la montée, vous ressentez une pression dans la tête et un essoufflement, alors que la cordée continue de monter comme prévu. Que faire ?",
    "q.m25#0.o0" to "Serrer les dents — on est venus jusqu'ici",
    "q.m25#0.o1" to "S'arrêter et dire honnêtement au guide ou aux compagnons, puis se reposer et observer",
    "q.m25#0.o2" to "Prendre quelque chose soi-même et suivre la cordée",
    "q.m25#0.o3" to "Accélérer ; atteindre le camp plus tôt réglera le problème",
    "q.m25#0.e" to "Deux choses ne doivent jamais être faites avec les signaux du corps en altitude : les cacher et s'automédiquer. Le bon premier pas est de dire honnêtement ce que l'on ressent, puis de s'arrêter pour se reposer et observer.\nCe n'est pas de la faiblesse — le guide ne peut juger qu'une fois informé, et il vous faut vous-même un temps d'observation pour savoir si cela s'atténue ou s'aggrave.",

    "q.m25#1.p" to "Pourquoi la phrase « on est venus jusqu'ici » est-elle dangereuse en altitude ?",
    "q.m25#1.o0" to "Parce que cela fait perdre du temps",
    "q.m25#1.o1" to "Parce que cela transforme le temps déjà investi en raison de continuer à prendre des risques",
    "q.m25#1.o2" to "Parce que cela affecte l'ambiance de la cordée",
    "q.m25#1.o3" to "Parce que cela sonne peu professionnel",
    "q.m25#1.e" to "C'est la pensée du coût irrécupérable à l'état pur : on a marché jusque-là, dépensé tant, pris tant de congés — cela ne peut donc pas être pour rien.\nMais le risque ne baisse pas parce qu'on a beaucoup investi. Ce qui est dépensé ne se récupère pas, tandis que le coût de continuer peut être d'autres choses encore plus irrécupérables.",

    "q.m25#2.p" to "Vous réalisez que vous ne pouvez clairement pas tenir le rythme de la cordée et que vous forcez. Quelle est la meilleure approche ?",
    "q.m25#2.o0" to "Serrer les dents et suivre pour ne pas retarder les autres",
    "q.m25#2.o1" to "Le dire honnêtement et demander à la cordée d'adopter le rythme du plus lent",
    "q.m25#2.o2" to "Ralentir discrètement en faisant comme si tout allait bien",
    "q.m25#2.o3" to "Ne rien dire à personne et redescendre seul",
    "q.m25#2.e" to "Forcer le rythme en altitude est un découvert caché : le coût immédiat n'est que de la fatigue, mais cela s'accumule en effondrement le lendemain. Et une cordée qui marche au rythme du plus rapide tire tout le monde vers la limite.\nLe bon geste est de fixer l'allure sur ce que la personne la plus lente peut tenir — ce qui protège à la fois l'individu et le groupe.",

    "q.m25#3.p" to "Un compagnon dit qu'il ne se sent pas bien mais insiste : « ça va, je peux marcher ». Que faire ?",
    "q.m25#3.o0" to "Faire confiance à son jugement et continuer",
    "q.m25#3.o1" to "Le prendre au sérieux et prévenir le guide",
    "q.m25#3.o2" to "Ne pas s'en mêler ; le laisser décider",
    "q.m25#3.o3" to "Ne pas prendre cela au sérieux — beaucoup disent ça",
    "q.m25#3.e" to "Le malaise en altitude a un trait cruel : le jugement est touché en premier, donc « je pense que ça va » n'est pas fiable là-haut.\nSignaler l'état de son compagnon au guide est la conduite responsable — si ce n'est rien, le coût est une vérification de plus ; si ce n'est pas rien, vous êtes peut-être le seul à l'avoir remarqué à temps.",

    "q.m25#4.p" to "Avant le départ, le guide annonce que l'itinéraire du lendemain doit être parcouru encordé. Quelqu'un pense : « une pente aussi douce n'en a pas besoin ». Quelle est la bonne compréhension ?",
    "q.m25#4.o0" to "Une pente douce n'a vraiment pas besoin de corde",
    "q.m25#4.o1" to "C'est au guide de décider de l'encordement ; il détient l'information sur le terrain et le manteau",
    "q.m25#4.o2" to "S'encorder sert surtout à faire propre",
    "q.m25#4.o3" to "C'est la personne la plus en forme qui devrait décider",
    "q.m25#4.e" to "Voir « doux » de loin et se tenir là à regarder la répartition des crevasses, des ponts de neige et des fissures cachées sont deux choses différentes. Le guide détient une information que vous n'avez pas — c'est précisément sa valeur.\nSur les décisions techniques, laisser juger celui qui détient le plus d'information est la règle de base de l'efficacité comme de la sécurité.",

    "q.m25#5.p" to "Vous marchez au milieu de la cordée et constatez que votre eau est finie, alors que le prochain point de ravitaillement est à deux heures. Que faire ?",
    "q.m25#5.o0" to "Rester silencieux et ne déranger personne",
    "q.m25#5.o1" to "Le dire immédiatement au chef de cordée et voir si cela peut se coordonner",
    "q.m25#5.o2" to "Demander de l'eau au compagnon le plus proche sans prévenir le chef",
    "q.m25#5.o3" to "Boire moins et continuer",
    "q.m25#5.e" to "Manquer d'eau ou de nourriture est une information d'équipe, pas un détail personnel — elle façonne le jugement du chef sur l'allure et le ravitaillement.\nDemander en privé à un compagnon ressemble à une attention discrète, mais coupe l'information : le chef croit encore la cordée en bon état et peut continuer comme prévu.",

    "q.m25#6.p" to "Que signifie réellement « lent, c'est rapide » en altitude ?",
    "q.m25#6.o0" to "Marcher lentement garantit le sommet",
    "q.m25#6.o1" to "Une allure régulière et soutenable fait gagner plus de temps, et est plus sûre, que des efforts répétés en coups",
    "q.m25#6.o2" to "Lent sert à accommoder les moins en forme",
    "q.m25#6.o3" to "La vitesse n'a pas d'importance en altitude",
    "q.m25#6.e" to "L'apport d'oxygène est limité en altitude, et des efforts explosifs répétés accumulent vite le lactate et aggravent l'hypoxie.\nUne allure régulière est en réalité plus rapide : elle supprime le besoin de pauses de récupération fréquentes et réduit le risque d'être contraint de faire demi-tour par surconsommation. La formule décrit le métabolisme énergétique, ce n'est pas une consolation.",

    "q.m25#7.p" to "Vous atteignez le camp avec deux heures de retard et il fait déjà nuit. Que faire ?",
    "q.m25#7.o0" to "Continuer de nuit vers le camp suivant",
    "q.m25#7.o1" to "Camper là où vous êtes et prévenir les personnes à la maison de votre position",
    "q.m25#7.o2" to "Repartir seul chercher d'éventuels retardataires",
    "q.m25#7.o3" to "Marcher jusqu'à rattraper le groupe devant",
    "q.m25#7.e" to "Progresser de nuit en altitude combine les pires facteurs : obscurité, fatigue, froid, et aucune capacité de lire le terrain. Camper sur place est le choix sain.\nMais cela doit inclure une chose de plus : prévenir l'extérieur de votre position. Ainsi, si un secours est nécessaire, quelqu'un saura au moins où chercher. Agir seul, à l'inverse, fait perdre deux personnes d'un coup à la cordée.",

    "q.m25#8.p" to "Un compagnon tombe nettement malade en route et ralentit sans cesse. La cordée se divise entre attendre ou envoyer certains devant. Quelle est l'approche la plus sensée ?",
    "q.m25#8.o0" to "Toute la cordée continue au rythme initial",
    "q.m25#8.o1" to "Ne jamais se séparer ; toute la cordée ralentit",
    "q.m25#8.o2" to "Affecter une personne expérimentée à l'accompagner pendant que les autres continuent en restant en contact",
    "q.m25#8.o3" to "Le laisser marcher lentement seul et se retrouver au camp",
    "q.m25#8.e" to "Se séparer comporte son propre risque en altitude, mais avec assez de monde, affecter la personne la plus expérimentée à accompagner le plus lent pendant que les autres continuent est souvent plus sensé que de ralentir tout le monde ou de forcer tout le monde.\nTrois choses sont indispensables : quelqu'un reste avec lui, les communications sont maintenues, et le groupe de devant est informé de la situation et de l'heure d'arrivée prévue. Rester totalement seul est la pire des options.",

    "q.m25#9.p" to "Quelle est la bonne compréhension de la place du sommet dans la course ?",
    "q.m25#9.o0" to "Le sommet est la fin de la course",
    "q.m25#9.o1" to "Le sommet n'est que la moitié de la course ; c'est à la descente que le risque se concentre",
    "q.m25#9.o2" to "Seul le sommet compte",
    "q.m25#9.o3" to "Pas de sommet signifie que la course a échoué",
    "q.m25#9.e" to "Beaucoup d'accidents surviennent à la descente, parce que la vigilance chute une fois l'objectif atteint alors que la forme est déjà près de sa limite.\nTraiter le sommet comme « la moitié » signifie prévoir dans le plan autant de temps, d'énergie et de protection pour la descente — au lieu de tout dépenser à la montée.",

    "q.m25#10.p" to "Situation : les premières 24 heures en altitude",
    "q.m25#10.c" to "C'est votre premier sommet de randonnée à 5 000 m. Après avoir atteint un camp à 4 300 m, plusieurs choses se produisent dans les 24 heures qui suivent.",
    "q.m25#10.e" to "L'intérêt de ces quatre étapes n'est pas la connaissance médicale mais deux habitudes : dire honnêtement, et réévaluer. Ce qui pousse réellement les gens en danger lors d'un séjour en altitude n'est pas un mauvais jugement isolé mais une chaîne de petits choix — serrer les dents, ne pas déranger — qui s'empilent.",
    "q.m25#10.s0.p" to "Étape 1 : le soir, vous avez mal à la tête et perdez l'appétit. Un compagnon dit : « c'est normal, dors et ça passera ». Que faire ?",
    "q.m25#10.s0.o0" to "Faire comme il dit et dormir",
    "q.m25#10.s0.o1" to "Dire honnêtement au guide ce que vous ressentez, puis vous reposer, manger et boire en petites quantités souvent, comme indiqué",
    "q.m25#10.s0.o2" to "Trouver un médicament soi-même et ne rien dire",
    "q.m25#10.s0.o3" to "Prendre un verre pour mieux dormir",
    "q.m25#10.s0.e" to "La céphalée et la perte d'appétit sont courantes en altitude, mais courant ne signifie pas négligeable. Un signalement honnête plus des mesures de base — repos, hydratation, petites quantités de nourriture — constituent la réponse standard.\nL'essentiel est que le guide ait besoin de savoir dès que votre état change, et non de le découvrir le lendemain matin.",
    "q.m25#10.s1.p" to "Étape 2 : vous n'avez presque pas dormi de la nuit. Le matin, la cordée se prépare à continuer de monter. Que choisissez-vous ?",
    "q.m25#10.s1.o0" to "Ne rien dire et suivre simplement",
    "q.m25#10.s1.o1" to "Signaler comment vous avez dormi et laisser le guide évaluer s'il faut continuer",
    "q.m25#10.s1.o2" to "Décider seul de rester en arrière sans prévenir la cordée",
    "q.m25#10.s1.o3" to "Demander à toute la cordée de s'arrêter et d'attendre que vous récupériez",
    "q.m25#10.s1.e" to "Mal dormir est l'une des plaintes d'altitude les plus courantes ; seul, cela ne justifie généralement pas d'arrêter l'ascension — mais cela doit alimenter l'évaluation plutôt que d'être porté en silence.\nLe guide le pèsera avec la céphalée, l'appétit et votre façon de marcher. C'est là la valeur de son expérience.",
    "q.m25#10.s2.p" to "Étape 3 : la cordée continue et vous vous sentez un peu mieux qu'hier, mais vous marchez lentement. De quel état d'esprit faut-il le plus se méfier maintenant ?",
    "q.m25#10.s2.o0" to "La peur d'être ridicule",
    "q.m25#10.s2.o1" to "Le sentiment que « ça ne peut pas être pour rien » — il vous rend réticent à vous arrêter quand il le faudrait",
    "q.m25#10.s2.o2" to "L'envie de prendre des photos",
    "q.m25#10.s2.o3" to "L'inquiétude sur la météo",
    "q.m25#10.s2.e" to "Le coût irrécupérable s'enflamme surtout le deuxième jour : on a souffert toute la nuit, donc abandonner maintenant rendrait cette souffrance inutile.\nCette logique transforme un coût déjà payé en raison de continuer, plutôt qu'en signal pour réévaluer.",
    "q.m25#10.s3.p" to "Étape 4 : finalement vous n'atteignez pas le sommet — vous faites demi-tour à une heure du but. Comment voir cette course ?",
    "q.m25#10.s3.o0" to "Un échec ; inutile d'y revenir",
    "q.m25#10.s3.o1" to "Une expérience d'acclimatation utile ; faire demi-tour était du jugement, pas un échec",
    "q.m25#10.s3.o2" to "C'est la faute des compagnons qui vous ont ralenti",
    "q.m25#10.s3.o3" to "La prochaine fois, le sommet quoi qu'il arrive",
    "q.m25#10.s3.e" to "L'acclimatation se construit par expositions répétées ; une première course à 4 000–5 000 m n'a jamais été censée avoir le sommet pour unique objectif.\nEt savoir faire demi-tour au bon moment est la capacité la plus valorisée dans ce sport. Elle vous mènera plus loin qu'un sommet obtenu par chance.",

    "q.m25#11.p" to "Situation : la pression du groupe",
    "q.m25#11.c" to "Quatrième jour de course ; le temps commence à tourner et la cordée est divisée. Votre propre jugement diffère quelque peu de celui du groupe.",
    "q.m25#11.e" to "Cette situation porte sur le fait d'exprimer une réserve. C'est difficile en pratique parce que le coût semble social — gâcher l'ambiance, ne pas être à sa place — tandis que le bénéfice est invisible : un accident qui n'a pas eu lieu. Retenez ces trois points et vous parlerez plus tôt la prochaine fois.",
    "q.m25#11.s0.p" to "Étape 1 : certains soutiennent « on pousse, le temps sera peut-être meilleur demain » ; d'autres veulent descendre. Vous penchez pour la descente mais ne voulez pas être celui qui gâche tout. Que faire ?",
    "q.m25#11.s0.o0" to "Rester silencieux et suivre le mouvement",
    "q.m25#11.s0.o1" to "Énoncer votre jugement et le raisonnement qui le fonde",
    "q.m25#11.s0.o2" to "Se plaindre en privé et en rester là",
    "q.m25#11.s0.o3" to "Faire semblant de soutenir la poursuite en gardant vos doutes",
    "q.m25#11.s0.e" to "La minorité silencieuse est un habitué des rapports d'accident. Avoir une réserve sans l'exprimer signifie que la cordée décide avec une information incomplète.\nLe coût de parler est faible, peut-être nul ; le coût du silence peut être très grand.",
    "q.m25#11.s1.p" to "Étape 2 : après discussion, la cordée décide de continuer, mais vous n'êtes toujours pas à l'aise. Et ensuite ?",
    "q.m25#11.s1.o0" to "Obéir passivement et en faire le minimum",
    "q.m25#11.s1.o1" to "Énoncer clairement votre réserve et confirmer les conditions de demi-tour et le plan de repli de la cordée",
    "q.m25#11.s1.o2" to "Redescendre seul immédiatement",
    "q.m25#11.s1.o3" to "Ne plus rien dire mais en garder rancune",
    "q.m25#11.s1.e" to "Une fois la décision prise, trois choses restent : laisser une trace claire (j'étais en désaccord, parce que…), confirmer que les conditions de repli sont explicites, et s'assurer que vous êtes toujours disposé et capable d'exécuter.\nUne réserve n'est pas une obéissance passive — après avoir dit ce que vous aviez à dire, vous faites votre part correctement.",
    "q.m25#11.s2.p" to "Étape 3 : il s'avère que votre inquiétude était juste et la cordée redescend tôt. Quelle est la valeur de cette expérience ?",
    "q.m25#11.s2.o0" to "Cela prouve que vous valez mieux que les autres",
    "q.m25#11.s2.o1" to "Cela confirme qu'exprimer une réserve à l'avance est efficace et n'abîme pas les relations",
    "q.m25#11.s2.o2" to "Cela montre qu'il faudra agir seul à l'avenir",
    "q.m25#11.s2.o3" to "Pas grand-chose, puisque vous n'avez pas atteint le sommet",
    "q.m25#11.s2.e" to "Beaucoup de gens craignent, la première fois qu'ils expriment une réserve, d'être vus comme mal intégrés. En réalité une bonne cordée finit plus confiante en elle-même, parce que cela prouve que quelqu'un accepte de dire la vérité.\nGardez cette expérience ; la prochaine fois, vous parlerez plus tôt."
)
